INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-achampet-umamaheswara-swamy-temple-the-northern-gateway-node', 'shiva', 'Umamaheswara Swamy Temple (The Northern Gateway node)', 'Andhra Pradesh', 'Achampet', 'Umamaheswaram, northern gateway tradition of Srisailam', 'Shiva (Umamaheswara)', 'Shaiva', '["Umamaheswara","Northern Gateway","Nallamala"]', 'Umamaheswara Swamy Temple is honored as the northern gateway node in Srisailam kshetra pilgrimage tradition.', 'A gateway-dvara shrine on the northern Nallamala approach linked to Srisailam worship circuits.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sri_Umamaheswara_Temple,_UmamaheswaraM(Achampet).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sri_Umamaheswara_Temple,_UmamaheswaraM(Achampet).jpg', 'October to February.', 'Open daily; timings vary by local administration.', 'Traditional/modest attire recommended.', 'This gateway shrine is currently administered in the Telangana region but remains integral to Srisailam gateway tradition.', '["Daily puja","Abhishekam"]', '["Mahashivratri"]', '{"history":"Umamaheswaram is counted in traditional narratives as the northern dvara of Srisailam.","architecture":"Hill-embedded shrine with regional stone and mandapa elements.","visitorNotes":"Check local route conditions before planning hill access.","sources":[{"label":"Wikimedia Commons: Sri Umamaheswara Temple","url":"https://commons.wikimedia.org/wiki/File:Sri_Umamaheswara_Temple,_UmamaheswaraM(Achampet).jpg","type":"Image source"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Umamaheswaram%20Temple%20Achampet","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-achanta-rameswara-swamy-temple', 'shiva', 'Rameswara Swamy Temple', 'Andhra Pradesh', 'Achanta', 'West Godavari district', 'Shiva (Rameswara)', 'Shaiva', '["Rama Legend","Ancient","Architecture"]', 'Ancient temple dedicated to Lord Shiva as Rameswara, believed to have been installed by Lord Rama.', 'The towering gopuram and intricate carvings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Achanta%20Rameswara%20Swamy%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Achanta_Rameswara_Swamy_Temple.jpg', 'October to March.', 'Open daily.', 'Traditional attire preferred.', 'Famous for its Lingam.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Dates back several centuries.","architecture":"Dravidian style.","visitorNotes":"A significant pilgrimage site in West Godavari.","sources":[{"label":"Achanta","url":"https://en.wikipedia.org/wiki/Achanta","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-alampur-bala-brahmeswara-swamy-temple-the-western-gateway-node-anchored-in-the-alampur-navabrahma-complex', 'shiva', 'Bala Brahmeswara Swamy Temple (The Western Gateway node, anchored in the Alampur Navabrahma complex)', 'Andhra Pradesh', 'Alampur', 'Alampur Navabrahma complex, western gateway tradition of Srisailam', 'Shiva (Bala Brahmeswara)', 'Shaiva', '["Bala Brahmeswara","Alampur","Western Gateway"]', 'Bala Brahmeswara Swamy Temple in the Alampur Navabrahma group is the western gateway node in Srisailam tradition.', 'Early Chalukyan stone temple architecture in one of South India\'s key Shiva temple clusters.', 'https://commons.wikimedia.org/wiki/Special:FilePath/7th_century_Bala_Brahma_Temple,_Navabrahma_group,_Alampur,_Telangana_India_-_4.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:7th_century_Bala_Brahma_Temple,_Navabrahma_group,_Alampur,_Telangana_India_-_4.jpg', 'October to February and Mahashivratri period.', 'Open daily; timings vary by season.', 'Traditional/modest attire recommended.', 'This gateway shrine is currently administered in the Telangana region but is historically tied to Srisailam western gateway tradition.', '["Daily puja","Abhishekam"]', '["Mahashivratri"]', '{"history":"Alampur Navabrahma temples include Bala Brahma and are among the earliest extant Chalukyan Shaiva monuments in the region.","architecture":"Early stone temple corpus with Chalukyan plan forms and sculpture panels.","visitorNotes":"Alampur can be integrated with Krishna-Tungabhadra confluence side itineraries.","sources":[{"label":"Alampur Navabrahma Temples","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples","type":"Encyclopedia"},{"label":"Wikimedia Commons: Bala Brahma Temple","url":"https://commons.wikimedia.org/wiki/File:7th_century_Bala_Brahma_Temple,_Navabrahma_group,_Alampur,_Telangana_India_-_4.jpg","type":"Image source"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-alampur-sangameshwara-temple', 'shiva', 'Sangameshwara Temple', 'Andhra Pradesh', 'Alampur', 'Jogulamba Gadwal district', 'Shiva (Sangameshwara)', 'Shaiva', '["Navabrahma","7th Century","River Confluence"]', 'Part of the Navabrahma temple group at the confluence of the Tungabhadra and Krishna rivers, this 7th-century temple is a Chalukyan gem.', 'The exquisite Chalukyan stone carvings and river-confluence setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/7th%20century%20Sangameshwara%20Temple%2C%20Alampur%2C%20Telangana%20India%20-%209.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:7th_century_Sangameshwara_Temple,_Alampur,_Telangana_India_-_9.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'ASI-maintained heritage site.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Built in the 7th century by the Badami Chalukyas, part of the Navabrahma temple complex.","architecture":"Early Chalukyan Nagara style with finely carved temple walls.","visitorNotes":"Alampur is near the Srisailam dam backwaters.","sources":[{"label":"Alampur Navabrahma Temples","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-amaravathi-amareswara-swamy-temple-amararama', 'shiva', 'Amareswara Swamy Temple (Amararama)', 'Andhra Pradesh', 'Amaravathi', 'Guntur district', 'Shiva (Amareswara)', 'Shaiva', '["Pancharama","Krishna River","Ancient"]', 'Situated on the banks of the Krishna River, this Pancharama Kshetra is believed to have a self-growing Shiva linga installed by Lord Indra.', 'The towering white marble linga and riverside setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Amaravathi%20Amareswara%20Swami%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amaravathi_Amareswara_Swami_Temple.jpg', 'October to March.', 'Open daily; timings vary by season.', 'Traditional attire preferred.', 'Near the famous Amaravathi Buddhist stupa.', '["Abhishekam","Rudrabhishekam"]', '["Mahashivratri","Ugadi"]', '{"history":"An ancient Pancharama Kshetra with a 15-foot marble linga said to be growing over time.","architecture":"Dravidian temple with a large gopuram on the Krishna riverbank.","visitorNotes":"Amaravathi is also a major Buddhist heritage site.","festivals":"Mahashivratri is the main festival.","sources":[{"label":"Amaravathi Temple","url":"https://en.wikipedia.org/wiki/Amareswara_temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-ambavaram-bhairavakona-cave-temple', 'shiva', 'Bhairavakona Cave Temple', 'Andhra Pradesh', 'Ambavaram', 'Prakasam district', 'Shiva (Bhairava)', 'Shaiva', '["Rock-cut","Nallamala","7th Century"]', 'A dramatic rock-cut cave shrine in the Nallamala Hills, often called nature\'s own Shiva temple.', 'The natural cave setting amid dense forests and waterfalls.', 'https://commons.wikimedia.org/wiki/Special:FilePath/7th%20to%208th%20century%20Bhairavakona%20rock%20cut%20cave%20temples%2C%20Ambavaram%20Nallamala%20Hills%2C%20Andhra%20Pradesh%20-%202.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:7th_to_8th_century_Bhairavakona_rock_cut_cave_temples,_Ambavaram_Nallamala_Hills,_Andhra_Pradesh_-_2.jpg', 'Monsoon and winter.', 'Open daily; best visited during daylight.', 'Comfortable trekking attire.', 'Involves a forest trek; carry water and provisions.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"7th-8th century rock-cut caves in the Nallamala Hills.","architecture":"Natural rock-cut cave shrines with carved panels.","visitorNotes":"The waterfall near the caves is a scenic attraction.","sources":[{"label":"Bhairavakona","url":"https://en.wikipedia.org/wiki/Bhairavakona","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-antarvedi-neelakantheswara-swamy-temple', 'shiva', 'Neelakantheswara Swamy Temple', 'Andhra Pradesh', 'Antarvedi', 'Konaseema district', 'Shiva (Neelakantheswara)', 'Shaiva', '["River Confluence","Sea","Narasimha"]', 'Located near the Lakshmi Narasimha temple at the confluence of the Godavari and Bay of Bengal.', 'The proximity to the sea and river confluence (Sangam).', 'https://commons.wikimedia.org/wiki/Special:FilePath/Antarvedi%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Antarvedi_Temple.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Usually visited along with the famous Narasimha temple.', '["Abhishekam","Samudra Snanam"]', '["Mahashivratri","Magha Saptami"]', '{"history":"Ancient temple at a sacred confluence point.","architecture":"Traditional coastal style.","visitorNotes":"Take a boat ride to the exact point where river meets sea.","sources":[{"label":"Antarvedi","url":"https://en.wikipedia.org/wiki/Antarvedi","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-appikonda-someswara-swamy-temple', 'shiva', 'Someswara Swamy Temple', 'Andhra Pradesh', 'Appikonda', 'Visakhapatnam district', 'Shiva (Someswara)', 'Shaiva', '["Coastal","Chola","Kapila"]', 'A coastal temple believed to have been installed by Sage Kapila, situated right on the beach.', 'The temple\'s location on the beach rocks.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Appikonda_temple_03.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Appikonda_temple_03.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Near Vizag Steel Plant.', '["Abhishekam","Samudra Snanam"]', '["Mahashivratri"]', '{"history":"Ancient temple with inscriptions dating to 12th century Cholas.","architecture":"Simple stone structure on the coast.","visitorNotes":"A scenic spot merging spirituality and sea views.","sources":[{"label":"Appikonda","url":"https://en.wikipedia.org/wiki/Visakhapatnam_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-badvel-shiva-temple', 'shiva', 'Shiva Temple', 'Andhra Pradesh', 'Badvel', 'YSR Kadapa district', 'Shiva', 'Shaiva', '["Town","Devotion","Community"]', 'The main Shiva temple in Badvel, attracting devotees from the surrounding agricultural belt.', 'The vibrant festivals celebrated here.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Badvel_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Badvel_Temple.jpg', 'Year-round.', 'Open daily.', 'Modest attire.', 'Located in town center.', '["Abhishekam"]', '["Mahashivratri","Kartika Masam"]', '{"history":"Long-standing institution.","architecture":"Traditional.","visitorNotes":"Busy on Mondays.","sources":[{"label":"Badvel","url":"https://en.wikipedia.org/wiki/Badvel","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-bandi-atmakur-omkareswara-swamy-temple', 'shiva', 'Omkareswara Swamy Temple', 'Andhra Pradesh', 'Bandi Atmakur', 'Nandyal district', 'Shiva (Omkareswara)', 'Shaiva', '["Om-shaped","Ancient","Heritage"]', 'A sacred Shiva temple in Bandi Atmakur known for its ancient sanctity and association with the sacred syllable Om.', 'The spiritual significance of the Om-named temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nandyal%20Mahanandi%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nandyal_Mahanandi_Temple.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'In Nandyal district; plan combined trip with nearby temples.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"An ancient Shiva temple in the Nandyal region.","architecture":"Traditional South Indian temple.","visitorNotes":"Can be combined with visits to Mahanandi and other Nava Nandi temples.","sources":[{"label":"Bandi Atmakur","url":"https://en.wikipedia.org/wiki/Bandi_Atmakur","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-bheemunipatnam-someswara-swamy-temple', 'shiva', 'Someswara Swamy Temple', 'Andhra Pradesh', 'Bheemunipatnam', 'Visakhapatnam district', 'Shiva (Someswara)', 'Shaiva', '["Coastal","Historic","Beach Town"]', 'A historic Shiva temple in the ancient coastal town of Bheemunipatnam, one of the oldest municipalities in India.', 'The coastal setting in one of India\'s oldest port towns.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lord%20Shiva%20temple%20at%20Bheemunipatnam.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lord_Shiva_temple_at_Bheemunipatnam.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Bheemunipatnam is a scenic beach town near Vizag.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Historic temple in one of the oldest municipalities and port towns of India.","architecture":"Traditional coastal temple architecture.","visitorNotes":"Combine with a visit to Bheemunipatnam beach and Dutch cemetery.","sources":[{"label":"Bheemunipatnam","url":"https://en.wikipedia.org/wiki/Bheemunipatnam","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-bhimavaram-someswara-swamy-temple-somarama', 'shiva', 'Someswara Swamy Temple (Somarama)', 'Andhra Pradesh', 'Bhimavaram', 'West Godavari district', 'Shiva (Someswara)', 'Shaiva', '["Pancharama","Color-changing Linga","Chandra Kundam"]', 'The fifth Pancharama Kshetra, famous for its Shiva linga that is believed to change color with the phases of the moon.', 'The color-changing Shiva linga and the sacred Chandra Kundam pond.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Someswara-Swamy-Temple-Bhimavaram.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Someswara-Swamy-Temple-Bhimavaram.jpg', 'October to March.', 'Open daily.', 'Traditional attire preferred.', 'Observe the linga\'s color on Pournami and Amavasya.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Pournami rituals"]', '{"history":"Ancient Pancharama Kshetra known for the lunar color-changing linga phenomenon.","architecture":"Dravidian temple with the sacred Chandra Kundam tank.","visitorNotes":"Bhimavaram is a major town in West Godavari, well connected by rail.","sources":[{"label":"Somarama Temple","url":"https://en.wikipedia.org/wiki/Someswara_temple,_Bhimavaram","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-biccavolu-golingeswara-swamy-temple', 'shiva', 'Golingeswara Swamy Temple', 'Andhra Pradesh', 'Biccavolu', 'East Godavari district', 'Shiva (Golingeswara)', 'Shaiva', '["Monolithic","Chalukya","Heritage"]', 'A magnificent Eastern Chalukyan temple famous for its monolithic Nandi and rich sculptural heritage.', 'The exquisite Chalukyan stone carvings and the large Nandi.', 'https://commons.wikimedia.org/wiki/Special:FilePath/9th_century_Golingeswara_temple%2C_Biccavolu_Andhra_Pradesh_-_47.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:9th_century_Golingeswara_temple,_Biccavolu_Andhra_Pradesh_-_47.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'ASI protected monument.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Built by the Eastern Chalukyas (9th-10th century).","architecture":"Dravidian style with Chalukyan signatures.","visitorNotes":"Biccavolu has several other temples including a Ganesha temple.","sources":[{"label":"Biccavolu","url":"https://en.wikipedia.org/wiki/Biccavolu","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-borra-caves-borra-guhalu-shiva-temple', 'shiva', 'Borra Guhalu Shiva Temple', 'Andhra Pradesh', 'Borra Caves', 'Alluri Sitharama Raju district', 'Shiva (Guheswara)', 'Shaiva', '["Stalagmite Linga","Cave","Nature"]', 'Deep inside the million-year-old Borra Caves, a natural stalagmite formation is worshipped as a Shiva Linga.', 'The natural Shiva Linga formation inside the spectacular cave.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Borra_Caves_Lingam.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Borra_Caves_Lingam.JPG', 'October to March.', '10:00 AM to 5:00 PM.', 'Comfortable footwear.', 'Entry fee for caves applies.', '["Darshan"]', '["Mahashivratri"]', '{"history":"Natural cave formations dating back a million years.","architecture":"Natural Karst limestone caves.","visitorNotes":"A major tourist attraction near Araku.","sources":[{"label":"Borra Caves","url":"https://en.wikipedia.org/wiki/Borra_Caves","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-bugga-kasi-visweswara-swamy-temple', 'shiva', 'Kasi Visweswara Swamy Temple', 'Andhra Pradesh', 'Bugga', 'Chittoor district', 'Shiva (Visweswara)', 'Shaiva', '["Waterfall","Kasi","Bugga"]', 'Known as the Kasi of the South, famous for the water stream (Bugga) in the temple premise.', 'The perennial water source and serene surroundings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bugga%20Temple%20Chittoor.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bugga_Temple_Chittoor.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Located near Nagari.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Ancient temple held in high regard locally.","architecture":"Dravidian style.","visitorNotes":"Scenically located with a stream.","sources":[{"label":"Bugga Agraharam","url":"https://en.wikipedia.org/wiki/Chittoor_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-chejerla-sri-kapoteswara-swamy-temple', 'shiva', 'Sri Kapoteswara Swamy Temple', 'Andhra Pradesh', 'Chejerla', 'Guntur district', 'Shiva (Kapoteswara)', 'Shaiva', '["Pigeon Legend","King Shibi","Ancient"]', 'Associated with the legend of King Shibi who offered his own flesh to save a pigeon, the linga here is named after the kapota (pigeon).', 'The mythological connection to King Shibi\'s sacrifice.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Amvar%20Chejerla%20Kapoteswara%20temple%20in%20guntur%20district.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amvar_Chejerla_Kapoteswara_temple_in_guntur_district.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Located near Narasaraopet.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Ancient temple linked to the Puranic legend of King Shibi and the pigeon.","architecture":"Traditional Dravidian temple.","visitorNotes":"A pilgrimage site for those following the Shibi Chakravarthy legend.","sources":[{"label":"Chejerla","url":"https://en.wikipedia.org/wiki/Chejerla","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-chilamakuru-agastyeswara-swamy-temple', 'shiva', 'Agastyeswara Swamy Temple', 'Andhra Pradesh', 'Chilamakuru', 'YSR Kadapa district', 'Shiva (Agastyeswara)', 'Shaiva', '["Agastya","Chola","Ancient"]', 'Another temple associated with Sage Agastya, featuring beautiful Chola architecture.', 'The Chola artistic influence and peaceful setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chilamakuru%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chilamakuru_Temple.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Located in a small village.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Historical records indicate Chola patronage.","architecture":"Dravidian style.","visitorNotes":"A hidden gem for heritage lovers.","sources":[{"label":"Chilamakuru","url":"https://en.wikipedia.org/wiki/Kadapa_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-cuddapah-pushpagiri-vaidyanatheswara-temple', 'shiva', 'Pushpagiri Vaidyanatheswara Temple', 'Andhra Pradesh', 'Cuddapah', 'Kadapa district', 'Shiva (Vaidyanatheswara)', 'Shaiva', '["7th Century","Temple Complex","Pushpagiri"]', 'Part of the ancient Pushpagiri temple complex dating to the 7th century, this temple honors Shiva as the divine healer.', 'The multi-temple complex on the sacred Pushpagiri hill.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pushpagiri%20Temple%20in%20Kadapa%20District.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pushpagiri_Temple_in_Kadapa_District.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Multiple temples within the Pushpagiri complex.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Founded around the 7th century CE, the complex includes seven Shiva temples.","architecture":"Chalukyan-era stone temples in a hilltop setting.","visitorNotes":"Near Cuddapah town, easily accessible by road.","sources":[{"label":"Pushpagiri","url":"https://en.wikipedia.org/wiki/Pushpagiri_(Andhra_Pradesh)","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-draksharamam-bhimeswara-swamy-temple-draksharama', 'shiva', 'Bhimeswara Swamy Temple (Draksharama)', 'Andhra Pradesh', 'Draksharamam', 'Konaseema district', 'Shiva (Bhimeswara)', 'Shaiva', '["Pancharama","Ancient","Chalukya"]', 'One of the five Pancharama Kshetras, this temple is believed to enshrine a fragment of Tarakasura\'s linga destroyed by Lord Kumara.', 'Intricate Chalukyan-era carvings and the massive sanctum.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Friezes%20at%20the%20Bhimeswara%20temple%20in%20Draksharamam.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Friezes_at_the_Bhimeswara_temple_in_Draksharamam.jpg', 'October to March.', 'Open daily; timings vary by season.', 'Traditional attire preferred.', 'Also an Ashta Dasha Shakti Peetha.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Kartika Pournami"]', '{"history":"Built during the Chalukya period (7th-8th century), it is both a Pancharama Kshetra and a Shakti Peetha.","architecture":"Blend of Chalukyan and Chola styles with elaborate friezes.","visitorNotes":"The temple complex includes shrines for Manikyamba Devi.","festivals":"Annual Brahmotsavam draws thousands.","sources":[{"label":"Draksharama Temple","url":"https://en.wikipedia.org/wiki/Draksharamam","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-galiveedu-shiva-temple', 'shiva', 'Shiva Temple', 'Andhra Pradesh', 'Galiveedu', 'Annamayya district', 'Shiva', 'Shaiva', '["Rural","Peaceful","Local"]', 'A serene Shiva temple in the Galiveedu area, known for its peaceful environment.', 'The quiet rural setting.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Year-round.', 'Open daily.', 'Modest attire.', 'Village temple.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Community temple.","architecture":"Traditional.","visitorNotes":"Good for a short spiritual stop.","sources":[{"label":"Galiveedu","url":"https://en.wikipedia.org/wiki/Galiveedu","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-gudimallam-gudimallam-parasurameswara-temple-a-highly-ancient-structurally-unique-2nd-century-bce-node-located-just-outside-the-core-grid', 'shiva', 'Gudimallam Parasurameswara Temple (A highly ancient, structurally unique 2nd-century BCE node located just outside the core grid)', 'Andhra Pradesh', 'Gudimallam', 'Chittoor district', 'Shiva (Parasurameswara)', 'Shaiva', '["Oldest Linga","2nd Century BCE","Unique Iconography"]', 'Housing one of the oldest known Shiva lingas in the world (2nd-3rd century BCE), depicting Shiva in a realistic hunter form.', 'A highly ancient and structurally unique 2nd-century BCE Shiva node with the iconic Gudimallam linga form.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Parasurameswara_Swamy_Shiva_temple_Gudimallam%2C_ancient_Shiva_Linga%2C_Yarpedu%2C_Chittoor_Andhra_Pradesh_-_10.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Parasurameswara_Swamy_Shiva_temple_Gudimallam,_ancient_Shiva_Linga,_Yarpedu,_Chittoor_Andhra_Pradesh_-_10.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'A site of immense archaeological importance.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"The linga dates back to the 2nd or 3rd century BCE, making it one of the earliest surviving Hindu icons.","architecture":"Apsidal (Gajaprishta) shrine typical of early Buddhist and Hindu structures.","visitorNotes":"Located near Renigunta/Tirupati.","sources":[{"label":"Gudimallam","url":"https://en.wikipedia.org/wiki/Gudimallam","type":"Encyclopedia"}]}', '2026-02-23T13:24:24+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-gunupudi-someswara-swamy-temple', 'shiva', 'Someswara Swamy Temple', 'Andhra Pradesh', 'Gunupudi', 'West Godavari district', 'Shiva (Someswara)', 'Shaiva', '["Pool","Local Legend","Bhimavaram"]', 'An important Shiva temple near Bhimavaram, known for its sacred tank and local annual festivals.', 'The large temple tank and festival celebrations.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Someswara-Swamy-Temple-Bhimavaram.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Someswara-Swamy-Temple-Bhimavaram.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Distinct from the Pancharama Somarama (also in Bhimavaram).', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Serves the Gunupudi locality of Bhimavaram.","architecture":"Dravidian style.","visitorNotes":"Often visited along with Somarama.","sources":[{"label":"Bhimavaram Temples","url":"https://en.wikipedia.org/wiki/Bhimavaram","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-hemavathi-doddeswara-swamy-temple', 'shiva', 'Doddeswara Swamy Temple', 'Andhra Pradesh', 'Hemavathi', 'Anantapur district', 'Shiva (Doddeswara)', 'Shaiva', '["Giant Nandi","Pallava","Black Basalt"]', 'An ancient temple with an imposing 8-foot Nandi carved from black basalt granite and a 6-foot linga in the sanctum.', 'The massive black basalt Nandi and the large Shiva linga.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Veerabhadra%20Temple%20Tower.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Veerabhadra_Temple_Tower.JPG', 'October to March.', 'Open daily.', 'Modest attire.', 'Hemavathi was an ancient Pallava capital.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Built during the Pallava and Nolamba period (8th-11th century) in the former capital.","architecture":"An 8-foot black basalt Nandi guards the 6-foot Shiva linga.","visitorNotes":"Hemavathi has several ancient temples worth exploring.","sources":[{"label":"Hemavathi","url":"https://en.wikipedia.org/wiki/Hemavati,_Anantapur_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
