INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-jammalamadugu-shiva-temple', 'shiva', 'Shiva Temple', 'Andhra Pradesh', 'Jammalamadugu', 'YSR Kadapa district', 'Shiva', 'Shaiva', '["Historical Town","Pennar","Canyon"]', 'Located in the historic town of Jammalamadugu near the Gandikota canyon.', 'The proximity to the \'Grand Canyon of India\'.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gandikota_View.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gandikota_View.jpg', 'October to February.', 'Open daily.', 'Modest attire.', 'Often visited along with Gandikota.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Jammalamadugu has a rich history connected to Gandikota fort.","architecture":"Vijayanagara influence.","visitorNotes":"A base for exploring Gandikota.","sources":[{"label":"Jammalamadugu","url":"https://en.wikipedia.org/wiki/Jammalamadugu","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-jonnawada-sri-mallikarjuna-swamy-temple', 'shiva', 'Sri Mallikarjuna Swamy Temple', 'Andhra Pradesh', 'Jonnawada', 'Nellore district', 'Shiva (Mallikarjuna)', 'Shaiva', '["12th Century","Kamakshi","Heritage"]', 'Constructed in 1150 CE, this temple is dedicated to Mallikarjuna Swamy alongside Kamakshi Tai.', 'The 12th-century heritage and dual deity worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Srisailam-temple-entrance.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Srisailam-temple-entrance.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Near Nellore; easy day trip.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Built in 1150 CE, one of the important medieval Shiva temples of Rayalaseema.","architecture":"12th-century Dravidian style.","visitorNotes":"Combined with Kamakshi Tai temple in the same complex.","sources":[{"label":"Jonnawada","url":"https://en.wikipedia.org/wiki/Jonnawada","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-kailasakona-kailasakona-cave-temple', 'shiva', 'Kailasakona Cave Temple', 'Andhra Pradesh', 'Kailasakona', 'Chittoor district', 'Shiva (Kailasanatha)', 'Shaiva', '["Waterfall","Cave","Scenic"]', 'A scenic temple near a perennial waterfall, believe to be the place where Lord Kailasanatha performed penance.', 'The crystal clear waterfall cascading near the temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Temple_of_Shiva_and_Parvathy_at_the_bottom_of_the_waterfall.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Temple_of_Shiva_and_Parvathy_at_the_bottom_of_the_waterfall.jpg', 'October to February.', 'Open daily.', 'Modest attire.', 'Easily accessible from the highway.', '["Abhishekam","Bath in falls"]', '["Mahashivratri"]', '{"history":"Legend links it to the wedding of Venkateswara and Padmavathi.","architecture":"Natural setting with constructed shrines.","visitorNotes":"Excellent weekend getaway spot.","sources":[{"label":"Kailasakona","url":"https://en.wikipedia.org/wiki/Kailasakona_Waterfalls","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-kalvabugga-bugga-rameswara-swamy-temple', 'shiva', 'Bugga Rameswara Swamy Temple', 'Andhra Pradesh', 'Kalvabugga', 'Kurnool district', 'Shiva (Rameswara)', 'Shaiva', '["Natural Spring","Tretayuga","Scenic"]', 'Known for a perennial water spring (Bugga) in the sanctum, believed to have been installed by Lord Rama.', 'The natural spring water flowing around the Shiva Linga.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bugga%20Rameswara%20Swamy%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bugga_Rameswara_Swamy_Temple.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Near Orvakal Rock Gardens.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Legends connect it to Parasurama and Rama.","architecture":"Traditional style in a scenic valley.","visitorNotes":"Can be combined with a visit to the rock formations nearby.","sources":[{"label":"Kalvabugga","url":"https://en.wikipedia.org/wiki/Kurnool_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-kamalapuram-shiva-temple', 'shiva', 'Shiva Temple', 'Andhra Pradesh', 'Kamalapuram', 'YSR Kadapa district', 'Shiva', 'Shaiva', '["Local","Heritage","River"]', 'A historic temple in Kamalapuram, near the Papaghni river.', 'The riverbank setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kamalapuram_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kamalapuram_Temple.jpg', 'Year-round.', 'Open daily.', 'Modest attire.', 'Peaceful environ.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Ancient roots.","architecture":"Dravidian.","visitorNotes":"Close to Kadapa city.","sources":[{"label":"Kamalapuram","url":"https://en.wikipedia.org/wiki/Kamalapuram,_YSR_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-kanipakam-manikanteswara-swamy-temple', 'shiva', 'Manikanteswara Swamy Temple', 'Andhra Pradesh', 'Kanipakam', 'Chittoor district', 'Shiva (Manikanteswara)', 'Shaiva', '["Chola","Historical","Complex"]', 'Situated within the famous Kanipakam Vinayaka temple complex, this ancient Shiva temple dates back to the Chola period.', 'The Chola-era architecture and historical significance.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kanipakam%20Temple%20Gopuram.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kanipakam_Temple_Gopuram.jpg', 'Year-round.', 'Open daily.', 'Traditional attire required.', 'Visited along with the swayambhu Vinayaka.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Brahmotsavam"]', '{"history":"Built by Kulothunga Chola I in the 11th century.","architecture":"Chola style.","visitorNotes":"Kanipakam is famous for truth-swearing vows.","sources":[{"label":"Kanipakam","url":"https://en.wikipedia.org/wiki/Kanipakam","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-kotappakonda-sri-trikoteswara-swamy-temple', 'shiva', 'Sri Trikoteswara Swamy Temple', 'Andhra Pradesh', 'Kotappakonda', 'Palnadu district', 'Shiva (Trikoteswara)', 'Shaiva', '["Hilltop","Trikuta Hill","Ancient"]', 'Perched on the three-peaked Trikuta Hill, this sacred shrine offers panoramic views and a challenging pilgrimage climb.', 'The three-peaked hill and the sweeping views from the summit.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sri%20Trikoteswara%20Swamy%20Temple%2C%20Kotappakonda.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sri_Trikoteswara_Swamy_Temple,_Kotappakonda.JPG', 'October to February.', 'Open daily.', 'Comfortable clothing for the climb.', 'Involves a steep hill climb; steps available.', '["Abhishekam","Giripradakshina"]', '["Mahashivratri","Shivaratri Brahmotsavam"]', '{"history":"An ancient pilgrimage center on the three-peaked Trikutachalam hill.","architecture":"Temple complex spread across multiple peaks.","visitorNotes":"Massive Shivaratri celebrations draw lakhs of devotees.","sources":[{"label":"Kotappakonda","url":"https://en.wikipedia.org/wiki/Kotappakonda","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-kotipalli-someswara-swamy-temple', 'shiva', 'Someswara Swamy Temple', 'Andhra Pradesh', 'Kotipalli', 'Konaseema district', 'Shiva (Someswara)', 'Shaiva', '["Pancharama","Kumararama","Gautami"]', 'Often considered a Kumararama Kshetra, this temple stands on the banks of the Gautami Godavari and is known for the Koteswara Lingam.', 'The sacred Godavari river ghats and the ancient linga.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kotipalli_Shiva_Temple_Gopuram_04.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kotipalli_Shiva_Temple_Gopuram_04.JPG', 'October to March.', 'Open daily.', 'Modest attire.', 'Access often involves crossing the river by boat/ferry.', '["Abhishekam","River bath"]', '["Mahashivratri","Magha Masam"]', '{"history":"Ancient temple associated with the moon god (Soma) and Lord Indra.","architecture":"Traditional riverside temple.","visitorNotes":"The temple tank and river confluence are sacred.","sources":[{"label":"Kotipalli","url":"https://en.wikipedia.org/wiki/Kotipalli","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-kurnool-rupala-sangameswara-swamy-temple', 'shiva', 'Rupala Sangameswara Swamy Temple', 'Andhra Pradesh', 'Kurnool', 'Nandyal district', 'Shiva (Sangameswara)', 'Shaiva', '["Submerged","Resurfacing","Seven Rivers"]', 'A magnificent temple usually submerged in the Srisailam backwaters, resurfacing only when water levels drop in summer.', 'The rare sighting of the temple when it emerges from the water.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rupala_Sangameswara_Temple_-_panoramio.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rupala_Sangameswara_Temple_-_panoramio.jpg', 'Summer (April-May) when water is low.', 'Accessible only when not submerged.', 'Modest attire.', 'Check water levels before planning; boat access required sometimes.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Ancient temple at the confluence of seven rivers (Saptaranadi Sangamam).","architecture":"Chalukyan style.","visitorNotes":"Located near the shore but requires low water levels for full darshan.","sources":[{"label":"Sangameswara Temple","url":"https://en.wikipedia.org/wiki/Sangameswara_Temple,_Kurnool","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-lakkireddipalli-shiva-temple', 'shiva', 'Shiva Temple', 'Andhra Pradesh', 'Lakkireddipalli', 'Annamayya district', 'Shiva', 'Shaiva', '["Village","Local","Worship"]', 'The main Shiva temple in Lakkireddipalli, acting as a center for community gatherings and worship.', 'The community atmosphere during festivals.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Year-round.', 'Open daily.', 'Modest attire.', 'Central location in the mandal.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Maintained by local devotees.","architecture":"Simple traditional style.","visitorNotes":"Visit to experience local devotion.","sources":[{"label":"Lakkireddipalli","url":"https://en.wikipedia.org/wiki/Lakkireddipalli","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-lepakshi-veerabhadra-temple', 'shiva', 'Veerabhadra Temple', 'Andhra Pradesh', 'Lepakshi', 'Anantapur district', 'Shiva (Veerabhadra)', 'Shaiva', '["Vijayanagara","Hanging Pillar","Murals"]', 'A Vijayanagara masterpiece famous for its hanging pillar, monolithic Nandi, and stunning ceiling murals depicting Puranic scenes.', 'The hanging pillar and the massive monolithic Nandi bull.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Veerabhadra%20Temple%20Tower.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Veerabhadra_Temple_Tower.JPG', 'October to March.', '6:00 AM to 6:00 PM.', 'Modest attire.', 'ASI-protected heritage monument.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Built in the 16th century by Virupanna and Veeranna, governors under the Vijayanagara Empire.","architecture":"Outstanding Vijayanagara style with 70 carved pillars and ceiling murals.","visitorNotes":"The hanging pillar that does not fully rest on the ground is a major attraction.","sources":[{"label":"Lepakshi","url":"https://en.wikipedia.org/wiki/Lepakshi","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-lepakshi-veerabhadra-temple-lepakshi', 'shiva', 'Veerabhadra Temple (Lepakshi)', 'Andhra Pradesh', 'Lepakshi', 'Sri Sathya Sai district', 'Shiva (Veerabhadra)', 'Shaiva', '["Vijayanagara","Hanging Pillar","Monolithic Nandi"]', 'A celebrated Vijayanagara-era Shiva temple famed for its murals, the hanging pillar, and the massive Nandi monolith nearby.', 'Hanging pillar and the monolithic Nandi.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Veerabhadra_swamy_temple_at_Lepakshi.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Veerabhadra_swamy_temple_at_Lepakshi.jpg', 'October to March.', 'Open daily; timings vary by season.', 'Traditional attire preferred.', 'The Nandi monolith is a short drive from the main shrine.', '["Daily puja","Abhishekam"]', '["Mahashivratri"]', '{"history":"Built in the 16th century during the Vijayanagara period.","architecture":"Vijayanagara style with richly painted ceilings.","visitorNotes":"Ask about the hanging pillar and murals.","sources":[{"label":"Veerabhadra Temple, Lepakshi","url":"https://en.wikipedia.org/wiki/Veerabhadra_Temple,_Lepakshi","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-mahanandi-mahanandi-temple', 'shiva', 'Mahanandi Temple', 'Andhra Pradesh', 'Mahanandi', 'Nandyal district', 'Shiva (Mahanandeeswara)', 'Shaiva', '["Nine Nandis","Sacred Pools","Nallamala"]', 'Set in the Nallamala foothills, this temple is famous for its nine Nandis and perennial freshwater spring pools.', 'Crystal-clear spring water emerging from the Nandi\'s mouth.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mahanandi%20temple%202.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahanandi_temple_2.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Bathing in the sacred pools is customary before darshan.', '["Abhishekam","Sacred bath"]', '["Mahashivratri"]', '{"history":"An ancient temple complex with nine Nandis and natural spring-fed pushkarinis.","architecture":"Traditional Dravidian temple surrounded by lush gardens.","visitorNotes":"Part of the Nava Nandi pilgrimage circuit.","sources":[{"label":"Mahanandi Temple","url":"https://en.wikipedia.org/wiki/Mahanandi","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-mahendragiri-mahendragiri-shiva-temple', 'shiva', 'Mahendragiri Shiva Temple', 'Andhra Pradesh', 'Mahendragiri', 'Srikakulam district', 'Shiva (Gokarneswara)', 'Shaiva', '["Highest Peak","Pandavas","Trek"]', 'Situated on the Mahendragiri peak (Eastern Ghats), associated with the Pandavas and Parasurama. It has shrines for Shiva and Gokarneswara.', 'The high-altitude setting and mythological connections.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mahendragiri%20Hills.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahendragiri_Hills.jpg', 'October to February.', 'Daylight hours.', 'Trekking attire.', 'Requires a trek or off-road drive.', '["Shivaratri Jagaran"]', '["Mahashivratri"]', '{"history":"Ancient site mentioned in the Ramayana and Mahabharata.","architecture":"Ancient stone structures using cyclopean masonry styles.","visitorNotes":"The highest peak in the Eastern Ghats of Odsha/Andhra border region.","sources":[{"label":"Mahendragiri","url":"https://en.wikipedia.org/wiki/Mahendragiri_(Odisha)","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-mandapalli-mandeswara-swamy-temple', 'shiva', 'Mandeswara Swamy Temple', 'Andhra Pradesh', 'Mandapalli', 'Konaseema district', 'Shiva (Mandeswara)', 'Shaiva', '["Saneeswara","Saturn","Dosha Nivarana"]', 'Famous as a temple for Saturn (Saneeswara), where Shiva is worshipped to ward off planetary doshas.', 'The Saneeswara shrine and the tail-oil abhishekam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mandapalli_temple_-_panoramio.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mandapalli_temple_-_panoramio.jpg', 'Saturdays are auspicious.', 'Open daily.', 'Traditional attire preferred.', 'Specific rituals involve sesame oil.', '["Tailabhishekam","Shani Dosha Puja"]', '["Mahashivratri","Shani Trayodashi"]', '{"history":"Legend links it to the sage Dadichi and the demon heavy metal bone weapon.","architecture":"Traditional Godavari style temple.","visitorNotes":"Devotees flock here for relief from Saturn\'s influence.","sources":[{"label":"Mandapalli","url":"https://en.wikipedia.org/wiki/Mandapalli,_East_Godavari_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-matsyagundam-matsyalingeswara-swamy-temple', 'shiva', 'Matsyalingeswara Swamy Temple', 'Andhra Pradesh', 'Matsyagundam', 'Alluri Sitharama Raju district', 'Shiva (Matsyalingeswara)', 'Shaiva', '["Fish Protection","Nature","Tribal"]', 'Famous for the sacred fish in the Machkund river pool that are protected and fed by devotees.', 'Feeding the large majestic mahseer fish in the temple pool.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Matsyagundam.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Matsyagundam.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Fishing is strictly prohibited.', '["Feeding fish","Abhishekam"]', '["Mahashivratri"]', '{"history":"Ancient tribal shrine with unique ecological traditions.","architecture":"Simple village style.","visitorNotes":"Located near Araku Valley.","sources":[{"label":"Matsyagundam","url":"https://en.wikipedia.org/wiki/Araku_Valley","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
