INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-rajahmundry-kotilingeswara-swamy-temple', 'shiva', 'Kotilingeswara Swamy Temple', 'Andhra Pradesh', 'Rajahmundry', 'East Godavari district', 'Shiva (Kotilingeswara)', 'Shaiva', '["Ten Million Lingas","Ravana","Ghat"]', 'Legend says Ravana worshipped Shiva here. The temple is famed for the belief that it was once the site of ten million (koti) lingas.', 'The Kotilingala Ghat and the river view.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sri_Uma_Kotilingeswara_Swamy_Temple_at_Kotilingala_Revu.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sri_Uma_Kotilingeswara_Swamy_Temple_at_Kotilingala_Revu.jpg', 'Year-round.', 'Open daily.', 'Modest attire.', 'A major bathing ghat temple.', '["Abhishekam","River aarti"]', '["Mahashivratri","Pushkaralu"]', '{"history":"Historically significant ghat temple traditionally linked to Ravana.","architecture":"Ghat-side temple structure.","visitorNotes":"Accessible by ferry or road.","sources":[{"label":"Kotilingeswara Temple","url":"https://en.wikipedia.org/wiki/Rajahmundry","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-rajahmundry-markandeya-swamy-temple', 'shiva', 'Markandeya Swamy Temple', 'Andhra Pradesh', 'Rajahmundry', 'East Godavari district', 'Shiva (Markandeyeswara)', 'Shaiva', '["City Temple","Markandeya","Godavari"]', 'Located in the heart of Rajahmundry near the Godavari ghats, believed to have been consecrated by Sage Markandeya.', 'Its central location near the Pushkar Ghat.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Uma_Markandeya_Swamy_Temple_Gopuram.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Uma_Markandeya_Swamy_Temple_Gopuram.jpg', 'Year-round.', 'Open daily.', 'Modest attire.', 'Very crowded during Godavari Pushkaralu.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Kartika Masam"]', '{"history":"Rebuilt in 1818 after earlier structures, it stands where Markandeya is said to have been saved by Shiva.","architecture":"Modern Dravidian style.","visitorNotes":"Close to the Godavari river bathing ghats.","sources":[{"label":"Markandeya Temple","url":"https://en.wikipedia.org/wiki/Rajahmundry","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-ravivalasa-endala-mallikarjuna-swamy-temple', 'shiva', 'Endala Mallikarjuna Swamy Temple', 'Andhra Pradesh', 'Ravivalasa', 'Srikakulam district', 'Shiva (Endala Mallikarjuna)', 'Shaiva', '["Miracle","Sun Rays","Legend"]', 'Known for the miracle where no shadow falls on the deity, and people suffering from skin diseases are believed to be cured here.', 'The belief in curing skin ailments and the sunny location.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ravivalasa%20Endala%20Mallikarjuna%20Swamy.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ravivalasa_Endala_Mallikarjuna_Swamy.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Devotees leave their old clothes here after a cure.', '["Abhishekam","Healing prayers"]', '["Mahashivratri"]', '{"history":"Ancient folklore connects it to the Pandavas.","architecture":"Simple stone structure.","visitorNotes":"Specifically famous for dermatological healing beliefs.","sources":[{"label":"Ravivalasa","url":"https://en.wikipedia.org/wiki/Ravivalasa,_Tekkali_mandal","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-rayachoti-veerabhadra-swamy-temple', 'shiva', 'Veerabhadra Swamy Temple', 'Andhra Pradesh', 'Rayachoti', 'Annamayya district', 'Shiva (Veerabhadra)', 'Shaiva', '["Dakshina Kailasam","Veerabhadra","Ancient"]', 'A major pilgrimage center where Veerabhadra is worshipped as the presiding deity. Known as Dakshina Kailasam.', 'The unique custom of sun rays falling on the idol in March.', 'https://commons.wikimedia.org/wiki/Special:FilePath/RACHAVEEDU_TEMPLE.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:RACHAVEEDU_TEMPLE.jpg', 'October to March.', 'Open daily.', 'Traditional attire preferred.', 'Sun rays illuminate the idol for 5 days in March.', '["Abhishekam","Kalyanam"]', '["Mahashivratri","Brahmotsavam"]', '{"history":"Ancient temple patronized by Kakatiyas and Vijayanagara kings.","architecture":"Dravidian style.","visitorNotes":"Located in the heart of Rayachoti town.","sources":[{"label":"Rayachoti Temple","url":"https://en.wikipedia.org/wiki/Rayachoti","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
