INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-srikalahasti-srikalahasteeswara-temple', 'shiva', 'Srikalahasteeswara Temple', 'Andhra Pradesh', 'Srikalahasti', 'Chittoor district', 'Shiva (Kalahasteeswara)', 'Shaiva', '["Vayu Linga","Kailasa of South","Rahu Ketu Puja"]', 'Known as the Kailasa of South India, this temple enshrines the Vayu Linga, representing the element of air. The lamp inside the sanctum flickers without wind.', 'The eternally flickering lamp in the windless sanctum.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Srikalahasti%20temple%20and%20Hill.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Srikalahasti_temple_and_Hill.jpg', 'Year-round; mornings are best.', '6:00 AM to 8:30 PM.', 'Traditional attire required.', 'Famous for Rahu-Ketu puja performed here.', '["Rahu Ketu Puja","Abhishekam"]', '["Mahashivratri","Brahmotsavam"]', '{"history":"Ancient temple mentioned in Shaiva texts, one of the Pancha Bhuta Sthalams representing air.","architecture":"Massive gopuram with Vijayanagara-era additions and a 36-meter tall tower.","visitorNotes":"Near Tirupati, about 36 km away.","sources":[{"label":"Srikalahasti Temple","url":"https://en.wikipedia.org/wiki/Srikalahasti_temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
