INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-srimukhalingam-srimukhalingam-temple', 'shiva', 'Srimukhalingam Temple', 'Andhra Pradesh', 'Srimukhalingam', 'Srikakulam district', 'Shiva (Mukhalingeswara)', 'Shaiva', '["Three Shiva Forms","Kalinga Style","8th Century"]', 'One of India\'s oldest Shiva temples, unique for depicting three forms of Shiva — Mukhalingeswara, Bhimeswara, and Someswara.', 'The three Shiva forms and the lingam with facial features.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Srimukhalingam%20temple%20nandi%20mandapam.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Srimukhalingam_temple_nandi_mandapam.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Remote location; plan transport in advance.', '["Daily puja","Abhishekam"]', '["Mahashivratri"]', '{"history":"Built by the Eastern Ganga king Kamarnava II in the 8th century AD.","architecture":"Kalinga and Dravidian architectural fusion with intricate carvings.","visitorNotes":"A trickle of water constantly flows from the middle face of the lingam.","sources":[{"label":"Srimukhalingam","url":"https://en.wikipedia.org/wiki/Srimukhalingam","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-srisailam-akkamahadevi-caves-shivalingam-a-naturally-occurring-ancient-shivalinga-located-deep-inside-a-pitch-black-cave-system-accessible-only-by-crossing-the-krishna-river', 'shiva', 'Akkamahadevi Caves Shivalingam (A naturally occurring, ancient Shivalinga located deep inside a pitch-black cave system accessible only by crossing the Krishna River)', 'Andhra Pradesh', 'Srisailam', 'Akkamahadevi Caves, Krishna River gorge, Srisailam', 'Shiva', 'Shaiva', '["Akkamahadevi Caves","Natural Shivalinga","Krishna River"]', 'Deep within the Akkamahadevi cave system lies a revered natural Shivalinga, reached via Krishna River crossing routes.', 'Cave-entry pilgrimage culminating in darshan of a naturally formed Shiva lingam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Divine_shiva_lingam_at_akka_mahadevi_caves.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Divine_shiva_lingam_at_akka_mahadevi_caves.jpg', 'Post-monsoon to winter, when boat access is generally steadier.', 'Access depends on river-boat schedules and local conditions.', 'Modest attire with practical cave-safe footwear.', 'Carry lighting support and follow local safety guidance for cave interiors.', '["Cave darshan","Lingam abhishekam"]', '["Mahashivratri"]', '{"history":"The cave and lingam are part of the wider ascetic and Shaiva tradition around Srisailam.","architecture":"Natural cave morphology rather than constructed temple architecture.","visitorNotes":"Boat movement can vary by reservoir and weather conditions.","sources":[{"label":"Wikimedia Commons: Akkamahadevi cave lingam","url":"https://commons.wikimedia.org/wiki/File:Divine_shiva_lingam_at_akka_mahadevi_caves.jpg","type":"Image source"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Akkamahadevi%20Caves%20Srisailam","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-srisailam-hatakeswara-swamy-temple', 'shiva', 'Hatakeswara Swamy Temple', 'Andhra Pradesh', 'Srisailam', 'Hatakeswaram zone, Srisailam forest belt, Nallamala Hills', 'Shiva (Hatakeswara)', 'Shaiva', '["Hatakeswara","Srisailam","Forest Shrine"]', 'Hatakeswara Swamy Temple is a Shiva shrine associated with the extended Srisailam sacred geography.', 'A lesser-visited but ritually valued Shiva node in the Srisailam forest region.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Htakeswaram-sreesailam.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Htakeswaram-sreesailam.jpg', 'October to February; avoid heavy rain days.', 'Open daily; local timings vary.', 'Modest attire recommended.', 'Best visited with local route guidance due forest approach sections.', '["Daily puja","Abhishekam"]', '["Mahashivratri"]', '{"history":"Hatakeswaram is referenced in local Srisailam-area Shiva worship circuits.","architecture":"Regional shrine style with simple mandapa and sanctum layout.","visitorNotes":"Coordinate transport in advance for return travel.","sources":[{"label":"Wikimedia Commons: Hatakeswaram","url":"https://commons.wikimedia.org/wiki/File:Htakeswaram-sreesailam.jpg","type":"Image source"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Hatakeswaram%20Srisailam","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-srisailam-kadalevanam-cave-shivalingas', 'shiva', 'Kadalevanam Cave Shivalingas', 'Andhra Pradesh', 'Srisailam', 'Kadalevanam forest-cave belt, Nallamala Hills, Srisailam', 'Shiva', 'Shaiva', '["Kadalevanam","Cave Lingas","Srisailam"]', 'Kadalevanam Cave Shivalingas represent a cave-based Shaiva worship node in the broader Srisailam ascetic landscape.', 'Forest-cave setting with naturally oriented Shiva worship traditions.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'October to February; daylight visits are recommended.', 'Access and worship timings vary by local route conditions.', 'Modest attire with suitable trekking footwear.', 'Use local guidance for cave routes and safety in forest terrain.', '["Cave darshan","Lingam puja"]', '["Mahashivratri"]', '{"history":"Kadalevanam is preserved in local Srisailam-area Shaiva memory as a cave-linga worship zone.","architecture":"Natural cave environment rather than formal temple construction.","visitorNotes":"Carry essentials and avoid isolated cave movement without local support.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Kadali%20Vanam%20Srisailam","type":"Map search"},{"label":"Srisailam overview","url":"https://en.wikipedia.org/wiki/Srisailam","type":"Regional reference"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-srisailam-mallikarjuna-swamy-temple', 'shiva', 'Mallikarjuna Swamy Temple', 'Andhra Pradesh', 'Srisailam', 'Kurnool district', 'Shiva (Mallikarjuna)', 'Shaiva', '["Jyotirlinga","Shakti Peetha","River Krishna"]', 'Nestled in the Nallamala Hills on the banks of the Krishna River, this ancient shrine is one of the twelve Jyotirlingas and a Shakti Peetha.', 'The forested hilltop setting and the river gorge views from the temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Srisailam-temple-entrance.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Srisailam-temple-entrance.jpg', 'Winter months, October to February.', '6:00 AM to 3:30 PM and 6:00 PM to 10:00 PM.', 'Traditional attire recommended.', 'Road access through forest routes can be seasonal.', '["Abhishekam","Kumkumarchana"]', '["Mahashivratri","Navratri"]', '{"history":"One of the twelve Jyotirlingas and an ancient Shakti Peetha, the temple is mentioned in inscriptions from the 2nd century onward.","architecture":"Dravidian style with large gopurams and a fortified complex on a hilltop.","visitorNotes":"Srisailam is surrounded by the Nallamala forest and tiger reserve.","festivals":"Mahashivratri is the principal festival.","sources":[{"label":"Srisailam Temple","url":"https://en.wikipedia.org/wiki/Mallikarjuna_Jyotirlinga","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-srisailam-sikhareswara-swamy-temple-anchored-on-the-highest-peak-of-the-nallamala-hills-visually-confirming-the-main-temple-from-this-node-is-a-core-structural-requirement', 'shiva', 'Sikhareswara Swamy Temple (Anchored on the highest peak of the Nallamala hills; visually confirming the main temple from this node is a core structural requirement)', 'Andhra Pradesh', 'Srisailam', 'Sikharam peak zone, Nallamala Hills, Srisailam', 'Shiva (Sikhareswara)', 'Shaiva', '["Sikharam","Srisailam","Peak Shrine"]', 'Sikhareswara Swamy Temple marks a peak-node in Srisailam pilgrimage, linked with the highest-viewpoint ritual tradition.', 'Pilgrims traditionally take visual confirmation of the main Srisailam temple axis from this high node.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'October to February for clear hill visibility.', 'Open daily; local timings vary.', 'Modest attire and suitable footwear for hill terrain.', 'Road and weather conditions in hill sections may affect access windows.', '["Darshan","Pradakshina","Peak-view offering"]', '["Mahashivratri"]', '{"history":"Sikharam traditions are integrated into broader Srisailam kshetra pilgrimage routes.","architecture":"Small hill-shrine architecture adapted to high-elevation terrain.","visitorNotes":"Early daytime visits provide better visibility and safer hill travel.","sources":[{"label":"Srisailam overview","url":"https://en.wikipedia.org/wiki/Srisailam","type":"Regional reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Sikharam%20Srisailam","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-surutapalli-pallikondeswara-swamy-temple', 'shiva', 'Pallikondeswara Swamy Temple', 'Andhra Pradesh', 'Surutapalli', 'Chittoor district', 'Shiva (Pallikondeswara)', 'Shaiva', '["Reclining Shiva","Pradosham","Unique"]', 'A unique temple where Lord Shiva is depicted in a reclining posture (Sayana Shiva), resting on Goddess Parvati\'s lap after consuming Halahala poison.', 'The rare idol of Shiva sleeping on Parvati\'s lap.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pallikondeswara_Temple_in_Surutupalle.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pallikondeswara_Temple_in_Surutupalle.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Located on the AP-Tamil Nadu border.', '["Pradosham Puja","Abhishekam"]', '["Mahashivratri","Pradosham"]', '{"history":"Built during the Vijayanagara period.","architecture":"Dravidian style.","visitorNotes":"Devotees believe this is where Shiva rested after the churning of the ocean.","sources":[{"label":"Surutapalli Temple","url":"https://en.wikipedia.org/wiki/Pallikondeswara_Temple,_Surutapalli","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-tadipatri-bugga-ramalingeswara-swamy-temple', 'shiva', 'Bugga Ramalingeswara Swamy Temple', 'Andhra Pradesh', 'Tadipatri', 'Anantapur district', 'Shiva (Ramalingeswara)', 'Shaiva', '["Stone Carvings","Hidden Gem","Ancient"]', 'A hidden gem admired for its incredibly detailed stone carvings rivaling those of Hampi and Belur.', 'The astonishingly intricate stone carvings on every surface.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bugga%20Ramalingeswara%20temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bugga_Ramalingeswara_temple.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Located in Tadipatri town, easy to access.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"A 15th-century Vijayanagara-era temple known for its exceptionally fine carvings.","architecture":"Vijayanagara style with extraordinary sculptural detail.","visitorNotes":"Often compared to Hampi for the quality of its stone work.","sources":[{"label":"Tadipatri Temples","url":"https://en.wikipedia.org/wiki/Tadipatri","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-talakona-siddheswara-swamy-temple-talakona', 'shiva', 'Siddheswara Swamy Temple (Talakona)', 'Andhra Pradesh', 'Talakona', 'Tirupati district', 'Shiva (Siddheswara)', 'Shaiva', '["Waterfall","Forest","Trekking"]', 'Set amidst the dense Seshachalam forests near the spectacular Talakona waterfall.', 'The stunning 270-foot waterfall and forest setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Siddheswara_Temple_Talakona_-_front.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Siddheswara_Temple_Talakona_-_front.jpg', 'October to February.', 'Open daily; forest entry restricted at night.', 'Comfortable trekking attire.', 'Involves a trek through the forest.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Ancient forest shrine revered by sages.","architecture":"Simple temple integrated with nature.","visitorNotes":"Talakona is the highest waterfall in Andhra Pradesh.","sources":[{"label":"Talakona","url":"https://en.wikipedia.org/wiki/Talakona","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-tekkali-shiva-temple', 'shiva', 'Shiva Temple', 'Andhra Pradesh', 'Tekkali', 'Srikakulam district', 'Shiva', 'Shaiva', '["Local","Heritage","Srikakulam"]', 'A historic Shiva temple in Tekkali, preserving the region\'s traditions.', 'The local heritage architecture.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tekkali_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tekkali_Temple.jpg', 'Year-round.', 'Open daily.', 'Modest attire.', 'Near Tekkali fort ruins.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Associated with local zamindars.","architecture":"Colonial-era Hindu architecture.","visitorNotes":"Interesting historical town.","sources":[{"label":"Tekkali","url":"https://en.wikipedia.org/wiki/Tekkali","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-tirupati-kapila-theertham-temple', 'shiva', 'Kapila Theertham Temple', 'Andhra Pradesh', 'Tirupati', 'Chittoor district', 'Shiva (Kapileshwara)', 'Shaiva', '["Waterfall","Ancient","Sage Kapila"]', 'The only Shiva temple in Tirupati, nestled beside a waterfall, associated with the sage Kapila\'s penance.', 'The natural waterfall cascading beside the temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kapila_Tirtham_temple_at_Tirupati_main_entrance.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kapila_Tirtham_temple_at_Tirupati_main_entrance.jpg', 'Monsoon for the waterfall; winter for pleasant weather.', '6:00 AM to 8:00 PM.', 'Modest attire.', 'Waterfall may dry up in summer.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Ancient temple associated with the sage Kapila, at the foot of Tirumala Hills.","architecture":"Dravidian temple built against the hillside with a natural waterfall.","visitorNotes":"Located at the foot of the Tirumala Hills, close to Tirupati town.","sources":[{"label":"Kapila Theertham","url":"https://en.wikipedia.org/wiki/Kapila_Theertham","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-tripurantakam-tripurantakeswara-swamy-temple-the-eastern-gateway-node', 'shiva', 'Tripurantakeswara Swamy Temple (The Eastern Gateway node)', 'Andhra Pradesh', 'Tripurantakam', 'Tripurantakam, Prakasam district, eastern gateway tradition of Srisailam', 'Shiva (Tripurantakeswara)', 'Shaiva', '["Tripurantakeswara","Eastern Gateway","Srisailam Kshetra"]', 'Tripurantakeswara Swamy Temple is revered as the eastern gateway node in the wider Srisailam pilgrimage framework.', 'A major Shiva shrine in Tripurantakam anchoring the eastern dvara tradition.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tripurantakam-Prakasam-Sri-Tripurantakeswara-Swamy-Temple-2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tripurantakam-Prakasam-Sri-Tripurantakeswara-Swamy-Temple-2.jpg', 'October to March.', 'Open daily; timings vary by season.', 'Traditional/modest attire recommended.', 'Can be combined with other regional Shaiva circuit temples.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Karthika Masam"]', '{"history":"Tripurantakam is a long-standing Shaiva center in Andhra and is linked to Srisailam gateway traditions.","architecture":"Regional Dravidian style with fortified-hill influence in surrounding terrain.","visitorNotes":"Verify festival-day schedules in advance.","sources":[{"label":"Wikimedia Commons: Tripurantakeswara Temple","url":"https://commons.wikimedia.org/wiki/File:Tripurantakam-Prakasam-Sri-Tripurantakeswara-Swamy-Temple-2.jpg","type":"Image source"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Tripurantakeswara%20Temple%20Tripurantakam","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-tripuranthakam-sri-tripurantakeswara-temple', 'shiva', 'Sri Tripurantakeswara Temple', 'Andhra Pradesh', 'Tripuranthakam', 'Prakasam district', 'Shiva (Tripurantakeswara)', 'Shaiva', '["Tripura Legend","Hilltop","Ancient"]', 'Named after Shiva as Tripurantaka, the destroyer of the three flying cities (Tripura), this temple sits on a scenic hilltop.', 'The Tripura legend connection and the hilltop views.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tripurantakam-Prakasam-Sri-Tripurantakeswara-Swamy-Temple-2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tripurantakam-Prakasam-Sri-Tripurantakeswara-Swamy-Temple-2.jpg', 'October to March.', 'Open daily.', 'Modest attire.', 'Involves a hill climb.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Ancient temple associated with the Tripurantaka form of Shiva.","architecture":"Dravidian temple on a hilltop.","visitorNotes":"Combined with Bala Tripurasundari shrine at the same location.","sources":[{"label":"Tripuranthakam","url":"https://en.wikipedia.org/wiki/Tripuranthakam","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
