INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-vijayawada-malleswara-swamy-temple', 'shiva', 'Malleswara Swamy Temple', 'Andhra Pradesh', 'Vijayawada', 'NTR district', 'Shiva (Malleswara)', 'Shaiva', '["Indrakeeladri","Ancient","City Temple"]', 'Located on the Indrakeeladri hill adjacent to the famous Kanaka Durga temple, dating back to the 10th century.', 'The view of the Krishna river and city from the hill.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sri_Durga_Malleswara_Swamy_temple_Vijayawada.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sri_Durga_Malleswara_Swamy_temple_Vijayawada.jpg', 'October to March.', 'Open daily.', 'Modern attire allowed.', 'Part of the Kanaka Durga temple complex visit.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Dasara"]', '{"history":"Installed by Yudhishthira of the Pandavas, according to legend.","architecture":"Dravidian style.","visitorNotes":"Can be visited along with Kanaka Durga temple.","sources":[{"label":"Vijayawada Temples","url":"https://en.wikipedia.org/wiki/Vijayawada","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-visakhapatnam-visweswara-swamy-temple', 'shiva', 'Visweswara Swamy Temple', 'Andhra Pradesh', 'Visakhapatnam', 'Visakhapatnam district', 'Shiva (Visweswara)', 'Shaiva', '["Coastal Battery","City Temple","Hanuman"]', 'Located near the Coastal Battery, this temple is a popular worship site in Vizag city.', 'The proximity to the sea and RK Beach.', 'https://commons.wikimedia.org/wiki/Special:FilePath/S-AP-456_.Visweswara_Swamy_varu_temple4.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:S-AP-456_.Visweswara_Swamy_varu_temple4.JPG', 'Year-round.', 'Open daily.', 'Modern attire allowed.', 'Easy access from RK Beach road.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Modern era temple with traditional rituals.","architecture":"Modern Dravidian style.","visitorNotes":"Can be visited during a beach outing.","sources":[{"label":"Visakhapatnam Temples","url":"https://en.wikipedia.org/wiki/Visakhapatnam","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-andhra-pradesh-yaganti-sri-yaganti-uma-maheshwara-temple', 'shiva', 'Sri Yaganti Uma Maheshwara Temple', 'Andhra Pradesh', 'Yaganti', 'Kurnool district', 'Shiva (Uma Maheshwara)', 'Shaiva', '["Growing Nandi","Cave Temple","5th Century"]', 'Dating to the 5th century, this cave temple is famous for its growing Nandi idol and unique Ardhanareeswara carved from a single stone.', 'The mysteriously growing Nandi idol and the natural cave shrine.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Yaganti%20Gopuram.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Yaganti_Gopuram.JPG', 'October to March.', '6:00 AM to 6:00 PM.', 'Modest attire recommended.', 'Located in a hilly area; comfortable footwear advised.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Kartika Masam"]', '{"history":"Dates to the 5th-6th century with contributions from Pallavas, Cholas, Chalukyas, and Vijayanagara rulers.","architecture":"Rock-cut cave temple with a naturally formed Ardhanareeswara idol.","visitorNotes":"The Nandi idol here is scientifically documented to be slowly growing.","sources":[{"label":"Yaganti Temple","url":"https://en.wikipedia.org/wiki/Yaganti","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
