INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-areraj-someshwar-nath-temple', 'shiva', 'Someshwar Nath Temple', 'Bihar', 'Areraj', 'East Champaran', 'Shiva (Panchmukhi)', 'Shaiva', '["Panchmukhi Lingam","Swayambhu","Shravani Mela"]', 'A 2000-year-old temple housing a rare Panchmukhi (five-faced) Shivalinga. Lord Rama is believed to have worshipped here.', 'The 55-feet tall temple and the five-faced Swayambhu Lingam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Someshwar.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Someshwar.JPG', 'Sawan.', 'Open daily.', 'Casual.', '28km from Motihari.', '["Jalabhishek","Rudrabhishek"]', '["Shravani Mela","Shivratri"]', '{"history":"Ancient; King Som established it.","architecture":"Shikhar style.","darshan":"Devotional.","seasonal":"Very crowded in Sawan.","visitorNotes":"Visit during the morning Aarti.","festivals":"Shivratri.","sources":[{"label":"Areraj","url":"https://eastchamparan.nic.in/tourist-place/areraj-someshwar-nath-mandir/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-baikatpur-baikatpur-gauri-shankar', 'shiva', 'Baikatpur Gauri Shankar', 'Bihar', 'Baikatpur', 'Patna district', 'Gauri-Shankar', 'Shaiva', '["Combined Form","Architecture","Rural"]', 'An ancient temple dedicated to the combined form of Shiva and Parvati (Gauri-Shankar). Located in the rural outskirts of Patna.', 'The unique Gauri-Shankar deity.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Khusrupur.', '["Marriage blessings"]', '["Shivratri"]', '{"history":"Ancient.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Famous for wedding rituals.","festivals":"Shivratri.","sources":[{"label":"Patna","url":"https://patna.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-barabar-hills-siddheshwar-nath-temple', 'shiva', 'Siddheshwar Nath Temple', 'Bihar', 'Barabar Hills', 'Jehanabad district', 'Shiva', 'Shaiva', '["Hill Top","Ashokan Caves","Trekking"]', 'Perched on the highest peak of the Barabar Hills, this ancient Shiva temple offers panoramic views and is near the famous Ashokan caves.', 'The trek to the top and the ancient caves nearby.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Siddheshwar_Nath_Barabar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Siddheshwar_Nath_Barabar.jpg', 'Winter.', 'Sunrise to Sunset.', 'Casual/Trekking gear.', 'Steep climb.', '["Mountain prayer"]', '["Shivratri","Sawan"]', '{"history":"7th Century AD (Gupta period).","architecture":"Ancient stone.","darshan":"Adventure.","seasonal":"Winter is best for climbing.","visitorNotes":"Combine with Barabar Caves.","festivals":"Shivratri.","sources":[{"label":"Barabar Hills","url":"https://en.wikipedia.org/wiki/Barabar_Caves","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
