INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-barauli-mahadeva-shiv-mandir', 'shiva', 'Mahadeva Shiv Mandir', 'Bihar', 'Barauli', 'Gopalganj district', 'Shiva', 'Shaiva', '["Oldest","Mahadeva","Heritage"]', 'Considered one of the oldest Shiva temples in the Gopalganj region, attracting devotees from far and wide.', 'The ancient Lingam and the sanctity.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Barauli road.', '["Jalabhishek"]', '["Shivratri"]', '{"history":"Ancient.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Crowded in Sawan.","visitorNotes":"Main Shiva temple of the area.","festivals":"Shivratri.","sources":[{"label":"Gopalganj","url":"https://gopalganj.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-barh-alakhnath-temple', 'shiva', 'Alakhnath Temple', 'Bihar', 'Barh', 'Patna district', 'Shiva', 'Shaiva/Nath', '["Naga Sannyasis","Alakh Niranjan","Ghat"]', 'Another significant temple in Barh, associated with Naga Sadhus and the \'Alakh Niranjan\' tradition.', 'The association with ascetics and the river.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Umnath.', '["Satsang"]', '["Shivratri"]', '{"history":"Historic.","architecture":"Traditional.","darshan":"Spiritual.","seasonal":"Pleasant.","visitorNotes":"Visit both Umnath and Alakhnath.","festivals":"Shivratri.","sources":[{"label":"Patna Tourism","url":"https://patna.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-barh-umnath-temple', 'shiva', 'Umnath Temple', 'Bihar', 'Barh', 'Patna district', 'Shiva (Umnath)', 'Shaiva', '["Ganga Ghat","Himalaya Daughter","Ancient"]', 'A historic temple on the banks of the Ganges. Legends say Goddess Parvati (Uma) worshipped Shiva here.', 'The scenic ghats and the ancient idol.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rajendra_Bridge_at_Simariya_Ghat.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ARajendra_Bridge_at_Simariya_Ghat.jpg', 'Kartik Purnima.', 'Open daily.', 'Casual.', 'On the river bank.', '["Ganga Aarti"]', '["Shivratri"]', '{"history":"Ancient.","architecture":"Ghat temple.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Serene atmosphere.","festivals":"Shivratri.","sources":[{"label":"Barh","url":"https://patna.nic.in/tourist-place/barh/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-barri-baneshwar-sthan', 'shiva', 'Baneshwar Sthan', 'Bihar', 'Barri', 'Madhubani district', 'Shiva', 'Shaiva', '["Ancient","King Banasur","Mithila"]', 'An ancient temple believed to be established by the mythological King Banasur. It is a center of deep faith in the Mithila region.', 'The connection to King Banasur and the ancient Lingam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'In Benipatti block.', '["Daily Puja"]', '["Shivratri"]', '{"history":"Mythological roots.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Remote but peaceful.","festivals":"Shivratri.","sources":[{"label":"Baneshwar Sthan","url":"https://en.wikipedia.org/wiki/Madhubani_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-basarh-basarh-shiva-temple-ancient-vaishali', 'shiva', 'Basarh Shiva Temple (Ancient Vaishali)', 'Bihar', 'Basarh', 'Vaishali district', 'Shiva', 'Shaiva', '["Ancient Capital Ruins","Historical Core","Lichchhavi Legacy"]', 'Located in the ancient Vaishali archaeological zone, this Shiva node is tied to deep civilizational layers and serves as a historical core anchor in the district\'s sacred landscape.', 'A Shaiva anchor rooted in the ruins of one of India\'s oldest republican capitals.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Winter and Shivratri.', 'Open daily.', 'Modest temple attire.', 'In the Basarh-ancient Vaishali heritage belt.', '["Jalabhishek","Ancestral prayers"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Linked to the archaeological layers of ancient Vaishali civilization.","architecture":"Simple shrine over a heritage-rich landscape.","darshan":"Historical and contemplative.","seasonal":"Best in winter months.","visitorNotes":"Can be combined with the Vaishali stupa and museum circuit.","festivals":"Mahashivratri.","sources":[{"label":"Vaishali (ancient city)","url":"https://en.wikipedia.org/wiki/Vaishali_(ancient_city)","type":"Encyclopedia"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-bela-belaganj-koteshwar-nath-bela', 'shiva', 'Koteshwar Nath (Bela)', 'Bihar', 'Bela (Belaganj)', 'Gaya district', 'Shiva (Koteshwar Nath)', 'Shaiva', '["Sahasralinga","Border Node","Confluence"]', 'An ancient Shiva site in the Bela-Belaganj belt, known for its Sahasralinga form and importance in the northern Gaya rural circuit near the Gaya-Jehanabad transition zone.', 'A multi-linga Shaiva anchor serving the agrarian sub-grid of northern Gaya.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kapileshwar_Sthan.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Kapileshwar_Sthan.jpg', 'Shivratri and Shravan.', 'Open daily.', 'Casual.', 'Near the Morhar-Dargha confluence belt.', '["Jalabhishek","Rural puja"]', '["Shivratri","Shravan Somvar"]', '{"history":"Historic local shrine tradition.","architecture":"Traditional stone-based shrine features.","darshan":"Devotional and community-focused.","seasonal":"Pleasant in winter; busy in Shravan.","visitorNotes":"Known in the area for its multi-linga Shiva form.","festivals":"Shivratri.","sources":[{"label":"Koteshwarnath","url":"https://gaya.nic.in/tourist-place/baba-koteshwarnath-temple/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-belarahi-dhaneshwar-nath-mahadev', 'shiva', 'Dhaneshwar Nath Mahadev', 'Bihar', 'Belarahi', 'Madhubani district', 'Shiva (Gaurishankar)', 'Shaiva', '["Gaurishankar","Village Temple","Mithila"]', 'Also known as Gaurishankar Mahadev Sthan, it is a significant center of worship in the Jhanjharpur subdivision.', 'The Gaurishankar form of Shiva.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Jhanjharpur.', '["Daily Puja"]', '["Shivratri"]', '{"history":"Local history.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Community center for the village.","festivals":"Shivratri.","sources":[{"label":"Dhaneshwar Nath","url":"https://en.wikipedia.org/wiki/Madhubani_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-bhagalpur-budhanath-temple', 'shiva', 'Budhanath Temple', 'Bihar', 'Bhagalpur', 'Bhagalpur district', 'Shiva', 'Shaiva', '["Urban Anchor","Elder Wisdom","Ganga Bank"]', 'One of Bhagalpur\'s principal riverfront Shiva temples, Budhanath serves as the city\'s primary urban anchor for daily life-cycle rituals and steady Shaiva worship.', 'Core city-level Shiva router for Bhagalpur\'s Ganga-facing urban sub-grid.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baba_Budhanath_Temple.png', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ABaba_Budhanath_Temple.png', 'Sawan.', 'Open daily.', 'Casual.', 'In Adampur area.', '["Ganga Aarti"]', '["Shivratri","Sawan"]', '{"history":"Ancient Bhagalpur shrine with enduring local scripture and oral-tradition references.","architecture":"Shikhar style.","darshan":"Urban riverfront devotional.","seasonal":"Pleasant.","visitorNotes":"Important stop for city rituals and evening ghat worship cycles.","festivals":"Shivratri.","sources":[{"label":"Budhanath","url":"https://en.wikipedia.org/wiki/Budhanath_Temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-bhairava-bhairava-ugna-mahadev', 'shiva', 'Bhairava Ugna Mahadev', 'Bihar', 'Bhairava', 'Madhubani district', 'Shiva', 'Shaiva/Maithil', '["Vidyapati","Ugna","Bisfi"]', 'Another significant temple dedicated to the Ugna incarnation of Shiva, located in the Bisfi block, the birthplace of Vidyapati.', 'The literary heritage of Bisfi and Vidyapati.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ugna_Mahadev_Bhawanipur.jpg', 'Wikimedia Commons (Representational - Ugna)', 'https://commons.wikimedia.org/wiki/File:Ugna_Mahadev_Bhawanipur.jpg', 'Vidyapati Jayanti.', 'Open daily.', 'Casual.', 'In Bisfi.', '["Literary tributes"]', '["Vidyapati Samaroh"]', '{"history":"Connected to Poet Vidyapati.","architecture":"Modern.","darshan":"Cultural.","seasonal":"Winter.","visitorNotes":"Visit Vidyapati\'s birthplace nearby.","festivals":"Shivratri.","sources":[{"label":"Bisfi","url":"https://en.wikipedia.org/wiki/Bisfi","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-bhaluni-bhaluni-dham-shiva-shakti-interface', 'shiva', 'Bhaluni Dham (Shiva-Shakti Interface)', 'Bihar', 'Bhaluni', 'Rohtas district', 'Shiva', 'Shaiva/Shakta', '["Shiva Shakti Interface","Rural Anchor","Agrarian Grid"]', 'A rural devotional center where Shiva shrines operate alongside stronger goddess worship streams, creating a balanced Shiva-Shakti pilgrimage node for the surrounding farming belt.', 'Important rural stabilizer between hill communities and river plain settlements.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Shivratri and local fair periods.', 'Open daily.', 'Modest temple attire.', 'In the rural Rohtas belt; check local road conditions.', '["Daily puja","Somvar worship"]', '["Mahashivratri","Shravan month"]', '{"history":"Sustained by village-level Shiva-Shakti worship traditions.","architecture":"Traditional rural temple structures.","darshan":"Community-oriented and grounded.","seasonal":"Accessible most of the year; monsoon travel may vary.","visitorNotes":"Often visited as part of local multi-temple circuits.","festivals":"Mahashivratri.","sources":[{"label":"Rohtas district","url":"https://rohtas.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-bhawanipur-ugna-mahadev-mandir', 'shiva', 'Ugna Mahadev Mandir', 'Bihar', 'Bhawanipur', 'Madhubani district', 'Shiva (Ugna)', 'Shaiva/Maithil', '["Vidyapati","Poet Saint","Legend"]', 'The site where Lord Shiva, in the guise of a servant named Ugna, revealed his true form to the great poet Vidyapati.', 'The deep literary and spiritual connection to Vidyapati.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ugna_Mahadev_Bhawanipur.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ugna_Mahadev_Bhawanipur.jpg', 'Vidyapati Parv.', 'Open daily.', 'Casual.', 'Near Pandaul.', '["Vidyapati Smriti"]', '["Shivratri","Vidyapati Samaroh"]', '{"history":"14th Century association with Vidyapati.","architecture":"Modern renovation.","darshan":"Cultural.","seasonal":"Winter.","visitorNotes":"A pilgrimage for literature lovers too.","festivals":"Shivratri.","sources":[{"label":"Ugna Mahadev","url":"https://en.wikipedia.org/wiki/Vidyapati","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-bhimbandh-bhimbandh-temple', 'shiva', 'Bhimbandh Temple', 'Bihar', 'Bhimbandh', 'Munger district', 'Shiva', 'Shaiva', '["Hot Springs","Mahabharata","Forest"]', 'Located in the Bhimbandh Wildlife Sanctuary, known for its hot springs. Legend says Bhima built a dam (bandh) here. There are old Shiva shrines.', 'The hot springs and the forest setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mandar_Hill.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Mandar_Hill.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Inside sanctuary.', '["Bath in hot spring"]', '["Shivratri"]', '{"history":"Mahabharata legend.","architecture":"Ruins/Natural.","darshan":"Nature.","seasonal":"Best in winter.","visitorNotes":"Wildlife sanctuary rules apply.","festivals":"Shivratri.","sources":[{"label":"Bhimbandh","url":"https://munger.nic.in/tourist-place/bhimbandh-wildlife-sanctuary/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-bounsi-mandar-hill-temple', 'shiva', 'Mandar Hill Temple', 'Bihar', 'Bounsi', 'Banka district', 'Shiva / Madhusudan', 'Mixed', '["Samudra Manthan","Hill Top","Jain/Hindu"]', 'Located on Mandar Hill, legendary for being the churning rod in Samudra Manthan. It has temples for Shiva, Vishnu, and Jain Tirthankaras.', 'The mythological significance of the hill and the views.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mandar_Mount_or_Hill.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AMandar_Mount_or_Hill.jpg', 'Makar Sankranti.', 'Sunrise to Sunset.', 'Casual.', 'Ropeway available.', '["Parikrama"]', '["Bounsi Mela"]', '{"history":"Mythological (Puranas).","architecture":"Rock cut/Stone.","darshan":"Mythological.","seasonal":"Crowded in Jan.","visitorNotes":"Take the ropeway for easy access.","festivals":"Makar Sankranti.","sources":[{"label":"Mandar Hill","url":"https://en.wikipedia.org/wiki/Mandar_Hill","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-brahmapur-brahmeshwar-nath-temple', 'shiva', 'Brahmeshwar Nath Temple', 'Bihar', 'Brahmapur', 'Buxar district', 'Shiva', 'Shaiva', '["Baba Brahmeshwar Nath","Raghunathpur","Regional Anchor"]', 'A major Shaiva center in the Raghunathpur sector, often referred to as the Deoghar of Buxar. Local tradition preserves the Gauripur legend in which the temple entrance miraculously shifted direction.', 'One of the most revered high-traffic Shiva nodes of the Buxar region.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Barhampur_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ABarhampur_Temple.jpg', 'Phalgun (Cattle Fair).', 'Open daily.', 'Casual.', 'Raghunathpur station nearby.', '["Cattle trading nearby","Puja"]', '["Shivratri","Phalgun Mela"]', '{"history":"Ancient shrine with enduring regional legends.","architecture":"Shikhar style.","darshan":"Historic and devotional.","seasonal":"Most crowded in Shravan and Shivratri cycles.","visitorNotes":"A key pilgrimage stop across Buxar and nearby districts.","festivals":"Shivratri.","sources":[{"label":"Brahmapur Buxar","url":"https://en.wikipedia.org/wiki/Brahmapur,_Buxar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-buxar-nath-baba-temple', 'shiva', 'Nath Baba Temple', 'Bihar', 'Buxar', 'Buxar district', 'Shiva', 'Nath Sampradaya', '["Nath Sampradaya","Lineage Anchor","Urban Node"]', 'A Nath-lineage Shiva center in Buxar town, known for disciplined yogic and Shaiva practice in the city core.', 'Important Nath Sampradaya reference point in the Buxar urban grid.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Shivratri and Guru Purnima.', 'Open daily.', 'Modest temple attire.', 'In Buxar town; associated with Nath tradition.', '["Nath lineage worship","Daily aarti"]', '["Mahashivratri","Guru Purnima"]', '{"history":"Part of the long-running Nath presence in the Buxar area.","architecture":"Ashram-temple style.","darshan":"Yogic and disciplined.","seasonal":"Most active in Shivratri and monsoon months.","visitorNotes":"A key stop for Nath Sampradaya seekers in town.","festivals":"Mahashivratri and Guru Purnima.","sources":[{"label":"Buxar","url":"https://en.wikipedia.org/wiki/Buxar","type":"Encyclopedia"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-buxar-rameshwar-nath-temple-ram-rekha-ghat', 'shiva', 'Rameshwar Nath Temple (Ram Rekha Ghat)', 'Bihar', 'Buxar', 'Buxar district', 'Shiva (Rameshwar Nath)', 'Shaiva', '["Ram Rekha Ghat","Ganga Bank","Purification"]', 'Located on the banks of the Ganga at Ram Rekha Ghat, this temple is linked to local traditions that Lord Rama established the lingam here after the Tadaka encounter.', 'A major riverfront Shiva shrine tied to Ramayana memory in Buxar.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Shravan and Shivratri.', 'Open daily.', 'Modest temple attire.', 'Located near Ram Rekha Ghat in Buxar town.', '["Jalabhishek","Ganga snan-linked puja"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Associated in local belief with the Ramayana-era Buxar sacred circuit.","architecture":"Traditional North Indian shrine form.","darshan":"Riverfront and purification-focused.","seasonal":"Peak footfall during monsoon pilgrimage months.","visitorNotes":"Best visited early morning with ghat darshan.","festivals":"Mahashivratri and Shravan observances.","sources":[{"label":"Buxar","url":"https://en.wikipedia.org/wiki/Buxar","type":"Encyclopedia"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-buxar-shri-adinath-akhara', 'shiva', 'Shri Adinath Akhara', 'Bihar', 'Buxar', 'Buxar district', 'Shiva', 'Nath Sampradaya', '["Akhara","Nath Sect","Ashram"]', 'An ashram and temple complex dedicated to Lord Shiva, following the Nath tradition. Located near the Buxar railway station.', 'The Akhara tradition and spiritual atmosphere.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_statue_at_Adinath_Akhara.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shiva_statue_at_Adinath_Akhara.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Rajendra Prasad Road.', '["Yoga","Puja"]', '["Guru Purnima","Shivratri"]', '{"history":"Nath order establishment.","architecture":"Ashram style.","darshan":"Spiritual.","seasonal":"Pleasant.","visitorNotes":"A place for meditation.","festivals":"Shivratri.","sources":[{"label":"Buxar","url":"https://en.wikipedia.org/wiki/Buxar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-buxar-rural-belt-kamrup-mahadev', 'shiva', 'Kamrup Mahadev', 'Bihar', 'Buxar rural belt', 'Buxar district', 'Shiva (Kamrup Mahadev)', 'Shaiva', '["Rural Sentinel","Border Transition","Ancient Stone"]', 'A weathered rural Shiva shrine of the Buxar sub-grid, recognized locally as a transition node linking western Buxar routes toward the Bihar interior.', 'A calm rural Mahadev site with strong local continuity.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Winter and Shivratri.', 'Open daily.', 'Modest temple attire.', 'Located in the rural Buxar corridor.', '["Rural Jalabhishek","Somvar puja"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Maintained through local community worship traditions.","architecture":"Simple rural shrine architecture.","darshan":"Quiet and grounded.","seasonal":"Most accessible outside heavy monsoon spells.","visitorNotes":"Best combined with other Buxar district Shiva circuits.","festivals":"Mahashivratri.","sources":[{"label":"Buxar district","url":"https://buxar.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-champanagar-champanagar-shiva-shrines', 'shiva', 'Champanagar Shiva Shrines', 'Bihar', 'Champanagar', 'Bhagalpur district', 'Shiva', 'Shaiva', '["Ancient Anga","Karna Legacy","Deep Time"]', 'A historic Shaiva cluster in the old Champanagar zone, tied to the memory of ancient Anga and Karna-era regional tradition within western Bhagalpur.', 'A resilient deep-time historical grounding node in the Bhagalpur urban-periphery belt.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Winter and Mahashivratri.', 'Open daily.', 'Modest temple attire.', 'In Champanagar historical zone near Bhagalpur city.', '["Jalabhishek","Local lineage prayers"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Linked to the ancient Anga civilizational region and later city growth of Bhagalpur.","architecture":"Mixed old and renovated shrine structures.","darshan":"Historic and community-centered.","seasonal":"Active during monsoon and winter pilgrimage windows.","visitorNotes":"Often visited as part of Bhagalpur old-city temple routes.","festivals":"Mahashivratri.","sources":[{"label":"Bhagalpur district","url":"https://bhagalpur.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-charaut-charaut-math', 'shiva', 'Charaut Math', 'Bihar', 'Charaut', 'Sitamarhi district', 'Shiva', 'Shaiva/Nath', '["Math Tradition","Mahant","Heritage"]', 'A historic Math (monastic establishment) which houses a prominent Shiva temple. It has a rich tradition of ascetics.', 'The monastic tradition and the old temple structure.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Charaut_Math.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ACharaut_Math.jpg', 'Guru Purnima.', 'Open daily.', 'Modest.', 'Near Sitamarhi.', '["Satsang"]', '["Guru Purnima"]', '{"history":"Established by Mahants.","architecture":"Math style.","darshan":"Spiritual.","seasonal":"Pleasant.","visitorNotes":"Respect the Math rules.","festivals":"Shivratri.","sources":[{"label":"Sitamarhi","url":"https://en.wikipedia.org/wiki/Sitamarhi_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-chautham-katyayani-sthan', 'shiva', 'Katyayani Sthan', 'Bihar', 'Chautham', 'Khagaria district', 'Katyayani / Shiva', 'Shakta/Shaiva', '["Shakti Peeth","Katyayani","River Bank"]', 'A major Shakti Peeth dedicated to Goddess Katyayani. As with all Shakti Peeths, it has a Bhairav (Shiva) shrine, integral to worship.', 'The connection to Goddess Durga and the river Kosi.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Matsyagandha_Temple_in_Saharsa_Town.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AMatsyagandha_Temple_in_Saharsa_Town.jpg', 'Navratri.', 'Open daily.', 'Casual.', 'On Kosi bank.', '["Navratri Puja"]', '["Navratri","Shivratri"]', '{"history":"Ancient.","architecture":"Temple complex.","darshan":"Devotional.","seasonal":"Crowded in Navratri.","visitorNotes":"Main temple of Khagaria.","festivals":"Navratri.","sources":[{"label":"Khagaria","url":"https://khagaria.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
