INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-darbhanga-ahilya-sthan', 'shiva', 'Ahilya Sthan', 'Bihar', 'Darbhanga', 'Darbhanga district', 'Ahilya / Shiva / Rama', 'Vaishnava/Shaiva', '["Ramayana","Ahilya","Redemption"]', 'The place where Ahilya, cursed to be a stone, was redeemed by Lord Rama. It is a major pilgrimage center with Shiva and Rama temples.', 'The Ramayana significance.', 'https://commons.wikimedia.org/wiki/Special:FilePath/%E0%A4%B6%E0%A5%8D%E0%A4%B0%E0%A5%80_%E0%A4%B0%E0%A4%BE%E0%A4%AE_%E0%A4%9C%E0%A4%BE%E0%A4%A8%E0%A4%95%E0%A5%80_%E0%A4%AE%E0%A4%A8%E0%A5%8D%E0%A4%A6%E0%A4%BF%E0%A4%B0%2C_%E0%A4%85%E0%A4%B9%E0%A4%BF%E0%A4%B2%E0%A5%8D%E0%A4%AF%E0%A4%BE_%E0%A4%B8%E0%A5%8D%E0%A4%A5%E0%A4%BE%E0%A4%A8%2C_%E0%A4%85%E0%A4%B9%E0%A4%BF%E0%A4%AF%E0%A4%BE%E0%A4%B0%E0%A5%80%2C_%E0%A4%A6%E0%A4%B0%E0%A4%AD%E0%A4%82%E0%A4%97%E0%A4%BE%2C_%E0%A4%AC%E0%A4%BF%E0%A4%B9%E0%A4%BE%E0%A4%B0.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3A%E0%A4%B6%E0%A5%8D%E0%A4%B0%E0%A5%80_%E0%A4%B0%E0%A4%BE%E0%A4%AE_%E0%A4%9C%E0%A4%BE%E0%A4%A8%E0%A4%95%E0%A5%80_%E0%A4%AE%E0%A4%A8%E0%A5%8D%E0%A4%A6%E0%A4%BF%E0%A4%B0%2C_%E0%A4%85%E0%A4%B9%E0%A4%BF%E0%A4%B2%E0%A5%8D%E0%A4%AF%E0%A4%BE_%E0%A4%B8%E0%A5%8D%E0%A4%A5%E0%A4%BE%E0%A4%A8%2C_%E0%A4%85%E0%A4%B9%E0%A4%BF%E0%A4%AF%E0%A4%BE%E0%A4%B0%E0%A5%80%2C_%E0%A4%A6%E0%A4%B0%E0%A4%AD%E0%A4%82%E0%A4%97%E0%A4%BE%2C_%E0%A4%AC%E0%A4%BF%E0%A4%B9%E0%A4%BE%E0%A4%B0.jpg', 'Ram Navami.', 'Open daily.', 'Casual.', 'Near Ahiyari.', '["Ramayana recitation"]', '["Ram Navami","Vivah Panchami"]', '{"history":"Mythological.","architecture":"Modern temple.","darshan":"Devotional.","seasonal":"Crowded.","visitorNotes":"Deep cultural roots.","festivals":"Ram Navami.","sources":[{"label":"Ahilya Sthan","url":"https://darbhanga.nic.in/tourist-place/ahilya-sthan/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
