INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-dhanauri-baba-khar-nath-temple', 'shiva', 'Baba Khar Nath Temple', 'Bihar', 'Dhanauri', 'Lakhisarai district', 'Shiva / Saint', 'Shaiva/Nath', '["Baba Khar Nath","Samadhi","Local Faith"]', 'Built over the Samadhi of Baba Khar Nath, a saint who took living Samadhi. It is a major center of local faith.', 'The Samadhi shrine and the faith of locals.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baba_khar_nath.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ABaba_khar_nath.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'In Dhanauri village.', '["Samadhi Pujan"]', '["Shivratri"]', '{"history":"Dedicated to a Siddha Saint.","architecture":"Modern.","darshan":"Spiritual.","seasonal":"Pleasant.","visitorNotes":"Experience the local village culture.","festivals":"Shivratri.","sources":[{"label":"Dhanauri","url":"https://en.wikipedia.org/wiki/Lakhisarai_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-dharhara-shiv-temple-dharhara', 'shiva', 'Shiv Temple Dharhara', 'Bihar', 'Dharhara', 'Supaul district', 'Shiva', 'Shaiva', '["Holy Place","Village Temple","Kosi Region"]', 'A revered Shiva temple in the Kosi region, considered a very holy place by the locals.', 'The spiritual atmosphere in a rural setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_temple_Dharhara_Supaul.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shiva_temple_Dharhara_Supaul.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Supaul.', '["Jalabhishek"]', '["Shivratri"]', '{"history":"Local heritage.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Authentic rural Bihar temple.","festivals":"Shivratri.","sources":[{"label":"Supaul","url":"https://en.wikipedia.org/wiki/Supaul_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-gaya-brahmajuni-hill-temple', 'shiva', 'Brahmajuni Hill Temple', 'Bihar', 'Gaya', 'Gaya district', 'Shiva / Devi', 'Shaiva/Shakta', '["1000 Steps","Brahma","Cave"]', 'Known for the 1000 stone steps leading to the top, it has a clear view of Vishnupad. It houses ancient shrines including Shiva.', 'The panoramic view of Gaya and the ancient caves.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Old_Gaya_from_the_outskirts_looking_west._Brahmajuni_hill_%26_temple_in_the_distance_-_DPLA_-_4dcd96580069d4cc532c89d25e07eacd.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AOld_Gaya_from_the_outskirts_looking_west._Brahmajuni_hill_%26_temple_in_the_distance_-_DPLA_-_4dcd96580069d4cc532c89d25e07eacd.jpg', 'Winter.', 'Sunrise to Sunset.', 'Casual.', 'Steep climb.', '["Meditation"]', '["Shivratri"]', '{"history":"Ancient; visited by Buddha.","architecture":"Cave/Temple.","darshan":"Scenic.","seasonal":"Pleasant.","visitorNotes":"Good for sunrise.","festivals":"Shivratri.","sources":[{"label":"Brahmajuni","url":"https://gaya.nic.in/tourist-place/brahmajuni-hill/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-gaya-mangla-gauri-shiva-shrines-gabhashteshwar', 'shiva', 'Mangla Gauri Shiva Shrines (Gabhashteshwar)', 'Bihar', 'Gaya', 'Gaya district', 'Shiva (Gabhashteshwar)', 'Shaiva/Shakta', '["Mangla Gauri","Gabhashteshwar","Shiva Shakti Interface"]', 'Within the Mangla Gauri sacred complex, the integrated Shiva shrines, especially Gabhashteshwar, form an important Shiva-Shakti interface in the Gaya ritual circuit.', 'A major interface point balancing Shakti devotion with Shaivite grounding.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Navratri and Shivratri.', 'Open daily.', 'Modest temple attire.', 'Part of the Mangla Gauri hill-temple zone.', '["Shiva-Shakti puja","Aarti"]', '["Navratri","Mahashivratri"]', '{"history":"Linked to the long-running Mangla Gauri pilgrimage tradition.","architecture":"Hill shrine complex with mixed temple structures.","darshan":"Interface of Shaiva and Shakta worship.","seasonal":"High footfall during Navratri and Pitrapaksha season.","visitorNotes":"Often combined with major Gaya circuit darshan points.","festivals":"Navratri and Shivratri.","sources":[{"label":"Gaya district","url":"https://gaya.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-gaya-markandeywar-mahadev', 'shiva', 'Markandeywar Mahadev', 'Bihar', 'Gaya', 'Gaya district', 'Shiva (Markandeywar)', 'Shaiva', '["Sage Markandeya","Rukmini Sarovar","Longevity"]', 'A Markandeya-linked Shiva shrine in the Gaya ritual landscape, associated with long-life prayers and resilience traditions, and locally connected to the Rukmini Sarovar zone.', 'A long-life and rejuvenation-oriented Shiva node in Gaya.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Historic_heritage_sites_of_Bihar_with_GPS_coordinates.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AHistoric_heritage_sites_of_Bihar_with_GPS_coordinates.jpg', 'Shivratri and Shravan.', 'Open daily.', 'Casual.', 'Gaya city circuit; associated with Rukmini Sarovar area.', '["Mahamrityunjaya Jaap","Ayushya prayers"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Part of the Markandeya-centered Shaiva devotional stream.","architecture":"Traditional shrine setting.","darshan":"Spiritual and meditative.","seasonal":"Pleasant in winter and monsoon pilgrimage months.","visitorNotes":"Frequently visited for health and longevity sankalpa.","festivals":"Shivratri.","sources":[{"label":"Gaya Temples","url":"https://gaya.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-gaya-pitamahshwar-mahadev', 'shiva', 'Pitamahshwar Mahadev', 'Bihar', 'Gaya', 'Gaya district', 'Shiva (Pitamahshwar)', 'Shaiva', '["Phalgu River","Ancestral Rites","Shaivite Anchor"]', 'A major Shiva shrine near the Phalgu river, associated with ancestral rites and the Pitamaha tradition in the Gaya sacred landscape.', 'A key grounding Shiva temple connected to the district\'s Shraddha circuit.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Pitrapaksha and Shivratri.', 'Open daily.', 'Modest temple attire.', 'Near Phalgu river ritual zone in Gaya.', '["Jalabhishek","Pitra-linked prayer offerings"]', '["Pitrapaksha Mela","Mahashivratri"]', '{"history":"Part of Gaya\'s long-standing Shaiva and ancestral ritual traditions.","architecture":"Traditional shrine layout.","darshan":"Ancestral and Shaivite.","seasonal":"Highest footfall during Pitrapaksha.","visitorNotes":"Best visited alongside Phalgu and Vishnupad-area rituals.","festivals":"Pitrapaksha and Shivratri.","sources":[{"label":"Gaya Tourism","url":"https://gaya.nic.in/tourist-places/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-gaya-ramshila-hill-temple', 'shiva', 'Ramshila Hill Temple', 'Bihar', 'Gaya', 'Gaya district', 'Shiva (Pataleshwar)', 'Shaiva', '["Pataleshwar","Pind Daan","Hill"]', 'The Ramshila Hill houses the ancient Pataleshwar Mahadev temple along with temples for Rama and Sita.', 'The Pataleshwar shrine and the Ramayana connection.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pataleshwar_Temple.JPG', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Pataleshwar_Temple.JPG', 'Pitrapaksha.', 'Open daily.', 'Casual.', 'Near Vishnupad.', '["Pind Daan","Rudra Puja"]', '["Shivratri"]', '{"history":"Ancient.","architecture":"Hill temple.","darshan":"Devotional.","seasonal":"Crowded in Pitrapaksha.","visitorNotes":"Sacred for ancestors.","festivals":"Shivratri.","sources":[{"label":"Ramshila","url":"https://gaya.nic.in/tourist-place/ramshila-hill/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-gaya-siddhnath-mahadev-pretshila-hill', 'shiva', 'Siddhnath Mahadev (Pretshila Hill)', 'Bihar', 'Gaya', 'Gaya district', 'Shiva (Siddhnath) / Yamraj tradition', 'Shaiva/Smarta', '["Pretshila","Sentinel Node","Hill Top"]', 'A high-elevation Shiva shrine on Pretshila Hill associated with the broader Pind Daan landscape of Gaya. It functions as a major hilltop darshan point overlooking the Falgu valley.', 'High-altitude Shiva darshan integrated with the Pretshila ancestral circuit.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Historic_heritage_sites_of_Bihar_with_GPS_coordinates.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AHistoric_heritage_sites_of_Bihar_with_GPS_coordinates.jpg', 'Pitrapaksha and winter.', 'Sunrise to Sunset.', 'Casual.', 'Requires stair climb on Pretshila hill route.', '["Pind Daan","Siddhnath puja"]', '["Pitrapaksha Mela","Mahashivratri"]', '{"history":"Ancient hill pilgrimage site; restoration linked to Ahilyabai-era patronage.","architecture":"Hill shrine typology.","darshan":"Ancestral and contemplative.","seasonal":"Most crowded during Pitrapaksha.","visitorNotes":"Prepare for climb and daytime visit.","festivals":"Pitrapaksha.","sources":[{"label":"Pretshila","url":"https://gaya.nic.in/tourist-place/pretshila-hill/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-gorakhpur-katihar-gorakhnath-temple', 'shiva', 'Gorakhnath Temple', 'Bihar', 'Gorakhpur (Katihar)', 'Katihar district', 'Gorakhnath (Shiva)', 'Nath', '["Nath Sect","Guru Gorakhnath","Ashram"]', 'Dedicated to Guru Gorakhnath, a form of Shiva. It acts as a spiritual center for the Nath tradition followers in the region.', 'The Nath tradition and serene environment.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_statue_at_Adinath_Akhara.jpg', 'Wikimedia Commons (Representational Nath)', 'https://commons.wikimedia.org/wiki/File:Shiva_statue_at_Adinath_Akhara.jpg', 'Makar Sankranti.', 'Open daily.', 'Casual.', 'In Katihar.', '["Dhuni Rama"]', '["Makar Sankranti"]', '{"history":"Nath lineage.","architecture":"Ashram.","darshan":"Spiritual.","seasonal":"Pleasant.","visitorNotes":"Peaceful.","festivals":"Shivratri.","sources":[{"label":"Katihar","url":"https://katihar.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-gupta-dham-gupteshwar-mahadev-gupt-dham', 'shiva', 'Gupteshwar Mahadev (Gupt Dham)', 'Bihar', 'Gupta Dham', 'Rohtas district', 'Shiva (Swayambhu)', 'Shaiva', '["Limestone Cave","Natural Stalagmite Lingam","Siddha Node"]', 'A major cave shrine in the Kaimur hills where the Shiva form is naturally expressed through stalagmite formations. The enclosed cavern creates a powerful natural acoustic chamber for mantra and Om recitation.', 'One of the strongest cave-based Shaiva coordinates in Rohtas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gupteshwar_Mahadev.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gupteshwar_Mahadev.jpg', 'Winter, Basant Panchami, and Shivratri.', 'Daylight hours.', 'Trekking gear/Casual.', 'Requires cave trek and basic preparedness.', '["Jalabhishek in cave"]', '["Basant Panchami","Shivratri"]', '{"history":"Ancient natural cave sanctuary with long-standing local worship.","architecture":"Natural Cave.","darshan":"Cave pilgrimage and meditation oriented.","seasonal":"Best outside heavy monsoon periods.","visitorNotes":"Carry torch and suitable footwear.","festivals":"Basant Panchami.","sources":[{"label":"Rohtas","url":"https://rohtas.nic.in/tourist-place/gupta-dham/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-hajipur-kameshwar-nath-temple-hajipur', 'shiva', 'Kameshwar Nath Temple (Hajipur)', 'Bihar', 'Hajipur', 'Vaishali district', 'Shiva (Kameshwar Nath)', 'Shaiva', '["Urban Anchor","District Hub","River Port City"]', 'A major Shiva temple serving Hajipur\'s urban devotional flow, functioning as a central grounding and routing node for the district headquarters.', 'Primary city-level Shaiva stabilizer for Hajipur and nearby riverfront communities.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Shravan and Mahashivratri.', 'Open daily.', 'Modest temple attire.', 'Within Hajipur urban area.', '["Jalabhishek","Daily aarti"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Part of Hajipur\'s long-running urban Shaiva worship tradition.","architecture":"City-temple style.","darshan":"High-traffic urban darshan.","seasonal":"Crowded in Shravan and during Monday worship cycles.","visitorNotes":"Usually visited with other Hajipur Shiva shrines.","festivals":"Mahashivratri.","sources":[{"label":"Vaishali district","url":"https://vaishali.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-hajipur-kaun-haara-ghat', 'shiva', 'Kaun Haara Ghat', 'Bihar', 'Hajipur', 'Vaishali district', 'Shiva / Vishnu', 'Smarta', '["Gajendra Moksha","Legend","Ghat"]', 'The legendary site of the elephant (Gajendra) and crocodile fight, where Vishnu saved the elephant. It has Shiva and Vishnu temples.', 'The mythological struggle and liberation legend.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Budhanath_Temple_Bhagalpur.jpg', 'Wikimedia Commons (Representational Ghat)', 'https://commons.wikimedia.org/wiki/File:Budhanath_Temple_Bhagalpur.jpg', 'Kartik Purnima.', 'Open daily.', 'Casual.', 'Confluence area.', '["Holip dip"]', '["Kartik Purnima"]', '{"history":"Puranic.","architecture":"Ghat shrines.","darshan":"Mythological.","seasonal":"Crowded in Kartik.","visitorNotes":"Scenic confluence view.","festivals":"Shivratri.","sources":[{"label":"Vaishali","url":"https://vaishali.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-hajipur-patalshwar-mahadev-hajipur', 'shiva', 'Patalshwar Mahadev (Hajipur)', 'Bihar', 'Hajipur', 'Vaishali district', 'Shiva', 'Shaiva', '["Deep Earth","Cooling Loop","Subterranean Lingam"]', 'A subterranean Shiva shrine in Hajipur where the lingam is worshipped below ground level, creating a naturally cool and grounded ritual environment in the Gandak basin belt.', 'One of the district\'s strongest below-ground Shaiva sanctums.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pataleshwar_Mandir%2C_view_from_inside_the_temple%2C_Deccan_(3).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3APataleshwar_Mandir%2C_view_from_inside_the_temple%2C_Deccan_(3).jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Jadhua Road.', '["Daily Aarti"]', '["Shivratri","Vivah Panchami"]', '{"history":"Historic local shrine with long-standing below-ground worship tradition.","architecture":"Shikhar style.","darshan":"Grounded and cooling.","seasonal":"Busy in Shravan and on Mondays.","visitorNotes":"A core Hajipur Shiva stop in Vaishali circuits.","festivals":"Shivratri.","sources":[{"label":"Pataleshwar Mandir","url":"https://en.wikipedia.org/wiki/Pataleshwar_Mandir,_Hajipur","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-hajipur-ramchaura-mandir', 'shiva', 'Ramchaura Mandir', 'Bihar', 'Hajipur', 'Vaishali district', 'Shiva & Rama', 'Vaishnava/Shaiva', '["Lord Rama","Footprints","Heritage"]', 'Marking the spot where Lord Rama stayed on his way to Janakpur. It houses a Shivling believed to be worshipped by Rama.', 'The footprints of Lord Rama and the historic significance.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ram_Charan.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ARam_Charan.jpg', 'Ram Navami.', 'Open daily.', 'Casual.', 'In Hajipur town.', '["Ram Navami celebration"]', '["Ram Navami","Shivratri"]', '{"history":"Ancient Ramayana connection.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Crowded during Ram Navami.","visitorNotes":"A key religious site in Hajipur.","festivals":"Ram Navami.","sources":[{"label":"Ramchaura","url":"https://en.wikipedia.org/wiki/Ramchaura_Mandir","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-jamui-giddheshwar-temple', 'shiva', 'Giddheshwar Temple', 'Bihar', 'Jamui', 'Jamui district', 'Shiva', 'Shaiva', '["Ravana-Jatayu","Hill","Nature"]', 'Legend says this is where the mythical fight between Ravana and Jatayu took place. The temple is situated in a scenic hilly spot.', 'The Ramayana connection and the boulders.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Siddheshwar_Nath_Barabar.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Siddheshwar_Nath_Barabar.jpg', 'Shivratri/Sawan.', 'Open daily.', 'Casual.', '15km from Jamui.', '["Offering boulders (belief)"]', '["Shivratri"]', '{"history":"Ramayana era legend.","architecture":"Hill shrine.","darshan":"Scenic.","seasonal":"Pleasant.","visitorNotes":"Good for picnic and prayer.","festivals":"Shivratri.","sources":[{"label":"Jamui","url":"https://jamui.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-jamui-patneshwar-mandir', 'shiva', 'Patneshwar Mandir', 'Bihar', 'Jamui', 'Jamui district', 'Shiva', 'Shaiva', '["Goswami Family","Kiul River","Nature"]', 'A scenic temple located near the Kiul river, established by the Goswami family. It is known for the mud wall that forms around the Lingam in Sawan.', 'The scenic location and the Sawan rituals.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baba_khar_Nath_ji.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Baba_khar_Nath_ji.jpg', 'Sawan.', 'Open daily.', 'Casual.', 'Near Jamui town.', '["Milk offering"]', '["Shravani Mela"]', '{"history":"Built in 1711 AD.","architecture":"Traditional.","darshan":"Nature + Divine.","seasonal":"Green in monsoon.","visitorNotes":"Beautiful riverside spot.","festivals":"Shivratri.","sources":[{"label":"Patneshwar","url":"https://jamui.nic.in/tourist-place/patneshwar-mandir/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-jaynagar-shilanath-mahadev-mandir', 'shiva', 'Shilanath Mahadev Mandir', 'Bihar', 'Jaynagar', 'Madhubani district', 'Shiva', 'Shaiva', '["Border Town","Local Deity","Shilanath"]', 'An ancient temple located in Dullipatti village near the Nepal border town of Jaynagar.', 'The proximity to the border and ancient roots.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Jaynagar.', '["Daily Puja"]', '["Shivratri"]', '{"history":"Ancient.","architecture":"Village style.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Near the railway station.","festivals":"Shivratri.","sources":[{"label":"Jaynagar","url":"https://en.wikipedia.org/wiki/Jainagar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-kahalgaon-batheshwar-sthan-shiva-node', 'shiva', 'Batheshwar Sthan Shiva Node', 'Bihar', 'Kahalgaon', 'Bhagalpur district', 'Shiva', 'Shaiva', '["Vikramshila Interface","Hill Shrine","Reflective Intelligence"]', 'A hill-linked Shiva site near the Vikramshila university ruins in Kahalgaon, where the river-facing landscape and archaeological setting create a strong wisdom-interface devotional zone.', 'A Vikramshila-adjacent Shiva node connecting contemplative heritage with river-grid pilgrimage.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bateshwar_sthan_caves.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ABateshwar_sthan_caves.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Vikramshila Excavation site.', '["Mundan","Pind Daan"]', '["Magh Purnima Mela"]', '{"history":"Ancient sacred area with layered Shaiva and monastic-era regional memory.","architecture":"Historic hill-shrine zone with cave-linked features.","darshan":"Scenic and reflective.","seasonal":"Crowded in Magh.","visitorNotes":"Best visited with the Vikramshila and Kahalgaon river circuit.","festivals":"Shivratri.","sources":[{"label":"Bateshwar Sthan","url":"https://bhagalpur.nic.in/tourist-place/bateshwar-sthan/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-kahalgaon-koteshwar-nath-kahalgaon', 'shiva', 'Koteshwar Nath (Kahalgaon)', 'Bihar', 'Kahalgaon', 'Bhagalpur district', 'Shiva (Koteshwar Nath)', 'Shaiva', '["Sahasralinga","Frequency Multiplier","Eastern Grid"]', 'A Kahalgaon Shiva anchor associated with Sahasralinga worship and the wider river-hill sacred corridor near rock-cut temple zones.', 'Multi-band Shaiva node for eastern Bhagalpur\'s river transition belt.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Mahashivratri and winter.', 'Open daily.', 'Modest temple attire.', 'Kahalgaon sub-grid near Vikramshila-Batheshwar route.', '["Sahasralinga puja","Jalabhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Local Kahalgaon Shaiva tradition with multi-linga worship continuity.","architecture":"Traditional shrine with regional stone features.","darshan":"Rural-urban transition node darshan.","seasonal":"Most comfortable in winter and post-monsoon months.","visitorNotes":"Can be combined with Batheshwar and Vikramshila visits.","festivals":"Mahashivratri.","sources":[{"label":"Bhagalpur district","url":"https://bhagalpur.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-kajra-shringirishi-dham', 'shiva', 'Shringirishi Dham', 'Bihar', 'Kajra', 'Lakhisarai district', 'Shiva', 'Shaiva', '["Rishya Sringa","Hills","Waterfall"]', 'A beautiful spot in the hills where Sage Shringi (Rishya Sringa) medititated. It has a Shiva temple and a waterfall.', 'The natural beauty and the cave shrine.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Singheshwar_Sthan_Temple.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Singheshwar_Sthan_Temple.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Requires climbing.', '["Jalabhishek"]', '["Shivratri"]', '{"history":"Ramayana era.","architecture":"Cave/Temple.","darshan":"Scenic.","seasonal":"Pleasant.","visitorNotes":"Adventure and spirituality.","festivals":"Shivratri.","sources":[{"label":"Lakhisarai","url":"https://lakhisarai.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-kakolat-kakolat-waterfall-temple', 'shiva', 'Kakolat Waterfall Temple', 'Bihar', 'Kakolat', 'Nawada district', 'Shiva', 'Shaiva', '["Waterfall","Snake Legend","Nature"]', 'A Shiva temple located at the base of the famous Kakolat waterfall. Legend says a king turned into a python was cursed here and attained salvation.', 'The cool waterfall and the scenic temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kakolat_waterfall,_Bihar,_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AKakolat_waterfall,_Bihar,_India.jpg', 'Summer/Chhath.', 'Daylight hours.', 'Casual/Swimwear nearby.', 'Nature spot.', '["Bath and Puja"]', '["Chhath","Baisakhi"]', '{"history":"Mythological.","architecture":"Simple.","darshan":"Nature.","seasonal":"Crowded in summer.","visitorNotes":"Refreshing spot.","festivals":"Baisakhi Mela.","sources":[{"label":"Kakolat","url":"https://nawada.nic.in/tourist-place/kakolat-waterfall/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-kesaria-viraat-ramayan-mandir', 'shiva', 'Viraat Ramayan Mandir', 'Bihar', 'Kesaria', 'East Champaran', 'Shiva & Rama', 'Vaishnava/Shaiva', '["Upcoming Marvel","Largest Lingam","World\'s Largest"]', 'An under-construction temple complex set to be the world\'s largest Ramayan temple, featuring the world\'s largest Shivling.', 'The ambitious scale and the future largest Lingam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Viraat_Ramayan_Mandir.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AViraat_Ramayan_Mandir.jpg', 'Future Visit.', 'Construction site.', 'Casual.', 'Near Kesaria Stupa.', '["Construction ongoing"]', '["Future events"]', '{"history":"Modern construction starting 2012.","architecture":"Angkor Wat inspired.","darshan":"Future.","seasonal":"All year.","visitorNotes":"Visit the nearby Kesaria Stupa.","festivals":"None yet.","sources":[{"label":"Viraat Ramayan Mandir","url":"https://en.wikipedia.org/wiki/Viraat_Ramayan_Mandir","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-konch-konch-shiva-temple', 'shiva', 'Konch Shiva Temple', 'Bihar', 'Konch', 'Gaya district', 'Shiva (Koncheswar)', 'Shaiva', '["Ancient Architecture","Brick Temple","Gupta Style"]', 'A magnificent ancient brick temple dating back to the later Gupta or early medieval period. It resembles the Deo Sun Temple and Bodh Gaya temple.', 'The curvilinear Sikhara and ancient brickwork.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Historic_heritage_sites_of_Bihar_with_GPS_coordinates.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AHistoric_heritage_sites_of_Bihar_with_GPS_coordinates.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Tekari.', '["Daily Puja"]', '["Shivratri"]', '{"history":"8th-11th Century AD.","architecture":"Nagara (Brick).","darshan":"Historic.","seasonal":"Pleasant.","visitorNotes":"A gem for archaeology lovers.","festivals":"Shivratri.","sources":[{"label":"Konch","url":"https://en.wikipedia.org/wiki/Konch,_Gaya","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-kursakanta-sundernath-dham', 'shiva', 'Sundernath Dham', 'Bihar', 'Kursakanta', 'Araria district', 'Shiva', 'Shaiva', '["Nepal Border","Sundari Math","Pilgrimage"]', 'A famous Shiva temple located right on the India-Nepal border. It is a major pilgrimage site for people from both countries.', 'The cross-border devotion and the Sundari Math.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sundernath_dham.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ASundernath_dham.jpg', 'Makar Sankranti.', 'Open daily.', 'Casual.', 'Near Nepal border.', '["Mela participation"]', '["Makar Sankranti Mela"]', '{"history":"Ancient Math tradition.","architecture":"Traditional.","darshan":"Crowded.","seasonal":"Winter.","visitorNotes":"Unique border culture.","festivals":"Makar Sankranti.","sources":[{"label":"Sundernath","url":"https://en.wikipedia.org/wiki/Araria_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-kusheshwar-asthan-kusheshwar-asthan', 'shiva', 'Kusheshwar Asthan', 'Bihar', 'Kusheshwar Asthan', 'Darbhanga district', 'Shiva', 'Shaiva', '["Bird Sanctuary","Wetlands","Pilgrimage"]', 'A major Shiva temple surrounded by wetlands which are a bird sanctuary. It is considered a \'Baba Dham\' of Mithila.', 'The combination of pilgrimage and bird watching.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kusheshwar_Asthan_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kusheshwar_Asthan_Temple.jpg', 'Winter (Birds + Temple).', 'Open daily.', 'Casual.', 'Eastern Darbhanga.', '["Jalabhishek"]', '["Shivratri","Sawan"]', '{"history":"Ancient site.","architecture":"North Indian style.","darshan":"Nature + Divine.","seasonal":"Winter for migratory birds.","visitorNotes":"Great for nature lovers.","festivals":"Shivratri.","sources":[{"label":"Kusheshwar Asthan","url":"https://en.wikipedia.org/wiki/Kusheshwar_Asthan_Bird_Sanctuary","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-lakhisarai-ashok-dham-temple', 'shiva', 'Ashok Dham Temple', 'Bihar', 'Lakhisarai', 'Lakhisarai district', 'Shiva', 'Shaiva', '["Indradamneshwar","Giant Lingam","Complex"]', 'Also known as Indradamneshwar Mahadev, this temple was discovered by a shepherd named Ashok. It houses a massive black stone Shivling.', 'The sheer size of the temple complex and the Lingam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ashokdham_Lakhisarai.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AAshokdham_Lakhisarai.jpg', 'Shivratri/Sawan.', 'Open daily.', 'Casual.', 'Large complex.', '["Jalabhishek"]', '["Shravani Mela","Shivratri"]', '{"history":"Discovered in 1977; ancient roots.","architecture":"Modern restructuring.","darshan":"Devotional.","seasonal":"Crowded in Sawan.","visitorNotes":"Has temples for other deities too.","festivals":"Shivratri.","sources":[{"label":"Ashok Dham","url":"https://en.wikipedia.org/wiki/Ashokdham_Temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-lalganj-gauri-shankar-temple-lalganj', 'shiva', 'Gauri Shankar Temple (Lalganj)', 'Bihar', 'Lalganj', 'Vaishali district', 'Gauri-Shankar', 'Shaiva', '["Rural Baseline","Agrarian Grid","Gauri Shankar"]', 'A rural Gauri-Shankar shrine in the Lalganj belt that maintains a stable Shaiva baseline across northern Vaishali\'s agrarian communities.', 'A quiet, weathered rural anchor with consistent local ritual continuity.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Shravan and post-monsoon months.', 'Open daily.', 'Modest temple attire.', 'In Lalganj block rural sector.', '["Village puja","Somvar worship"]', '["Mahashivratri","Shravan month rituals"]', '{"history":"Sustained by local village worship cycles over generations.","architecture":"Traditional rural shrine form.","darshan":"Community-centered and calm.","seasonal":"Most active in monsoon pilgrimage months.","visitorNotes":"Best visited with local Vaishali rural temple routes.","festivals":"Mahashivratri.","sources":[{"label":"Vaishali district","url":"https://vaishali.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-madanpur-madanpur-devi-temple', 'shiva', 'Madanpur Devi Temple', 'Bihar', 'Madanpur', 'West Champaran', 'Devi / Shiva', 'Shakta', '["Devi","Local Faith","Forest Edge"]', 'A revered Goddess temple in West Champaran, known for fulfilling wishes. It has a significant Shiva Lingam worshipped alongside the Devi.', 'The devotion of the local Tharu community.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mundeshwari_Temple.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Mundeshwari_Temple.jpg', 'Navratri.', 'Open daily.', 'Casual.', 'Near Valmiki Nagar.', '["Animal sacrifice (symbolic)"]', '["Navratri"]', '{"history":"Local legend.","architecture":"Village style.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Experience local culture.","festivals":"Navratri.","sources":[{"label":"West Champaran","url":"https://westchamparan.nic.in/tourist-place/madanpur-devi-asthana/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-madanpur-umga-shiva-temple', 'shiva', 'Umga Shiva Temple', 'Bihar', 'Madanpur', 'Aurangabad district', 'Shiva & Surya', 'Shaiva/Saura', '["Sun Temple Complex","Architecture","Hill"]', 'Part of the famous Umga Sun Temple complex, this temple houses Lord Shiva and is a masterpiece of stone architecture.', 'The majestic stone architecture on the hill.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Umgeswari_Umga_Mandir,_Bihar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AUmgeswari_Umga_Mandir,_Bihar.jpg', 'Chhath/Winter.', 'Open daily.', 'Casual.', 'On Umga Hill.', '["Hill Parikrama"]', '["Chhath","Shivratri"]', '{"history":"Ancient; similar to Deo Sun Temple.","architecture":"Nagara Stone.","darshan":"Historic.","seasonal":"Pleasant.","visitorNotes":"Architectural marvel.","festivals":"Shivratri.","sources":[{"label":"Umga","url":"https://aurangabad.nic.in/tourist-place/umga/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-mahpura-karu-khirhari-temple', 'shiva', 'Karu Khirhari Temple', 'Bihar', 'Mahpura', 'Saharsa district', 'Shiva / Karu Baba', 'Folk/Shaiva', '["Saint","Local Hero","Folk"]', 'Dedicated to Sant Karu Khirhari, a great devotee of Shiva and protector of cows. He is worshipped as a divine figure in the Kosi region.', 'The folk deity tradition and cow worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baba_khar_Nath_ji.jpg', 'Wikimedia Commons (Representational Saint)', 'https://commons.wikimedia.org/wiki/File:Baba_khar_Nath_ji.jpg', 'Makar Sankranti.', 'Open daily.', 'Casual.', 'On Kosi embankment.', '["Milk offering"]', '["Khirhari Puja"]', '{"history":"Folk history.","architecture":"Village shrine.","darshan":"Cultural.","seasonal":"Pleasant.","visitorNotes":"Unique regional culture.","festivals":"Shivratri.","sources":[{"label":"Saharsa","url":"https://saharsa.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-manjhaul-jaimangla-gadh', 'shiva', 'Jaimangla Gadh', 'Bihar', 'Manjhaul', 'Begusarai district', 'Jaimangla / Shiva', 'Shakta/Shaiva', '["Shakti Peeth","Bird Sanctuary","Kabartal"]', 'Located on an island in the Kabartal Lake, this temple is dedicated to Goddess Jaimangla (Durga). It features ancient Shiva shrines.', 'The location in the bird sanctuary lake.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jaimanglagarh_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AJaimanglagarh_Temple.jpg', 'Navratri/Winter.', 'Boat access.', 'Casual.', 'Inside Kabartal.', '["Navratri Puja"]', '["Navratri"]', '{"history":"Tantric Buddhism history.","architecture":"Island temple.","darshan":"Nature.","seasonal":"Winter for birds.","visitorNotes":"Combine with bird watching.","festivals":"Navratri.","sources":[{"label":"Begusarai","url":"https://begusarai.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-mehdar-mahendranath-temple', 'shiva', 'Mahendranath Temple', 'Bihar', 'Mehdar', 'Siwan district', 'Shiva', 'Shaiva', '["Nepal King","52 Bigha Pond","Clay Bells"]', 'Built by King Mahendra of Nepal, this temple is famous for its large pond and the tradition of offering clay bells.', 'The massive temple pond and hanging bells.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baba_Mahendra_Nath_Mandir_Mehdar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ABaba_Mahendra_Nath_Mandir_Mehdar.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Siwan town.', '["Bell offering"]', '["Shivratri","Sawan"]', '{"history":"17th century construction by Nepal Royals.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Crowded in Sawan.","visitorNotes":"Famous for removing skin diseases (belief).","festivals":"Shivratri.","sources":[{"label":"Siwan District","url":"https://siwan.nic.in/tourist-place/mahendra-nath-temple/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-morwa-khudneshwar-asthan', 'shiva', 'Khudneshwar Asthan', 'Bihar', 'Morwa', 'Samastipur district', 'Shiva', 'Synced', '["Communal Harmony","Khudni","Swayambhu"]', 'Named after a Muslim woman, Khudni, who discovered the Lingam. It is a unique symbol of Hindu-Muslim unity.', 'The story of Khudni Mai and the communal harmony.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Khudneshwar_Dham_Mandir.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AKhudneshwar_Dham_Mandir.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Burial site of Khudni is inside.', '["Mixed reverence"]', '["Shivratri"]', '{"history":"Discovered in 14th century (legend).","architecture":"Modern renovation.","darshan":"Unique.","seasonal":"Crowded in Sawan.","visitorNotes":"Respect the unique tradition.","festivals":"Shivratri.","sources":[{"label":"Khudneshwar Asthan","url":"https://en.wikipedia.org/wiki/Khudneshwar_Asthan","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-munger-chandika-sthan', 'shiva', 'Chandika Sthan', 'Bihar', 'Munger', 'Munger district', 'Chandika / Shiva', 'Shakta', '["Shakti Peeth","Karna","Eye Cure"]', 'A Shakti Peeth where Sati\'s eye fell. It is associated with Karna of Mahabharata. A Shiva temple ensures the balance of energies.', 'The legend of Karna worshipping here.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chandika_Asthan_at_Munger%2C_Bihar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AChandika_Asthan_at_Munger%2C_Bihar.jpg', 'Navratri.', 'Open daily.', 'Casual.', 'In Munger town.', '["Eye cure prayers"]', '["Navratri"]', '{"history":"Mahabharata era.","architecture":"Cave/Temple.","darshan":"Powerful.","seasonal":"Crowded in Navratri.","visitorNotes":"Famous for curing eye ailments.","festivals":"Navratri.","sources":[{"label":"Munger","url":"https://munger.nic.in/tourist-place/chandika-sthan/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-munger-kashtaharini-ghat-shiva-shrines', 'shiva', 'Kashtaharini Ghat Shiva Shrines', 'Bihar', 'Munger', 'Munger district', 'Shiva', 'Shaiva', '["Relief Node","Ganga Ghat","River Steps"]', 'A cluster of Shiva shrines along the Kashtaharini ghat steps, traditionally associated with relief from suffering and purification through the river-linked ritual cycle.', 'High-resolution riverbank shrine network that absorbs and grounds city devotional flow.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kashtharni_Ghat_Munger.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AKashtharni_Ghat_Munger.jpg', 'Magh Purnima, Shravan, and sunrise hours.', 'Open daily.', 'Casual.', 'On the Ganga river steps in Munger.', '["Ganga snan","Jal offering"]', '["Magh Purnima","Mahashivratri"]', '{"history":"Associated with long-standing pain-relief and purification traditions.","architecture":"Ghat-integrated shrine layout.","darshan":"River-facing and restorative.","seasonal":"Pleasant in winter and active in monsoon cycles.","visitorNotes":"Best experienced at dawn with river darshan.","festivals":"Shivratri.","sources":[{"label":"Munger","url":"https://munger.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-munger-manokamna-nath-mahadev', 'shiva', 'Manokamna Nath Mahadev', 'Bihar', 'Munger', 'Munger district', 'Shiva (Manokamna Nath)', 'Shaiva', '["Wish Fulfilling","Ganga Bank","Primary Anchor"]', 'A major Shiva shrine on the banks of the Ganga in Munger, revered as a Manokamna (wish-fulfilling) Mahadev node and a key grounding center for the district\'s riverfront sacred circuit.', 'Primary Shaivite anchor of Munger\'s urban Ganga corridor.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Shravan and Mahashivratri.', 'Open daily.', 'Modest temple attire.', 'Ganga-facing Munger urban belt.', '["Jalabhishek","Manokamna sankalpa puja"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Long-standing local riverfront worship tradition.","architecture":"Traditional urban shrine style.","darshan":"High-footfall devotional.","seasonal":"Most active in monsoon pilgrimage months.","visitorNotes":"Often paired with Kashtaharini and fort circuit visits.","festivals":"Mahashivratri.","sources":[{"label":"Munger district","url":"https://munger.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-munger-munger-fort-shiva-shrines', 'shiva', 'Munger Fort Shiva Shrines', 'Bihar', 'Munger', 'Munger district', 'Shiva', 'Shaiva', '["Fort Sentinel","High Promontory","Warrior Saint"]', 'Shiva shrines located within and around the ancient Munger Fort complex overlooking the river corridor, preserving a sturdy sentinel tradition in the district\'s fort heritage zone.', 'Strategic high-ground Shiva nodes linked to Munger\'s historic fort lineage.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'Winter and Mahashivratri.', 'Daylight hours.', 'Casual.', 'Within Munger fort heritage and river overlook area.', '["Fort-circuit darshan","Shiva puja"]', '["Mahashivratri"]', '{"history":"Fort-associated sacred nodes with layered medieval to modern use.","architecture":"Small fort shrines and stone sanctums.","darshan":"Historic and elevated.","seasonal":"Best in winter and dry months.","visitorNotes":"Combine with other Munger riverfront sacred points.","festivals":"Mahashivratri.","sources":[{"label":"Munger district","url":"https://munger.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-munger-rishikund-shiva-node', 'shiva', 'Rishikund Shiva Node', 'Bihar', 'Munger', 'Munger district', 'Shiva', 'Shaiva', '["Thermal Sync","Hot Springs","Kharagpur Hills"]', 'A geothermal Shiva site in the Kharagpur hill zone where natural hot springs and Shaiva worship combine into a distinctive thermal-synchronised pilgrimage environment.', 'One of the district\'s key hot-spring Shiva nodes for healing-oriented pilgrimage.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Historic_heritage_sites_of_Bihar_with_GPS_coordinates.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AHistoric_heritage_sites_of_Bihar_with_GPS_coordinates.jpg', 'Winter and Malmas Mela period.', 'Daylight hours.', 'Casual.', 'Remote hill location with thermal springs.', '["Holy dip"]', '["Malmas Mela"]', '{"history":"Ancient thermal pilgrimage association.","architecture":"Natural spring plus shrine setting.","darshan":"Nature-embedded and restorative.","seasonal":"Best in winter and festival windows.","visitorNotes":"Follow local safety guidance near hot springs.","festivals":"Shivratri.","sources":[{"label":"Munger Tourism","url":"https://munger.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-muzaffarpur-garib-nath-temple', 'shiva', 'Garib Nath Temple', 'Bihar', 'Muzaffarpur', 'Muzaffarpur district', 'Shiva', 'Shaiva', '["Second Deoghar","Wish Fulfilling","City"]', 'Known as the \'Second Deoghar\', this temple is the heart of Muzaffarpur. The Lingam appeared from a banyan tree.', 'The intense devotion during Sawan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shikhar_of_Garib_Nath_Mandir_Muzaffarpur.png', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AShikhar_of_Garib_Nath_Mandir_Muzaffarpur.png', 'Sawan.', 'Open daily.', 'Casual.', 'Center of town.', '["Jalabhishek"]', '["Shravani Mela","Shivratri"]', '{"history":"Discovered by a landlord cutting a Banyan tree.","architecture":"Modern temple complex.","darshan":"Crowded.","seasonal":"Sawan is peak.","visitorNotes":"Traffic can be high.","festivals":"Shivratri.","sources":[{"label":"Garib Nath","url":"https://muzaffarpur.nic.in/tourist-place/baba-garibnath-temple/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-nalanda-kundu-mahadev-nalanda-ruins-adjacent', 'shiva', 'Kundu Mahadev (Nalanda Ruins Adjacent)', 'Bihar', 'Nalanda', 'Nalanda district', 'Shiva (Kundu Mahadev)', 'Shaiva', '["Nalanda Ruins","Memory Sync","Quiet Node"]', 'A Shiva shrine in the greater Nalanda archaeological corridor, revered as a quiet contemplative node near the ancient university landscape.', 'An intellectual-heritage-linked Shaiva node in the Nalanda ruins belt.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Winter and early mornings year-round.', 'Open daily.', 'Modest temple attire.', 'Near Nalanda heritage-ruins approach zone.', '["Silent darshan","Jal offering"]', '["Mahashivratri"]', '{"history":"Part of the enduring temple layer around the ancient Nalanda region.","architecture":"Simple local shrine form.","darshan":"Meditative and low-noise.","seasonal":"Comfortable in winter.","visitorNotes":"Can be combined with Nalanda archaeological circuit visits.","festivals":"Mahashivratri.","sources":[{"label":"Nalanda","url":"https://en.wikipedia.org/wiki/Nalanda","type":"Encyclopedia"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-nauhatta-dasshisha-nath-mahadev', 'shiva', 'Dasshisha Nath Mahadev', 'Bihar', 'Nauhatta', 'Rohtas district', 'Shiva', 'Shaiva', '["Ravana","Son River","Submerged"]', 'Located in the middle of the Son River, believed to be established by Ravana. The Lingam remains submerged for 8 months a year.', 'The unique location inside the river.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bateshwar_Sthan.jpg', 'Wikimedia Commons (Representational River)', 'https://commons.wikimedia.org/wiki/File:Bateshwar_Sthan.jpg', 'Summer (when water is low).', 'Seasonal access.', 'Casual.', 'Accessible when river is low.', '["River water offering"]', '["Shivratri"]', '{"history":"Mythological Ravana connection.","architecture":"Island shrine.","darshan":"Unique.","seasonal":"Inaccessible in monsoon.","visitorNotes":"Check water levels.","festivals":"Shivratri.","sources":[{"label":"Rohtas","url":"https://rohtas.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-nawada-shobhnath-temple', 'shiva', 'Shobhnath Temple', 'Bihar', 'Nawada', 'Nawada district', 'Shiva', 'Shaiva', '["Sobhiya","City Temple","Panchmukhi"]', 'An important Shiva temple in Nawada town, known for its spiritual ambiance and rituals.', 'The central role in Nawada\'s religious life.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ashokdham_Temple_Main.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Ashokdham_Temple_Main.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'In Nawada town.', '["Daily Aarti"]', '["Shivratri"]', '{"history":"Local history.","architecture":"Modern.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Heart of the town.","festivals":"Shivratri.","sources":[{"label":"Nawada","url":"https://nawada.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-patna-badi-patan-devi', 'shiva', 'Badi Patan Devi', 'Bihar', 'Patna', 'Patna district', 'Patan Devi / Bhairav', 'Shakta', '["City Deity","Shakti Peeth","Bhairav"]', 'One of the oldest and most sacred temples in Patna, considered the presiding deity of the city. It houses a Bhairav (Shiva) idol.', 'The history of Patna (Pataliputra) tied to this temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pretshila_Hill_Gaya.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Pretshila_Hill_Gaya.jpg', 'Navratri.', 'Open daily.', 'Casual.', 'In Patna City.', '["Navratri Puja"]', '["Navratri"]', '{"history":"Ancient Pataliputra era.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Very crowded in Navratri.","visitorNotes":"Guardian deity of Patna.","festivals":"Navratri.","sources":[{"label":"Patan Devi","url":"https://patna.nic.in/tourist-place/patan-devi/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-patna-chhoti-patan-devi', 'shiva', 'Chhoti Patan Devi', 'Bihar', 'Patna', 'Patna district', 'Devi / Shiva', 'Shakta', '["Sati","Clothes","Local"]', 'Located near the Badi Patan Devi, this temple is where Sati\'s clothes (Pat) are believed to have fallen. It has an active Shiva shrine.', 'The intimate and powerful atmosphere.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chhoti_Patandevi_during_Durga_Puja.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AChhoti_Patandevi_during_Durga_Puja.jpg', 'Navratri.', 'Open daily.', 'Casual.', 'Patna City.', '["Daily Aarti"]', '["Navratri"]', '{"history":"Ancient.","architecture":"House style.","darshan":"Devotional.","seasonal":"Crowded.","visitorNotes":"Less crowded than Badi Patan Devi.","festivals":"Navratri.","sources":[{"label":"Patna Tourism","url":"https://patna.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-paunra-mundeshwari-devi-temple', 'shiva', 'Mundeshwari Devi Temple', 'Bihar', 'Paunra', 'Kaimur district', 'Shiva & Shakti', 'Shaiva/Shakta', '["Oldest Functional","Octagonal","ASI Protected"]', 'Considered the oldest functional Hindu temple in the world, dating back to 108 AD. It is dedicated to Shiva (Mandaleshwar) and Shakti (Mundeshwari).', 'The unique octagonal plan and the Chaturmukha Shivlinga.', 'https://commons.wikimedia.org/wiki/Special:FilePath/IMG20200317101053_Mundeshwari_Dham.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AIMG20200317101053_Mundeshwari_Dham.jpg', 'Ramnavami/Shivratri.', 'Sunrise to Sunset.', 'Casual.', 'Located on Mundeshwari Hill.', '["Daily worship","Animal sacrifice (Satvik - no killing)"]', '["Ramnavami","Shivratri"]', '{"history":"Built in 108 AD (Saka era) as per inscriptions.","architecture":"Nagara style (Octagonal).","darshan":"Historic.","seasonal":"Pleasant.","visitorNotes":"A must-visit for history buffs.","festivals":"Ramnavami Mela.","sources":[{"label":"Mundeshwari Temple","url":"https://en.wikipedia.org/wiki/Mundeshwari_Temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-rahika-kapileshwar-sthan', 'shiva', 'Kapileshwar Sthan', 'Bihar', 'Rahika', 'Madhubani district', 'Shiva', 'Shaiva', '["Sage Kapila","Mithila","Pond"]', 'Believed to be the hermitage of Sage Kapila, who established the Shiva Lingam here. It is a major center of faith in Mithila.', 'The large temple pond and the connection to Sage Kapila.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kapileshwar_Sthan.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kapileshwar_Sthan.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Madhubani town.', '["Jalabhishek"]', '["Shivratri Mela"]', '{"history":"Ancient Puranic roots.","architecture":"Maithil style.","darshan":"Devotional.","seasonal":"Crowded in Sawan.","visitorNotes":"Peaceful atmosphere.","festivals":"Shivratri.","sources":[{"label":"Kapileshwar","url":"https://madhubani.nic.in/tourist-place/kapileshwar-sthan/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-rajgir-maniyamath-shiva-temple-rajgir', 'shiva', 'Maniyamath Shiva Temple (Rajgir)', 'Bihar', 'Rajgir', 'Nalanda district', 'Shiva (Maniyamath/Maniyar tradition)', 'Shaiva', '["Octagonal Plan","Rajgir Valley","Geometric Node"]', 'Associated with the historic Maniyar Math zone of Rajgir, this Shiva-linked node is part of the seven-hill valley sacred corridor and is treated as a key geometric anchor in the district.', 'A high-importance Rajgir anchor in the southern Nalanda spiritual corridor.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Maniyar_Math%2C_Rajgir%2C_Bihar_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AManiyar_Math%2C_Rajgir%2C_Bihar_01.jpg', 'Winter and Rajgir pilgrimage season.', 'Sunrise to Sunset.', 'Casual.', 'In the Rajgir heritage zone.', '["Shiva darshan","Meditative prayer"]', '["Mahashivratri","Rajgir Mahotsav period visits"]', '{"history":"Ancient Rajgir sacred geography with layered ritual traditions.","architecture":"Rare geometric/circular-octagonal legacy form.","darshan":"Historic and contemplative.","seasonal":"Pleasant in winter.","visitorNotes":"Best visited with other Rajgir hill and hot-spring temples.","festivals":"Mahashivratri.","sources":[{"label":"Rajgir","url":"https://en.wikipedia.org/wiki/Rajgir","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-rajgir-venu-van-shiva-shrines', 'shiva', 'Venu Van Shiva Shrines', 'Bihar', 'Rajgir', 'Nalanda district', 'Shiva', 'Shaiva', '["Bamboo Grove","Bio Resonance","Brahmkund"]', 'A group of Shiva shrines in the Venu Van-Rajgir sacred ecology where vegetation cover and nearby thermal spring zones create a distinctive bio-thermal devotional atmosphere.', 'A unique Rajgir Shiva cluster linked with bamboo grove and hot-spring energy.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Winter and early morning visits.', 'Open daily.', 'Modest temple attire.', 'In the Venu Van-Rajgir pilgrimage zone near hot springs.', '["Jalabhishek","Meditative prayer"]', '["Mahashivratri","Shravan month"]', '{"history":"Part of the layered Rajgir sacred landscape across traditions.","architecture":"Mixed small-shrine typology in a garden/forest setting.","darshan":"Nature-integrated and calm.","seasonal":"Most comfortable in winter; active year-round.","visitorNotes":"Often combined with Brahmkund and Rajgir hill circuit.","festivals":"Mahashivratri.","sources":[{"label":"Rajgir","url":"https://en.wikipedia.org/wiki/Rajgir","type":"Encyclopedia"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-rajnagar-rajnagar-shiva-temple', 'shiva', 'Rajnagar Shiva Temple', 'Bihar', 'Rajnagar', 'Madhubani district', 'Shiva', 'Shaiva', '["Palace Complex","Ruins","Heritage"]', 'Located inside the Rajnagar Palace complex built by Maharaja Rameshwar Singh. The temple survived the 1934 earthquake which destroyed much of the palace.', 'The association with the Raj Darbhanga and the palace ruins.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Temple_at_Rajnagar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AShiva_Temple_at_Rajnagar.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Inside Rajnagar Palace ruins.', '["Royal family traditions"]', '["Shivratri"]', '{"history":"Built by Maharaja Rameshwar Singh (20th Century).","architecture":"Indo-Saracenic mix.","darshan":"Historic.","seasonal":"Winter is best.","visitorNotes":"Explore the palace ruins too.","festivals":"Shivratri.","sources":[{"label":"Rajnagar","url":"https://en.wikipedia.org/wiki/Rajnagar_Bihar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-ramgarh-baidyanath-temple-kaimur', 'shiva', 'Baidyanath Temple Kaimur', 'Bihar', 'Ramgarh', 'Kaimur district', 'Shiva', 'Shaiva', '["Pratihar Style","Octagonal","Heritage"]', 'An ancient temple built by the Pratihar dynasty, known for its unique octagonal architecture similar to Khajuraho styles.', 'The intricate stone carvings and historical value.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational Ancient)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Winter.', 'Open daily.', 'Casual.', 'ASI protected site.', '["Visiting"]', '["Shivratri"]', '{"history":"Pratihar dynasty.","architecture":"Nagara style.","darshan":"Historic.","seasonal":"Pleasant.","visitorNotes":"For history lovers.","festivals":"Shivratri.","sources":[{"label":"Kaimur History","url":"https://kaimur.nic.in/history/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-ramnagar-shiv-mandir-ramnagar', 'shiva', 'Shiv Mandir Ramnagar', 'Bihar', 'Ramnagar', 'West Champaran', 'Shiva', 'Shaiva', '["Historical","Architecture","Town Temple"]', 'The most famous temple in Ramnagar, known for its splendid architecture and long-standing presence.', 'The intricate interior and outer structure.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiv_Mandir_Ramnagar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AShiv_Mandir_Ramnagar.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Center of Ramnagar.', '["Daily Puja"]', '["Shivratri"]', '{"history":"Historical.","architecture":"North Indian.","darshan":"Local.","seasonal":"Pleasant.","visitorNotes":"A key landmark in Ramnagar.","festivals":"Shivratri.","sources":[{"label":"Ramnagar","url":"https://en.wikipedia.org/wiki/Ramnagar,_West_Champaran","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-rohtas-chaurasan-temple', 'shiva', 'Chaurasan Temple', 'Bihar', 'Rohtas', 'Rohtas district', 'Shiva', 'Shaiva', '["84 Steps","King Harishchandra","Hill"]', 'Famous for the 84 steps (Chaurasi) leading to it. It is associated with King Harishchandra and Rohitashwa.', 'The climb of 84 steps and the view.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chaurasan_temple%2C_Rohtas.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AChaurasan_temple%2C_Rohtas.jpg', 'Shivratri.', 'Open daily.', 'Casual/Active wear.', 'Steep stairs.', '["Climbing"]', '["Shivratri"]', '{"history":"Ancient legends.","architecture":"Hill temple.","darshan":"Adventure.","seasonal":"Winter.","visitorNotes":"Physical climb involved.","festivals":"Shivratri.","sources":[{"label":"Rohtas Tourism","url":"https://rohtas.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-rohtasgarh-fort-rohtasgarh-fort-shiva-shrines', 'shiva', 'Rohtasgarh Fort Shiva Shrines', 'Bihar', 'Rohtasgarh Fort', 'Rohtas district', 'Shiva', 'Shaiva', '["Fort Plateau","Sentinel Nodes","High Altitude"]', 'A cluster of Shiva shrines within the massive Rohtasgarh Fort complex, positioned on a high plateau above the Sone valley. These act as historic sentinel nodes in the district\'s hill-fort sacred landscape.', 'Strategic high-altitude Shaiva shrines inside one of India\'s largest forts.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Temple_-_Rohtasgarh_Fort.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AShiva_Temple_-_Rohtasgarh_Fort.jpg', 'Winter.', 'Sunrise to Sunset.', 'Casual.', 'Requires trekking/vehicle to fort.', '["Visiting"]', '["Shivratri"]', '{"history":"Medieval-era fort shrine tradition with older regional roots.","architecture":"Stone temple.","darshan":"Historic and panoramic.","seasonal":"Best in winter and dry months.","visitorNotes":"Plan as a full fort circuit visit.","festivals":"Shivratri.","sources":[{"label":"Rohtasgarh","url":"https://en.wikipedia.org/wiki/Rohtasgarh_Fort","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-saharsa-matsyagandha-mandir', 'shiva', 'Matsyagandha Mandir', 'Bihar', 'Saharsa', 'Saharsa district', 'Ugra Tara / Shiva', 'Tantric', '["Lake","Tantric","Park"]', 'A modern temple complex located near a lake (Rakt Kali). It features the 64 Yogini temple and a Shiva temple.', 'The beautiful architecture and the lake.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mundeshwari_Temple.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Mundeshwari_Temple.jpg', 'Navratri.', 'Open daily.', 'Casual.', 'In Saharsa town.', '["Tantric worship"]', '["Navratri"]', '{"history":"Modern construction.","architecture":"Grand style.","darshan":"Grand.","seasonal":"Pleasant.","visitorNotes":"Good for evening visit.","festivals":"Navratri.","sources":[{"label":"Saharsa","url":"https://saharsa.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sarmera-siddheshwar-nath-sarmera', 'shiva', 'Siddheshwar Nath (Sarmera)', 'Bihar', 'Sarmera', 'Nalanda district', 'Shiva (Siddheshwar Nath)', 'Shaiva', '["Rural Plains","Attainment Node","Agrarian Grid"]', 'A major rural Shiva temple serving the eastern plains of Nalanda, known as a stable devotional center for village and farming communities.', 'A steady eastern Nalanda anchor with strong local worship continuity.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Shravan and Shivratri.', 'Open daily.', 'Modest temple attire.', 'In Sarmera block area.', '["Jalabhishek","Somvar puja"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Sustained through long-running local Shaiva worship.","architecture":"Traditional rural shrine structure.","darshan":"Community-centered.","seasonal":"Peak visits during monsoon pilgrimage months.","visitorNotes":"Important local temple for nearby village clusters.","festivals":"Mahashivratri.","sources":[{"label":"Nalanda district","url":"https://nalanda.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sasaram-pilot-baba-somnath-temple-complex', 'shiva', 'Pilot Baba Somnath Temple Complex', 'Bihar', 'Sasaram', 'Rohtas district', 'Shiva (Somnath)', 'Shaiva', '["Somnath Complex","Urban Anchor","NH-2 Corridor"]', 'A major modern-era Shaiva complex in Sasaram whose central Somnath shrine functions as a high-visibility urban devotional center for the district.', 'Large-scale Shiva complex serving as a key Sasaram city pilgrimage point.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Mahashivratri and Shravan month.', 'Open daily.', 'Modest temple attire.', 'In/near Sasaram urban area.', '["Daily aarti","Jalabhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Contemporary large temple complex with active local patronage.","architecture":"Modern temple complex.","darshan":"High-footfall urban darshan.","seasonal":"Most crowded during Shivratri and monsoon pilgrimage cycles.","visitorNotes":"Can be combined with Sasaram heritage sites in one route.","festivals":"Mahashivratri.","sources":[{"label":"Rohtas district","url":"https://rohtas.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-saurath-madhaweshwar-nath-mahadev', 'shiva', 'Madhaweshwar Nath Mahadev', 'Bihar', 'Saurath', 'Madhubani district', 'Shiva', 'Shaiva/Maithil', '["Saurath Sabha","Marriage Market","Historic"]', 'Located in the historic Saurath Sabha Gachhi, famous for the annual gathering of Maithil Brahmins for marriage negotiations. The temple is central to this tradition.', 'The connection to the unique Saurath Sabha tradition.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Saurath_Sabha-17.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ASaurath_Sabha-17.jpg', 'Sabha Season (June).', 'Open daily.', 'Casual.', 'Near Madhubani.', '["Vivah Sankalp"]', '["Saurath Sabha"]', '{"history":"Ancient social tradition.","architecture":"Maithil style.","darshan":"Cultural.","seasonal":"Crowded during Sabha.","visitorNotes":"Unique cultural experience.","festivals":"Shivratri.","sources":[{"label":"Saurath","url":"https://en.wikipedia.org/wiki/Saurath","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sheikhpura-girihinda-shiv-mandir', 'shiva', 'Girihinda Shiv Mandir', 'Bihar', 'Sheikhpura', 'Sheikhpura district', 'Shiva', 'Shaiva', '["Hill Top","Panoramic View","Peace"]', 'Located on the Girihinda hill, this Shiva temple offers a stunning view of the surrounding town and fields.', 'The hilltop view and the serene temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mandar_Hill.jpg', 'Wikimedia Commons (Representational Hill)', 'https://commons.wikimedia.org/wiki/File:Mandar_Hill.jpg', 'Winter.', 'Sunrise to Sunset.', 'Casual.', 'Requires climb/vehicle.', '["Meditation"]', '["Shivratri"]', '{"history":"Local heritage.","architecture":"Hill temple.","darshan":"Scenic.","seasonal":"Pleasant.","visitorNotes":"Great picnic spot.","festivals":"Shivratri.","sources":[{"label":"Sheikhpura","url":"https://sheikhpura.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-simaria-simaria-ghat-temple', 'shiva', 'Simaria Ghat Temple', 'Bihar', 'Simaria', 'Begusarai district', 'Shiva', 'Shaiva', '["Kumbh Sthal","Ganga","Dinkar"]', 'Simaria Ghat is a major pilgrimage site known as the birthplace of poet Ramdhari Singh Dinkar. It hosts a Kalpvas and is considered a \'Mini Kumbh\'.', 'The vibrant devout atmosphere at the Ghat.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Budhanath_Temple_Bhagalpur.jpg', 'Wikimedia Commons (Representational Ghat)', 'https://commons.wikimedia.org/wiki/File:Budhanath_Temple_Bhagalpur.jpg', 'Kartik (Kalpvas).', 'Open daily.', 'Casual.', 'Near Rajendra Bridge.', '["Ganga Snan","Kalpvas"]', '["Kartik Mela","Kumbh (Ardh)"]', '{"history":"Ancient river crossing.","architecture":"Ghat temples.","darshan":"Devotional.","seasonal":"Crowded in Kartik.","visitorNotes":"A center of Mithila culture.","festivals":"Shivratri.","sources":[{"label":"Begusarai","url":"https://begusarai.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-singheshwar-singheshwar-sthan', 'shiva', 'Singheshwar Sthan', 'Bihar', 'Singheshwar', 'Madhepura district', 'Shiva', 'Shaiva', '["Rishya Sringa","Maha Kumbh","Mythology"]', 'Associated with Sage Rishya Sringa who performed the Putrakameshti Yagna for Dasharatha. It is a major pilgrimage center in Mithila.', 'The ancient Lingam and the association with Ramayana.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Madhepura-Singheswar_Sthan_Mandir-1.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AMadhepura-Singheswar_Sthan_Mandir-1.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Madhepura.', '["Yagna","Puja"]', '["Shivratri Mela"]', '{"history":"Vedic era connections.","architecture":"Traditional.","darshan":"Mythological.","seasonal":"Huge fair during Shivratri.","visitorNotes":"The heart of Madhepura\'s culture.","festivals":"Shivratri.","sources":[{"label":"Singheshwar Sthan","url":"https://en.wikipedia.org/wiki/Singheshwar_Sthan","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sitamarhi-haleshwar-sthan', 'shiva', 'Haleshwar Sthan', 'Bihar', 'Sitamarhi', 'Sitamarhi district', 'Shiva', 'Shaiva', '["King Videha","Mithila","Mundan"]', 'An ancient temple believed to have been established by King Videha (Janaka). It founded the Haleshwar Nath Mahadev.', 'The connection to the Videha kingdom.', 'https://commons.wikimedia.org/wiki/Special:FilePath/An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:An_old_Temple_dedicated_to_the_Lord_Shiva(_Haleswar_Mandir).jpg', 'Sawan.', 'Open daily.', 'Casual.', 'Near Sitamarhi.', '["Mundan ceremony"]', '["Sawan Mela"]', '{"history":"Vedic period association.","architecture":"Ancient structures.","darshan":"Mythological.","seasonal":"Sawan is best.","visitorNotes":"Near Punaura Dham.","festivals":"Shivratri.","sources":[{"label":"Sitamarhi Tourism","url":"https://sitamarhi.nic.in/tourist-place/haleshwar-sthan/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sitamarhi-panth-pakar', 'shiva', 'Panth Pakar', 'Bihar', 'Sitamarhi', 'Sitamarhi district', 'Shiva / Nature', 'Folk/Shaiva', '["Banyan Tree","Palanquin","Ramayana"]', 'Associated with the marriage procession of Lord Rama. An ancient banyan tree is the focus, with Shiva shrines underneath.', 'The ancient banyan tree and the legend.', 'https://commons.wikimedia.org/wiki/Special:FilePath/An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:An_old_Temple_dedicated_to_the_Lord_Shiva(_Haleswar_Mandir).jpg', 'Vivah Panchami.', 'Open daily.', 'Casual.', 'Natural site.', '["Tree worship"]', '["Vivah Panchami"]', '{"history":"Ramayana legend.","architecture":"Open air.","darshan":"Nature.","seasonal":"Pleasant.","visitorNotes":"Unique natural shrine.","festivals":"Shivratri.","sources":[{"label":"Sitamarhi","url":"https://sitamarhi.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sitamarhi-punaura-dham', 'shiva', 'Punaura Dham', 'Bihar', 'Sitamarhi', 'Sitamarhi district', 'Shiva & Sita', 'Vaishnava/Shaiva', '["Janaki Birthplace","Ramayana","Shiva Shrine"]', 'The birthplace of Goddess Sita. While primarily dedicated to Janaki, it houses ancient Shiva shrines worshipped by the royal family of Mithila.', 'The birthplace of Sita and the temple tank.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Punaura_Dham.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3APunaura_Dham.jpg', 'Janaki Navami.', 'Open daily.', 'Casual.', 'Near Sitamarhi town.', '["Janaki Puja"]', '["Janaki Navami","Vivah Panchami"]', '{"history":"Mythological.","architecture":"Mithila style.","darshan":"Divine.","seasonal":"Crowded on events.","visitorNotes":"Main pilgrimage in Sitamarhi.","festivals":"Shivratri.","sources":[{"label":"Punaura Dham","url":"https://sitamarhi.nic.in/tourist-place/punaura-dham/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sonpur-harihar-nath-temple', 'shiva', 'Harihar Nath Temple', 'Bihar', 'Sonpur', 'Saran district', 'Harihar (Shiva-Vishnu)', 'Smarta/Shaiva', '["Confluence Titan","Harihar Fusion","Ganga-Gandak"]', 'A major fusion shrine at the Gandak-Ganga confluence where Hari (Vishnu) and Hara (Shiva) are worshipped in one form, making it a powerful signal-combiner in the North Bihar sacred river grid.', 'Rare Hari-Hara combined worship at one of the most energetic river confluences in the region.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hariharnath_temple%2C_Sonepur._%285448166304%29.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AHariharnath_temple%2C_Sonepur._%285448166304%29.jpg', 'Kartik Purnima (Nov).', 'Open daily.', 'Casual.', 'At Sonpur confluence; closely linked to Vaishali-Saran pilgrimage movement.', '["Gajendra Moksha recitation"]', '["Sonpur Mela","Kartik Purnima"]', '{"history":"Ancient confluence shrine with strong medieval and early-modern patronage layers.","architecture":"Hindu Temple style.","darshan":"High-footfall confluence darshan.","seasonal":"Best during the fair.","visitorNotes":"Best visited with the Sonpur-Kaun Haara Ghat confluence circuit.","festivals":"Kartik Purnima.","sources":[{"label":"Harihar Nath","url":"https://en.wikipedia.org/wiki/Sonepur_Cattle_Fair","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sultanganj-ajgaibinath-temple', 'shiva', 'Ajgaibinath Temple', 'Bihar', 'Sultanganj', 'Bhagalpur district', 'Shiva', 'Shaiva', '["Hydro Granitic","Shravani Source Node","Granite Rock Island"]', 'Built on a massive granite outcrop rising from the Ganga at Sultanganj, Ajgaibinath is the source node of the Shravani Mela route where pilgrims collect water before the Deoghar Kanwar yatra.', 'The district\'s premier hydro-granitic Shiva anchor and Shravani pilgrimage origin point.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ajgaibinath_temple_Day-View.png', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3AAjgaibinath_temple_Day-View.png', 'Shravan (July-Aug) and Mahashivratri.', 'Open daily.', 'Casual.', 'Accessible by boat.', '["Jalabhishek","Kanwar collection"]', '["Shravani Mela"]', '{"history":"Ancient river-island shrine with long-standing Kanwar pilgrimage significance.","architecture":"Temple over natural granite river rock.","darshan":"High-energy river darshan.","seasonal":"Crowded in Shravan.","visitorNotes":"Primary water-collection point for the Sultanganj to Deoghar pilgrimage corridor.","festivals":"Shravani Mela.","sources":[{"label":"Ajgaibinath","url":"https://en.wikipedia.org/wiki/Sultanganj","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-sunari-sunari-shiva-temple', 'shiva', 'Sunari Shiva Temple', 'Bihar', 'Sunari', 'Nalanda district', 'Shiva', 'Shaiva', '["Rural Anchor","Ancient Lingam","Village Router"]', 'A longstanding village Shiva temple with a weathered lingam and strong local continuity across life-cycle and seasonal agrarian rituals.', 'A stable spiritual hub for surrounding Nalanda villages.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'Shravan and harvest-season observances.', 'Open daily.', 'Modest temple attire.', 'In rural Nalanda sector.', '["Village puja","Jalabhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Maintained through local hereditary and community worship systems.","architecture":"Traditional rural temple layout.","darshan":"Grounded and community-driven.","seasonal":"Most active in monsoon and post-harvest periods.","visitorNotes":"Important for local annual ritual cycles.","festivals":"Mahashivratri.","sources":[{"label":"Nalanda district","url":"https://nalanda.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-tarapur-dakshineswar-mahadev-tarapur', 'shiva', 'Dakshineswar Mahadev (Tarapur)', 'Bihar', 'Tarapur', 'Munger district', 'Shiva (Dakshineswar Mahadev)', 'Shaiva', '["Rural Anchor","Tarapur Sector","Hill Plains Transition"]', 'A steady rural Shiva node in the Tarapur belt that supports ritual continuity across the transition between hill terrain and agricultural plains.', 'Baseline Shaivite stabilizer for southern Munger villages.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Shravan and Shivratri.', 'Open daily.', 'Modest temple attire.', 'In Tarapur rural sub-grid.', '["Somvar worship","Village jalabhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Maintained through local village devotional traditions.","architecture":"Traditional rural shrine form.","darshan":"Grounded and rhythmic.","seasonal":"Most active in monsoon pilgrimage cycles.","visitorNotes":"Useful addition to the southern Munger temple route.","festivals":"Mahashivratri.","sources":[{"label":"Munger district","url":"https://munger.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-thakurganj-harugauri-temple', 'shiva', 'Harugauri Temple', 'Bihar', 'Thakurganj', 'Kishanganj district', 'Harugauri (Shiva-Parvati)', 'Shaiva', '["Composite Deity","Border","Heritage"]', 'A temple dedicated to the combined form of Shiva and Parvati (Harugauri), located near the Nepal/West Bengal border.', 'The unique Harugauri idol.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chaturmukha_Shiva_Linga_at_Vaishali_Museum.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Chaturmukha_Shiva_Linga_at_Vaishali_Museum.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Remote location.', '["Mixed Puja"]', '["Shivratri"]', '{"history":"Local heritage.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Border region culture.","festivals":"Shivratri.","sources":[{"label":"Kishanganj","url":"https://kishanganj.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-tutla-bhawani-tutla-bhawani-shiva-node', 'shiva', 'Tutla Bhawani Shiva Node', 'Bihar', 'Tutla Bhawani', 'Rohtas district', 'Shiva (with Bhawani tradition)', 'Shaiva/Shakta', '["Waterfall Shrine","Hydro Acoustic","Canyon Setting"]', 'A Shiva-linked shrine zone near the Tutla Bhawani waterfall where continuous water flow, mist, and canyon acoustics shape a strong hydro-acoustic devotional setting.', 'A waterfall-linked Shiva-Shakti pilgrimage node in the Rohtas hills.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'Post-monsoon and winter.', 'Daylight hours.', 'Casual/trek-friendly attire.', 'Waterfall approach route; terrain can be slippery.', '["Jal offering","Nature-linked prayer"]', '["Mahashivratri","Navratri"]', '{"history":"Long-standing local hill and waterfall worship tradition.","architecture":"Natural setting with shrine structures.","darshan":"Nature-interface pilgrimage.","seasonal":"Most vibrant around monsoon and post-monsoon flow.","visitorNotes":"Use caution during heavy rain days.","festivals":"Shivratri and Navratri observances.","sources":[{"label":"Tutla Bhawani","url":"https://rohtas.nic.in/tourist-place/tutla-bhawani/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-bihar-umanath-gauri-shankar-temple-umanath', 'shiva', 'Gauri Shankar Temple (Umanath)', 'Bihar', 'Umanath', 'Buxar district', 'Gauri-Shankar', 'Shaiva', '["Ganga High Bank","Gauri Shankar","Dual Resonance"]', 'A Shiva-Shakti shrine on the higher bank corridor of the Ganga, revered as a stabilizing Gauri-Shankar node in the Buxar-Arrah belt.', 'Balanced Shiva-Shakti worship with strong riverbank devotional culture.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Shivratri and Kartik period.', 'Open daily.', 'Modest temple attire.', 'In the Umanath area of Buxar district.', '["Shiva-Parvati puja","Jal offering"]', '["Mahashivratri","Sawan month observances"]', '{"history":"Local riverbank Shaiva-Shakti tradition.","architecture":"Traditional mandir layout.","darshan":"Calm, devotional, and family-oriented.","seasonal":"Pleasant in winter and during post-monsoon months.","visitorNotes":"Often visited with other Buxar Ganga ghat temples.","festivals":"Mahashivratri.","sources":[{"label":"Buxar district","url":"https://buxar.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
