INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-alor-lingeshwar-mahadev-alor', 'shiva', 'Lingeshwar Mahadev (Alor)', 'Chhattisgarh', 'Alor', 'Kondagaon district', 'Shiva (Lingeshwar Mahadev, naturally formed lingam tradition)', 'Shaiva', '["Lingeshwar","Alor","Cave Node"]', 'Lingeshwar Mahadev at Alor is a highly shielded cave-based Shiva node, traditionally opened to the public only during a specific annual post-Diwali window.', 'Subterranean annual-access anomaly with concentrated cave-shielded resonance.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Seasonal annual opening period; otherwise local access is limited.', 'Special opening windows apply; verify locally before travel.', 'Modest attire with cave-friendly footwear.', 'Access is typically restricted outside the annual opening event.', '["Special annual darshan","Abhishekam"]', '["Post-Diwali annual opening","Mahashivratri"]', '{"history":"Local tradition preserves this site as a rare annual-access cave shrine with naturally formed lingam worship continuity.","architecture":"Natural cave-chamber shrine with strong earth-shielded acoustics.","visitorNotes":"Confirm schedule and entry rules before planning a visit.","sources":[{"label":"Kondagaon district","url":"https://en.wikipedia.org/wiki/Kondagaon_district","type":"Encyclopedia"}]}', '2026-02-25T16:29:42+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-ambikapur-patalbhairav-mahadev-ambikapur', 'shiva', 'Patalbhairav Mahadev (Ambikapur)', 'Chhattisgarh', 'Ambikapur', 'Ambikapur urban grid, Surguja district', 'Shiva (Patalbhairav Mahadev)', 'Shaiva', '["Patalbhairav","Subterranean","Ambikapur"]', 'Patalbhairav Mahadev in Ambikapur is a below-surface Shiva node with a deep subterranean sanctum profile and a strong earth-shielded ritual setting.', 'Subterranean Patal-resonance anchor for the Ambikapur city sector.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'October to March.', 'Open daily; local timings vary.', 'Modest attire.', 'Inner approach can be compact; mornings are generally easier for darshan.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Maintained as a key Ambikapur Shaiva node in the wider Surguja devotional landscape.","architecture":"Sub-ground sanctum orientation with compact temple circulation.","visitorNotes":"Best visited in daylight, especially on festival weeks.","sources":[{"label":"Ambikapur, Chhattisgarh","url":"https://en.wikipedia.org/wiki/Ambikapur,_Chhattisgarh","type":"Encyclopedia"},{"label":"Surguja district","url":"https://en.wikipedia.org/wiki/Surguja_district","type":"Encyclopedia"}]}', '2026-02-25T16:23:11+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-amodipara-amodipara-shiva-temple', 'shiva', 'Amodipara Shiva Temple', 'Chhattisgarh', 'Amodipara', 'Bastar region', 'Shiva', 'Shaiva', '["Amodipara","Shiva","Local temple"]', 'Amodipara Shiva Temple is part of Bastar\'s local network of active Shiva worship spaces.', 'Amodipara neighborhood Shiva shrine.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'Year-round.', 'Open daily; local timings vary.', 'Modest attire.', 'Best visited in daytime for easier local navigation.', '["Daily puja"]', '["Mahashivratri","Shravan month"]', '{"history":"Continues the local Shaiva worship stream in the Bastar region.","architecture":"Small regional shrine profile.","visitorNotes":"Expect local queues on Mondays.","sources":[{"label":"Bastar district","url":"https://en.wikipedia.org/wiki/Bastar_district","type":"Encyclopedia"}]}', '2026-02-23T16:48:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-antagarh-charre-marre-waterfall-shrines', 'shiva', 'Charre-Marre Waterfall Shrines', 'Chhattisgarh', 'Antagarh', 'Antagarh block, Kanker district', 'Shiva (waterfall lingam shrines)', 'Shaiva', '["Charre-Marre","Waterfall Shrines","Jogidhara Stream"]', 'Charre-Marre waterfall shrines in the Antagarh block are nature-interface Shiva nodes where lingams sit along the Jogidhara stream cascade over rock beds.', 'Continuous natural acoustic-resonance shrine points in the Charre-Marre falls corridor.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'July to February.', 'Open daily; access varies by weather.', 'Modest attire with non-slip footwear.', 'Waterfall surfaces are slippery; caution needed in monsoon.', '["Jal abhishek","Local puja"]', '["Mahashivratri","Shravan month"]', '{"history":"These shrines are maintained through local stream-linked Shaiva worship traditions in Antagarh.","architecture":"Rock-water integrated micro-shrine forms in a natural cascade setting.","visitorNotes":"Visit in daylight and avoid high-flow hazard windows.","sources":[{"label":"Antagarh","url":"https://en.wikipedia.org/wiki/Antagarh","type":"Encyclopedia"},{"label":"Kanker district","url":"https://en.wikipedia.org/wiki/Kanker_district","type":"Encyclopedia"}]}', '2026-02-25T16:26:53+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-bailadila-belt-phoolpad-waterfall-shiva-node', 'shiva', 'Phoolpad Waterfall Shiva Node', 'Chhattisgarh', 'Bailadila belt', 'Dantewada district', 'Shiva', 'Shaiva', '["Phoolpad","Waterfall Node","Bailadila"]', 'Phoolpad Waterfall Shiva Node is an isolated nature-interface shrine in the Bailadila mountain influence zone where waterfall cooling meets mineral-rich highland terrain.', 'Ultra-isolated hydro-cooled Shiva node in the southern Dantewada mountainscape.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'July to February.', 'Open daily; access varies seasonally.', 'Modest attire with non-slip footwear.', 'Travel conditions can be rugged; local guidance is recommended.', '["Jal abhishek","Local puja"]', '["Mahashivratri","Shravan month"]', '{"history":"Maintained in local worship memory as a raw waterfall-linked Shiva point in the southern highland corridor.","architecture":"Minimal natural-rock shrine configuration integrated with cascade flow.","visitorNotes":"Avoid peak monsoon hazard windows and plan daylight visits.","sources":[{"label":"Dantewada district","url":"https://en.wikipedia.org/wiki/Dantewada_district","type":"Encyclopedia"},{"label":"Bailadila Range","url":"https://en.wikipedia.org/wiki/Bailadila_Range","type":"Encyclopedia"}]}', '2026-02-25T16:32:23+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-barsur-battisa-temple-barsur', 'shiva', 'Battisa Temple (Barsur)', 'Chhattisgarh', 'Barsur', 'Barsur, Dantewada district', 'Shiva', 'Shaiva', '["Battisa","32 Pillars","Dual Lingams"]', 'Battisa Temple at Barsur is a rare flat-roofed 32-pillar Shiva shrine that houses twin large lingams on a shared platform, creating a distinctive dual-resonance ritual geometry.', 'Unique dual-lingam structural anchor of the Barsur archaeological grid.', 'https://commons.wikimedia.org/wiki/Special:FilePath/012_01_2022_Barsur_Battisa_Temple_Chattisgarh_016.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:012_01_2022_Barsur_Battisa_Temple_Chattisgarh_016.jpg', 'October to February.', 'Open daily; local timings vary.', 'Modest attire.', 'Carry water and plan daytime travel for heritage visits.', '["Local puja observances"]', '["Mahashivratri"]', '{"history":"Barsur\'s temple matrix is one of the densest medieval Shaiva landscapes in southern Chhattisgarh, and Battisa is a core structural node within it.","architecture":"Flat-roof load distribution over 32 pillars with dual sanctum-focus around twin lingams.","visitorNotes":"Best explored in a combined Barsur circuit with Chandaditya and Mama-Bhanja.","sources":[{"label":"Barsur","url":"https://en.wikipedia.org/wiki/Barsur","type":"Encyclopedia"}]}', '2026-02-25T16:32:23+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-barsur-chandaditya-temple-barsur', 'shiva', 'Chandaditya Temple (Barsur)', 'Chhattisgarh', 'Barsur', 'Barsur, Dantewada district', 'Shiva', 'Shaiva', '["Chandraditya","Chhindaka Naga","Tank-side Temple"]', 'Chandaditya Temple at Barsur is an 11th-century Chhindaka Naga-era Shiva monument near an ancient tank, known for rich pantheon carvings and a distinctive lingam pedestal geometry.', 'Architectural masterpiece node stabilizing the Barsur heritage energy loop.', 'https://commons.wikimedia.org/wiki/Special:FilePath/012_01_2022_Barsur_Chandraditya_Temple_Chattisgarh_012.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:012_01_2022_Barsur_Chandraditya_Temple_Chattisgarh_012.jpg', 'October to February.', 'Open daily; local timings vary.', 'Modest attire.', 'Visit during daylight for better architectural viewing.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"This shrine belongs to Barsur\'s medieval royal temple phase and remains one of Dantewada\'s strongest archaeological Shaiva references.","architecture":"Stone temple massing with intricate sculptural program and an emphasized circular lingam base.","visitorNotes":"Visit with local guidance to map full Barsur temple cluster.","sources":[{"label":"Barsur","url":"https://en.wikipedia.org/wiki/Barsur","type":"Encyclopedia"}]}', '2026-02-25T16:32:23+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
