INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-sirpur-surang-tila-sirpur', 'shiva', 'Surang Tila (Sirpur)', 'Chhattisgarh', 'Sirpur', 'Sirpur elevated temple zone, Mahasamund district', 'Shiva (Surang Tila multi-sanctum tradition)', 'Shaiva', '["Surang Tila","Sirpur","Multi-shrine"]', 'Surang Tila is a high-platform white-stone temple complex of Sirpur with multiple Shiva lingam sanctums and a naturally ventilated sub-structure associated with stable cooling flow.', 'High-platform architectural anomaly with multi-lingam sanctum configuration in Sirpur.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Surang_Tila_monuments%2C_Sirpur_Chhattisgarh.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Surang_Tila_monuments,_Sirpur_Chhattisgarh.jpg', 'October to March.', 'Open daily; archaeology-site timings may vary.', 'Modest attire and comfortable footwear.', 'Treat as both a heritage and devotional site.', '["Local puja observances"]', '["Mahashivratri"]', '{"history":"Surang Tila is one of Sirpur\'s most significant early-medieval temple monuments and remains central to the Mahasamund sacred-heritage map.","architecture":"Elevated platform construction with multiple sanctum units and under-structure airflow channels linked to the site name.","visitorNotes":"Daylight visits are best for reading platform geometry and stone details.","sources":[{"label":"Sirpur, Chhattisgarh","url":"https://en.wikipedia.org/wiki/Sirpur,_Chhattisgarh","type":"Encyclopedia"}]}', '2026-02-25T16:14:37+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
