INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-chhattisgarh-tala-didneshwari-rudra-shiva-temple-tala', 'shiva', 'Didneshwari (Rudra Shiva) Temple, Tala', 'Chhattisgarh', 'Tala', 'Tala, Bilaspur district', 'Shiva (Rudra form)', 'Shaiva', '["Rudra Shiva","Monolithic Icon","Archaeology"]', 'A major Tala heritage node where the Devrani-Jethani 6th-century ruins frame the iconic monolithic Rudra Shiva form, one of the most unusual composite Shaivite images in India.', 'Titanic Rudra Shiva anomaly with creature-composite iconography at the core of the Tala complex.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0010822_6th_century_Tala_Enigmatic_statue%2C_Devrani_Jethani_temple_Chattisgarh_009.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0010822_6th_century_Tala_Enigmatic_statue,_Devrani_Jethani_temple_Chattisgarh_009.jpg', 'October to March.', 'Open daily; archaeology-site timings vary.', 'Comfortable modest attire.', 'Treat as both an archaeological site and an active sacred node.', '["Local worship observances"]', '["Mahashivratri"]', '{"history":"Tala is an early-medieval Shaiva archaeological center, with the Rudra Shiva icon serving as a key interpretive and devotional anchor.","architecture":"Ruined temple matrix and monolithic Rudra form with dense symbolic animal-human compositing.","visitorNotes":"Allocate time for the sculpture core and surrounding Devrani-Jethani remains.","sources":[{"label":"Devrani-Jethani temple","url":"https://en.wikipedia.org/wiki/Devrani-Jethani_temple","type":"Encyclopedia"}]}', '2026-02-25T15:52:16+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
