INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-goa-tambdi-surla-mahadev-temple-tambdi-surla', 'shiva', 'Mahadev Temple (Tambdi Surla)', 'Goa', 'Tambdi Surla', 'Bhagwan Mahaveer Sanctuary, South Goa', 'Shiva', 'Shaiva', '["Kadamba","Basalt","Western Ghats"]', 'A 12th-century Shiva temple deep in the Western Ghats forest belt, preserved as Goa\'s most complete surviving Kadamba-era basalt stone shrine.', 'Primary Goa Shaiva heritage anchor with dense jungle shielding and intact Kadamba architecture.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Post-monsoon and winter mornings.', 'Open daily; local timings vary.', 'Modest attire recommended.', 'Forest approach routes are best planned in daylight.', '["Abhishekam","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Tambdi Surla is widely recognized as a key surviving Kadamba-period Shiva temple in Goa and a major marker of pre-colonial Shaiva continuity.","architecture":"Basalt stone construction with finely carved pillars, sanctum, and mandapa adapted to a heavy-rainfall forest setting.","darshan":"Darshan remains steady year-round with increased pilgrimage movement during Shiva festival cycles.","seasonal":"Monsoon is scenic but can make forest access slippery; winter is most comfortable.","visitorNotes":"Combine temple visit with sanctuary travel planning and local weather checks.","festivals":"Mahashivratri and Shravan Mondays are the principal observances.","sources":[{"label":"Tambdi Surla Temple","url":"https://en.wikipedia.org/wiki/Tambdi_Surla_Temple","type":"Encyclopedia"}]}', '2026-02-25T15:44:31+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
