INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-gujarat-galteshwar-near-dakor-galteshwar-mahadev', 'shiva', 'Galteshwar Mahadev', 'Gujarat', 'Galteshwar (near Dakor)', 'Kheda district', 'Shiva', 'Shaiva', '["Shiva Temple","Gujarat"]', 'The Galteshwar is a Hindu temple dedicated to Shiva, located at Sarnal village near Dakor in Kheda district, Gujarat, India. The 12th century temple is unique in its style and of its period because it is built in central Indian Malwa style, bhumija, without influence of Paramara architecture and with influence of Gujarati Chaulukya architecture. It has a square garbhagriha (shrine proper) as well as octagonal mandapa (dancing hall).', 'Not Available', 'https://commons.wikimedia.org/wiki/Special:FilePath/Galteshwar_Mahadev_Temple_Gujarat.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Galteshwar_Mahadev_Temple_Gujarat.jpg', 'Not Available', 'Not Available', 'Not Available', 'Not Available', '["Not Available"]', '["Maha Shivaratri"]', '{"history":"The Galteshwar is a Hindu temple dedicated to Shiva, located at Sarnal village near Dakor in Kheda district, Gujarat, India. The 12th century temple is unique in its style and of its period because it is built in central Indian Malwa style, bhumija, without influence of Paramara architecture and with influence of Gujarati Chaulukya architecture. It has a square garbhagriha (shrine proper) as well as octagonal mandapa (dancing hall).","puranicView":"Not Available","puranicSources":[],"sources":[{"label":"Galteshwar Temple","url":"https://en.wikipedia.org/wiki/Galteshwar_Temple"},{"label":"District Kheda: Galteshwar Mahadev Temple","url":"https://kheda.nic.in/tourist-place/galteshwar-mahadev-temple/"}],"folkloreSources":[]}', '2026-02-21T17:33:10.290Z', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T14:18:07Z');
