INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-gujarat-kavi-kamboi-stambheshwar-mahadev-temple-kavi-kamboi', 'shiva', 'Stambheshwar Mahadev Temple (Kavi Kamboi)', 'Gujarat', 'Kavi Kamboi', 'Kavi Kamboi, Bharuch district', 'Shiva', 'Shaiva', '["Disappearing Temple","Tidal Submergence","Bharuch"]', 'Known as the \'Disappearing Temple\', Stambheshwar Mahadev submerges during high tide and re-emerges at low tide along the Kavi Kamboi coast.', 'Tide-driven disappearance and reappearance of the shrine.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stambheshwar_Mahadev_Temple_at_Kamboi_Gujarat_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Stambheshwar_Mahadev_Temple_at_Kamboi_Gujarat_India.jpg', 'Any time of year, check tides.', 'Darshan depends on tidal cycles; verify tide chart before visit.', 'Not Available', 'Check tide timings and local safety guidance before planning darshan.', '["Not Available"]', '["Maha Shivaratri"]', '{"history":"Roots tie deeply into mythology where Lord Kartikeya established the lingam.","puranicView":"Described in the Skanda Purana.","puranicSources":[],"sources":[{"label":"Stambheshwar Mahadev","url":"https://en.wikipedia.org/wiki/Stambheshwar_Mahadev"}],"folkloreSources":[]}', '2026-02-21T17:33:04.389Z', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T14:18:07Z');
