INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-gujarat-prabhas-patan-shree-somnath-jyotirlinga-temple', 'shiva', 'Shree Somnath Jyotirlinga Temple', 'Gujarat', 'Prabhas Patan', 'Prabhas Patan, Gir Somnath district', 'Shiva', 'Shaiva', '["Jyotirlinga","First Jyotirlinga","Coastal"]', 'Recognized as the first among the twelve Jyotirlingas...', 'Stunning sea-facing architecture and the evening Light and Sound Show.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Somnath_Temple_Gujarat.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Somnath_Temple_Gujarat.jpg', 'October to March. Evening is best for Aarti and the Light & Sound show.', 'Open daily from 6:00 AM to 9:00 PM.', 'Strict traditional and modest dress code. Shorts and skirts are not allowed.', 'High security. Electronics like mobile phones and cameras are strictly deposited outside.', '["Pratha Aarti","Madhyahna Aarti","Sayam Aarti"]', '["Mahashivratri","Kartik Purnima","Shravan Month"]', '{"history":"Known as \'The Shrine Eternal\', it was destroyed and rebuilt many times by Islamic invaders and Hindu kings respectively.","puranicView":"According to the Shiva Purana, the Moon God (Soma) built this temple in gold after Lord Shiva freed him from a curse of waning entirely.","puranicSources":[{"label":"Shiva Purana","url":"https://en.wikipedia.org/wiki/Shiva_Purana","type":"Puranic literature"}],"sources":[{"label":"Shree Somnath Trust","url":"https://somnath.org/"},{"label":"Somnath Temple","url":"https://en.wikipedia.org/wiki/Somnath_temple"}],"folkloreSources":[]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T14:18:07Z');
