INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-haryana-kiloi-shiv-mandir-kiloi', 'shiva', 'Shiv Mandir, Kiloi', 'Haryana', 'Kiloi', 'Rohtak district', 'Shiva', 'Shaiva', '["Kiloi","High Footfall","Mahashivratri"]', 'A prominent regional Shiva temple in Kiloi with very strong festival attendance and deep local devotional continuity in the Rohtak district grid.', 'Major people\'s-grid Shiva anchor for the Kiloi-Rohtak belt.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Mahashivratri, Shravan, and October-March.', 'Open daily; local timings vary.', 'Modest attire preferred.', 'Kiloi area, Rohtak district.', '["Jalabhishek","Aarti"]', '["Mahashivratri","Shravan Mondays"]', '{"history":"Maintained through long-running community worship and seasonal mela-like gatherings.","architecture":"Regional temple form with active ritual throughput.","darshan":"Very high turnout during festival windows.","seasonal":"Shravan and Shivratri are peak periods.","visitorNotes":"Arrive early on major Mondays and Shivratri.","festivals":"Shivratri remains the principal high-density event.","sources":[{"label":"Rohtak District Portal","url":"https://rohtak.gov.in/tourist-place/","type":"Government"}]}', '2026-02-25T16:52:23+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-haryana-kultajpur-narnaul-side-dhosi-hill-chyavan-rishi-ashram-shiva-node', 'shiva', 'Dhosi Hill (Chyavan Rishi Ashram) Shiva Node', 'Haryana', 'Kultajpur (Narnaul side)', 'Mahendragarh district', 'Shiva', 'Shaiva', '["Dhosi Hill","Aravalli","Ancient"]', 'Dhosi Hill is a major sacred volcanic landscape linked with Chyavan Rishi traditions, where Shiva shrines on and around the crater edge function as high-altitude transmitters for the wider Mahendragarh belt.', 'Primary high-transmitter Shiva anchor on the extinct-volcanic Dhosi ridge.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Shiva_Temple_at_Dhosi_Hill%2C_Chyvan_Rishi_Ashram.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ancient_Shiva_Temple_at_Dhosi_Hill%2C_Chyvan_Rishi_Ashram.JPG', 'October-March / Somvati Amavasya.', 'Daylight hours.', 'Trek-friendly modest attire.', 'Approach from Mahendragarh (Haryana side) or Jhunjhunu side.', '["Parikrama","Snan and puja on special dates"]', '["Somvati Amavasya","Mahashivratri"]', '{"history":"Important Vedic-period sacred geography in regional memory.","architecture":"Hilltop and crater-level shrine structures.","darshan":"Pilgrimage plus trekking destination.","seasonal":"Avoid peak summer heat for ascent.","visitorNotes":"Carry water and start early for climb.","festivals":"Large gatherings on auspicious lunar dates.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dhosi_Hill","type":"Encyclopedia"}]}', '2026-02-25T16:52:23+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-haryana-kurukshetra-bhadrakali-temple-shiva-node', 'shiva', 'Bhadrakali Temple Shiva Node', 'Haryana', 'Kurukshetra', 'Kurukshetra district', 'Shiva', 'Shaiva-Shakta', '["Bhadrakali Complex","Shiva Node","Shaiva-Shakta"]', 'Within the Bhadrakali temple complex, this Shiva node provides a balancing Shaiva anchor alongside the site\'s strong Shakti worship tradition.', 'Dual-resonance Shaiva-Shakta stop in the Kurukshetra pilgrimage grid.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Mahashivratri, Navratri, and cooler months.', 'Open daily; local temple schedule applies.', 'Modest attire preferred.', 'Inside/near the Bhadrakali pilgrimage complex in Kurukshetra.', '["Jalabhishek","Aarti"]', '["Mahashivratri","Navratri"]', '{"history":"Locally visited as the Shaiva complement to one of Kurukshetra\'s major Shakti centers.","architecture":"Regional temple-complex shrine architecture.","darshan":"Regular darshan with peak turnout in festival windows.","seasonal":"Most comfortable from October to March.","visitorNotes":"Can be combined with Sthaneshwar and Brahma Sarovar circuits.","festivals":"High footfall around Shivratri and Navratri.","sources":[{"label":"Kurukshetra Attractions","url":"https://kurukshetra.gov.in/kurukshetraattractions/","type":"Government"},{"label":"48 Kos Kurukshetra","url":"https://kurukshetra.gov.in/48-kos-kurukshetra-tirth/","type":"Government"}]}', '2026-02-25T16:38:43+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
