INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-haryana-thanesar-sthaneshwara-mahadev-temple', 'shiva', 'Sthaneshwara Mahadev Temple', 'Haryana', 'Thanesar', 'Kurukshetra district', 'Shiva (Sthaneshwar)', 'Shaiva', '["48 Kos","Mahabharata","Ancient"]', 'One of the most revered Shiva shrines of Kurukshetra. Tradition says the Pandavas prayed here before the Mahabharata war.', 'Sacred tank beside the temple and 48-kos pilgrimage linkage.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sthaneshwar_mahadev_temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sthaneshwar_mahadev_temple.jpg', 'Mahashivratri / Shravan.', 'Open daily.', 'Modest attire preferred.', 'Near old Thanesar in Kurukshetra.', '["Jalabhishek","Rudrabhishek"]', '["Mahashivratri","Shravan Mondays"]', '{"history":"Associated with the historic city of Sthaneshwar (Thanesar).","architecture":"North Indian temple style with sacred pond complex.","darshan":"High footfall during Shivratri and eclipse pilgrimage days.","seasonal":"Pleasant from October to March.","visitorNotes":"Often visited with other Kurukshetra tirthas.","festivals":"Part of major Kurukshetra religious circuits.","sources":[{"label":"Haryana Tourism","url":"https://haryanatourism.gov.in/places_of_interest/sthaneshwara-mahadev-temple/","type":"Government"},{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sthaneshwar_Mahadev_Temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
