INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-himachal-pradesh-arki-lutru-mahadev-temple-arki', 'shiva', 'Lutru Mahadev Temple (Arki)', 'Himachal Pradesh', 'Arki', 'Solan district', 'Shiva (Lutru Mahadev)', 'Shaiva', '["Lutru Mahadev","Hill Shrine","Arki"]', 'A local Lutru Mahadev shrine in the Arki belt of Solan district, maintained through longstanding devotional continuity.', 'Arki-side historic Shiva anchor in the Solan sub-grid.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baijnath_temple%2C_Himachal_Pradesh.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baijnath_temple,_Himachal_Pradesh.jpg', 'Year-round.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Check local approach details before travel.', '["Daily puja","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Lutru Mahadev is part of Solan district\'s older local Shiva worship network centered around the Arki side.","architecture":"Regional hill-temple style.","darshan":"Moderate local attendance with periodic festival peaks.","seasonal":"Accessible in most weather conditions.","visitorNotes":"Useful as part of an Arki-Solan temple route.","festivals":"Mahashivratri draws the largest annual gathering.","sources":[{"label":"Arki","url":"https://en.wikipedia.org/wiki/Arki,_Himachal_Pradesh","type":"Encyclopedia"}]}', '2026-02-26T00:35:01+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-himachal-pradesh-baijnath-baijnath-jyotirlinga-baijnath', 'shiva', 'Baijnath Jyotirlinga (Baijnath)', 'Himachal Pradesh', 'Baijnath', 'Kangra district', 'Shiva (Vaidyanath/Baijnath)', 'Shaiva', '["Primary Anchor","Vaidyanath","Nagara Architecture"]', 'A major 13th-century Shiva temple at Baijnath, associated with healing-linked Vaidyanath traditions and one of the most important Shaiva nodes in the Kangra valley.', 'District motherboard node with deep-healing Vaidyanath resonance.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baijnath_temple%2C_Himachal_Pradesh.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baijnath_temple,_Himachal_Pradesh.jpg', 'Year-round; spring and autumn are generally comfortable.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Located in Baijnath town with easy road access.', '["Abhishekam","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Traditionally dated to 1204 CE, with Ravana-linked legends and a sustained Vaidyanath healing association in local Shaiva practice.","architecture":"Classical Nagara stone architecture with richly carved temple surfaces and a strong axial mandapa-sanctum layout.","darshan":"Continuous local and regional footfall with strong festival spikes.","seasonal":"Accessible in all seasons; winter mornings can be cold.","visitorNotes":"Can be paired with Upper Baijnath Mahakal and nearby valley shrines.","festivals":"Mahashivratri and Shravan are the primary high-activity observance periods.","sources":[{"label":"Baijnath Temple, Himachal Pradesh","url":"https://en.wikipedia.org/wiki/Baijnath_Temple,_Himachal_Pradesh","type":"Encyclopedia"}]}', '2026-02-25T23:25:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-himachal-pradesh-baijnath-baijnath-temple', 'shiva', 'Baijnath Temple', 'Himachal Pradesh', 'Baijnath', 'Kangra Valley (Deep-Layer)', 'Shiva (Baijnath)', 'Shaiva', '["Baijnath","Deep Layer","Valley Anchor"]', 'Baijnath Temple serves as a core Shaiva anchor in the Kangra Valley deep-layer mapping.', 'Primary deep-layer Baijnath node in the Kangra Valley grid.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baijnath_temple%2C_Himachal_Pradesh.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baijnath_temple,_Himachal_Pradesh.jpg', 'Year-round.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Deep-layer entry, separate from existing district-level Baijnath records.', '["Abhishekam","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Mapped here as a deep-layer continuity node within the broader Kangra Shaiva tradition.","architecture":"Classical temple profile with strong regional identity.","darshan":"Steady pilgrimage flow with festival spikes.","seasonal":"Accessible through all seasons.","visitorNotes":"Can be paired with Mahakal and nearby valley Shiva sites.","festivals":"Mahashivratri remains the highest activity period.","sources":[{"label":"Kangra district, Himachal Pradesh","url":"https://en.wikipedia.org/wiki/Kangra_district","type":"Encyclopedia"}]}', '2026-02-26T02:25:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-himachal-pradesh-baijnath-mahakal-temple', 'shiva', 'Mahakal Temple', 'Himachal Pradesh', 'Baijnath', 'Kangra Valley (Deep-Layer)', 'Shiva (Mahakal)', 'Shaiva', '["Mahakal","Deep Layer","Kangra Valley"]', 'Mahakal Temple is represented as a protective deep-layer Shiva node in the Baijnath corridor.', 'Fierce-time Mahakal layer within the valley core grid.', 'https://upload.wikimedia.org/wikipedia/commons/3/3a/Baijnath_Mahakal_Mandir.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File%3ABaijnath_Mahakal_Mandir.jpg', 'Year-round.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Deep-layer entry, separate from the existing Upper Baijnath Mahakal record.', '["Daily puja","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Mapped as part of the fiercer Mahakal expression in the Kangra Valley sequence.","architecture":"Regional shrine profile with active ritual continuity.","darshan":"Steady flow with periodic festival surges.","seasonal":"Accessible through the year.","visitorNotes":"Useful in the same circuit as Baijnath core nodes.","festivals":"Mahashivratri is the key observance window.","sources":[{"label":"Kangra district, Himachal Pradesh","url":"https://en.wikipedia.org/wiki/Kangra_district","type":"Encyclopedia"}]}', '2026-02-26T02:25:02+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-himachal-pradesh-baijnath-mahakal-temple-upper-baijnath', 'shiva', 'Mahakal Temple (Upper Baijnath)', 'Himachal Pradesh', 'Baijnath', 'Kangra district', 'Shiva (Mahakal)', 'Shaiva', '["Mahakal","Protective Firewall","Upper Baijnath"]', 'A Mahakal-form Shiva node near the Baijnath core circuit, associated with protective and time-resolution energies in local valley worship.', 'Fierce-time protective node complementing the Baijnath motherboard.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baijnath_temple%2C_Himachal_Pradesh.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baijnath_temple,_Himachal_Pradesh.jpg', 'Year-round.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Usually visited as part of the wider Baijnath temple loop.', '["Daily puja","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Preserved in local Baijnath worship routes as a fiercer protective Shiva expression.","architecture":"Regional hill-temple format with local stone and masonry adaptations.","darshan":"Moderate footfall with higher movement on major Shiva observances.","seasonal":"Accessible across seasons with weather-based variation in hill-route comfort.","visitorNotes":"Combine with Baijnath main temple for full ritual context.","festivals":"Mahashivratri and Shravan are the primary visitation peaks.","sources":[{"label":"Baijnath, Himachal Pradesh","url":"https://en.wikipedia.org/wiki/Baijnath,_Himachal_Pradesh","type":"Encyclopedia"}]}', '2026-02-25T23:25:02+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
