INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jammu-and-kashmir-pahalgam-gauri-shankar-temple', 'shiva', 'Gauri Shankar Temple', 'Jammu and Kashmir', 'Pahalgam', 'Pahalgam-Amarnath route region', 'Shiva (Gauri Shankar tradition)', 'Shaiva', '["Gauri Shankar","Mahadev","Shaiva"]', 'Gauri Shankar Temple serves as a Shiva worship point in the wider Pahalgam-Amarnath devotional belt.', 'Gauri-Shankar tradition in the Kashmir pilgrimage landscape.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gauri%20Shankar%20temple%20premises%20in%20Naggar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gauri_Shankar_temple_premises_in_Naggar.jpg', 'Summer and early autumn.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Confirm exact local approach route before travel.', '["Daily puja"]', '["Mahashivratri","Shravan month"]', '{"history":"Part of local Shiva worship traditions connected with the Amarnath corridor.","architecture":"Regional shrine layout with active devotional use.","visitorNotes":"Check on-ground timings with local caretakers.","sources":[{"label":"Anantnag district","url":"https://en.wikipedia.org/wiki/Anantnag_district","type":"Encyclopedia"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Gauri%20Shankar%20Temple%20Pahalgam","type":"Map search"}]}', '2026-02-23T17:34:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T12:05:00Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jammu-and-kashmir-pahalgam-mamleshwar-temple', 'shiva', 'Mamleshwar Temple', 'Jammu and Kashmir', 'Pahalgam', 'Mamal area, Pahalgam', 'Shiva', 'Shaiva', '["Mamleshwar","Pahalgam","Shaiva"]', 'Mamleshwar Temple is a historic Shiva shrine in the Pahalgam area linked with regional pilgrimage traditions.', 'Ancient stone-temple atmosphere near the Pahalgam route.', 'https://commons.wikimedia.org/wiki/Special:FilePath/MamleshwarTemple_1_DivyaGupta_forWiki.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:MamleshwarTemple_1_DivyaGupta_forWiki.jpg', 'April to October for easier access.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Can be combined with Pahalgam and yatra-route visits.', '["Daily puja","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Mamleshwar is recognized in local Kashmir Shaiva worship circuits near Pahalgam.","architecture":"Traditional stone-temple profile with ongoing worship.","visitorNotes":"Morning visits are generally less crowded.","sources":[{"label":"Pahalgam","url":"https://en.wikipedia.org/wiki/Pahalgam","type":"Encyclopedia"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Mamleshwar%20Temple%20Pahalgam","type":"Map search"}]}', '2026-02-23T17:34:20+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T12:05:00Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-aamtoli-sarita-aamtoli-shiv-temple', 'shiva', 'Aamtoli Shiv Temple', 'Jharkhand', 'Aamtoli (Sarita)', 'Gumla district', 'Shiva', 'Shaiva', '["Old Temple","Hill Base","Shivratri Fair"]', 'An old Shiva temple at the foot of a hill in Aamtoli, known for its Shivratri fair.', 'Annual Shivratri fair at the hill base.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Mahashivratri.', 'Open daily.', 'Casual.', 'Around 10 km from Kamdara HQ.', '["Jalabhishek"]', '["Mahashivratri"]', '{"history":"Local pilgrimage site.","architecture":"Small hill-base temple.","darshan":"Devotional.","seasonal":"Best in winter.","visitorNotes":"Fair draws large crowds.","festivals":"Mahashivratri fair.","sources":[{"label":"Gumla","url":"https://gumla.nic.in/tourist-place/kamdara/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-bagodar-harihar-dham', 'shiva', 'Harihar Dham', 'Jharkhand', 'Bagodar', 'Giridih district', 'Shiva', 'Shaiva', '["65 ft Linga","Form Amplifier","Iconic Anomaly"]', 'Known for its monumental 65-foot Shiva-linga form, this Bagodar site functions as a strong geometric broadcaster of Shaiva symbolism across surrounding rural sub-grids.', 'One of the region\'s most iconic large-form Shiva structures.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiv_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shiv_Temple.jpg', 'Winter and Mahashivratri.', 'Open daily.', 'Casual.', 'On GT Road.', '["Marriage ceremonies"]', '["Shivratri"]', '{"history":"Modern monumental temple development with strong regional devotional adoption.","architecture":"Monumental.","darshan":"Grand-scale iconic darshan.","seasonal":"All year.","visitorNotes":"Highly visible from GT Road; popular pilgrimage stop.","festivals":"Shivratri.","sources":[{"label":"Giridih","url":"https://giridih.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-baharagora-chitreshwar-temple', 'shiva', 'Chitreshwar Temple', 'Jharkhand', 'Baharagora', 'East Singhbhum', 'Shiva', 'Shaiva', '["Largest Linga","Natural","Border"]', 'Home to one of the largest natural Shiva Lingas. Legend says the Pandavas worshipped here. It is near the Bengal-Odisha border.', 'The massive natural Linga.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Shiva_Linga_Varanasi.jpg/640px-Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Baharagora.', '["Linga Abhishek"]', '["Shivratri"]', '{"history":"Mahabharata legend.","architecture":"Ancient.","darshan":"Unique.","seasonal":"Pleasant.","visitorNotes":"Huge gathering on Shivratri.","festivals":"Shivratri.","sources":[{"label":"East Singhbhum","url":"https://eastsinghbhum.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-bandgaon-hirni-falls-temple', 'shiva', 'Hirni Falls Temple', 'Jharkhand', 'Bandgaon', 'West Singhbhum', 'Shiva', 'Shaiva', '["Waterfall","Forest","Tribal"]', 'Situated in a dense forest, Hirni Falls is a popular spot. Small tribal shrines in the woods revere nature and Shiva.', 'The forest setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jharkhand_Hirni_fall.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jharkhand_Hirni_fall.jpg', 'Monsoon.', 'Daylight hours.', 'Casual.', 'Forest entry.', '["Nature worship"]', '["None"]', '{"history":"Natural.","architecture":"None.","darshan":"Scenic.","seasonal":"Beautiful in rains.","visitorNotes":"Drive carefully.","festivals":"None.","sources":[{"label":"Chaibasa","url":"https://chaibasa.nic.in/tourist-place/hirni-falls/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-banpur-rerwa-banpur-shiv-temple', 'shiva', 'Banpur Shiv Temple', 'Jharkhand', 'Banpur (Rerwa)', 'Gumla district', 'Shiva', 'Shaiva', '["Old Temple","Pondside","Shivratri Fair"]', 'A historic Shiva temple in Banpur with a pond nearby where pilgrims bathe before worship.', 'Pondside Shiva shrine with a Shivratri fair.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Mahashivratri.', 'Open daily.', 'Casual.', 'Around 11 km from Kamdara HQ.', '["Holy dip","Jalabhishek"]', '["Mahashivratri"]', '{"history":"Old village temple.","architecture":"Simple shrine.","darshan":"Community worship.","seasonal":"Best in winter.","visitorNotes":"Pond nearby for ritual bathing.","festivals":"Mahashivratri fair.","sources":[{"label":"Gumla","url":"https://gumla.nic.in/tourist-place/kamdara/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-barhait-shivgadi-temple', 'shiva', 'Shivgadi Temple', 'Jharkhand', 'Barhait', 'Sahibganj district', 'Shiva', 'Shaiva', '["Cave","Trekking","Remote"]', 'A cave temple located deep in the hills, housing a Swayambhu Shiva Linga. Access requires a short trek through scenic surroundings.', 'The cave entrance and trek.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Gupteshwar_Mahadev.jpg/640px-Gupteshwar_Mahadev.jpg', 'Wikimedia Commons (Representational Cave)', 'https://commons.wikimedia.org/wiki/File:Gupteshwar_Mahadev.jpg', 'Shivratri.', 'Daylight hours.', 'Casual.', 'Requires climbing.', '["Cave puja"]', '["Shivratri"]', '{"history":"Ancient.","architecture":"Natural cave.","darshan":"Adventurous.","seasonal":"Pleasant.","visitorNotes":"Carry water.","festivals":"Shivratri.","sources":[{"label":"Sahibganj","url":"https://sahibganj.nic.in/tourist-place/shivgadi/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-barkatha-surajkund-shiva-shrine', 'shiva', 'Surajkund Shiva Shrine', 'Jharkhand', 'Barkatha', 'Hazaribagh district', 'Shiva / Surya', 'Shaiva/Solar', '["Hot Spring","Sulfur","Health"]', 'Famous for its hot water springs. The complex has shrines for various deities including Shiva, frequented by people seeking cures.', 'The hot springs.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Budhanath_Temple_Bhagalpur.jpg/640px-Budhanath_Temple_Bhagalpur.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Budhanath_Temple_Bhagalpur.jpg', 'Winter (Mela).', 'Open daily.', 'Casual.', 'On GT Road.', '["Holy dip"]', '["Surajkund Mela"]', '{"history":"Ancient springs.","architecture":"Kund style.","darshan":"Wellness.","seasonal":"Crowded in winter.","visitorNotes":"Water is very hot.","festivals":"Makar Sankranti.","sources":[{"label":"Hazaribagh","url":"https://hazaribag.nic.in/tourist-place/surajkund/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-barwadih-pahadi-mandir-barwadih', 'shiva', 'Pahadi Mandir (Barwadih)', 'Jharkhand', 'Barwadih', 'Latehar district', 'Shiva / Hanuman', 'Shaiva', '["Hilltop","Shiva-Hanuman","Panoramic View"]', 'A hilltop temple dedicated to Lord Shiva and Lord Hanuman, known for its serene setting and sweeping views.', 'Panoramic views from the hilltop.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mandar_Hill.jpg', 'Wikimedia Commons (Representational Hill)', 'https://commons.wikimedia.org/wiki/File:Mandar_Hill.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Near Barwadih Railway Station.', '["Jal offering"]', '["Mahashivratri"]', '{"history":"Popular local pilgrimage.","architecture":"Hilltop shrine.","darshan":"Scenic and peaceful.","seasonal":"Accessible year-round.","visitorNotes":"Short climb to the top.","festivals":"Mahashivratri is busy.","sources":[{"label":"Latehar","url":"https://latehar.nic.in/tourist-place/pahadi-mandir-barwadih-latehar/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-basukinath-basukinath-mahadev', 'shiva', 'Basukinath Mahadev', 'Jharkhand', 'Basukinath', 'Dumka district', 'Shiva (Basukinath)', 'Shaiva', '["Court of Shiva","Administrative Router","Kanwar Completion"]', 'Revered as the \'court of Shiva\' in local tradition, this temple acts as the secondary administrative router of the Baidyanath pilgrimage stream, where many yatris complete their circuit after Deoghar.', 'Essential sync-point in the Baidyanath-Basukinath pilgrimage sequence.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baba_Basukinath_Temple_complex_at_Basukinath%2C_Jharkhand_02.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baba_Basukinath_Temple_complex_at_Basukinath%2C_Jharkhand_02.jpg', 'Shravan.', 'Open daily.', 'Casual.', 'Often visited as the completion stop after Baidyanath darshan.', '["Milk offering"]', '["Shravani Mela"]', '{"history":"Ancient regional shrine with later-period renovations and sustained yatra linkage.","architecture":"Traditional.","darshan":"Devotional and pilgrimage-sequence focused.","seasonal":"Monsoon peak.","visitorNotes":"Best approached as part of the Deoghar-Basukinath route.","festivals":"Shivratri.","sources":[{"label":"Dumka","url":"https://dumka.nic.in/tourist-place/basukinath-temple/","type":"Government"}]}', '2026-02-23T02:10:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-benisagar-benisagar-temples', 'shiva', 'Benisagar Temples', 'Jharkhand', 'Benisagar', 'West Singhbhum', 'Shiva', 'Shaiva/Historical', '["Archaeology","Ruins","Panchayatana"]', 'An archaeological site maintained by ASI, featuring ruins of ancient temples including Shiva lingas and Panchayatana style structures.', 'The historical ruins and sculptures.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Benisagar_Archaeological_Museum_Image_16.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Benisagar_Archaeological_Museum_Image_16.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'ASI protected site.', '["Historical tour"]', '["Heritage walks"]', '{"history":"5th-10th Century.","architecture":"Gupta/Odisha style.","darshan":"Educational.","seasonal":"Pleasant.","visitorNotes":"Border of Odisha.","festivals":"None specific.","sources":[{"label":"Chaibasa","url":"https://chaibasa.nic.in/tourist-place/benisagar/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-bhatdiha-ratneshwar-nath-dham', 'shiva', 'Ratneshwar Nath Dham', 'Jharkhand', 'Bhatdiha', 'Godda district', 'Shiva', 'Shaiva', '["Ancient","Local Kashi","River"]', 'An ancient temple on the banks of the Sundar river, often called the \'Baba Dham\' of the Godda region. It holds great local significance.', 'The riverside setting and ancient Linga.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Konch_Eshwar_Mahadev.jpg/640px-Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Shravan.', 'Open daily.', 'Casual.', 'Near Godda town.', '["River bath","Jalabhishek"]', '["Shivratri"]', '{"history":"Ancient legend.","architecture":"North Indian.","darshan":"Devotional.","seasonal":"Festive in Sawan.","visitorNotes":"Peaceful vibe.","festivals":"Shivratri.","sources":[{"label":"Godda","url":"https://godda.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-bokaro-belkupi-ruins', 'shiva', 'Belkupi Ruins', 'Jharkhand', 'Bokaro', 'Bokaro district', 'Shiva', 'Shaiva/History', '["Ruins","Jain/Hindu","Historic"]', 'An ancient site with ruins of temples that show a mix of Jain and Hindu influences, including Shiva lingas.', 'The ancient foundations.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg/640px-An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg', 'Wikimedia Commons (Representational Ruins)', 'https://commons.wikimedia.org/wiki/File:An_old_Temple_dedicated_to_the_Lord_Shiva(_Haleswar_Mandir).jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Ruins site.', '["Observation"]', '["None"]', '{"history":"Ancient.","architecture":"Ruins.","darshan":"Historical.","seasonal":"Pleasant.","visitorNotes":"Archaeology interest.","festivals":"None.","sources":[{"label":"Bokaro","url":"https://bokaro.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-bokaro-steel-city-ram-mandir-shiva-shrine', 'shiva', 'Ram Mandir Shiva Shrine', 'Jharkhand', 'Bokaro Steel City', 'Bokaro district', 'Shiva', 'Shaiva/Vaishnava', '["Oldest in City","Market","Devotion"]', 'Located in Sector 1, this is one of the oldest and most visited temples in Bokaro. The Shiva shrine here attracts huge crowds on Mondays.', 'The main market location.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Konch_Eshwar_Mahadev.jpg/640px-Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Monday.', 'Open daily.', 'Casual.', 'Near Ram Mandir market.', '["Jalabhishek"]', '["Shivratri"]', '{"history":"City foundation era.","architecture":"North Indian.","darshan":"Active.","seasonal":"All year.","visitorNotes":"Best shoping nearby.","festivals":"Ram Navami.","sources":[{"label":"Bokaro","url":"https://bokaro.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-bokaro-steel-city-shiv-mandir-sector-4', 'shiva', 'Shiv Mandir Sector 4', 'Jharkhand', 'Bokaro Steel City', 'Bokaro district', 'Shiva', 'Shaiva', '["Urban","Jagannath Complex","Community"]', 'Part of the Jagannath Temple complex in Sector 4, this Shiva temple is a major spiritual hub for the residents of the steel city.', 'The well-maintained complex.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Konch_Eshwar_Mahadev.jpg/640px-Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Evening.', 'Open daily.', 'Casual.', 'City center.', '["Evening Aarti"]', '["Rath Yatra"]', '{"history":"Modern.","architecture":"Odia style.","darshan":"Peaceful.","seasonal":"All year.","visitorNotes":"Near City Park.","festivals":"Shivratri.","sources":[{"label":"Bokaro","url":"https://bokaro.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-chandil-chandil-ancient-temple', 'shiva', 'Chandil Ancient Temple', 'Jharkhand', 'Chandil', 'Seraikela Kharsawan', 'Shiva', 'Shaiva', '["Submerged","Museum","History"]', 'The construction of Chandil dam submerged many ancient temples. Artifacts and Shiva lingas have been preserved in a museum nearby.', 'The rescued sculptures.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chandil_Dam.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chandil_Dam.jpg', 'Winter.', 'Museum hours.', 'Casual.', 'Visit the museum.', '["Observation"]', '["None"]', '{"history":"Ancient.","architecture":"Museum.","darshan":"Educational.","seasonal":"Pleasant.","visitorNotes":"Rich history lost.","festivals":"None.","sources":[{"label":"Seraikela","url":"https://seraikela.nic.in/tourist-place/chandil-dam/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-chatra-bichkiliya-falls-temple', 'shiva', 'Bichkiliya Falls Temple', 'Jharkhand', 'Chatra', 'Chatra district', 'Shiva', 'Shaiva', '["Waterfall","Picnic","Nature"]', 'Located on the banks of Niranjana river, this site is a popular picnic spot with a waterfall and a temple for nature worship.', 'The waterfall.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Usri_falls%2Cgiridih%2Cjharkhand.jpg/640px-Usri_falls%2Cgiridih%2Cjharkhand.jpg', 'Wikimedia Commons (Representational Waterfall)', 'https://commons.wikimedia.org/wiki/File:Usri_falls,giridih,jharkhand.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Nature spot.', '["Picnic"]', '["New Year"]', '{"history":"Natural.","architecture":"Simple.","darshan":"Scenic.","seasonal":"Best in winter.","visitorNotes":"Good for outing.","festivals":"Local fun.","sources":[{"label":"Chatra","url":"https://chatra.nic.in/tourist-place/bichkiliya/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-chilka-dham-bokaro-chilka-dham', 'shiva', 'Chilka Dham', 'Jharkhand', 'Chilka Dham (Bokaro)', 'Bokaro district', 'Shiva', 'Shaiva', '["Border Shrine","Shravan","Pilgrimage"]', 'A Shiva dham near the Jharkhand-West Bengal border that draws large crowds during Shravan Somvar.', 'Border-area Shiva pilgrimage during Shravan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Shravan.', 'Open daily.', 'Casual.', 'Near the Jharkhand-West Bengal border.', '["Jalabhishek"]', '["Shravan Somvar"]', '{"history":"Local dham.","architecture":"Pilgrimage shrine.","darshan":"Crowded in Shravan.","seasonal":"Peak in monsoon.","visitorNotes":"Expect heavy footfall in Shravan.","festivals":"Shravan Somvar.","sources":[{"label":"Times of India","url":"https://timesofindia.indiatimes.com/city/ranchi/devotees-throng-temples-since-crack-of-dawn/articleshow/122449921.cms","type":"News"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-baidyanath-jyotirlinga-baba-dham', 'shiva', 'Baidyanath Jyotirlinga (Baba Dham)', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Shiva (Baidyanath)', 'Shaiva', '["Jyotirlinga","Siddha Peeth","Healing Restoration"]', 'One of the twelve Jyotirlingas and a major Siddha Peeth, this temple is the primary healing-restoration Shiva node of the region. The Baidyanath-Shakti linkage and ritual gathbandhan tradition form a continuous Shiva-Shakti circuit in the core complex.', 'The principal pilgrimage motherboard of Deoghar with massive Shravani footfall.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sacred_Pond_-_Baidyanath_Dham_Temple_Complex_-_Deoghar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sacred_Pond_-_Baidyanath_Dham_Temple_Complex_-_Deoghar.jpg', 'Shravan (July-Aug) and Mahashivratri.', '4:00 AM - 9:00 PM', 'Traditional preferred.', 'Heavy queues during Shravan; plan early darshan.', '["Jalabhishek","Rudrabhishek"]', '["Shravani Mela","Shivratri"]', '{"history":"Ancient Puranic Jyotirlinga center with long-standing pan-Indian yatra routes.","architecture":"Nagara style.","darshan":"High-intensity pilgrimage darshan; touch darshan in designated conditions.","seasonal":"Monsoon is peak.","visitorNotes":"Primary spiritual hub of Deoghar and wider Jharkhand.","festivals":"Shravani Mela drives the largest annual surge.","sources":[{"label":"Deoghar","url":"https://deoghar.nic.in/tourist-place/baba-baidyanath-temple/","type":"Government"}]}', '2026-02-23T01:56:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-baiju-temple', 'shiva', 'Baiju Temple', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Shiva (Baiju tradition)', 'Shaiva', '["Baidyanath tradition","Legend","Shaiva"]', 'A Shiva shrine in Deoghar associated with the Baiju/Baiju Bawra devotional tradition linked to Baba Baidyanath.', 'Part of the wider Baidyanath pilgrimage narrative.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Shravan and Maha Shivaratri.', 'Open daily; local timings vary.', 'Traditional preferred.', 'Usually visited as part of the Deoghar Shiva circuit.', '["Jalabhishek","Belpatra offering"]', '["Shravani Mela","Maha Shivaratri"]', '{"history":"The shrine is tied to local oral traditions around the Baiju-Baidyanath devotional stream.","architecture":"Local temple architecture.","darshan":"Often combined with Baidyanath Dham visits.","seasonal":"Heavy footfall during Shravan.","visitorNotes":"Plan early-morning darshan in peak pilgrimage season.","festivals":"Shravan and Shivaratri are key observances.","sources":[{"label":"Deoghar district tourism","url":"https://deoghar.nic.in/tourist-place/baba-baidyanath-temple/","type":"Government"}]}', '2026-02-23T01:58:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-harila-jori-shiva-temple', 'shiva', 'Harila Jori Shiva Temple', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Shiva', 'Shaiva', '["Harila Jori","Pilgrimage","Shaiva"]', 'A Shiva temple site at Harila Jori in the Deoghar sacred geography, visited by Baidyanath pilgrims.', 'Local Shaiva shrine connected to the Deoghar yatra belt.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Shravan and winter mornings.', 'Open daily; local timings vary.', 'Traditional preferred.', 'Commonly covered in Deoghar pilgrimage routes.', '["Jal offering","Rudra path"]', '["Shravani Mela","Maha Shivaratri"]', '{"history":"Harila Jori is preserved in local pilgrimage memory around Baidyanath Dham.","architecture":"Small regional shrine style.","darshan":"Devotees usually include it in multi-stop Deoghar darshan.","seasonal":"Shravan sees peak pilgrim movement.","visitorNotes":"Expect heavier queues in Shravan Mondays.","festivals":"Shravan month and Shivaratri are major periods.","sources":[{"label":"Deoghar district","url":"https://deoghar.nic.in/","type":"Government"}]}', '2026-02-23T01:59:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-kundeshwari-temple', 'shiva', 'Kundeshwari Temple', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Shiva (Kundeshwar/Kundeshwari tradition)', 'Shaiva', '["Kundeshwari","Shaiva","Local shrine"]', 'A Kundeshwari temple in Deoghar district associated with the local Shiva worship tradition.', 'Local Deoghar temple stop in the Shiva circuit.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Maha Shivaratri and Shravan month.', 'Open daily; local timings vary.', 'Traditional preferred.', 'Part of regional Deoghar worship routes.', '["Abhishek","Aarti"]', '["Maha Shivaratri","Shravan Somvar"]', '{"history":"Kundeshwari worship is maintained through local temple practices in the Deoghar region.","architecture":"Traditional local shrine format.","darshan":"Usually calm outside major festival days.","seasonal":"Festival attendance rises in Shravan.","visitorNotes":"Prefer morning visits for shorter lines.","festivals":"Shivaratri and Shravan Mondays are significant.","sources":[{"label":"Deoghar district","url":"https://deoghar.nic.in/","type":"Government"}]}', '2026-02-23T02:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-mansarovar-shiva-temple', 'shiva', 'Mansarovar Shiva Temple', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Shiva', 'Shaiva', '["Mansarovar","Baidyanath circuit","Shaiva"]', 'A Mansarovar-area Shiva temple in Deoghar, visited as part of the Baidyanath pilgrimage zone.', 'Mansarovar-linked Shiva darshan near Deoghar\'s core sacred circuit.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Early morning and Shravan period.', 'Open daily; local timings vary.', 'Traditional preferred.', 'Combine with nearby Baidyanath temple visits.', '["Jalabhishek","Daily aarti"]', '["Shravani Mela","Maha Shivaratri"]', '{"history":"Mansarovar in Deoghar is part of the expanded sacred geography around Baba Baidyanath Dham.","architecture":"Local shrine architecture.","darshan":"Frequently visited as an auxiliary stop in the Deoghar circuit.","seasonal":"Shravan draws the largest pilgrim turnout.","visitorNotes":"Visit early in the day during peak months.","festivals":"Shravan and Shivaratri observances are prominent.","sources":[{"label":"Deoghar district tourism","url":"https://deoghar.nic.in/tourist-place/baba-baidyanath-temple/","type":"Government"}]}', '2026-02-23T02:01:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-nandan-pahar-temple', 'shiva', 'Nandan Pahar Temple', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Nandi / Shiva', 'Shaiva', '["Nandi","Amusement Park","View"]', 'A hill dedicated to Nandi, Shiva\'s vehicle. It has temples for Shiva, Parvati, and Nandi, and offers a view of the Baidyanath temple.', 'The Nandi temple and city view.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Trikut_Pahar.jpg/640px-Trikut_Pahar.jpg', 'Wikimedia Commons (Representational Hill)', 'https://commons.wikimedia.org/wiki/File:Trikut_Pahar.jpg', 'Evening.', 'Open daily.', 'Casual.', 'Ideal for families.', '["Nandi Puja"]', '["Shivratri"]', '{"history":"Mythological.","architecture":"Hill temple.","darshan":"Recreational.","seasonal":"Pleasant.","visitorNotes":"Amusement park adjacent.","festivals":"Shivratri.","sources":[{"label":"Deoghar","url":"https://deoghar.nic.in/tourist-place/nandan-pahar/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-naulakha-mandir-shiva-shrine', 'shiva', 'Naulakha Mandir Shiva Shrine', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Shiva', 'Shaiva', '["Refined Frequency","Urban Buffer","Devotional Architecture"]', 'Within the Naulakha Mandir devotional zone, associated Shiva markers function as a refined buffer layer that steps down the high-intensity Baidyanath pilgrimage flow for urban worshippers.', 'A calmer devotional-artistic Shiva node in the broader Deoghar circuit.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Winter, Shravan, and Shivratri.', 'Open daily.', 'Modest temple attire.', 'Deoghar urban sacred circuit.', '["Daily puja","Jalabhishek"]', '["Mahashivratri","Shravan month observances"]', '{"history":"20th-century devotional complex with integrated Shaiva worship points.","architecture":"Refined temple form with strong devotional focus.","darshan":"Calmer urban darshan.","seasonal":"Most active during Shravan and major festival periods.","visitorNotes":"Often visited with Baidyanath and Tapovan stops.","festivals":"Mahashivratri.","sources":[{"label":"Deoghar district tourism","url":"https://deoghar.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-tapovan-shiva-caves', 'shiva', 'Tapovan Shiva Caves', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Shiva (Taponath)', 'Shaiva/Ascetic', '["Meditation Anchor","Caves","Penance","Taponath"]', 'A cave-based Shaiva meditation anchor with Taponath Mahadev worship, known for low-noise inward practice and long-standing tapasya traditions.', 'Natural cave sanctums suited for contemplative Shaiva practice.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Gupteshwar_Mahadev.jpg/640px-Gupteshwar_Mahadev.jpg', 'Wikimedia Commons (Representational Cave)', 'https://commons.wikimedia.org/wiki/File:Gupteshwar_Mahadev.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Rocky cave zone near Deoghar city.', '["Meditation"]', '["Shivratri"]', '{"history":"Ancient tapasya site preserved in local ascetic traditions.","architecture":"Cave temple.","darshan":"Inward-focused and spiritual.","seasonal":"Pleasant.","visitorNotes":"Explore the caves.","festivals":"Shivratri.","sources":[{"label":"Deoghar","url":"https://deoghar.nic.in/tourist-place/tapovan/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-deoghar-trikut-pahar-shiva-nodes', 'shiva', 'Trikut Pahar Shiva Nodes', 'Jharkhand', 'Deoghar', 'Deoghar district', 'Shiva (Trikutachal shrines)', 'Shaiva', '["Three Peaks","Vertical Transmitters","Ropeway","Granite Plateau"]', 'A network of Shiva shrines on the three-peaked Trikut hill system near Deoghar. These elevated nodes function as vertical transmitters across the wider Santhal Pargana forest belt.', 'High-altitude Shiva transmission zone with ropeway and ridge-level darshan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Trikut_pahar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Trikut_pahar.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Ropeway and trek routes available.', '["Hill worship"]', '["Mela"]', '{"history":"Myth-linked hill pilgrimage zone in Deoghar district.","architecture":"Hill shrine.","darshan":"Adventure and panoramic.","seasonal":"Avoid monsoon for trek.","visitorNotes":"Beware of monkeys.","festivals":"Shivratri and local hill fairs.","sources":[{"label":"Deoghar","url":"https://deoghar.nic.in/tourist-place/trikut-pahar/","type":"Government"}]}', '2026-02-23T01:57:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-dhalbhumgarh-amadubi-village-temple', 'shiva', 'Amadubi Village Temple', 'Jharkhand', 'Dhalbhumgarh', 'East Singhbhum', 'Shiva', 'Tribal/Shaiva', '["Rural","Art","Pyatkar"]', 'A rural tourism village famous for Pyatkar paintings. The village temple is a center of local life and art.', 'The tribal art.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Konch_Eshwar_Mahadev.jpg/640px-Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Art village.', '["Village Puja"]', '["Tusu"]', '{"history":"Ancient art.","architecture":"Village style.","darshan":"Cultural.","seasonal":"Winter.","visitorNotes":"Buy paintings.","festivals":"Tusu Parab.","sources":[{"label":"Jamshedpur","url":"https://tourism.jharkhand.gov.in/destination/amadubi-rural-tourism-village","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-dhanbad-bhatinda-fall-temple', 'shiva', 'Bhatinda Fall Temple', 'Jharkhand', 'Dhanbad', 'Dhanbad district', 'Shiva', 'Shaiva', '["Waterfall","Rocks","Nature"]', 'A small Shiva shrine nestled near the Bhatinda (Moonidih) waterfall, offering a serene spot for nature lovers and devotees.', 'The rugged rocky waterfall.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhatinda-fall-dhanbad.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bhatinda-fall-dhanbad.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Near Moonidih.', '["Picnic"]', '["New Year"]', '{"history":"Natural site.","architecture":"Simple.","darshan":"Scenic.","seasonal":"Best in winter.","visitorNotes":"Caution near water.","festivals":"Local fairs.","sources":[{"label":"Dhanbad","url":"https://dhanbad.nic.in/tourist-place/bhatinda-fall/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-dhanbad-bhuphor-mahadev', 'shiva', 'Bhuphor Mahadev', 'Jharkhand', 'Dhanbad', 'Dhanbad district', 'Shiva (Bhuphor Mahadev)', 'Shaiva', '["Swayambhu","Deep Crust","Primary Anchor"]', 'A major Dhanbad Shiva node traditionally described as a Bhu-phor manifestation, where the lingam is revered as emerging from the earth and linked with deep-ground stabilization.', 'Primary earth-linked Shaiva motherboard for Dhanbad\'s urban grid.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Mahashivratri and Shravan.', 'Open daily.', 'Modest temple attire.', 'Dhanbad urban sacred circuit.', '["Jalabhishek","Somvar worship"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Preserved in local oral tradition as a self-manifested earth node.","architecture":"Traditional shrine form.","darshan":"Grounded and high-intensity.","seasonal":"Most active in Shravan.","visitorNotes":"A key Shiva stop for central Dhanbad devotees.","festivals":"Mahashivratri.","sources":[{"label":"Dhanbad district","url":"https://dhanbad.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-dhanbad-langta-baba-shiva-shrine-dhanbad', 'shiva', 'Langta Baba Shiva Shrine (Dhanbad)', 'Jharkhand', 'Dhanbad', 'Dhanbad district', 'Shiva (integrated with Langta Baba shrine tradition)', 'Shaiva/Folk', '["Siddha Interface","Yoga Stability","Folk Logic"]', 'A saint-associated devotional site in Dhanbad with integrated Shiva worship markers, bridging classical Shaiva practice with living folk and local lineage traditions.', 'Folk-Vedic bridge node for district-level spiritual continuity.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Mahashivratri and local fair dates.', 'Open daily.', 'Modest temple attire.', 'Dhanbad local saint-shrine network.', '["Aarti","Saint-lineage offerings"]', '["Mahashivratri","Local annual mela"]', '{"history":"Evolved through local saint devotion with embedded Shiva worship.","architecture":"Mixed shrine setting.","darshan":"Folk-integrated and meditative.","seasonal":"Festival-driven activity peaks.","visitorNotes":"Important for local oral and devotional continuity.","festivals":"Shivratri and local fair cycles.","sources":[{"label":"Dhanbad district","url":"https://dhanbad.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-dhanbad-rural-belt-amreshwar-dham-dhanbad', 'shiva', 'Amreshwar Dham (Dhanbad)', 'Jharkhand', 'Dhanbad rural belt', 'Dhanbad district', 'Shiva (Amreshwar)', 'Shaiva', '["Rural Anchor","Soil Sutra","Mining Fringe"]', 'A rural Shiva stabilizer for agricultural communities around the mining periphery, maintaining steady ritual continuity and land-linked worship patterns.', 'A rhythmic baseline node balancing industrial and agrarian life zones.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Shravan and Mahashivratri.', 'Open daily.', 'Modest temple attire.', 'In interior Dhanbad rural sub-grid.', '["Village jalabhishek","Harvest-linked offerings"]', '["Mahashivratri","Shravan month rituals"]', '{"history":"Maintained through village worship traditions near industrial transition zones.","architecture":"Rural shrine architecture.","darshan":"Steady and community-focused.","seasonal":"Most active in monsoon and festival windows.","visitorNotes":"Represents the agrarian side of Dhanbad\'s sacred matrix.","festivals":"Mahashivratri.","sources":[{"label":"Dhanbad district","url":"https://dhanbad.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-dhori-phusro-shiv-shani-mandir-dhori', 'shiva', 'Shiv Shani Mandir (Dhori)', 'Jharkhand', 'Dhori (Phusro)', 'Bokaro district', 'Shiva / Shani', 'Shaiva', '["Shiva-Shani","Bermo","Community"]', 'A notable shrine where Lord Shiva and Lord Shani are worshipped together in the Bermo area.', 'Shared Shiva-Shani worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Mahashivratri.', 'Open daily.', 'Casual.', 'Near Phusro, Bokaro.', '["Jal offering"]', '["Mahashivratri"]', '{"history":"Established in 1975; Shani shrine added later.","architecture":"Community temple.","darshan":"Local pilgrimage.","seasonal":"Busy on Mondays and festivals.","visitorNotes":"Popular in the Bermo region.","festivals":"Mahashivratri.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Shiv_Shani_Mandir,_Dhori","type":"Wikipedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-dhuroides-sukhaldari-falls-shrine', 'shiva', 'Sukhaldari Falls Shrine', 'Jharkhand', 'Dhuroides', 'Garhwa district', 'Shiva', 'Shaiva', '["Niagara of Jharkhand","River","Nature"]', 'Located on the Kanhar river, this waterfall is stunning. Local shrines celebrate the river\'s power, including Shiva worship.', 'The powerful waterfall.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Usri_falls%2Cgiridih%2Cjharkhand.jpg/640px-Usri_falls%2Cgiridih%2Cjharkhand.jpg', 'Wikimedia Commons (Representational Waterfall)', 'https://commons.wikimedia.org/wiki/File:Usri_falls,giridih,jharkhand.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Border area.', '["Nature worship"]', '["Makar Sankranti"]', '{"history":"Natural.","architecture":"None.","darshan":"Scenic.","seasonal":"Best flow in monsoon.","visitorNotes":"Impressive fall.","festivals":"Mela nearby.","sources":[{"label":"Garhwa","url":"https://garhwa.nic.in/tourist-place/sukhaldari-waterfall/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-digwar-tooti-jharna-temple', 'shiva', 'Tooti Jharna Temple', 'Jharkhand', 'Digwar', 'Ramgarh district', 'Shiva', 'Shaiva', '["Miracle","Waterfall","Swayambhu"]', 'A mysterious temple where water from a hill naturally falls onto the Shiva Linga 24/7 throughout the year. The source of water remains unknown.', 'The perpetual natural Jalabhishek.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Moti_jharna_jharkhand.jpeg/640px-Moti_jharna_jharkhand.jpeg', 'Wikimedia Commons (Representational Waterfall)', 'https://commons.wikimedia.org/wiki/File:Moti_jharna_jharkhand.jpeg', 'All year.', 'Open daily.', 'Casual.', '7 km from Ramgarh.', '["Witnessing miracle"]', '["Shivratri"]', '{"history":"British era discovery.","architecture":"Simple.","darshan":"Miraculous.","seasonal":"Always active.","visitorNotes":"Don\'t miss the water flow.","festivals":"Shivratri.","sources":[{"label":"Ramgarh","url":"https://ramgarh.nic.in/tourist-place/tooti-jharna-temple/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
