INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-gidhour-balbal-duari', 'shiva', 'Balbal Duari', 'Jharkhand', 'Gidhour', 'Chatra district', 'Shiva', 'Shaiva', '["Hot Spring","Mela","Cure"]', 'A famous hot spring site. A Shiva temple here is the center of the annual Balbal Mela, where people come to bathe and pray.', 'The hot springs.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Budhanath_Temple_Bhagalpur.jpg/640px-Budhanath_Temple_Bhagalpur.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Budhanath_Temple_Bhagalpur.jpg', 'Makar Sankranti.', 'Open daily.', 'Casual.', 'On highway.', '["Holy dip"]', '["Balbal Mela"]', '{"history":"Ancient.","architecture":"Kund.","darshan":"Wellness.","seasonal":"Winter.","visitorNotes":"Very hot water.","festivals":"Makar Sankranti.","sources":[{"label":"Chatra","url":"https://chatra.nic.in/tourist-place/balbal-duari/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-giridih-dukhiya-mahadev', 'shiva', 'Dukhiya Mahadev', 'Jharkhand', 'Giridih', 'Giridih district', 'Shiva (Dukhiya Mahadev)', 'Shaiva', '["Urban Grounding Rod","Usri River Bank","Relief Focused"]', 'A central Shiva shrine for Giridih town on the Usri river belt, serving daily devotional and community life for the city\'s trading and mining-linked population.', 'Primary urban Shaiva stabilizer for Giridih municipal flow.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Shravan and Mahashivratri.', 'Open daily.', 'Modest temple attire.', 'In Giridih urban river corridor.', '["Jalabhishek","Daily aarti"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Maintained through long-running local town worship traditions.","architecture":"Urban riverbank temple style.","darshan":"Relief-oriented and community-centric.","seasonal":"Peak activity during Shravan month.","visitorNotes":"Important city-level stop in Giridih Shiva routes.","festivals":"Mahashivratri.","sources":[{"label":"Giridih district","url":"https://giridih.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-giridih-jharkhandi-dham', 'shiva', 'Jharkhandi Dham', 'Jharkhand', 'Giridih', 'Giridih district', 'Shiva', 'Shaiva', '["Roofless","Raw Primordial","Primary Anchor"]', 'A roofless Shiva sanctuary where the lingam remains directly exposed to the elements, preserving an open-sky vertical alignment and raw grounding quality in the Giridih sacred landscape.', 'The district\'s primary roofless Shaiva grounding node.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jharkhand_Dham.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jharkhand_Dham.jpg', 'Mahashivratri and Shravan.', 'Open daily.', 'Casual.', 'Near Dhanwar.', '["Open air puja"]', '["Shivratri"]', '{"history":"Long-standing open-sky worship tradition in the Giridih region.","architecture":"Roofless structure.","darshan":"Raw and elemental.","seasonal":"Pleasant.","visitorNotes":"A key stop in the northern Jharkhand Shaiva route.","festivals":"Large Shivratri fair.","sources":[{"label":"Giridih","url":"https://giridih.nic.in/tourist-place/jharkhand-dham/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-giridih-khandoli-temple', 'shiva', 'Khandoli Temple', 'Jharkhand', 'Giridih', 'Giridih district', 'Shiva', 'Shaiva', '["Dam","Migratory Birds","Hill"]', 'Located near the Khandoli dam and hill, this Shiva temple attracts tourists who come for water sports and bird watching.', 'The dam and adventure activities.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Khandoli_Park_Giridih.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Khandoli_Park_Giridih.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Adventure park nearby.', '["Picnic"]', '["New Year"]', '{"history":"Modern development.","architecture":"Simple.","darshan":"Recreational.","seasonal":"Winter for birds.","visitorNotes":"Boating and climbing.","festivals":"Local gatherings.","sources":[{"label":"Giridih","url":"https://giridih.nic.in/tourist-place/khandoli/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-giridih-langta-baba-shiva-shrine', 'shiva', 'Langta Baba Shiva Shrine', 'Jharkhand', 'Giridih', 'Giridih district', 'Shiva (integrated shrine)', 'Shaiva/Folk', '["Siddha Interface","Folk Logic","Yoga Stability"]', 'A saint-associated devotional site in Giridih where integrated Shiva markers sustain a strong yoga-stability stream connecting formal Shaiva worship with local folk traditions.', 'Bridges mainstream Shaiva practices with local saint-lineage devotional culture.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Mahashivratri and local fair periods.', 'Open daily.', 'Modest temple attire.', 'In Giridih district local saint-shrine circuit.', '["Aarti","Saint-lineage offerings"]', '["Mahashivratri","Local annual melas"]', '{"history":"Evolved through local saint and community devotion traditions.","architecture":"Mixed shrine format around saint-node worship.","darshan":"Folk-integrated and meditative.","seasonal":"Most active during festival cycles.","visitorNotes":"Useful reference point for local oral-tradition circuits.","festivals":"Mahashivratri and local fairs.","sources":[{"label":"Giridih district","url":"https://giridih.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-giridih-usri-falls-shiva-node', 'shiva', 'Usri Falls Shiva Node', 'Jharkhand', 'Giridih', 'Giridih district', 'Shiva', 'Shaiva', '["Hydro Kinetic","Granite Steps","Waterfall Shrine"]', 'A waterfall-linked Shiva shrine where the Usri river drops across granite shelves, creating a charged hydro-kinetic devotional environment.', 'A sharp, river-ionized Shiva node in Giridih\'s natural waterfall corridor.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Usri_falls%2Cgiridih%2Cjharkhand.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Usri_falls%2Cgiridih%2Cjharkhand.jpg', 'Monsoon and winter.', 'Daylight hours.', 'Casual.', 'Waterfall zone; terrain can be slippery in monsoon.', '["Nature worship"]', '["New Year"]', '{"history":"Long-standing local shrine associated with Usri waterfall worship.","architecture":"Small shrine.","darshan":"Nature-charged and scenic.","seasonal":"Best flow in monsoon.","visitorNotes":"Visit with caution near wet rocks and strong flow periods.","festivals":"Shivratri and local seasonal gatherings.","sources":[{"label":"Giridih","url":"https://giridih.nic.in/tourist-place/usri-falls/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-godda-shivpur-ratneshwar-dham', 'shiva', 'Ratneshwar Dham', 'Jharkhand', 'Godda (Shivpur)', 'Godda district', 'Shiva', 'Shaiva', '["Many Shivalingas","Sawan Pilgrimage","Shivpur"]', 'A major Shiva dham in Shivpur mohalla of Godda town, known for its many Shivalingas and Sawan pilgrimage.', 'Kanwariyas bring holy water during Shravan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Sawan (Shravan).', 'Open daily.', 'Traditional preferred.', 'In Shivpur mohalla, Godda.', '["Jalabhishek"]', '["Shravan Kanwar","Mahashivratri"]', '{"history":"Prominent local pilgrimage site.","architecture":"Dham complex.","darshan":"Crowded in Shravan.","seasonal":"Peak in monsoon.","visitorNotes":"Devotees bring water from Sultanganj.","festivals":"Shravan Kanwar.","sources":[{"label":"Godda","url":"https://godda.nic.in/culture-heritage/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-goelkera-mahadevshal-temple', 'shiva', 'Mahadevshal Temple', 'Jharkhand', 'Goelkera', 'West Singhbhum', 'Shiva', 'Shaiva', '["Forest","Railway Line","Powerful"]', 'Located deep in the Saranda forest, this temple was once on the railway track. The track was diverted to save the temple.', 'The legend of the diverted railway line.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Shiva_Linga_Varanasi.jpg/640px-Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Shravan.', 'Daylight hours.', 'Casual.', 'Inside forest.', '["Stone offering"]', '["Shravani Mela"]', '{"history":"British era legend.","architecture":"Simple.","darshan":"Nature.","seasonal":"Green in monsoon.","visitorNotes":"Unique location.","festivals":"Shivratri.","sources":[{"label":"Chaibasa","url":"https://chaibasa.nic.in/tourist-place/mahadevshal-temple/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-gomia-luguburu-ghantabari', 'shiva', 'Luguburu Ghantabari', 'Jharkhand', 'Gomia', 'Bokaro district', 'Lugu Baba / Shiva', 'Santhal/Shaiva', '["Tribal","Lugu Baba","Cave"]', 'A supreme pilgrimage site for the Santhal community. Lugu Baba is revered here, often identified with Lord Shiva in syncretic traditions.', 'The massive tribal gathering.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Luguburu_Ghantabari_entrance.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Luguburu_Ghantabari_entrance.jpg', 'Kartik Purnima.', 'Open daily.', 'Casual/Traditional.', 'Respect tribal customs.', '["Nature worship"]', '["Luguburu Mela"]', '{"history":"Santhal heritage.","architecture":"Natural/Cave.","darshan":"Cultural.","seasonal":"Best in Kartik.","visitorNotes":"Significant cultural site.","festivals":"Kartik Purnima.","sources":[{"label":"Bokaro","url":"https://bokaro.nic.in/tourist-place/luguburu-ghantabari/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
