INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-hazaribagh-budhwa-mahadev', 'shiva', 'Budhwa Mahadev', 'Jharkhand', 'Hazaribagh', 'Hazaribagh district', 'Shiva', 'Shaiva', '["Ancient","500 Years Old","City"]', 'An ancient 500-year-old temple in the heart of Hazaribagh. Legend says the Linga appeared on its own. It is a major local landmark.', 'The ancient Swayambhu Linga.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Konch_Eshwar_Mahadev.jpg/640px-Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Monday.', 'Open daily.', 'Casual.', 'City center.', '["Daily Puja"]', '["Shivratri"]', '{"history":"16th Century.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"All year.","visitorNotes":"Very popular.","festivals":"Shivratri.","sources":[{"label":"Hazaribagh","url":"https://hazaribag.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-hazaribagh-canary-hill-temple', 'shiva', 'Canary Hill Temple', 'Jharkhand', 'Hazaribagh', 'Hazaribagh district', 'Shiva', 'Shaiva', '["Viewpoint","Watchtower","Nature"]', 'A famous landmark in Hazaribagh with a watchtower and a park. A small temple invites offering amidst the nature walk.', 'The view of Hazaribagh town.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hazaribagh_Canary_Hill.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hazaribagh_Canary_Hill.jpg', 'Sunset.', 'Daylight hours.', 'Casual.', 'Entry fee for park.', '["Sightseeing"]', '["None"]', '{"history":"Colonial park.","architecture":"British watchtower.","darshan":"Scenic.","seasonal":"Pleasant.","visitorNotes":"Monkeys present.","festivals":"New Year.","sources":[{"label":"Hazaribagh","url":"https://hazaribag.nic.in/tourist-place/canary-hill/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-itkhori-itkhori-sahasralinga', 'shiva', 'Itkhori Sahasralinga', 'Jharkhand', 'Itkhori', 'Chatra district', 'Shiva', 'Shaiva/Shakta', '["1008 Lingas","Sahasralinga","Bhadrakali"]', 'Located in the Bhadrakali temple complex, this monolithic black stone Linga has 1008 miniature Lingas carved on it.', 'The Sahasralinga sculpture.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Shiva_Linga_Varanasi.jpg/640px-Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Itkhori Mahotsav.', 'Open daily.', 'Casual.', 'Buddhist/Jain site too.', '["Abhishek"]', '["Itkhori Mahotsav","Shivratri"]', '{"history":"9th Century.","architecture":"Ancient sculpture.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"See Buddhist stupas too.","festivals":"Shivratri.","sources":[{"label":"Chatra","url":"https://chatra.nic.in/tourist-place/maa-bhadrakali-temple-itkhori/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
