INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-jamshedpur-dalma-shiva-temple', 'shiva', 'Dalma Shiva Temple', 'Jharkhand', 'Jamshedpur', 'East Singhbhum', 'Shiva', 'Shaiva', '["Wildlife Sanctuary","Hill Top","Trekking"]', 'Situated atop the Dalma hills within a wildlife sanctuary, this ancient Shiva temple is a favorite for trekkers and devotees.', 'The trek through the elephant sanctuary.', 'https://upload.wikimedia.org/wikipedia/commons/4/45/Shiva_lingam_dalma_hills.jpg', 'Wikimedia Commons', 'https://upload.wikimedia.org/wikipedia/commons/4/45/Shiva_lingam_dalma_hills.jpg', 'Winter/Shivratri.', 'Daylight hours.', 'Casual.', 'Check sanctuary timings.', '["Hill worship"]', '["Shivratri"]', '{"history":"Ancient.","architecture":"Hill temple.","darshan":"Nature.","seasonal":"Best in winter.","visitorNotes":"Elephants nearby.","festivals":"Shivratri.","sources":[{"label":"Dalma","url":"https://eastsinghbhum.nic.in/tourist-place/dalma-wild-life-sanctuary/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-jamshedpur-dimna-lake-temple', 'shiva', 'Dimna Lake Temple', 'Jharkhand', 'Jamshedpur', 'East Singhbhum', 'Shiva', 'Shaiva', '["Lake","Dalma View","Nature"]', 'At the foot of Dalma hills, Dimna Lake is a reservoir with scenic beauty. Small shrines dot the area for the spiritual tourist.', 'The lake view.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dimna_Lake%2C_Jamshedpur.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dimna_Lake%2C_Jamshedpur.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Picnic spot.', '["Nature worship"]', '["New Year"]', '{"history":"Modern.","architecture":"Small shrines.","darshan":"Scenic.","seasonal":"Pleasant.","visitorNotes":"Great for walking.","festivals":"Picnic season.","sources":[{"label":"Jamshedpur","url":"https://eastsinghbhum.nic.in/tourist-place/dimna-lake/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-jamtara-parvat-vihar-temple', 'shiva', 'Parvat Vihar Temple', 'Jharkhand', 'Jamtara', 'Jamtara district', 'Shiva', 'Shaiva', '["Park","Sunrise","Hill"]', 'A hilltop park and temple complex that offers a beautiful sunrise view. It is a popular recreational and spiritual spot in Jamtara.', 'The sunrise view.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Trikut_Pahar.jpg/640px-Trikut_Pahar.jpg', 'Wikimedia Commons (Representational Hill)', 'https://commons.wikimedia.org/wiki/File:Trikut_Pahar.jpg', 'Winter.', 'Morning/Evening.', 'Casual.', '5 km from station.', '["Morning prayer"]', '["New Year"]', '{"history":"Modern.","architecture":"Park style.","darshan":"Scenic.","seasonal":"Pleasant.","visitorNotes":"Good for kids.","festivals":"Local fairs.","sources":[{"label":"Jamtara","url":"https://jamtara.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-jayda-jayda-temple', 'shiva', 'Jayda Temple', 'Jharkhand', 'Jayda', 'Seraikela Kharsawan district', 'Shiva', 'Shaiva', '["Riverbank","Ancient","Makar Sankranti Fair"]', 'An ancient Shiva temple on the banks of the Swarnarekha river, known for its annual fair during Makar Sankranti (Tusu Festival).', 'Riverbank shrine with a major annual fair.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jayda_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jayda_Temple.jpg', 'Makar Sankranti.', 'Open daily.', 'Traditional preferred.', 'Near Chandil, on the Ranchi-Tata road.', '["River worship","Jal offering"]', '["Makar Sankranti","Tusu Festival"]', '{"history":"Ancient pilgrimage site.","architecture":"Temple by the river.","darshan":"Pilgrimage.","seasonal":"Busy during Sankranti.","visitorNotes":"Easy road access from NH-33.","festivals":"Annual fair on Sankranti.","sources":[{"label":"Seraikela Kharsawan","url":"https://seraikela.nic.in/tourist-place/jayda-temple/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-jharia-bhootnath-mandir', 'shiva', 'Bhootnath Mandir', 'Jharkhand', 'Jharia', 'Dhanbad district', 'Shiva (Bhootnath)', 'Shaiva/Tantric', '["Cremation Guard","Tantric","Powerful"]', 'Located near the cremation grounds (Shamshan), this temple is dedicated to Shiva as Bhootnath, the lord of spirits. It is a powerful tantric site.', 'The intense atmosphere.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Konch_Eshwar_Mahadev.jpg/640px-Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Shivratri/Amavasya.', 'Open daily.', 'Casual.', 'Respect traditions.', '["Bhasma Aarti"]', '["Shivratri"]', '{"history":"Local.","architecture":"Traditional.","darshan":"Intense.","seasonal":"All year.","visitorNotes":"Not for faint hearted.","festivals":"Kali Puja.","sources":[{"label":"Dhanbad","url":"https://dhanbad.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-karon-karneshwar-dham-karon', 'shiva', 'Karneshwar Dham (Karon)', 'Jharkhand', 'Karon', 'Deoghar district', 'Shiva (Karneshwar)', 'Shaiva', '["Temple Complex","Karna","Ancient"]', 'An ancient temple complex associated with Karna, featuring the main Shiva shrine and 27 additional temples.', 'A 28-temple complex dedicated to Shiva.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Mahashivratri.', 'Open daily.', 'Traditional preferred.', 'Located in Karon, Deoghar.', '["Abhishek"]', '["Mahashivratri"]', '{"history":"Linked in tradition to Karna.","architecture":"Multi-shrine complex.","darshan":"Pilgrimage.","seasonal":"Festive during Mahashivratri.","visitorNotes":"Complex includes multiple small temples.","festivals":"Mahashivratri.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Karneshwar_Dham","type":"Wikipedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-katri-river-belt-dhanbad-lillori-sthan-shiva-node', 'shiva', 'Lillori Sthan Shiva Node', 'Jharkhand', 'Katri river belt, Dhanbad', 'Dhanbad district', 'Shiva (integrated with Lillori Sthan complex)', 'Shaiva/Shakta', '["Shiva Shakti Interface","Miner Safety Ground","Ancient Residue"]', 'A Shiva-linked stabilizing node in the Lillori Sthan zone near the Katri river corridor, where integrated Shakti and Pashupata streams are both actively observed by local communities.', 'A miner-linked pre-shift grounding shrine in Dhanbad\'s earth-work culture.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Mahashivratri and Shravan.', 'Open daily.', 'Modest temple attire.', 'Katri river-side pilgrimage zone.', '["Jalabhishek","Safety and livelihood prayers"]', '["Mahashivratri","Navratri-linked local observances"]', '{"history":"Evolved as a local protective worship interface around mining communities.","architecture":"Mixed rural shrine structures.","darshan":"Protective and grounding.","seasonal":"Active through year with peaks in monsoon festivals.","visitorNotes":"Visit respectfully as an active community faith node.","festivals":"Shivratri and local melas.","sources":[{"label":"Dhanbad district","url":"https://dhanbad.nic.in/","type":"Government"}]}', '2026-02-25T00:00:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-kechki-kechki-sangam-temple', 'shiva', 'Kechki Sangam Temple', 'Jharkhand', 'Kechki', 'Palamau district', 'Shiva', 'Shaiva', '["Confluence","River","Picnic"]', 'Located at the confluence of Koel and Auranga rivers, this spot has a Shiva temple and was a setting for Satyajit Ray\'s films.', 'The scenic river confluence.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg/640px-An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:An_old_Temple_dedicated_to_the_Lord_Shiva(_Haleswar_Mandir).jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Betla.', '["River worship"]', '["Makar Sankranti"]', '{"history":"Colonial connection.","architecture":"Simple.","darshan":"Scenic.","seasonal":"Best in winter.","visitorNotes":"Visit Betla Park too.","festivals":"Local fairs.","sources":[{"label":"Palamau","url":"https://palamu.nic.in/tourist-place/kechki/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-khakparta-prachin-shiv-mandir-khakparta', 'shiva', 'Prachin Shiv Mandir (Khakparta)', 'Jharkhand', 'Khakparta', 'Lohardaga district', 'Shiva', 'Shaiva', '["Hilltop","Prachin","Scenic"]', 'A popular hilltop Shiva temple in Khakparta village, known for its tranquil ambiance and scenic surroundings.', 'A quiet hilltop shrine near Lohardaga.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Khakparta_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Khakparta_Temple.jpg', 'Winter / Mahashivratri.', 'Daylight hours.', 'Casual.', 'Around 8 km from Lohardaga HQ.', '["Hill worship"]', '["Mahashivratri"]', '{"history":"Local heritage site.","architecture":"Hilltop shrine.","darshan":"Peaceful.","seasonal":"Pleasant in winter.","visitorNotes":"Short climb to the temple.","festivals":"Mahashivratri.","sources":[{"label":"Lohardaga","url":"https://lohardaga.nic.in/tourist-place/prachin-shiv-mandir-khakparta/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-khunti-amreshwar-dham', 'shiva', 'Amreshwar Dham', 'Jharkhand', 'Khunti', 'Khunti district', 'Shiva (Amreshwar)', 'Shaiva', '["Swayambhu","Angrabari","Peaceful"]', 'Also known as Angrabari, it houses a Swayambhu Shivlinga under a mango tree. It is a major pilgrimage site in the region.', 'The self-manifested Linga and serene complex.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Amreshwar_temple%2C_Torpa%2C_Jharkhand_.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amreshwar_temple%2C_Torpa%2C_Jharkhand_.jpg', 'All year.', 'Open daily.', 'Casual.', 'Near Khunti town.', '["Belpatra offering"]', '["Shivratri","Sawan"]', '{"history":"Modern discovery.","architecture":"Temple complex.","darshan":"Devotional.","seasonal":"Pleasant.","visitorNotes":"Very clean and maintained.","festivals":"Shivratri.","sources":[{"label":"Khunti","url":"https://khunti.nic.in/tourist-place/amreshwar-dham/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-koderma-dhwajadhari-pahari', 'shiva', 'Dhwajadhari Pahari', 'Jharkhand', 'Koderma', 'Koderma district', 'Shiva', 'Shaiva', '["Hill Top","700 Steps","Scenic"]', 'A significant pilgrimage site located on a hill, requiring a climb of over 700 steps. It houses shrines for Shiva, Parvati, and Hanuman.', 'The panoramic view and the climb.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dhwajadhari_Hill.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dhwajadhari_Hill.jpg', 'Winter/Shivratri.', 'Daylight hours.', 'Casual.', 'Be prepared for stairs.', '["Hill trekking"]', '["Shivratri"]', '{"history":"Local heritage.","architecture":"Hill temple.","darshan":"Physical & Spiritual.","seasonal":"Pleasant.","visitorNotes":"Carry water.","festivals":"Shivratri Mela.","sources":[{"label":"Koderma","url":"https://koderma.nic.in/tourist-place/dhwajadhari-hill/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-kumhari-ghas-chechaka-dham-chechakeshwar', 'shiva', 'Chechaka Dham (Chechakeshwar)', 'Jharkhand', 'Kumhari (Ghas)', 'Bokaro district', 'Shiva', 'Shaiva', '["Mini Baba Dham","Pilgrimage","Damodar"]', 'Chechaka Dham, also called Chechakeshwar Dham, is a major Shiva shrine in Bokaro often known locally as Mini Baba Dham.', 'Known locally as Mini Baba Dham.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Oct-Mar.', 'Open daily.', 'Traditional preferred.', 'About 20 km from Bokaro HQ.', '["Jalabhishek","Belpatra offering"]', '["Makar Sankranti","Mahashivratri"]', '{"history":"The lingam is described locally as representing Brahma, Vishnu, and Maheshwara.","architecture":"Temple complex.","darshan":"Pilgrimage focused.","seasonal":"Best in winter.","visitorNotes":"Also called Chechakeshwar Dham.","festivals":"Crowds peak during Makar Sankranti.","sources":[{"label":"Bokaro","url":"https://bokaro.nic.in/tourist-place/chechaka-dham/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-latehar-sati-ghat-temple', 'shiva', 'Sati Ghat Temple', 'Jharkhand', 'Latehar', 'Latehar district', 'Shiva', 'Shaiva', '["River","Fair","Local"]', 'A prominent Ghat on the banks of the Damodar river. It hosts a massive fair on Makar Sankranti and has a Shiva temple.', 'The river bank fair.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Konch_Eshwar_Mahadev.jpg/640px-Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Makar Sankranti.', 'Open daily.', 'Casual.', 'Fair in Jan.', '["River dip"]', '["Makar Sankranti"]', '{"history":"Local tradition.","architecture":"Ghat style.","darshan":"Festive.","seasonal":"Winter.","visitorNotes":"Great culture.","festivals":"Huge gathering.","sources":[{"label":"Latehar","url":"https://latehar.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-latehar-tattapani-shrine', 'shiva', 'Tattapani Shrine', 'Jharkhand', 'Latehar', 'Latehar district', 'Shiva', 'Shaiva', '["Hot Spring","Sulfur","Healing"]', 'Famous for its hot sulfur springs believed to cure skin diseases. A small shrine is present where locals offer prayers before bathing.', 'The hot water springs.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Budhanath_Temple_Bhagalpur.jpg/640px-Budhanath_Temple_Bhagalpur.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Budhanath_Temple_Bhagalpur.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Medicinal water.', '["Bath"]', '["Makar Sankranti"]', '{"history":"Natural.","architecture":"Open shrine.","darshan":"Wellness.","seasonal":"Winter is best.","visitorNotes":"Bring change of clothes.","festivals":"Mela.","sources":[{"label":"Latehar","url":"https://latehar.nic.in/tourist-place/tattapani/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-lohardaga-akhileshwer-dham', 'shiva', 'Akhileshwer Dham', 'Jharkhand', 'Lohardaga', 'Lohardaga district', 'Shiva', 'Shaiva', '["8th Century","Sculpture","Peace"]', 'An ancient temple site dating back to the 8th century, housing beautiful sculptures and a revered Shiva Linga.', 'The ancient stone carvings.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Konch_Eshwar_Mahadev.jpg/640px-Konch_Eshwar_Mahadev.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Konch_Eshwar_Mahadev.jpg', 'Shivratri.', 'Open daily.', 'Casual.', 'Near Lohardaga.', '["Rudra Abhishek"]', '["Shivratri"]', '{"history":"Medieval.","architecture":"Stone.","darshan":"Historical.","seasonal":"Pleasant.","visitorNotes":"Hidden gem.","festivals":"Shivratri.","sources":[{"label":"Lohardaga","url":"https://lohardaga.nic.in/tourist-place/akhileshwer-dham/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
