INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-mahesiadighi-deori-mahesiadighi-shiv-dham', 'shiva', 'Mahesiadighi Shiv Dham', 'Jharkhand', 'Mahesiadighi (Deori)', 'Giridih district', 'Shiva', 'Shaiva', '["Village Shrine","Heritage","150 Years"]', 'A well-known Shiv Dham in Mahesiadighi village, noted as a long-standing shrine in the area.', 'Historic village Shiva shrine.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Mahashivratri.', 'Open daily.', 'Casual.', 'In Deori block, Giridih.', '["Jal offering"]', '["Mahashivratri"]', '{"history":"Shrine of about 150 years.","architecture":"Village temple.","darshan":"Community worship.","seasonal":"Festive during Shivratri.","visitorNotes":"Local community centerpiece.","festivals":"Mahashivratri.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mahesiadighi","type":"Wikipedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-mahuadand-bhim-chulha', 'shiva', 'Bhim Chulha', 'Jharkhand', 'Mahuadand', 'Palamau district', 'Shiva / Bhima', 'Folk/Shaiva', '["Mahabharata","Rock","Legend"]', 'A massive rock formation resembling a stove (Chulha) believed to be used by Bhima. Local tribal rituals and Shiva worship happen here.', 'The mythology and rock size.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Mandar_Hill.jpg/640px-Mandar_Hill.jpg', 'Wikimedia Commons (Representational Hill)', 'https://commons.wikimedia.org/wiki/File:Mandar_Hill.jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Nature spot.', '["Rock worship"]', '["Local fairs"]', '{"history":"Mahabharata.","architecture":"Natural.","darshan":"Mythological.","seasonal":"Pleasant.","visitorNotes":"Unique geology.","festivals":"Tribal fairs.","sources":[{"label":"Palamau","url":"https://palamu.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-maithon-kalyaneshwari-adjacent-shiva-nodes', 'shiva', 'Kalyaneshwari-adjacent Shiva Nodes', 'Jharkhand', 'Maithon', 'Dhanbad district', 'Shiva', 'Shaiva', '["Hydro Electric","Reservoir Stabilizer","Border Corridor"]', 'A cluster of Shiva shrines in the Maithon-Kalyaneshwari border belt where the reservoir system creates a strong hydro-pressure stabilization loop for eastern Dhanbad worship routes.', 'Highly stable Shiva routing zone near Maithon Dam and the Bengal border.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Shiva_Linga_Varanasi.jpg/640px-Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Winter and Shivratri.', 'Open daily.', 'Casual.', 'Maithon border belt near dam and Kalyaneshwari route.', '["Jalabhishek","Hill and river puja"]', '["Mahashivratri"]', '{"history":"Developed as part of the larger Maithon sacred and dam-zone travel corridor.","architecture":"Mixed hill and small-shrine architecture.","darshan":"Scenic and stabilizing.","seasonal":"Pleasant in winter; active year-round.","visitorNotes":"Often paired with Kalyaneshwari-side routes.","festivals":"Shivratri.","sources":[{"label":"Dhanbad","url":"https://dhanbad.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-maluti-maluti-shiva-temples', 'shiva', 'Maluti Shiva Temples', 'Jharkhand', 'Maluti', 'Dumka district', 'Shiva (Maulishwar)', 'Shaiva/Tantric', '["Terracotta","Temple Town","Heritage"]', 'A village of 72 ancient terracotta temples, mostly dedicated to Shiva. It is a hidden heritage gem of Jharkhand.', 'The exquisite terracotta carvings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Maluti_Temples._Maluti.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Maluti_Temples._Maluti.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Heritage village.', '["Kali Puja","Shiva Puja"]', '["Kali Puja"]', '{"history":"Baj Basanta dynasty.","architecture":"Terracotta/Chala.","darshan":"Artistic.","seasonal":"Pleasant.","visitorNotes":"Walk around the village.","festivals":"Diwali.","sources":[{"label":"Dumka","url":"https://dumka.nic.in/tourist-place/maluti/","type":"Government"}]}', '2026-02-23T02:12:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-mandal-mandal-dam-shiva', 'shiva', 'Mandal Dam Shiva', 'Jharkhand', 'Mandal', 'Latehar district', 'Shiva', 'Shaiva', '["Dam","North Koel","Nature"]', 'Near the North Koel Reservoir (Mandal Dam), local shrines dedicated to Shiva protect the waters and the forest.', 'The dam and forest view.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg/640px-An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:An_old_Temple_dedicated_to_the_Lord_Shiva(_Haleswar_Mandir).jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Inside tiger reserve area.', '["Nature worship"]', '["Shivratri"]', '{"history":"Modern.","architecture":"Simple.","darshan":"Scenic.","seasonal":"Best in winter.","visitorNotes":"Part of Palamau Tiger Reserve.","festivals":"Local fairs.","sources":[{"label":"Latehar","url":"https://latehar.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
