INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-pakur-shiv-sheetla-mandir', 'shiva', 'Shiv Sheetla Mandir', 'Jharkhand', 'Pakur', 'Pakur district', 'Shiva / Sheetla', 'Shaiva/Shakta', '["Local","Devotion","Shakti"]', 'A revered temple in Pakur dedicated to Lord Shiva and Goddess Sheetla. It is a center of local faith and festivals.', 'The dual worship of Shiva and Shakti.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Shiva_Linga_Varanasi.jpg/640px-Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Basoda/Shivratri.', 'Open daily.', 'Casual.', 'In Pakur town.', '["Jal offering"]', '["Sheetla Ashtami"]', '{"history":"Local.","architecture":"Traditional.","darshan":"Devotional.","seasonal":"All year.","visitorNotes":"Clean and peaceful.","festivals":"Shivratri.","sources":[{"label":"Pakur","url":"https://pakur.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
