INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-pratappur-kunda-cave-temple', 'shiva', 'Kunda Cave Temple', 'Jharkhand', 'Pratappur', 'Chatra district', 'Shiva', 'Shaiva', '["Cave","Ruins","Historical"]', 'An ancient site with a cave temple dedicated to Shiva and ruins of the Kunda Palace. It hosts a massive fair on Shivratri.', 'The cave and the historical ruins.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Gupteshwar_Mahadev.jpg/640px-Gupteshwar_Mahadev.jpg', 'Wikimedia Commons (Representational Cave)', 'https://commons.wikimedia.org/wiki/File:Gupteshwar_Mahadev.jpg', 'Shivratri.', 'Daylight hours.', 'Casual.', 'Remote area.', '["Cave worship"]', '["Pratappur Mela"]', '{"history":"17th Century.","architecture":"Indo-Mughal ruins.","darshan":"Historical.","seasonal":"Pleasant.","visitorNotes":"Explore the fort ruins.","festivals":"Shivratri.","sources":[{"label":"Chatra","url":"https://chatra.nic.in/tourist-place/kunda-cave/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-rajrappa-rajrappa-shiva-temple', 'shiva', 'Rajrappa Shiva Temple', 'Jharkhand', 'Rajrappa', 'Ramgarh district', 'Shiva / Chhinnamasta', 'Shakta/Shaiva', '["Shakti Peeth","Confluence","Tantric"]', 'Adjacent to the famous Chhinnamasta Temple, this Shiva temple is part of the sacred complex at the confluence of Damodar and Bhairavi rivers.', 'The rock formations and river confluence.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rajrappa_Temple_2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rajrappa_Temple_2.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Scenic drive.', '["Tantric rituals"]', '["Makar Sankranti"]', '{"history":"Ancient Shakti Peeth.","architecture":"North Indian.","darshan":"Powerful.","seasonal":"Best in winter.","visitorNotes":"Boating available.","festivals":"Navratri.","sources":[{"label":"Ramgarh","url":"https://ramgarh.nic.in/tourist-place/rajrappa-temple/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-ramgarh-kaitha-shiv-mandir', 'shiva', 'Kaitha Shiv Mandir', 'Jharkhand', 'Ramgarh', 'Ramgarh district', 'Shiva', 'Shaiva', '["Monument of National Importance","17th Century","Architectural Blend"]', 'An ancient Shiva temple built in 1670 by Maharaja Dalel Singh, recognized as a monument of national importance.', 'A 12-foot Shivling beneath a naga canopy.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'All year.', 'Open daily.', 'Traditional preferred.', 'About 3 km from Ramgarh.', '["Jalabhishek"]', '["Mahashivratri"]', '{"history":"Built in 1670 by Maharaja Dalel Singh.","architecture":"Blend of Bengal, Rajput, and Mughal styles.","darshan":"Historic.","seasonal":"Pleasant year-round.","visitorNotes":"Declared a national monument.","festivals":"Mahashivratri.","sources":[{"label":"Jharkhand Tourism","url":"https://tourism.jharkhand.gov.in/destinationDetails/212","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-ranchi-ghaghari-shiva-temple', 'shiva', 'Ghaghari Shiva Temple', 'Jharkhand', 'Ranchi', 'Ranchi district', 'Shiva', 'Shaiva', '["Local Temple","Mahadev","Shaiva"]', 'A local Shiva shrine in Ranchi district known as Ghaghari Shiva Temple.', 'Community-led Shiva worship in Ranchi.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Mahashivratri and Mondays.', 'Open daily; local timings vary.', 'Traditional preferred.', 'Part of Ranchi district local temple network.', '["Abhishek","Evening aarti"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Maintained through local devotional continuity in the Ranchi area.","architecture":"Small regional shrine.","darshan":"Steady local footfall through the week.","seasonal":"Peak attendance during Shravan.","visitorNotes":"Weekday mornings are usually less crowded.","festivals":"Mahashivratri is the major annual observance.","sources":[{"label":"Ranchi district","url":"https://ranchi.nic.in/","type":"Government"}]}', '2026-02-23T02:07:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-ranchi-kurtiya-pahad-shiv-mandir', 'shiva', 'Kurtiya Pahad Shiv Mandir', 'Jharkhand', 'Ranchi', 'Ranchi district', 'Shiva', 'Shaiva', '["Hilltop","Local Shrine","Shaiva"]', 'A hilltop Shiva shrine in Ranchi district known in local worship circuits as Kurtiya Pahad Shiv Mandir.', 'Hill darshan in the Ranchi urban-periphery belt.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Shravan month and Mahashivratri.', 'Daylight hours; local timings vary.', 'Traditional preferred.', 'Expect short uphill access near the shrine.', '["Jalabhishek","Aarti"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"The shrine is part of Ranchi\'s local neighborhood Shiva worship tradition.","architecture":"Small hill shrine format.","darshan":"Usually busiest on Mondays and festival dates.","seasonal":"Monsoon and winter are preferred by devotees.","visitorNotes":"Use morning slots for easier darshan.","festivals":"Mahashivratri and Shravan observances are the main draws.","sources":[{"label":"Ranchi district","url":"https://ranchi.nic.in/tourist-places/","type":"Government"}]}', '2026-02-23T02:05:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-ranchi-mahadev-bera', 'shiva', 'Mahadev Bera', 'Jharkhand', 'Ranchi', 'Ranchi district', 'Shiva', 'Shaiva', '["Rock Formation","Nature","Remote"]', 'A site known for its unique rock formations and a Shiva temple. It is a popular spot for locals seeking peace.', 'The rocky landscape.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Shiva_Linga_Varanasi.jpg/640px-Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Outskirts.', '["Nature worship"]', '["Shivratri"]', '{"history":"Unknown.","architecture":"Rock/Simple.","darshan":"Natural.","seasonal":"Best in winter.","visitorNotes":"Offbeat location.","festivals":"Shivratri.","sources":[{"label":"Ranchi","url":"https://ranchi.nic.in/tourist-places/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
