INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-ranchi-pahari-mandir', 'shiva', 'Pahari Mandir', 'Jharkhand', 'Ranchi', 'Ranchi district', 'Shiva', 'Shaiva', '["Hill Top","City View","Freedom Fighter"]', 'Located on a hill (Phansi Tongri), this temple has a history linked to freedom fighters. It offers a panoramic view of Ranchi.', 'The 468 steps and the city view.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pahari_Mandir_-_Ranchi_Hill_9242.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pahari_Mandir_-_Ranchi_Hill_9242.JPG', 'Winter/Shivratri.', 'Sunrise to Sunset.', 'Casual.', 'Steep climb.', '["Jal offering"]', '["Shivratri","Independence Day"]', '{"history":"British era execution hill.","architecture":"Hilltop shrine.","darshan":"Scenic.","seasonal":"Pleasant.","visitorNotes":"Carry water.","festivals":"Tricolor hoisting.","sources":[{"label":"Ranchi","url":"https://ranchi.nic.in/tourist-place/pahari-mandir/","type":"Government"}]}', '2026-02-23T02:02:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
