INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-ranchi-sureshwar-mahadev-mandir', 'shiva', 'Sureshwar Mahadev Mandir', 'Jharkhand', 'Ranchi', 'Chutia, Ranchi district', 'Shiva', 'Shaiva', '["108-ft Temple","Modern Landmark","Shiv Barat"]', 'A modern 108-foot-high Shivling-shaped temple in Chutia, built over a decade and consecrated in 2022.', '108-foot temple structure.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Mahashivratri / Shravan.', 'Open daily.', 'Traditional preferred.', 'Located in Chutia, Ranchi.', '["Rudrabhishek"]', '["Mahashivratri"]', '{"history":"Construction took about 10 years; consecration in 2022.","architecture":"Shivling-shaped temple.","darshan":"Landmark.","seasonal":"Crowded during major festivals.","visitorNotes":"Known for Shiv Barat celebrations.","festivals":"Mahashivratri.","sources":[{"label":"Dainik Bhaskar","url":"https://www.bhaskar.com/local/jharkhand/ranchi/news/jharkhands-tallest-108-feet-pagoda-became-sureshwar-mahadev-temple-it-took-10-years-to-build-130939552.html","type":"News"}]}', '2026-02-23T02:03:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-ranchi-swarnarekha-dham-shri-shiv-mandir', 'shiva', 'Swarnarekha Dham Shri Shiv Mandir', 'Jharkhand', 'Ranchi', 'Swarnarekha belt, Ranchi district', 'Shiva', 'Shaiva', '["Swarnarekha","Riverbank","Shaiva"]', 'A Shiva temple in Ranchi\'s Swarnarekha river belt, visited for regular Mahadev worship and river-linked rituals.', 'Swarnarekha-side Shiva darshan.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Morning darshan and Shravan month.', 'Open daily; local timings vary.', 'Traditional preferred.', 'Best visited in daytime for easier access.', '["Jal offering","Rudrabhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Swarnarekha riverbank shrines form an important part of Ranchi\'s local Shiva tradition.","architecture":"Local shrine architecture.","darshan":"Commonly visited by neighborhood devotees.","seasonal":"Shravan sees the highest devotional turnout.","visitorNotes":"Crowds increase significantly on Mondays in Shravan.","festivals":"Mahashivratri and Shravan are key periods.","sources":[{"label":"Ranchi district","url":"https://ranchi.nic.in/tourist-places/","type":"Government"}]}', '2026-02-23T02:06:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-saraiyahat-baba-sumeshwarnath-temple', 'shiva', 'Baba Sumeshwarnath Temple', 'Jharkhand', 'Saraiyahat', 'Dumka district', 'Shiva', 'Shaiva', '["Saraiyahat","Large Temple","Mahashivratri"]', 'A major Shiva temple in Saraiyahat block, known for large Mahashivratri gatherings.', 'Big Shiva temple in Saraiyahat.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shiva_Linga_Varanasi.jpg', 'Wikimedia Commons (Representational)', 'https://commons.wikimedia.org/wiki/File:Shiva_Linga_Varanasi.jpg', 'Mahashivratri.', 'Open daily.', 'Traditional preferred.', 'Around 60 km from Dumka HQ.', '["Jalabhishek"]', '["Mahashivratri"]', '{"history":"Important local pilgrimage site.","architecture":"Large temple.","darshan":"Pilgrimage.","seasonal":"Crowded during festivals.","visitorNotes":"Known for Mahashivratri worship.","festivals":"Mahashivratri.","sources":[{"label":"Dumka","url":"https://dumka.nic.in/places-of-interest/","type":"Government"}]}', '2026-02-23T02:11:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-jharkhand-shahpur-shahpur-fort-temple', 'shiva', 'Shahpur Fort Temple', 'Jharkhand', 'Shahpur', 'Palamau district', 'Shiva', 'Shaiva', '["Fort","Royal","History"]', 'Located within the historic Shahpur Fort (Chera Fort), this temple was the place of worship for the royal family. It overlooks the Koel river.', 'The fort view and history.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg/640px-An_old_Temple_dedicated_to_the_Lord_Shiva%28_Haleswar_Mandir%29.jpg', 'Wikimedia Commons (Representational Ruins)', 'https://commons.wikimedia.org/wiki/File:An_old_Temple_dedicated_to_the_Lord_Shiva(_Haleswar_Mandir).jpg', 'Winter.', 'Daylight hours.', 'Casual.', 'Enter fort.', '["Heritage view"]', '["Shivratri"]', '{"history":"Chero dynasty.","architecture":"Fort style.","darshan":"Historical.","seasonal":"Pleasant.","visitorNotes":"See the fort.","festivals":"Local fairs.","sources":[{"label":"Palamau","url":"https://palamu.nic.in/tourist-place/shahpur-fort/","type":"Government"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
