INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-bhimbetka-bhimbetka-pre-sutra-shrines', 'shiva', 'Bhimbetka Pre-Sutra Shrines', 'Madhya Pradesh', 'Bhimbetka', 'Bhimbetka rock shelters, Raisen district', 'Shiva (primordial marker forms)', 'Shaiva/Pre-classical sacred landscape', '["Raisen","Bhimbetka","Primordial Shiva"]', 'Within the Bhimbetka rock-shelter landscape, natural stone forms and early sacred markers are locally read as primordial Shiva expressions in a deep-time pre-classical ritual environment.', 'Sub-acoustic pre-historic sacred memory node in the Bhimbetka shelter zone.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Morning and cooler daylight hours.', 'Open daily; ASI/site timings vary.', 'Modest attire recommended for sacred site visits.', 'Treat as a sacred-heritage landscape entry; follow protected-site rules.', '["Darshan","Meditative observation"]', '["Mahashivratri (regional observance)"]', '{"history":"Bhimbetka preserves one of the oldest known human cultural landscapes in central India, with layered sacred interpretations over time.","architecture":"Natural rock shelters with symbolic sacred reading in later traditions.","visitorNotes":"Respect archaeology restrictions and avoid touching protected surfaces.","sources":[{"label":"Bhimbetka Rock Shelters","url":"https://en.wikipedia.org/wiki/Bhimbetka_rock_shelters","type":"Heritage reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Bhimbetka%20Raisen","type":"Map search"}]}', '2026-02-25T20:05:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-25T14:35:00Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-bhind-vankhandeshwar-temple', 'shiva', 'Vankhandeshwar Temple', 'Madhya Pradesh', 'Bhind', 'Bhind District', 'Shiva', 'Shaiva', '["Bhind","Akhand Jyoti","Mahashivratri"]', 'An old Shiva temple in Bhind known for its akhand jyoti and Monday maha aarti.', 'Eternal flame and weekly Shiva worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vankhandeshwar%20mahadev%20bhind.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vankhandeshwar_mahadev_bhind.jpg', 'Monday aarti and evening darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect larger crowds during Mahashivratri.', '["Daily puja","Monday maha aarti"]', '["Mahashivratri"]', '{"history":"Bhind district tourism describes Vankhandeshwar as an old Shiva temple in Bhind with an eternal flame (akhand jyoti).","architecture":"The same source highlights the temple\'s Monday maha aarti and annual Mahashivratri fair.","puranicView":"The shrine is dedicated to Shiva and draws regular weekly worship by local devotees.","puranicSources":[{"label":"Vankhandeshwar Temple (Bhind)","url":"https://bhind.nic.in/en/tourist-place/vankhandeshwar-temple/","type":"Government tourism"}],"folklore":"The akhand jyoti and Mahashivratri fair are central to the temple\'s living tradition.","folkloreSources":[{"label":"Vankhandeshwar Temple (Bhind)","url":"https://bhind.nic.in/en/tourist-place/vankhandeshwar-temple/","type":"Government tourism"}],"sources":[{"label":"Vankhandeshwar Temple (Bhind)","url":"https://bhind.nic.in/en/tourist-place/vankhandeshwar-temple/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-bhojpur-bhojpur-temple-bhojeshwar-mahadev', 'shiva', 'Bhojpur Temple (Bhojeshwar Mahadev)', 'Madhya Pradesh', 'Bhojpur', 'Raisen District', 'Shiva', 'Shaiva', '["High Voltage Motherboard","Unfinished Circuit","Monolithic Linga"]', 'Commissioned in the age of King Bhoja, this monumental yet unfinished temple enshrines one of India\'s largest monolithic Shivalingas and preserves an unusually raw open-circuit architectural energy.', 'A towering vertical Shiva transmitter centered on a colossal single-stone lingam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhojeshwar%20Temple,%20Bhojpur.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bhojeshwar_Temple,_Bhojpur.jpg', 'Morning visits for calmer darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage site with uneven stone flooring.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Wikipedia describes Bhojeshwar as an incomplete 11th-century Shiva temple at Bhojpur, associated with Paramara king Bhoja and housing a massive lingam.","architecture":"The sanctum centers on a huge lingam and preserves unfinished architectural elements that reveal the temple\'s construction plan.","puranicView":"The shrine\'s worship centers on Shiva in linga form, with devotion sustained at the historic site.","puranicSources":[{"label":"Bhojeshwar Temple","url":"https://en.wikipedia.org/wiki/Bhojeshwar_Temple","type":"Encyclopedia"}],"folklore":"Local tradition links the site to Raja Bhoja\'s temple-building patronage, reinforcing its identity as a Paramara-era Shiva shrine.","folkloreSources":[{"label":"Bhojeshwar Temple","url":"https://en.wikipedia.org/wiki/Bhojeshwar_Temple","type":"Encyclopedia"}],"sources":[{"label":"Bhojeshwar Temple","url":"https://en.wikipedia.org/wiki/Bhojeshwar_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
