INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shakti-madhya-pradesh-khajuraho-chausath-yogini-temple-khajuraho', 'shakti', 'Chausath Yogini Temple (Khajuraho)', 'Madhya Pradesh', 'Khajuraho', 'Chhatarpur district', 'Yoginis', 'Tantric', '["Yogini","Granite","Oldest"]', 'The oldest temple in Khajuraho; dedicated to the 64 Yoginis and made of granite.', 'Oldest Khajuraho temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chausath_Yogini_temple%2C_Khajuraho%2C_Madhya_Pradesh.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chausath_Yogini_temple,_Khajuraho,_Madhya_Pradesh.jpg', 'Winter.', 'Sunrise to Sunset.', 'Casual.', 'ASI protected.', '["None (Heritage)"]', '["Not Available"]', '{"history":"9th Century Chandela.","architecture":"Rectangular Yogini style.","visitorNotes":"Near Shivsagar lake.","sources":[{"label":"Khajuraho","url":"https://en.wikipedia.org/wiki/Khajuraho_Group_of_Monuments","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shakti-madhya-pradesh-khajuraho-devi-jagadambi-temple', 'shakti', 'Devi Jagadambi Temple', 'Madhya Pradesh', 'Khajuraho', 'Chhatarpur district', 'Jagadambi (Parvati)', 'Shakta', '["Parvati","Erotic","Chandela"]', 'A finely decorated temple dedicated to Jagadambi (Mother of the Universe); originally a Vishnu temple converted to Devi.', 'Intricate carvings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Devi_Jagadambi_Temple_Khajuraho.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Devi_Jagadambi_Temple_Khajuraho.jpg', 'Khajuraho Dance Festival.', 'Sunrise to Sunset.', 'Casual.', 'Western Group.', '["None (Heritage)"]', '["Khajuraho Festival"]', '{"history":"11th Century.","architecture":"Nagara.","visitorNotes":"Share platform with Kandariya.","sources":[{"label":"Khajuraho","url":"https://en.wikipedia.org/wiki/Khajuraho_Group_of_Monuments","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-khajuraho-duladeo-temple', 'shiva', 'Duladeo Temple', 'Madhya Pradesh', 'Khajuraho', 'Southern Group', 'Shiva', 'Shaiva', '["Khajuraho","Southern Group","Chandela"]', 'A late Chandela-era Shiva temple in Khajuraho\'s southern group.', 'Graceful carvings and a quieter southern setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Duladeo-Temple,%20Khajuraho.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Duladeo-Temple,_Khajuraho.jpg', 'Morning visits for a quiet walk.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage site near the Khodar River.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Wikipedia describes Duladeo as a Chandela-period Shiva temple in Khajuraho, dated about 1000-1150 and among the last built there.","architecture":"The temple stands in the southern group near the Khodar River.","puranicView":"The shrine venerates Shiva in linga form, with the name Duladeo meaning \\"Holy Bridegroom.\\"","puranicSources":[{"label":"Duladeo Temple","url":"https://en.wikipedia.org/wiki/Duladeo_Temple","type":"Encyclopedia"}],"folklore":"Local heritage notes Duladeo as one of the last temples completed in the Khajuraho sequence.","folkloreSources":[{"label":"Duladeo Temple","url":"https://en.wikipedia.org/wiki/Duladeo_Temple","type":"Encyclopedia"}],"sources":[{"label":"Duladeo Temple","url":"https://en.wikipedia.org/wiki/Duladeo_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-khajuraho-kandariya-mahadeva-temple', 'shiva', 'Kandariya Mahadeva Temple', 'Madhya Pradesh', 'Khajuraho', 'Western Group', 'Shiva', 'Shaiva', '["Khajuraho","Chandela","UNESCO"]', 'Khajuraho\'s largest and most ornate Shiva temple, famed for sculptural detail.', 'Rising shikhara towers and intricate Chandela carvings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kandariya%20Mahadeva%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kandariya_Mahadeva_Temple.jpg', 'Morning light for the carvings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Photography is permitted in the outer complex.', '["Daily puja"]', '["Mahashivratri","Khajuraho Dance Festival"]', '{"history":"Wikipedia calls Kandariya Mahadeva the largest and most ornate temple in the Khajuraho group, built around 1025-1050 under the Chandela dynasty.","architecture":"It is a North Indian Nagara-style temple and part of the UNESCO-listed Khajuraho Group of Monuments.","puranicView":"Dedicated to Shiva as Mahadeva, the temple anchors Shaiva worship within the western group of Khajuraho.","puranicSources":[{"label":"Kandariya Mahadeva Temple","url":"https://en.wikipedia.org/wiki/Kandariya_Mahadeva_Temple","type":"Encyclopedia"}],"folklore":"Khajuraho heritage narratives celebrate Kandariya Mahadeva as the grandest temple of the complex.","folkloreSources":[{"label":"Kandariya Mahadeva Temple","url":"https://en.wikipedia.org/wiki/Kandariya_Mahadeva_Temple","type":"Encyclopedia"}],"sources":[{"label":"Kandariya Mahadeva Temple","url":"https://en.wikipedia.org/wiki/Kandariya_Mahadeva_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-khajuraho-lalguan-mahadeva-temple', 'shiva', 'Lalguan Mahadeva Temple', 'Madhya Pradesh', 'Khajuraho', 'Near Lalguan Sagar', 'Shiva', 'Shaiva', '["Khajuraho","Granite","Early"]', 'An early, partly ruined granite Shiva temple near Lalguan Sagar.', 'Early Khajuraho architecture and a lakeside setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lalguan%20Mahadev%20Temple%20Khajuraho.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lalguan_Mahadev_Temple_Khajuraho.jpg', 'Morning visits for softer light on granite.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Ruined temple with uneven stone footing.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Wikipedia notes Lalguan Mahadeva is a ruined Shiva temple at Khajuraho, dated around 900 CE and built of granite near Lalguan Sagar.","architecture":"Smaller and plainer than later Khajuraho temples, it reflects the earlier phase of Chandela-era building.","puranicView":"The shrine is dedicated to Shiva as Mahadeva.","puranicSources":[{"label":"Lalguan Mahadeva Temple","url":"https://en.wikipedia.org/wiki/Lalguan_Mahadeva_Temple","type":"Encyclopedia"}],"folklore":"Local heritage treats it as one of the earliest surviving temples of Khajuraho.","folkloreSources":[{"label":"Lalguan Mahadeva Temple","url":"https://en.wikipedia.org/wiki/Lalguan_Mahadeva_Temple","type":"Encyclopedia"}],"sources":[{"label":"Lalguan Mahadeva Temple","url":"https://en.wikipedia.org/wiki/Lalguan_Mahadeva_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-khajuraho-mahadeva-temple-khajuraho', 'shiva', 'Mahadeva Temple (Khajuraho)', 'Madhya Pradesh', 'Khajuraho', 'Western Group', 'Shiva', 'Shaiva', '["Khajuraho","Small Shrine","Heritage"]', 'A small Khajuraho shrine between Kandariya Mahadeva and Jagadambi.', 'Shaiva lintel and a Shardula sculpture.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mahadeva_temple,_Khajuraho_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahadeva_temple,_Khajuraho_01.jpg', 'Morning light in the Western Group.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Within the Western Group of Khajuraho monuments.', '["Heritage darshan"]', '["Mahashivratri"]', '{"history":"The Mahadeva Temple is a small shrine between Kandariya Mahadeva and Jagadambi; its lintel suggests a Shaiva dedication.","architecture":"The shrine is compact and preserves a lintel with Shaiva iconography alongside a Shardula sculpture.","darshan":"A brief heritage darshan within the Khajuraho group.","seasonal":"Cool-season visits are most comfortable.","visitorNotes":"Combine with other Western Group temples nearby.","festivals":"Mahashivratri","sources":[{"label":"Mahadeva Temple, Khajuraho (Commons file description)","url":"https://commons.wikimedia.org/wiki/File:Mahadeva_temple,_Khajuraho_01.jpg"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-khajuraho-matangeshvara-temple', 'shiva', 'Matangeshvara Temple', 'Madhya Pradesh', 'Khajuraho', 'Western Group', 'Shiva', 'Shaiva', '["Khajuraho","Active Shrine","Lingam"]', 'Khajuraho\'s active Shiva shrine, revered for its massive lingam.', 'The towering lingam and ongoing daily worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Matangeshwar%20Mahadev%20Temple,%20Khajuraho.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Matangeshwar_Mahadev_Temple,_Khajuraho.jpg', 'Morning darshan while the shrine is most active.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Active temple with ongoing worship.', '["Daily puja","Abhishekam"]', '["Mahashivratri"]', '{"history":"Wikipedia describes the Matangeshvara temple as an 11th-century Shiva temple at Khajuraho and the only temple there still in active worship.","architecture":"The shrine houses a large lingam and belongs to the Khajuraho group of monuments.","puranicView":"The temple honors Shiva as Matangeshvara, sustaining Shaiva worship at Khajuraho.","puranicSources":[{"label":"Matangeshvara Temple, Khajuraho","url":"https://en.wikipedia.org/wiki/Matangeshvara_temple,_Khajuraho","type":"Encyclopedia"}],"folklore":"Local devotion emphasizes the temple\'s continuity of worship within the Khajuraho complex.","folkloreSources":[{"label":"Matangeshvara Temple, Khajuraho","url":"https://en.wikipedia.org/wiki/Matangeshvara_temple,_Khajuraho","type":"Encyclopedia"}],"sources":[{"label":"Matangeshvara Temple, Khajuraho","url":"https://en.wikipedia.org/wiki/Matangeshvara_temple,_Khajuraho"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shakti-madhya-pradesh-khajuraho-matangeshwari-temple', 'shakti', 'Matangeshwari Temple', 'Madhya Pradesh', 'Khajuraho', 'Chhatarpur district', 'Matangeshwari', 'Shaiva/Shakta', '["Live Temple","Shiva-Shakti","Pilgrimage"]', 'The only \'live\' temple in the Western Group; dedicated to Shiva but Matangeshwari Devi is also worshipped.', 'Live worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Matangeshwar_Temple_Khajuraho.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Matangeshwar_Temple_Khajuraho.jpg', 'Shivratri.', 'Open daily.', 'Traditional.', 'Free entry.', '["Daily Abhishekam"]', '["Shivratri","Navaratri"]', '{"history":"Chandela.","architecture":"Nagara.","visitorNotes":"Huge Lingam.","sources":[{"label":"Khajuraho","url":"https://en.wikipedia.org/wiki/Khajuraho_Group_of_Monuments","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-khajuraho-vishvanatha-temple', 'shiva', 'Vishvanatha Temple', 'Madhya Pradesh', 'Khajuraho', 'Western Group', 'Shiva', 'Shaiva', '["Khajuraho","Chandela","Nandi"]', 'A Chandela-era Shiva temple in Khajuraho\'s western group, known for its Nandi shrine.', 'The Nandi pavilion and richly carved exterior.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vishvanatha%20Temple,%20Khajuraho.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vishvanatha_Temple,_Khajuraho.jpg', 'Morning light for temple carvings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage site within the western group complex.', '["Daily puja"]', '["Mahashivratri","Khajuraho Dance Festival"]', '{"history":"Wikipedia notes the Vishvanatha temple is a Chandela-era Shiva temple in Khajuraho\'s western group, commissioned by King Dhanga around 999-1002 CE.","architecture":"The complex includes a Nandi shrine aligned with the main sanctum.","puranicView":"Vishvanatha means \\"Lord of the Universe,\\" a Shiva epithet honored at this shrine.","puranicSources":[{"label":"Vishvanatha Temple, Khajuraho","url":"https://en.wikipedia.org/wiki/Vishvanatha_Temple,_Khajuraho","type":"Encyclopedia"}],"folklore":"Khajuraho tradition highlights the Nandi pavilion as part of the temple\'s ceremonial approach.","folkloreSources":[{"label":"Vishvanatha Temple, Khajuraho","url":"https://en.wikipedia.org/wiki/Vishvanatha_Temple,_Khajuraho","type":"Encyclopedia"}],"sources":[{"label":"Vishvanatha Temple, Khajuraho","url":"https://en.wikipedia.org/wiki/Vishvanatha_Temple,_Khajuraho"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
