INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-nemawar-siddhanath-temple-nemawar', 'shiva', 'Siddhanath Temple (Nemawar)', 'Madhya Pradesh', 'Nemawar', 'Narmada River', 'Shiva', 'Shaiva', '["Narmada","Paramara","Nagara"]', 'A 10th-century Paramara Shiva temple on the Narmada at Nemawar.', 'Nagara-style architecture on a riverside plinth.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0102521%20Siddhanath%20temple,%20Siddheshwar%20Mahadev%20temple,%20Nemawar,%20Madhya%20Pradesh%20051.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0102521_Siddhanath_temple,_Siddheshwar_Mahadev_temple,_Nemawar,_Madhya_Pradesh_051.jpg', 'Morning darshan by the Narmada.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage site with stone steps.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Wikipedia describes Siddhanath (Sidheshwara) as a 10th-century Paramara-era Shiva temple at Nemawar on the Narmada, listed as a Monument of National Importance.","architecture":"The Nagara-style temple includes mandapa, antarala, and sanctum on a raised plinth.","puranicView":"The shrine remains in active Shiva worship along the Narmada.","puranicSources":[{"label":"Siddhanath Temple, Nemawar","url":"https://en.wikipedia.org/wiki/Siddhanath_Temple,_Nemawar","type":"Encyclopedia"}],"folklore":"Local worship patterns continue the temple\'s identity as a riverside Shiva shrine.","folkloreSources":[{"label":"Siddhanath Temple, Nemawar","url":"https://en.wikipedia.org/wiki/Siddhanath_Temple,_Nemawar","type":"Encyclopedia"}],"sources":[{"label":"Siddhanath Temple, Nemawar","url":"https://en.wikipedia.org/wiki/Siddhanath_Temple,_Nemawar"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shakti-madhya-pradesh-nohata-badi-devi-nohata', 'shakti', 'Badi Devi (Nohata)', 'Madhya Pradesh', 'Nohata', 'Damoh district', 'Devi', 'Shakta', '["Ancient","Kalachuri","Ruins"]', 'Ancient temple site in Nohata, the old capital of Kalachuris; Badi Devi is revered here.', 'Ancient capital.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Badi_Devi_Nohata.jpg', 'Representative Image', 'Not Available', 'Winter.', 'Open daily.', 'Casual.', 'Historical site.', '["Village offering"]', '["Navaratri"]', '{"history":"Kalachuri era.","architecture":"Ruins.","visitorNotes":"Nohata Shiva temple nearby.","sources":[{"label":"Damoh","url":"https://en.wikipedia.org/wiki/Damoh_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-nohta-noheleshwar-mahadev-temple-nohta', 'shiva', 'Noheleshwar Mahadev Temple (Nohta)', 'Madhya Pradesh', 'Nohta', 'Nohta area, Damoh district', 'Shiva', 'Shaiva', '["Damoh","Nohta","Noheleshwar"]', 'Noheleshwar Mahadev Temple is a Shiva shrine in the Nohta area of Damoh district.', 'Nohta-region Shiva worship node with regular local darshan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0010122%20Mahadeva%20Temple,%20Nohta%20Madhya%20Pradesh%20079.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0010122_Mahadeva_Temple,_Nohta_Madhya_Pradesh_079.jpg', 'Morning and evening darshan.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Confirm local route details before travel.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Shravan month"]', '{"history":"Maintained through local Shaiva tradition in the Nohta-Damoh belt.","architecture":"Regional temple profile with active ritual practices.","visitorNotes":"Weekday mornings are generally less crowded.","sources":[{"label":"Damoh district","url":"https://en.wikipedia.org/wiki/Damoh_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Noheleshwar%20Mahadev%20Temple%20Nohta%20Damoh","type":"Map search"}]}', '2026-02-23T20:50:54+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T04:14:00Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-nohta-nohleshwar-temple', 'shiva', 'Nohleshwar Temple', 'Madhya Pradesh', 'Nohta', 'Damoh District', 'Shiva', 'Shaiva', '["Kalchuri","Damoh","Heritage"]', 'A Kalchuri-era Shiva temple at Nohta, known for its 10th-century plan and platform.', 'High plinth and well-preserved mandapa.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0010122%20Mahadeva%20Temple,%20Nohta%20Madhya%20Pradesh%20079.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0010122_Mahadeva_Temple,_Nohta_Madhya_Pradesh_079.jpg', 'Morning visits for quieter exploration.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage site with stone steps.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Damoh district tourism states the Nohleshwar temple at Nohta was built around 950-1000 AD and is a key example of Kalchuri-era architecture.","architecture":"The plan includes garbhgrih, antaral, mandap, and mukh mandap on a high platform.","puranicView":"The shrine venerates Shiva as Nohleshwar, with ongoing local worship.","puranicSources":[{"label":"Nohleshwar Temple (Nohta)","url":"https://damoh.nic.in/en/tourist-place/nohleshwar-temple-nohta/","type":"Government tourism"}],"folklore":"Local tradition credits Kalchuri-era patronage for the temple\'s enduring sanctity.","folkloreSources":[{"label":"Nohleshwar Temple (Nohta)","url":"https://damoh.nic.in/en/tourist-place/nohleshwar-temple-nohta/","type":"Government tourism"}],"sources":[{"label":"Nohleshwar Temple (Nohta)","url":"https://damoh.nic.in/en/tourist-place/nohleshwar-temple-nohta/"},{"label":"Nohleshwar Temple","url":"https://en.wikipedia.org/wiki/Nohleshwar_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-obaidullaganj-shiva-temple-obaidullaganj', 'shiva', 'Shiva Temple (Obaidullaganj)', 'Madhya Pradesh', 'Obaidullaganj', 'Obaidullaganj area, Raisen district', 'Shiva', 'Shaiva', '["Raisen","Obaidullaganj","Shiva"]', 'Shiva Temple at Obaidullaganj is a local Shiva worship node in Raisen district.', 'Obaidullaganj-based Shiva darshan point.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Morning and evening darshan.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Confirm exact local route and temple timings before travel.', '["Daily puja","Jal abhishek"]', '["Mahashivratri","Shravan month"]', '{"history":"Maintained in local worship traditions as part of the district-level Shiva pilgrimage network.","architecture":"Regional shrine architecture with active devotional use.","visitorNotes":"Daylight visits are generally easier for navigation.","sources":[{"label":"Raisen district","url":"https://en.wikipedia.org/wiki/Raisen_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Shiva%20Temple%20(Obaidullaganj)%20Obaidullaganj%20Raisen%20Madhya%20Pradesh","type":"Map search"}]}', '2026-02-24T13:33:27+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-24T08:03:21Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-omkareshwar-gauri-somnath-temple', 'shiva', 'Gauri Somnath Temple', 'Madhya Pradesh', 'Omkareshwar', 'Mandhata Island, Khandwa District', 'Shiva', 'Shaiva', '["Mandhata Island","Heritage","Omkareshwar"]', 'A double-storey Mandhata island Shiva temple with one of the largest lingas at Omkareshwar.', 'Two-storey shrine with lingas on both levels.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0102621_Gauri_Somnath_temple,_Omkareswar_Madhya_Pradesh_040.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0102621_Gauri_Somnath_temple,_Omkareswar_Madhya_Pradesh_040.jpg', 'Morning visits for island views.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple sits on a plateau on Mandhata island.', '["Daily puja"]', '["Mahashivratri","Shravan month"]', '{"history":"The Gauri Somnath temple is a 9th to 11th-century Shiva temple on Mandhata island, rebuilt in the 18th century after earlier damage.","architecture":"It stands on a jagati, is two storeys high, and has a Nandi mandapa facing the shrine.","darshan":"Shiva lingas are present on both floors of the temple.","seasonal":"Cool-season visits are most comfortable on the island.","visitorNotes":"Expect steps up to the plateau and open-air views of Omkareshwar.","festivals":"Mahashivratri, Shravan month","sources":[{"label":"Khandwa district: Omkareshwar","url":"https://khandwa.nic.in/en/tourist-place/omkareshwar/"},{"label":"Commons Category: Gauri Somnath Temple, Omkareshwar","url":"https://commons.wikimedia.org/wiki/Category:Gauri_Somnath_Temple,_Omkareshwar"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
