INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-sihoniya-kakanmath-temple', 'shiva', 'Kakanmath Temple', 'Madhya Pradesh', 'Sihoniya', 'Sihoniya (Morena district)', 'Shiva', 'Shaiva', '["Heritage","Ruins","Shaiva"]', 'An 11th-century Shiva temple now in ruins, notable for its soaring stone tower.', 'Massive stone blocks and dramatic ruin silhouette.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0121621_Kakanmath_temple,_Sihoniya_Madhya_Pradesh_026.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0121621_Kakanmath_temple,_Sihoniya_Madhya_Pradesh_026.jpg', 'Winter mornings for clear light.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Kakanmath is an 11th-century Shiva temple at Sihoniya, commissioned by the Kachchhapaghata ruler Kirttiraja.","puranicView":"Kakanmath is a ruined 11th-century Shiva temple at Sihoniya, commissioned by the Kachchhapaghata ruler Kirttiraja. The shrine\'s Shaiva dedication anchors its sacred identity in devotion to Shiva rather than to a single Puranic episode.","puranicSources":[{"label":"Kakanmath","url":"https://en.wikipedia.org/wiki/Kakanmath","type":"Encyclopedia"}],"folklore":"A local folk legend says the temple was named after Queen Kakanavati (Kakanade), though the historicity of this story is considered doubtful. Even so, the name continues to circulate in popular retellings of the site.","folkloreSources":[{"label":"Kakanmath","url":"https://en.wikipedia.org/wiki/Kakanmath","type":"Encyclopedia (folk legend)"}],"sources":[{"label":"Kakanmath","url":"https://en.wikipedia.org/wiki/Kakanmath"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
