INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shakti-madhya-pradesh-ujjain-harsiddhi-mata-temple', 'shakti', 'Harsiddhi Mata Temple', 'Madhya Pradesh', 'Ujjain', 'Ujjain district', 'Harsiddhi (Annapurna)', 'Shakta', '["Shakti Peeth","Elbow","Lamp Tower"]', 'A major Shakti Peeth where Sati\'s elbow fell; famous for the two towering Deep Stambhas (lamp towers) lit during Navaratri.', 'Deep Stambhas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Harsiddhi_Temple%2C_Ujjain_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Harsiddhi_Temple,_Ujjain_01.jpg', 'Navaratri.', 'Open daily.', 'Traditional.', 'Near Mahakaleshwar.', '["Deep Prajvalan"]', '["Navaratri"]', '{"history":"Maratha renovations.","architecture":"Maratha style.","visitorNotes":"Visit during evening aarti.","sources":[{"label":"Ujjain","url":"https://en.wikipedia.org/wiki/Ujjain","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-ujjain-kal-bhairav-temple', 'shiva', 'Kal Bhairav Temple', 'Madhya Pradesh', 'Ujjain', 'Bhairavgarh', 'Shiva (Bhairav)', 'Shaiva', '["Bhairav","Guardian","Pilgrimage"]', 'A fierce guardian shrine dedicated to Kal Bhairav on the outskirts of Ujjain.', 'Powerful Bhairav sanctum and devotional offerings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kal_Bhairav_temple_Ujjain.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kal_Bhairav_temple_Ujjain.jpg', 'Early morning for quieter darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Bhairav Ashtami","Mahashivratri"]', '{"puranicView":"Kal Bhairav is revered as the guardian deity of Ujjain, and the temple is linked in tradition to the Avanti Khanda of the Skanda Purana. The shrine\'s identity centers on Bhairav as Shiva\'s fierce protector form.","puranicSources":[{"label":"Kal Bhairav Temple, Ujjain","url":"https://en.wikipedia.org/wiki/Kal_Bhairav_Temple,_Ujjain","type":"Encyclopedia"}],"folklore":"A distinctive local practice is the offering of liquor to the deity, which devotees treat as prasad. This ritual has become one of the most widely retold traditions associated with the temple.","folkloreSources":[{"label":"Kal Bhairav Temple, Ujjain","url":"https://en.wikipedia.org/wiki/Kal_Bhairav_Temple,_Ujjain","type":"Encyclopedia (ritual tradition)"}],"sources":[{"label":"Kal Bhairav Temple, Ujjain","url":"https://en.wikipedia.org/wiki/Kal_Bhairav_Temple,_Ujjain"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-ujjain-karkoteshwar-mahadev', 'shiva', 'Karkoteshwar Mahadev', 'Madhya Pradesh', 'Ujjain', 'Ujjain city, Ujjain district', 'Shiva', 'Shaiva', '["Ujjain","Karkoteshwar","Mahadev"]', 'Karkoteshwar Mahadev is a Shiva temple in Ujjain\'s sacred Shaiva landscape.', 'Ujjain-based Shiva worship with regular abhishek rituals.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Mahashivratri and Shravan month.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Verify local darshan timings and route details before visit.', '["Daily puja","Jal abhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Listed as a Shiva temple in Ujjain city, Ujjain district.","architecture":"Traditional neighborhood temple architecture.","visitorNotes":"Morning and evening darshan are generally preferred.","sources":[{"label":"Ujjain district","url":"https://en.wikipedia.org/wiki/Ujjain_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Karkoteshwar%20Mahadev%20Ujjain%20Ujjain","type":"Map search"}]}', '2026-02-23T20:50:24+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T11:05:00Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-ujjain-kedareshwar-mahadev', 'shiva', 'Kedareshwar Mahadev', 'Madhya Pradesh', 'Ujjain', 'Ujjain city, Ujjain district', 'Shiva', 'Shaiva', '["Ujjain","Kedareshwar","Mahadev"]', 'Kedareshwar Mahadev is a Shiva temple in Ujjain\'s sacred Shaiva landscape.', 'Ujjain-based Shiva worship with regular abhishek rituals.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Mahashivratri and Shravan month.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Verify local darshan timings and route details before visit.', '["Daily puja","Jal abhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Listed as a Shiva temple in Ujjain city, Ujjain district.","architecture":"Traditional neighborhood temple architecture.","visitorNotes":"Morning and evening darshan are generally preferred.","sources":[{"label":"Ujjain district","url":"https://en.wikipedia.org/wiki/Ujjain_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Kedareshwar%20Mahadev%20Ujjain%20Ujjain","type":"Map search"}]}', '2026-02-23T20:50:26+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T11:05:00Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-ujjain-mahakaleshwar-temple', 'shiva', 'Mahakaleshwar Temple', 'Madhya Pradesh', 'Ujjain', 'Shipra River', 'Shiva', 'Shaiva', '["Jyotirlinga","Bhasma Aarti","Kumbh"]', 'Ujjain offers a powerful jyotirlinga experience with timeless rituals at dawn.', 'Pre-dawn Bhasma Aarti and Shipra ghats.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mahakaleshwar%20Temple,%20Ujjain.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahakaleshwar_Temple,_Ujjain.jpg', 'Pre-dawn for the signature aarti.', 'Open daily; timings vary by season.', 'Traditional attire recommended.', 'Entry for early aarti often requires prior booking.', '["Bhasma aarti","Evening aarti"]', '["Mahashivratri","Kumbh period"]', '{"history":"Mahakaleshwar Jyotirlinga is a major Shiva temple in Ujjain and is counted among the twelve jyotirlinga shrines.","puranicView":"Incredible India notes that the Puranas connect Ujjain (Avantika) with Mahakaleshwar, including a Varaha Purana reference that places Mahakaleshwar at the earth\'s central point. It also recounts the Chandrasena-Shrikhar-Dushanan legend that ends with Shiva establishing the jyotirlinga in Ujjain.","puranicSources":[{"label":"Incredible India: Mahakaleshwar Temple","url":"https://www.incredibleindia.gov.in/en/madhya-pradesh/ujjain/mahakaleshwar-temple","type":"Government tourism (Purana tradition)"}],"sources":[{"label":"Mahakaleshwar Jyotirlinga","url":"https://en.wikipedia.org/wiki/Mahakaleshwar_Jyotirlinga"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-ujjain-mangalnath-temple', 'shiva', 'Mangalnath Temple', 'Madhya Pradesh', 'Ujjain', 'Kshipra River', 'Shiva', 'Shaiva', '["Shiva","Kshipra","Mars"]', 'Riverside Shiva shrine associated with the planet Mars in Ujjain traditions.', 'Riverbank darshan and sunrise rituals.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mangalnath_Ujjain.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mangalnath_Ujjain.JPG', 'Sunrise by the river.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja","Evening aarti"]', '["Mahashivratri"]', '{"history":"Mangalnath is a Shiva temple on the banks of the Shipra in Ujjain and is traditionally associated with Mars (Mangal) worship.","puranicView":"Mangalnath is regarded as the birthplace of Mars (Mangal) according to the Matsya Purana, and the shrine is dedicated to Shiva on the banks of the Shipra. The site was once noted for a clear view of the planet, giving it an astronomical dimension in local sacred geography.","puranicSources":[{"label":"Mangalnath (Ujjain district)","url":"https://ujjain.nic.in/en/tourist-place/mangalnath/","type":"Government tourism"}],"folklore":"Tuesday worship at the Mangal linga draws special crowds, and local practice treats this day as the most auspicious for Mars-related prayers. This weekly ritual rhythm is a key part of the shrine\'s living tradition.","folkloreSources":[{"label":"Places of Interest (Ujjain district)","url":"https://ujjain.nic.in/en/places-of-interest/","type":"Government tourism"}],"sources":[{"label":"Mangalnath Temple","url":"https://en.wikipedia.org/wiki/Mangalnath"},{"label":"Mangalnath (Ujjain district)","url":"https://ujjain.nic.in/en/tourist-place/mangalnath/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-ujjain-navgrah-shani-mandir-where-shani-is-uniquely-worshipped-as-shiva', 'shiva', 'Navgrah Shani Mandir (where Shani is uniquely worshipped as Shiva)', 'Madhya Pradesh', 'Ujjain', 'Ujjain city, Ujjain district', 'Shiva (Shani aspect)', 'Shaiva', '["Ujjain","Navgrah","Shani","Shaiva"]', 'Navgrah Shani Mandir (where Shani is uniquely worshipped as Shiva) is a Shiva temple in Ujjain\'s sacred Shaiva landscape.', 'Ujjain-based Shiva worship with regular abhishek rituals.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Mahashivratri and Shravan month.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Verify local darshan timings and route details before visit.', '["Daily puja","Jal abhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Listed as a Shiva temple in Ujjain city, Ujjain district.","architecture":"Traditional neighborhood temple architecture.","visitorNotes":"Morning and evening darshan are generally preferred.","sources":[{"label":"Ujjain district","url":"https://en.wikipedia.org/wiki/Ujjain_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Navgrah%20Shani%20Mandir%20(where%20Shani%20is%20uniquely%20worshipped%20as%20Shiva)%20Ujjain%20Ujjain","type":"Map search"}]}', '2026-02-23T20:50:22+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T11:05:00Z');
