INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-ujjain-shree-chandradityeshwar-mahadev', 'shiva', 'Shree Chandradityeshwar Mahadev', 'Madhya Pradesh', 'Ujjain', 'Ujjain city, Ujjain district', 'Shiva', 'Shaiva', '["Ujjain","Chandradityeshwar","Mahadev"]', 'Shree Chandradityeshwar Mahadev is a Shiva temple in Ujjain\'s sacred Shaiva landscape.', 'Ujjain-based Shiva worship with regular abhishek rituals.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Mahashivratri and Shravan month.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Verify local darshan timings and route details before visit.', '["Daily puja","Jal abhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Listed as a Shiva temple in Ujjain city, Ujjain district.","architecture":"Traditional neighborhood temple architecture.","visitorNotes":"Morning and evening darshan are generally preferred.","sources":[{"label":"Ujjain district","url":"https://en.wikipedia.org/wiki/Ujjain_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Shree%20Chandradityeshwar%20Mahadev%20Ujjain%20Ujjain","type":"Map search"}]}', '2026-02-23T20:50:21+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T11:05:00Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-ujjain-siddhavat-temple', 'shiva', 'Siddhavat Temple', 'Madhya Pradesh', 'Ujjain', 'Kshipra River', 'Shiva', 'Shaiva', '["Riverbank","Pilgrimage","Rituals"]', 'A sacred riverside temple area associated with ancestral rites and a revered banyan tree.', 'Rituals by the Kshipra and the ancient banyan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ram_Ghat,_Ujjain_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ram_Ghat,_Ujjain_01.jpg', 'Early morning during river rituals.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Kumbh period","Mahashivratri"]', '{"history":"Ujjain district tourism describes Siddhavat as a siddh place on the Shipra and links it to the sacred banyan tradition, comparing it to the Akshay Vat at Prayag.","puranicView":"Ujjain traditions place Siddhavat among the sacred banyans of India and narrate that the vat tree here was planted and worshipped by Parvati. The site is treated as a paapmochan tirtha where rites like shraddha, pind daan, and tarpan are believed to yield special merit.","puranicSources":[{"label":"Places of Interest (Siddhavat)","url":"https://ujjain.nic.in/en/places-of-interest/","type":"Government tourism"},{"label":"Siddhwat Temple","url":"https://en.wikipedia.org/wiki/Siddhwat_Temple","type":"Encyclopedia"}],"folklore":"Nath sadhus continue to worship here, and the riverside rituals keep the place active through the year. Siddhavat is also remembered as a key Kshipra bank for ancestral rites during Kumbh cycles.","folkloreSources":[{"label":"Places of Interest (Siddhavat)","url":"https://ujjain.nic.in/en/places-of-interest/","type":"Government tourism"},{"label":"Siddhwat Temple","url":"https://en.wikipedia.org/wiki/Siddhwat_Temple","type":"Encyclopedia"}],"sources":[{"label":"Places of Interest (Ujjain district)","url":"https://ujjain.nic.in/en/places-of-interest/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
