INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-un-ballaleshwar-temple-un', 'shiva', 'Ballaleshwar Temple (Un)', 'Madhya Pradesh', 'Un', 'Khargone District', 'Shiva', 'Shaiva', '["Un Temples","Dome","Heritage"]', 'A mid-11th-century Shiva temple in Un notable for its later dome-like superstructure.', 'Dome above a sunken garbhagriha.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0102221_Ballaleswar_temple,_Un_056.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0102221_Ballaleswar_temple,_Un_056.jpg', 'Morning light for architectural details.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage site with later repairs and uneven floors.', '["Heritage darshan"]', '["Mahashivratri"]', '{"history":"The Ballaleshwar temple is a mid 11th-century Shiva temple in Un village, notable for its dome-like superstructure added in later repairs.","architecture":"It faces east with a square inner plan and an outer pancharatha plan; the original mandapa is lost and the garbhagriha sits below ground level.","darshan":"The sanctum holds a svambhu-style jaladhari without a Shiva linga.","seasonal":"Best visited in cooler months for long heritage walks.","visitorNotes":"Look for later masonry repairs and reused stonework.","festivals":"Mahashivratri","sources":[{"label":"Ballaleshwar temple, Un (Commons file description)","url":"https://commons.wikimedia.org/wiki/File:0102221_Ballaleswar_temple,_Un_056.jpg"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-un-mahakaleshwar-temple-1-un', 'shiva', 'Mahakaleshwar Temple 1 (Un)', 'Madhya Pradesh', 'Un', 'Khargone District', 'Shiva', 'Shaiva', '["Un Temples","11th Century","Heritage"]', 'A late 11th-century Shaiva temple in the Un cluster with large mandapa ruins.', 'Jagati platform and twin trabeate arches.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0102221_Mahakaleswar_temple_1,_Un,_Khargone_district,_Madhya_Pradesh_125.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0102221_Mahakaleswar_temple_1,_Un,_Khargone_district,_Madhya_Pradesh_125.jpg', 'Morning light for heritage photography.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage ruins with uneven stone surfaces.', '["Heritage darshan"]', '["Mahashivratri"]', '{"history":"Mahakaleshwar temple 1 is a late 11th-century Shiva temple in Un village, located near Chaubara Dera 1 in the Khargone district.","architecture":"The temple faces east, stands on a jagati, and retains a damaged mandapa and shikhara with two trabeate arches between the mandapa and sanctum.","darshan":"The sanctum and mandapa remains form the core of the heritage darshan.","seasonal":"Cool-season visits are most comfortable for long heritage walks.","visitorNotes":"Plan for uneven stone steps and ruined sections.","festivals":"Mahashivratri","sources":[{"label":"Mahakaleshwar temple 1, Un (Commons category)","url":"https://commons.wikimedia.org/wiki/Category:Mahakaleshwar_temple_1,_Un"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-un-mahakaleshwar-temple-2-un', 'shiva', 'Mahakaleshwar Temple 2 (Un)', 'Madhya Pradesh', 'Un', 'Khargone District', 'Shiva', 'Shaiva', '["Un Temples","11th Century","Heritage"]', 'An older mid-11th-century Shiva temple in Un, retaining parts of its antarala and shikhara.', 'Trabeate arch and surviving outer-wall carvings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0102221_Mahakaleswar_Mandir_number_2,_Un_Madhya_Pradesh_15.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0102221_Mahakaleswar_Mandir_number_2,_Un_Madhya_Pradesh_15.jpg', 'Morning visits for cooler weather.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage ruins with partial structures.', '["Heritage darshan"]', '["Mahashivratri"]', '{"history":"Mahakaleshwar temple 2 is a mid 11th-century Shiva temple in Un village, east of Jain Chaubara Dera 2 and older than Mahakaleshwar temple 1.","architecture":"The mandapa is lost, while the antarala and part of the shikhara survive along with a trabeate arch and mutilated outer-wall artwork.","darshan":"The surviving sanctum and architectural fragments form the heritage darshan.","seasonal":"Dry months are best for walking the Un temple cluster.","visitorNotes":"Expect broken masonry and exposed structures.","festivals":"Mahashivratri","sources":[{"label":"Mahakaleshwar temple 2, Un (Commons category)","url":"https://commons.wikimedia.org/wiki/Category:Mahakaleshwar_temple_2,_Un"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-madhya-pradesh-un-nilkantheshvara-temple-un', 'shiva', 'Nilkantheshvara Temple (Un)', 'Madhya Pradesh', 'Un', 'Khargone District', 'Shiva', 'Shaiva', '["Un Temples","11th Century","Heritage"]', 'A late-11th-century Shaiva monument in Un with surviving sanctum doorway and carved panels.', 'Standing pillar from the lost mandapa.', 'https://commons.wikimedia.org/wiki/Special:FilePath/0102221_Nilkanthesvara_temple,_Un_Madhya_Pradesh_070.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:0102221_Nilkanthesvara_temple,_Un_Madhya_Pradesh_070.jpg', 'Morning visits for clearer light.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple stands amid village homes.', '["Heritage darshan"]', '["Mahashivratri"]', '{"history":"The Nilkantheshvara temple of Un is a late 11th-century Shiva temple in the middle of Un village, with the mandapa largely lost.","architecture":"A portion of the antarala and the original sanctum doorway survive, along with parts of the shikhara and outer sanctum sculptures.","darshan":"A Shiva linga remains in the surviving sanctum.","seasonal":"Open year-round with the best light in the morning.","visitorNotes":"A lone pillar from the original mandapa stands nearby.","festivals":"Mahashivratri","sources":[{"label":"Nilkantheshvara temple, Un (Commons file description)","url":"https://commons.wikimedia.org/wiki/File:0102221_Nilkanthesvara_temple,_Un_Madhya_Pradesh_070.jpg"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-22T13:34:37Z');
