INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-alibaug-kankeshwar-temple-alibaug', 'shiva', 'Kankeshwar Temple (Alibaug)', 'Maharashtra', 'Alibaug', 'Mapgaon hills, Alibaug, Raigad district', 'Shiva', 'Shaiva', '["Hilltop","Coastal Fortress Grid","Long Stair Climb"]', 'An ancient hilltop Shiva anchor in the Alibaug belt, reached by a long stair ascent (often described locally as around 5,000 steps) through forested terrain.', 'Elevated coastal transmitter-node with panoramic Raigad coastal-grid views.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Kanakeshwar_Temple.jpg/640px-Kanakeshwar_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kanakeshwar_Temple.jpg', 'Winter.', 'Open daily.', 'Modest attire with trekking-friendly footwear.', 'Prepare for a long stair climb and carry water, especially outside winter.', '["Abhishekam"]', '["Mahashivratri"]', '{"history":"Kankeshwar has long-standing Raigad coastal pilgrimage importance with documented medieval-to-early modern temple continuity.","architecture":"Hilltop stone-temple profile with surrounding sacred tanks and elevated worship platform.","darshan":"Darshan combines climb-based pilgrimage effort with a quiet hilltop shrine atmosphere.","seasonal":"Winter and post-monsoon mornings are most comfortable for ascent.","visitorNotes":"Start early to avoid heat during the staircase climb.","festivals":"Mahashivratri and Kartik observances are key annual peaks.","sources":[{"label":"Alibaug","url":"https://en.wikipedia.org/wiki/Alibag","type":"Encyclopedia"},{"label":"Raigad district","url":"https://en.wikipedia.org/wiki/Raigad_district","type":"Encyclopedia"}]}', '2026-02-25T15:38:45+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-alibaug-vyaghreshwar-shiva-temple-alibaug', 'shiva', 'Vyaghreshwar Shiva Temple (Alibaug)', 'Maharashtra', 'Alibaug', 'Alibaug belt, Raigad district', 'Shiva', 'Shaiva', '["Vyaghreshwar","Alibaug","Coastal Fortress Grid"]', 'A quiet, old Shiva shrine in the Alibaug region, maintained as a vegetation-shielded local anchor in the Raigad coastal temple network.', 'Secluded Alibaug Shaiva node with a calm, forest-buffered darshan environment.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Morning darshan and winter season.', 'Open daily; local timings vary.', 'Modest attire recommended.', 'Confirm local route and temple timings before travel.', '["Abhishekam","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Vyaghreshwar traditions in coastal Raigad are preserved through local Shaiva worship lineages and community festival cycles.","architecture":"Regional temple form with a compact sanctum and locally maintained precinct.","darshan":"Typically peaceful darshan outside peak festival days.","seasonal":"Post-monsoon and winter offer easier access and comfortable weather.","visitorNotes":"Plan early visits for quieter darshan and better road movement in the coastal belt.","festivals":"Mahashivratri and Shravan observances are the main annual peaks.","sources":[{"label":"Alibag","url":"https://en.wikipedia.org/wiki/Alibag","type":"Encyclopedia"},{"label":"Raigad district","url":"https://en.wikipedia.org/wiki/Raigad_district","type":"Encyclopedia"}]}', '2026-02-25T15:38:45+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
