INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-ambajogai-sakaleshwar-temple', 'shiva', 'Sakaleshwar Temple', 'Maharashtra', 'Ambajogai', 'Beed district', 'Shiva', 'Shaiva', '["Barakhambi","Rashtrakuta","Carvings"]', 'Also known as Barakhambi (12 pillars), this 13th-century temple features intricate carvings of Shiva, Saptamatrikas, and Ganesha.', 'The open mandapa with 12 beautifully carved pillars.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Sakaleshwar_Temple_Ambajogai.jpg/640px-Sakaleshwar_Temple_Ambajogai.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sakaleshwar_Temple_Ambajogai.jpg', 'Winter.', 'Open daily.', 'Casual.', 'In Ambajogai town.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Built in 1228 AD by Yadava general Kholeshwar.","architecture":"Hemadpanti style.","darshan":"Historic.","seasonal":"Pleasant in winter.","visitorNotes":"Visit the Yogeshwari temple nearby.","festivals":"Shivratri.","sources":[{"label":"Ambajogai","url":"https://en.wikipedia.org/wiki/Ambajogai","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-ambarnath-ambreshwar-shiva-temple-ambarnath', 'shiva', 'Ambreshwar Shiva Temple (Ambarnath)', 'Maharashtra', 'Ambarnath', 'Thane district, Waldhuni River', 'Shiva', 'Shaiva', '["Shilahara","Bhumija","Heritage"]', 'A celebrated 11th-century Shiva temple at Ambarnath, associated with Shilahara-era stone architecture and a step-down subterranean sanctum.', '1060 CE heritage shrine with interlocked stone construction and a sunken sanctum core.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ambernath_Shiv_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ambernath_Shiv_Temple.jpg', 'Mahashivratri and winter evenings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect large crowds during Mahashivratri fair days.', '["Abhishekam","Evening aarti"]', '["Mahashivratri"]', '{"history":"The Ambarnath Shiva temple was built in 1060 CE by the Shilahara dynasty and is among Maharashtra\'s most important medieval shrines.","architecture":"Bhumija-style temple with a sunken sanctum and an incomplete open-to-sky shikhara.","darshan":"The sanctum is reached by steps leading down into the main garbhagriha.","seasonal":"Mahashivratri brings a multi-day pilgrimage fair.","visitorNotes":"Plan early visits during festival periods for easier darshan.","festivals":"Mahashivratri is the key annual celebration.","sources":[{"label":"Ambreshwar Shiva Temple (Ambarnath)","url":"https://en.wikipedia.org/wiki/Shiv_Mandir,_Ambarnath","type":"Encyclopedia"},{"label":"MTDC: Ambarnath Temple","url":"https://www.mtdc.co/en/explore-maharashtra/heritage-destinations/ambarnath-temple/","type":"State tourism"}]}', '2026-02-25T14:54:24+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
