INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-aundha-nagnath-aundha-nagnath-jyotirlinga', 'shiva', 'Aundha Nagnath Jyotirlinga', 'Maharashtra', 'Aundha Nagnath', 'Hingoli district', 'Shiva', 'Shaiva', '["Hemadpanti","Heritage","Jyotirlinga Tradition"]', 'A major Hingoli Shaiva center locally revered as a jyotirlinga node, known for deep-set sanctum access and dense medieval stone carving.', 'Subterranean sanctum approach and richly carved elephant-and-mythic friezes on the temple base.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aundha_Nagnath_temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Aundha_Nagnath_temple.jpg', 'Mahashivratri and winter pilgrimage season.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect queues during festival days.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Aundha Nagnath is locally revered as a jyotirlinga center in Hingoli, with regional narratives linking its sacred history to Pandava-era tradition and later Yadava-Maratha patronage.","architecture":"Hemadpanti-influenced stone construction, a step-down sanctum core, and extensive carved exterior bands define the temple\'s architecture.","darshan":"The sanctum is set below ground level, accessed by steps.","seasonal":"Mahashivratri brings the largest pilgrim gatherings.","visitorNotes":"Plan early entry during festival weeks for smoother access.","festivals":"Mahashivratri is the key annual celebration.","sources":[{"label":"Aundha Nagnath Jyotirlinga","url":"https://en.wikipedia.org/wiki/Aundha_Nagnath_Temple","type":"Encyclopedia"},{"label":"Aundha Nagnath District Collectorate","url":"https://hingoli.gov.in/","type":"District administration"}]}', '2026-02-25T15:15:01+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
