INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-harihareshwar-harihareshwar-temple', 'shiva', 'Harihareshwar Temple', 'Maharashtra', 'Harihareshwar', 'Harihareshwar coast, Raigad district', 'Harihareshwar (Shiva)', 'Shaiva', '["Dakshin Kashi","Coastal Node","Cliff Pradakshina"]', 'Known as \'Dakshin Kashi\', this Harihareshwar Shiva node sits between hills and the Arabian Sea, with a famed pradakshina route running across rocky coastal cliffs.', 'Massive naturally shielded coastal Shiva anchor with sea-cliff pradakshina.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Harihareshwar_Temple_View.jpg/640px-Harihareshwar_Temple_View.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Harihareshwar_Temple_View.jpg', 'Winter; avoid Pradakshina during high tide/monsoon.', 'Open daily.', 'Modest attire recommended.', 'Check tide timings before doing the rock pradakshina.', '["Pradakshina"]', '["Mahashivratri"]', '{"history":"Harihareshwar is a long-standing Konkan pilgrimage center with strong Peshwa-era devotional associations.","architecture":"Konkani coastal-temple profile integrated with hill contours and the nearby Kalbhairav shrine sequence.","darshan":"Darshan combines temple worship with the iconic cliff-side pradakshina circuit.","seasonal":"Sea conditions and high tides can restrict the pradakshina route in monsoon.","visitorNotes":"Check tide charts and begin circuit only under safe local conditions.","festivals":"Mahashivratri and key Konkan Shiva observances draw major crowds.","sources":[{"label":"Harihareshwar","url":"https://en.wikipedia.org/wiki/Harihareshwar","type":"Encyclopedia"},{"label":"Raigad district","url":"https://en.wikipedia.org/wiki/Raigad_district","type":"Encyclopedia"}]}', '2026-02-25T15:38:45+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-haripur-sangameshwar-temple-haripur', 'shiva', 'Sangameshwar Temple (Haripur)', 'Maharashtra', 'Haripur', 'Haripur confluence, Sangli district', 'Shiva', 'Shaiva', '["Sangam","Krishna-Warna","Sangli"]', 'A major Sangameshwar shrine at Haripur, located near the confluence of the Krishna and Warna rivers in Sangli district.', 'River-confluence Shiva darshan in the Haripur Sangam zone.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Morning darshan and post-monsoon months.', 'Open daily; local timings vary.', 'Modest attire recommended.', 'Check riverbank access conditions during heavy monsoon.', '["Abhishekam","Sangam puja"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Sangameshwar worship at river confluences is a long-standing Shaiva pattern across western Maharashtra.","architecture":"Traditional temple layout adapted to the river-confluence setting.","darshan":"Steady local darshan with increased footfall on Mondays and festival days.","seasonal":"Monsoon amplifies the riverfront setting; post-monsoon is most comfortable.","visitorNotes":"Prefer daylight visits and verify local water-level advisories.","festivals":"Mahashivratri and Shravan Mondays are principal observances.","sources":[{"label":"Sangli district","url":"https://en.wikipedia.org/wiki/Sangli_district","type":"Encyclopedia"}]}', '2026-02-25T14:49:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-harishchandragad-kedareshwar-cave-temple', 'shiva', 'Kedareshwar Cave Temple', 'Maharashtra', 'Harishchandragad', 'Ahmednagar district', 'Shiva', 'Shaiva', '["Cave","Trek","Water shrine"]', 'A cave shrine on Harishchandragad where the Shiva linga is surrounded by water.', 'Water-surrounded linga and trekking approach.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kedareshwar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kedareshwar.jpg', 'Post-monsoon trekking season.', 'Open daily; timings vary by season.', 'Trekking attire recommended.', 'The cave often has water on the floor; plan accordingly.', '["Seasonal puja"]', '["Mahashivratri"]', '{"history":"Kedareshwar Cave is a noted Shiva shrine on Harishchandragad, approached via a trek.","architecture":"Natural cave shrine with a central linga and carved niches.","darshan":"The linga is surrounded by water, requiring wading for closer access.","seasonal":"Water levels rise during monsoon; post-monsoon is preferred.","visitorNotes":"Carry trekking essentials and plan for wet cave floors.","festivals":"Mahashivratri draws trekkers and devotees.","sources":[{"label":"Harishchandragad","url":"https://en.wikipedia.org/wiki/Harishchandragad","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
