INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-khed-bhimashankar-jyotirlinga-khed', 'shiva', 'Bhimashankar Jyotirlinga (Khed)', 'Maharashtra', 'Khed', 'Bhimashankar, Khed taluka, Pune district', 'Shiva', 'Shaiva', '["Jyotirlinga","Sahyadri","Nagara"]', 'The Bhimashankar Jyotirlinga is the primary Shaiva macro-center in this forested Sahyadri circuit.', 'Jyotirlinga sanctum, Sahyadri setting, and heritage temple bell.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhimashankar_temple.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bhimashankar_temple.JPG', 'Monsoon greenery and cool winter mornings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Monsoon weekends can be crowded; expect forest sanctuary checks.', '["Abhishekam","Morning aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"One of the twelve jyotirlingas, Bhimashankar has been a pilgrimage center for centuries, with later additions including a temple hall associated with the Peshwa era.","architecture":"Nagara-style temple architecture with later Maratha-period additions in the mandapa.","darshan":"The sanctum enshrines the jyotirlinga, with a heritage bell visible within the complex.","seasonal":"Shravan and Mahashivratri bring peak pilgrim traffic.","visitorNotes":"The temple sits within the Bhimashankar Wildlife Sanctuary; plan travel accordingly.","festivals":"Mahashivratri and Shravan month rituals draw major crowds.","sources":[{"label":"Bhimashankar Jyotirlinga (Khed)","url":"https://en.wikipedia.org/wiki/Bhimashankar_Temple","type":"Encyclopedia"},{"label":"Maharashtra Tourism: Bhimashankar","url":"https://www.maharashtratourism.gov.in/","ty