INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-mumbai-babulnath-temple-malabar-hill', 'shiva', 'Babulnath Temple (Malabar Hill)', 'Maharashtra', 'Mumbai', 'Malabar Hill, South Mumbai', 'Shiva', 'Shaiva', '["Hilltop","Mumbai","Historic"]', 'A prominent hilltop Shiva temple in South Mumbai, with tradition that the original linga was rediscovered after being buried underground for centuries.', 'High-elevation South Mumbai shrine with strong historic continuity.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Babulnath_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Babulnath_Temple.jpg', 'Evening aarti and winter months.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect stair climbs and city traffic near Girgaum.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Diwali"]', '{"history":"Babulnath is dedicated to Shiva as the Lord of the Babul tree and is among Mumbai\'s oldest temples.","architecture":"Hilltop shrine with a stepped approach and city-facing courtyard.","darshan":"The main sanctum houses the Shiva linga with daily rituals.","seasonal":"Mahashivratri and Diwali bring the biggest crowds.","visitorNotes":"Plan visits during off-peak hours for easier access.","festivals":"Mahashivratri and Diwali are key celebrations.","sources":[{"label":"Babulnath Temple","url":"https://en.wikipedia.org/wiki/Babulnath_Temple","type":"Encyclopedia"}]}', '2026-02-25T14:52:32+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-mumbai-jabreshwar-mahadev-mandir', 'shiva', 'Jabreshwar Mahadev Mandir', 'Maharashtra', 'Mumbai', 'Walkeshwar, Banganga', 'Shiva', 'Shaiva', '["Nagara","Banganga","19th century"]', 'A Nagara-style Shiva temple near Banganga tank in Walkeshwar, Malabar Hill.', 'Banganga precinct and Malabar Hill heritage walks.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jabreshwar_Mahadev_Mandir,_Walkeshwar.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jabreshwar_Mahadev_Mandir,_Walkeshwar.jpg', 'Morning and evening aarti hours.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple sits near Banganga tank; expect narrow lanes.', '["Abhishekam","Daily puja"]', '["Mahashivratri"]', '{"history":"Jabreshwar Mahadev Mandir was built in the 19th century and is part of the Walkeshwar-Banganga heritage area.","architecture":"North Indian Nagara-style shikhara over the sanctum.","darshan":"The sanctum houses the Shiva linga, with Banganga tank nearby.","seasonal":"Evening visits are popular during cooler months.","visitorNotes":"Combine darshan with Banganga heritage walk.","festivals":"Mahashivratri is observed with special pujas.","sources":[{"label":"Jabreshwar Mahadev Mandir","url":"https://en.wikipedia.org/wiki/Jabreshwar_Mahadev_Mandir","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-mumbai-jogeshwari-caves', 'shiva', 'Jogeshwari Caves', 'Maharashtra', 'Mumbai', 'Jogeshwari East', 'Shiva', 'Shaiva', '["Oldest Cave","City Heritage","Rock-cut"]', 'One of the earliest major Hindu cave-temple complexes in India, with deep Shaivite and Pashupata rock-cut heritage in Mumbai.', 'Early rock-cut Shaiva cave architecture embedded in dense urban Mumbai.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Jogeshwari_Caves_Entrance.jpg/640px-Jogeshwari_Caves_Entrance.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jogeshwari_Caves_Entrance.jpg', 'All year.', 'Open daily.', 'Casual.', 'Narrow access lanes.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Built by Pashupata sect monks in the 6th century.","architecture":"Rock-cut.","darshan":"Historic.","seasonal":"Can get flooded in monsoon.","visitorNotes":"Surrounded by slums but historically vital.","festivals":"Shivratri.","sources":[{"label":"Jogeshwari Caves","url":"https://en.wikipedia.org/wiki/Jogeshwari_Caves","type":"Encyclopedia"}]}', '2026-02-25T14:52:32+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-mumbai-mandapeshwar-caves', 'shiva', 'Mandapeshwar Caves', 'Maharashtra', 'Mumbai', 'Borivali', 'Shiva', 'Shaiva', '["Converted Church","Portuguese","Rock-cut"]', 'A rock-cut Shiva temple that was converted into a church by the Portuguese and later reclaimed. It sits just below a Portuguese monastery ruins.', 'The Nataraja carving and the history of religious conversion.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Mandapeshwar_Caves.jpg/640px-Mandapeshwar_Caves.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mandapeshwar_Caves.jpg', 'All year.', 'Open daily.', 'Casual.', 'Near Borivali station.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"8th century cave; witnessed turbulent history.","architecture":"Rock-cut.","darshan":"Historic.","seasonal":"Monsoon creates waterfalls nearby.","visitorNotes":"Visit Kanheri caves nearby too.","festivals":"Shivratri.","sources":[{"label":"Mandapeshwar","url":"https://en.wikipedia.org/wiki/Mandapeshwar_Caves","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-mumbai-walkeshwar-temple-banganga-tank', 'shiva', 'Walkeshwar Temple (Banganga Tank)', 'Maharashtra', 'Mumbai', 'Malabar Hill, Banganga Tank', 'Shiva', 'Shaiva', '["Banganga","Rama Legend","City Heritage"]', 'An ancient Shiva shrine at Banganga where tradition holds that Lord Rama formed a sand linga (Valuka Ishwar) while searching for Sita.', 'Banganga tank precinct and early coastal-heritage Shiva worship zone.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Walkeshwar_Temple_Mumbai.jpg/640px-Walkeshwar_Temple_Mumbai.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Walkeshwar_Temple_Mumbai.jpg', 'Evening.', 'Open daily.', 'Modest.', 'Parking is difficult in Malabar Hill.', '["Abhishekam"]', '["Mahashivratri","Banganga Music Festival"]', '{"history":"Original temple built by Shilaharas; destroyed by Portuguese and rebuilt.","architecture":"Maratha/Modern mix.","darshan":"Urban spiritual oasis.","seasonal":"Pleasant in winter evenings.","visitorNotes":"Walk around the Banganga tank for a timeless feel.","festivals":"Music festival is a cultural treat.","sources":[{"label":"Walkeshwar","url":"https://en.wikipedia.org/wiki/Walkeshwar_Temple","type":"Encyclopedia"}]}', '2026-02-25T14:52:32+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
