INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-raigad-fort-jagadishwar-temple-raigad-fort', 'shiva', 'Jagadishwar Temple (Raigad Fort)', 'Maharashtra', 'Raigad Fort', 'Raigad Fort plateau, Raigad district', 'Shiva (Jagadishwar)', 'Shaiva', '["Shivaji Maharaj","Fort Capital","High-altitude"]', 'A high-altitude Shiva temple at Raigad Fort, built in the capital-fort matrix of Chhatrapati Shivaji Maharaj and closely tied to the fort\'s core ceremonial zone.', 'Historic Raigad capital-node blending spiritual continuity and fort-energy legacy.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Jagadishwar_Temple_Raigad.jpg/640px-Jagadishwar_Temple_Raigad.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jagadishwar_Temple_Raigad.jpg', 'Monsoon and Winter.', 'Open daily.', 'Modest/Active wear.', 'Access requires fort ascent (trek/steps/ropeway route planning).', '["Daily puja"]', '["Shivrajyabhishek"]', '{"history":"Jagadishwar is one of the principal sacred structures in the Raigad capital complex associated with the Shivaji-era state formation period.","architecture":"Fort-temple construction with robust stonework adapted to elevated plateau conditions.","darshan":"Darshan experience is deeply linked to the wider Raigad fort pilgrimage route.","seasonal":"Monsoon fog and rain can reduce visibility and make fort paths slippery.","visitorNotes":"Plan combined darshan with nearby Raigad heritage points including the Samadhi area.","festivals":"Shivrajyabhishek-linked observances and Mahashivratri draw higher footfall.","sources":[{"label":"Raigad Fort","url":"https://en.wikipedia.org/wiki/Raigad_Fort","type":"Encyclopedia"},{"label":"Raigad district"