INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-ter-uttareshwar-temple-ter', 'shiva', 'Uttareshwar Temple (Ter)', 'Maharashtra', 'Ter', 'Osmanabad district', 'Shiva', 'Shaiva', '["Brick Temple","Ancient","Vakataka"]', 'One of the oldest surviving brick temples in Maharashtra, dating back to the Vakataka/Gupta period (4th-6th century).', 'Rare ancient brick architecture and carved wooden doorframes.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Trivikrama_Temple_Ter.jpg/640px-Trivikrama_Temple_Ter.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Trivikrama_Temple_Ter.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Archaeological site.', '["None (Heritage site)","Viewing"]', '["None"]', '{"history":"Ter was a major trade center (Tagara); the temple is a survivor from that era.","architecture":"Brick construction with stupa-like roof (Wagora style).","darshan":"History walk.","seasonal":"Hot summers.","visitorNotes":"Visit the museum in Ter.","festivals":"None.","sources":[{"label":"Ter","url":"https://en.wikipedia.org/wiki/Ter,_Maharashtra","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-thane-kopineshwar-mahadev-temple-thane-city', 'shiva', 'Kopineshwar Mahadev Temple (Thane City)', 'Maharashtra', 'Thane', 'Masunda Lake', 'Shiva', 'Shaiva', '["Shilahara","Thane","Large linga"]', 'The principal Shiva anchor in Thane city, revered for housing one of the largest Swayambhu lingas in Maharashtra.', 'Major Thane-city Mahadev temple near Masunda Lake with a large Swayambhu linga.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shri_Kopineshwar_Mandir.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shri_Kopineshwar_Mandir.jpg', 'Evening aarti hours.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect local market crowds around the temple lanes.', '["Abhishekam","Daily aarti"]', '["Mahashivratri"]', '{"history":"Built by the Shilahara dynasty, Kopineshwar has undergone multiple renovations since the 18th century.","architecture":"Traditional temple complex with a large central linga and multiple shrines.","darshan":"The main sanctum houses the large Shiva linga revered by Thane devotees.","seasonal":"Festival days see extended queues.","visitorNotes":"Two entry gates serve the complex; plan based on crowd flow.","festivals":"Mahashivratri is the most visited festival.","sources":[{"label":"Kopineshwar Mahadev Temple (Thane City)","url":"https://en.wikipedia.org/wiki/Kopineshwar_Mandir,_Thane","type":"Encyclopedia"}]}', '2026-02-25T14:54:24+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
