INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-trimbak-kedareshwar-temple', 'shiva', 'Kedareshwar Temple', 'Maharashtra', 'Trimbak', 'Near Kushavarta Kund, Trimbak', 'Shiva', 'Shaiva', '["Kushavarta","Trimbak","Pilgrimage"]', 'A Kedareshwar Mahadev shrine near Kushavarta Kund in Trimbak, linked to the core Godavari-origin pilgrimage circuit.', 'Kushavarta-adjacent darshan node in Trimbak.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carvings%20at%20Kedareswara%20Mahadev%20Mandir%20near%20Kusavarta%20kund,%20Nashik.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Carvings_at_Kedareswara_Mahadev_Mandir_near_Kusavarta_kund,_Nashik.jpg', 'Early morning in Trimbak.', 'Open daily; timings vary by local schedule.', 'Traditional attire preferred.', 'Commonly visited with Trimbakeshwar and Kushavarta Kund.', '["Abhishekam","Kund parikrama"]', '["Mahashivratri","Shravan month"]', '{"history":"Kedareshwar worship is part of the wider Trimbak sacred geography around Kushavarta.","architecture":"Stone carvings around the shrine indicate continuous ritual use.","darshan":"Typically included in local Trimbak temple circuits.","seasonal":"Pilgrim movement increases during Shravan and Kumbh-linked periods.","visitorNotes":"Plan darshan early to avoid peak queue windows.","festivals":"Mahashivratri and Shravan Somvar draw local devotees.","sources":[{"label":"Wikimedia: Kedareswara Mahadev Mandir near Kusavarta","url":"https://commons.wikimedia.org/wiki/File:Carvings_at_Kedareswara_Mahadev_Mandir_near_Kusavarta_kund,_Nashik.jpg","type":"Wikimedia Commons"},{"label":"Kushavart Tirtha - Nashik District","url":"https://nashik.gov.in/en/tourist-place/kushavart-tirtha-trimbakeshwar/","type":"Government tourism"}]}', '2026-02-23T00:36:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-trimbak-shiv-jata-mandir', 'shiva', 'Shiv Jata Mandir', 'Maharashtra', 'Trimbak', 'Brahmagiri Hill, Trimbak', 'Shiva', 'Shaiva', '["Brahmagiri","Hill Shrine","Godavari Origin Tradition"]', 'A hill shrine on Brahmagiri linked to the local tradition of Shiva\'s jata and the origin narrative of the Godavari.', 'High-elevation darshan on the Brahmagiri route.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Clear-weather mornings.', 'Daytime access; timings vary by season and route conditions.', 'Comfortable modest attire for uphill walking.', 'Access involves a climb on Brahmagiri routes.', '["Hill darshan","Pradakshina"]', '["Mahashivratri","Shravan month"]', '{"history":"The shrine is part of the extended sacred landscape around Trimbak and Brahmagiri.","architecture":"Small hill shrine format aligned with trekking-pilgrimage practice.","darshan":"Often paired with Trimbakeshwar and nearby kund visits.","seasonal":"Monsoon routes can be slippery; winter visibility is clearer.","visitorNotes":"Carry water and use suitable footwear for the climb.","festivals":"Shravan observances increase pilgrim movement on the hill routes.","sources":[{"label":"Trimbakeshwar Shiva Temple","url":"https://en.wikipedia.org/wiki/Trimbakeshwar_Shiva_Temple","type":"Encyclopedia"},{"label":"Kushavart Tirtha - Nashik District","url":"https://nashik.gov.in/en/tourist-place/kushavart-tirtha-trimbakeshwar/","type":"Government tourism"}]}', '2026-02-23T00:37:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-trimbak-shri-trimbakeshwar-jyotirlinga', 'shiva', 'Shri Trimbakeshwar Jyotirlinga', 'Maharashtra', 'Trimbak', 'Brahmagiri Hills, Nashik', 'Shiva', 'Shaiva', '["Jyotirlinga","Godavari","Peshwa Era"]', 'The jyotirlinga shrine of Trimbak, revered as a primary Shaiva macro-center where the Godavari source tradition begins.', 'Three-faced linga tradition with Brahmagiri and Kushavarta pilgrimage circuit.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Trimbakeshwar_Shiva_Temple_Gopuram.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Trimbakeshwar_Shiva_Temple_Gopuram.jpg', 'Early morning; Shravan Mondays for devotional ambience.', 'Open daily; timings vary by season.', 'Modest traditional attire recommended.', 'Expect queues during Shravan and Mahashivratri.', '["Abhishekam","Rudra puja"]', '["Mahashivratri","Shravan month"]', '{"history":"An ancient jyotirlinga shrine at Trimbak, rebuilt in stone during the Peshwa era, with a linga that represents Brahma, Vishnu, and Shiva.","architecture":"Hemadpanthi-style stone architecture with a prominent courtyard and carved shikhara.","darshan":"The sanctum enshrines the three-faced jyotirlinga, with the Godavari source nearby at Brahmagiri.","seasonal":"Shravan Somvars and Mahashivratri draw the highest crowds.","visitorNotes":"Plan early entries during peak seasons for smoother darshan.","festivals":"Mahashivratri and Shravan Somvar rituals are the major highlights.","sources":[{"label":"Trimbakeshwar Shiva Temple","url":"https://en.wikipedia.org/wiki/Trimbakeshwar_Shiva_Temple","type":"Encyclopedia"},{"label":"Trimbakeshwar Trust","url":"http://www.trimbakeshwartrust.com/","type":"Temple trust"}]}', '2026-02-23T00:31:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
