INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-verul-grishneshwar-jyotirlinga-verul', 'shiva', 'Grishneshwar Jyotirlinga (Verul)', 'Maharashtra', 'Verul', 'Ellora, Chhatrapati Sambhajinagar', 'Shiva', 'Shaiva', '["Jyotirlinga","Ellora","Hemadpanthi"]', 'The 12th and final jyotirlinga in the classical tradition, this Verul shrine is a major Shaiva pilgrimage center near Ellora.', 'Jyotirlinga darshan at Verul with red-stone temple architecture restored in the Holkar period.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Grishneshwar_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Grishneshwar_Temple.jpg', 'Morning darshan in winter months.', 'Open daily; timings vary by season.', 'Traditional attire preferred.', 'Footwear is not allowed inside the sanctum area.', '["Abhishekam","Evening aarti"]', '["Mahashivratri"]', '{"history":"Grishneshwar is one of the twelve jyotirlingas at Verul near Ellora, and the present temple form is associated with 18th-century restoration by Ahilyabai Holkar.","architecture":"The temple is associated with Hemadpanthi-style stone construction common in the region.","darshan":"The jyotirlinga sanctum is the focal point of daily rituals and pilgrim queues.","seasonal":"Mahashivratri brings the heaviest footfall.","visitorNotes":"Combine darshan with Ellora heritage visits in the same trip.","festivals":"Mahashivratri is the key annual celebration.","sources":[{"label":"Grishneshwar Jyotirlinga (Verul)","url":"https://en.wikipedia.org/wiki/Grishneshwar_Temple","type":"Encyclopedia"},{"label":"Sambhaji Nagar District Administration","url":"https://aurangabad.gov.in/","type":"District administration"}]}', '2026-02-25T14:37:20+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-verul-kailasa-temple-ellora-cave-16', 'shiva', 'Kailasa Temple (Ellora Cave 16)', 'Maharashtra', 'Verul', 'Ellora Caves, Chhatrapati Sambhajinagar district', 'Shiva', 'Shaiva', '["Rock-cut","Rashtrakuta","Ellora"]', 'An iconic monolithic Shiva temple at Ellora Cave 16, carved top-down from a single basalt rock mass in the form of Mount Kailash symbolism.', 'One-piece top-down monolithic excavation with monumental Shaiva sculptural program.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kailasa_temple_Ellora.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kailasa_temple_Ellora.jpg', 'Morning heritage walks and winter weather.', 'Heritage site hours; timings vary by season.', 'Comfortable walking attire recommended.', 'Part of the Ellora heritage complex; plan for additional cave visits.', '["Not Available"]', '["Not Available"]', '{"history":"Commissioned in the Rashtrakuta period, the Kailasa Temple is a giant top-down monolithic excavation and one of the largest rock-cut Shiva temples in India.","architecture":"Carved from a single rock mass with elaborate sculptural treatments and multi-level courts.","darshan":"The shrine is approached through monumental rock-cut gateways and courtyards.","seasonal":"Winter and early morning visits are most comfortable.","visitorNotes":"Ellora has multiple cave groups; allow extra time for exploration.","festivals":"Primarily a heritage destination rather than a festival site.","sources":[{"label":"Kailasa Temple (Ellora Cave 16)","url":"https://en.wikipedia.org/wiki/Kailasa_Temple,_Ellora","type":"Encyclopedia"}]}', '2026-02-25T14:37:20+05:30', 'seed', 'src/d