INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-yawat-bhuleshwar-temple-yavat', 'shiva', 'Bhuleshwar Temple (Yavat)', 'Maharashtra', 'Yawat', 'Pune district', 'Shiva', 'Shaiva', '["Hilltop","Protected monument","8th century"]', 'A major Yadava-period Shaiva hill temple near Yawat, known for its sculpted basalt architecture.', '13th-century hilltop shrine geometry and extensive stone carvings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhuleshwar_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bhuleshwar_Temple.jpg', 'Monsoon greenery and winter mornings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'The temple sits on a hill; expect short climbs.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Bhuleshwar Temple is a medieval Yadava-era Shiva shrine and protected monument near Pune.","architecture":"Basalt stone construction with classical carvings and sculpted panels.","darshan":"The sanctum houses the Shiva linga, reached via a hilltop approach.","seasonal":"Monsoon and winter visits are most comfortable.","visitorNotes":"Carry water for the hill climb during hot months.","festivals":"Mahashivratri attracts the largest crowds.","sources":[{"label":"Bhuleshwar Temple","url":"https://en.wikipedia.org/wiki/Bhuleshwar_Temple","type":"Encyclopedia"}]}', '2026-02-23T00:45:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-maharashtra-yedshi-ramling-temple-yedshi', 'shiva', 'Ramling Temple (Yedshi)', 'Maharashtra', 'Yedshi', 'Yedshi Ramling Ghat Wildlife Sanctuary, Dharashiv (Osmanabad) district', 'Shiva', 'Shaiva', '["Ramling","Cave Node","Wildlife Sanctuary"]', 'An ancient cave-linked Shiva shrine inside the Yedshi Ramling Ghat sanctuary, set at the base of a ravine with a natural spring-fed, hydro-cooled worship environment.', 'Deep-forest ravine temple with continuous spring-linked lingam worship.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Ramling_Temple_Yedshi.jpg/640px-Ramling_Temple_Yedshi.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ramling_Temple_Yedshi.jpg', 'Post-monsoon and winter mornings.', 'Open daily; local timings vary.', 'Modest attire and trekking-friendly footwear recommended.', 'Inside a wildlife sanctuary; terrain can be slippery near spring-fed sections.', '["Abhishekam","Jalabhishek"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Ramling at Yedshi is preserved in local tradition as an old cave-linked Shiva shrine connected to long-running forest pilgrimage routes.","architecture":"Natural-rock and cave-context shrine profile with sanctum-focused ritual flow.","darshan":"Darshan combines forest silence, ravine setting, and spring-fed worship practice.","seasonal":"Monsoon intensifies water flow; post-monsoon and winter are easier for access.","visitorNotes":"Visit in daylight and follow sanctuary safety guidance.","festivals":"Mahashivratri and Shravan Mondays are the key observance windows.","sources":[{"label":"Yedshi Ramling","url":"https://en.wikipedia.org/wiki/Yedshi_Ramling_Ghat_Wildlife_Sanctuary","type":"Encyclopedia"},{"label":"Dharashiv district","url":"https://en.wikipedia.org/wiki/Osmanabad_district","type":"Encyclopedia"}]}', '2026-02-25T15:40:47+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
