INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-rajasthan-baroli-baroli-temples-complex', 'shiva', 'Baroli Temples Complex', 'Rajasthan', 'Baroli', 'Rawatbhata, Chittorgarh district', 'Shiva', 'Shaiva', '["Gurjara-Pratihara","Temple complex","Heritage"]', 'A walled complex of early medieval temples at Baroli, noted for Gurjara-Pratihara architecture and Shiva worship.', 'Cluster of stone shrines near the Chambal River.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baroli_temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baroli_temple.jpg', 'October to March for comfortable weather.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'The complex is spread out; wear comfortable footwear.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"The Baroli Temples Complex is a group of early medieval shrines in Baroli village under ASI protection.","architecture":"The temples are built in the Gurjara-Pratihara style with richly carved stonework.","darshan":"Several shrines within the complex are dedicated to Shiva.","seasonal":"Winter months are best for exploring the open-air complex.","visitorNotes":"Carry water and plan time for multiple shrines within the enclosure.","festivals":"Mahashivratri draws local visitors to the Shiva shrines.","sources":[{"label":"Baroli Temples","url":"https://en.wikipedia.org/wiki/Baroli_Temples","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
