INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-rajasthan-bisalpur-bisaldeo-mahadev-temple-bisalpur-12th-century-gokarneshwar-temple-asi-monument', 'shiva', 'Bisaldeo Mahadev Temple (Bisalpur - 12th century Gokarneshwar Temple, ASI monument)', 'Rajasthan', 'Bisalpur', 'Bisalpur, Tonk district', 'Shiva', 'Shaiva', '["Rajasthan","Tonk","Shiva"]', 'Bisaldeo Mahadev Temple at Bisalpur is a major Shaiva heritage site in Tonk district, linked with the 12th-century Gokarneshwar tradition and protected as an ASI monument.', 'Historic Bisalpur Mahadev anchor in the Tonk Shaiva circuit.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bisaldeo%20temple%20and%20Bisalpur%20dam.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bisaldeo_temple_and_Bisalpur_dam.jpg', 'Morning and evening darshan.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Heritage-zone visit; confirm ASI/local access timing before travel.', '["Daily puja","Jal abhishek"]', '["Mahashivratri","Shravan month"]', '{"history":"Bisaldeo Mahadev Temple (Bisalpur) is a heritage Shaiva site in the Tonk district temple coverage set.","architecture":"Regional shrine architecture with active local worship traditions.","visitorNotes":"Plan local navigation in daylight for smoother district travel.","sources":[{"label":"Tonk district","url":"https://en.wikipedia.org/wiki/Tonk_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Bisaldeo%20Mahadev%20Temple%20Bisalpur%20Tonk","type":"Map search"}]}', '2026-02-26T20:15:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-26T14:45:00Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-rajasthan-bisalpur-bisaldeo-temple', 'shiva', 'Bisaldeo Temple', 'Rajasthan', 'Bisalpur', 'Tonk district, Banas River', 'Shiva', 'Shaiva', '["Chahamana","Banas River","Heritage"]', 'A 12th-century Shiva temple at Bisalpur, known for its riverside setting and partial submersion during high water.', 'Stone temple beside the Bisalpur Dam reservoir.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bisaldeo_temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bisaldeo_temple.jpg', 'Post-monsoon for water views and pleasant weather.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Water levels can affect access to the lower courtyard.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Bisaldeo is a 12th-century Shiva temple commissioned in the Chahamana period near the Banas River.","architecture":"The temple includes a garbhagriha, mandapa, and stone shikhara typical of the era.","darshan":"Darshan is offered at the Shiva linga in the main sanctum.","seasonal":"Reservoir levels can partially submerge the courtyard during heavy rains.","visitorNotes":"Plan visits in daylight and check access during monsoon months.","festivals":"Mahashivratri is the main annual observance.","sources":[{"label":"Bisaldeo temple","url":"https://en.wikipedia.org/wiki/Bisaldeo_temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
