INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-rajasthan-dausa-neelkanth-mahadev-temple-dausa', 'shiva', 'Neelkanth Mahadev Temple (Dausa)', 'Rajasthan', 'Dausa', 'Devgiri Hill, Dausa district', 'Shiva', 'Shaiva', '["Hilltop","Pilgrimage","Steps"]', 'A hilltop Shiva temple on Devgiri Hill, reached by a long staircase and known for its local pilgrimage traditions.', 'Devgiri hill ascent and panoramic views around Dausa.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Neelkanth_Mahadev,_Temple_Dausa.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Neelkanth_Mahadev,_Temple_Dausa.jpg', 'Early mornings or cooler winter days for the climb.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect a stair climb; carry water and visit during daylight hours.', '["Abhishekam","Daily puja"]', '["Mahashivratri","Shravan month"]', '{"history":"Neelkanth Mahadev Temple sits on Devgiri Hill in Dausa district and is a key local Shiva pilgrimage.","architecture":"The temple complex crowns the hilltop, with a prominent approach via steps.","darshan":"Darshan focuses on the Shiva shrine at the hill summit.","seasonal":"Shravan and Mahashivratri bring the highest footfall.","visitorNotes":"The climb can be steep; plan early to avoid heat.","festivals":"Mahashivratri and Shravan month are peak devotional periods.","sources":[{"label":"Neelkanth Mahadev Temple, Dausa","url":"https://en.wikipedia.org/wiki/Neelkanth_Mahadev_Temple,_Dausa","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
