INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-rajasthan-kota-char-choma-mahadev-temple', 'shiva', 'Char Choma Mahadev Temple', 'Rajasthan', 'Kota', 'Char Choma Village', 'Shiva', 'Shaiva', '["Gupta Period","Archaeology","Ancient"]', 'A hidden archaeological treasure, this is one of the few surviving temples from the Gupta period in Rajasthan.', 'Rare Gupta-era architecture and flat-roofed style.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Winter months.', 'Open daily.', 'Casual/Modest.', 'Located about 30km from Kota; requires private transport.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Dates back to the Gupta empire (approx 5th-6th century AD).","architecture":"Flat roof (unlike the later shikhara style) with heavy stone pillars.","darshan":"A step back in time to ancient India.","seasonal":"Avoid peak summer heat.","visitorNotes":"A must for history students and archaeology enthusiasts.","festivals":"Local villagers celebrate Shivratri here.","sources":[{"label":"Kota History","url":"https://en.wikipedia.org/wiki/Kota,_Rajasthan","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-rajasthan-kota-garadia-mahadev-temple', 'shiva', 'Garadia Mahadev Temple', 'Rajasthan', 'Kota', 'Chambal Valley, near Kota', 'Shiva', 'Shaiva', '["Canyon view","Nature","Chambal"]', 'A Shiva temple perched on a cliff edge offering a breathtaking view of the Chambal River\'s horseshoe bend.', 'Panoramic view of the Chambal river canyon.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Garadiya_Mahadev.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Garadiya_Mahadev.jpg', 'Monsoon and winter for lush greenery and clear views.', 'Open daily; entry usually closes before sunset.', 'Comfortable attire; walking shoes recommended.', 'Requires a ticket for vehicle entry; located within a forest zone.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"A local shrine that gained fame for its dramatic location overlooking the Chambal gorge.","architecture":"Simple shrine structure; the natural setting is the main attraction.","darshan":"The shrine is small, but the view of the river gorge is the spiritual highlight.","seasonal":"Monsoon brings waterfalls and green landscapes.","visitorNotes":"Careful near the cliff edges; carry water and snacks.","festivals":"Mahashivratri attracts local crowds.","sources":[{"label":"Garadia Mahadev","url":"https://en.wikipedia.org/wiki/Kota,_Rajasthan#Tourism","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-rajasthan-kota-geparnath-mahadev-temple', 'shiva', 'Geparnath Mahadev Temple', 'Rajasthan', 'Kota', 'Chambal valley, Kota district', 'Shiva', 'Shaiva', '["Cave temple","Waterfall","Adventure"]', 'A Shiva temple situated deep in a gorge near Kota, accessible by a long flight of stairs.', 'Natural waterfall dropping directly onto the temple area.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gaipar_nath_tample.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gaipar_nath_tample.jpg', 'Monsoon (with caution) and winter.', 'Open daily; strictly daylight hours.', 'Comfortable trekking attire.', 'Requires descending ~300 steps; difficult for elderly.', '["Jalabhishekam (natural)"]', '["Mahashivratri"]', '{"history":"An ancient spot dating back to the 16th century, associated with royal patronage.","architecture":"Cave-like shrine integrated into the rock face.","darshan":"The Shiva linga is often bathed by the natural spring water.","seasonal":"Access can be closed during heavy rains due to flash floods.","visitorNotes":"Monkeys are common; keep food hidden.","festivals":"Mahashivratri sees heavy footfall despite the steep climb.","sources":[{"label":"Geparnath Mahadev Temple","url":"https://en.wikipedia.org/wiki/Geparnath_Mahadev_Temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
