INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-avinashi-avinashiappar-temple', 'shiva', 'Avinashiappar Temple', 'Tamil Nadu', 'Avinashi', 'Tiruppur District', 'Shiva (Avinashiappar)', 'Shaiva', '["Kongu Nadu","Crocodile Miracle","Ancient"]', 'One of the seven Shiva temples of Kongu Nadu. Legend says saint Sundarar rescued a boy from a crocodile\'s mouth here through a song.', 'The \'Mudalai-Yunda-Siruvan\' festival re-enacting the miracle.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Avinashi_avinashiappar_temple2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Avinashi_avinashiappar_temple2.jpg', 'April-May (Chariot Festival).', '6:00 AM - 1:00 PM, 4:00 PM - 8:30 PM.', 'Modest.', 'Known for its massive and beautiful wooden chariot.', '["Sundarar pathigam recitation"]', '["Panguni Uthiram"]', '{"history":"Built by the Cholas and later expanded by the Mysore kings.","architecture":"Features a tall gopuram and detailed pillar carvings."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-bannari-bannari-mariamman-temple', 'shiva', 'Bannari Mariamman Temple', 'Tamil Nadu', 'Bannari', 'Erode District', 'Bannari', 'Shakta', '["Mariamman","Kongu","Pilgrimage"]', 'A prominent Mariamman temple near Sathyamangalam in the Kongu region.', 'Panguni Kundam festival and vibrant temple rituals.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bannari_Amman_Temple.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bannari_Amman_Temple.JPG', 'Panguni festival season.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Crowds increase during festival days.', '["Daily puja","Evening aarti"]', '["Panguni Kundam","Navratri"]', '{"history":"Bannari Mariamman Temple is an Amman temple near Sathyamangalam in Erode district.","sources":[{"label":"Bannari Mariamman Temple","url":"https://en.wikipedia.org/wiki/Bannari_Mariamman_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-bhavani-sangameswarar-temple', 'shiva', 'Sangameswarar Temple', 'Tamil Nadu', 'Bhavani', 'Erode District', 'Shiva (Sangameswarar)', 'Shaiva', '["Triveni Sangam","Rivers","Remedy"]', 'Located at the holy confluence of three rivers: Bhavani, Kaveri, and the invisible Amudha. It is often called the \'Kashi of the South\'.', 'The Sangam point where devotees perform rituals for their ancestors.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhavani_sangameswarar_temple2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bhavani_sangameswarar_temple2.jpg', 'Aadi Perukku (August).', '6:00 AM - 1:00 PM, 4:00 PM - 9:00 PM.', 'Modest.', 'Devotees usually take a dip in the river confluence before darshan.', '["Pithru Tharpanam"]', '["Maha Shivratri"]', '{"history":"Ancient site visited by various saints; renovated by the Pandyas.","architecture":"Riverside temple with long corridors."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chakkarappalli-chakravageswarar-temple', 'shiva', 'Chakravageswarar Temple', 'Tamil Nadu', 'Chakkarappalli', 'Thanjavur District', 'Shiva', 'Shaiva', '["Shaiva","Thanjavur district","Temple"]', 'Chakravageswarar Temple is a Shiva temple in Thanjavur district with active local worship traditions.', 'Traditional Shiva worship at Chakkarappalli.', 'Not Available', 'Not Available', 'Not Available', 'October to March and Mahashivratri period.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Chakravageswarar Temple is listed among Shiva temples in Thanjavur district, Tamil Nadu.","architecture":"Dravidian temple architecture with regional variation.","visitorNotes":"Check local opening times before planning your visit.","sources":[{"label":"Chakravageswarar Temple (Wikipedia)","url":"https://en.wikipedia.org/wiki/Chakravageswarar_Temple%2C_Chakkarappalli","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chennai-ashtalakshmi-temple-chennai', 'shiva', 'Ashtalakshmi Temple (Chennai)', 'Tamil Nadu', 'Chennai', 'Besant Nagar', 'Ashtalakshmi', 'Shakta', '["Lakshmi","Chennai","Besant Nagar"]', 'A multi-level shrine in Besant Nagar housing the eight forms of Goddess Lakshmi.', 'Nine sanctums across four levels for the Ashtalakshmis.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ashtalakshmi%20temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ashtalakshmi_temple.jpg', 'Navratri and weekday mornings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Located near the beach; expect weekend crowds.', '["Daily puja","Evening aarti"]', '["Navratri","Varalakshmi Vratam"]', '{"history":"The Ashtalakshmi Temple in Chennai was consecrated in 1976 and enshrines the eight forms of Lakshmi.","architecture":"A multi-level temple with separate sanctums for each Lakshmi form.","darshan":"Darshan is available daily with regular aarti timings.","seasonal":"Navratri is the busiest festival season.","visitorNotes":"Plan early visits on weekends and festival days.","festivals":"Navratri · Varalakshmi Vratam","sources":[{"label":"Ashtalakshmi Temple, Chennai","url":"https://en.wikipedia.org/wiki/Ashtalakshmi_Temple%2C_Chennai"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chennai-kalikambal-temple', 'shiva', 'Kalikambal Temple', 'Tamil Nadu', 'Chennai', 'George Town', 'Kalikambal (Kamakshi)', 'Shakta', '["Kalikambal","Chennai","Heritage"]', 'A historic city shrine dedicated to Kalikambal (Kamakshi) in the heart of old Chennai.', 'Heritage temple street near Parry’s Corner.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arulmigu%20Sri%20Kalikambal.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Arulmigu_Sri_Kalikambal.jpg', 'Morning darshan and weekday visits.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple sits within a busy market street; plan for traffic.', '["Daily puja","Evening aarti"]', '["Navratri"]', '{"history":"The Kalikambal Temple in Chennai was relocated in the 17th century and remains a prominent urban shrine.","architecture":"Traditional South Indian temple layout with a gopuram entrance.","darshan":"Darshan is available daily with regular aarti timings.","seasonal":"Navratri draws the largest crowds.","visitorNotes":"Expect busy streets and limited parking in George Town.","festivals":"Navratri","sources":[{"label":"Kalikambal Temple","url":"https://en.wikipedia.org/wiki/Kalikambal_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chennai-kapaleeshwarar-temple', 'shiva', 'Kapaleeshwarar Temple', 'Tamil Nadu', 'Chennai', 'Mylapore', 'Shiva (Kapaleeshwarar)', 'Shaiva', '["Dravidian","Mylapore","Shiva"]', 'A classic example of Dravidian architecture in the heart of Chennai. Legend says Parvati worshipped Shiva here in the form of a peacock (Mayil), giving the area its name, Mylapore.', 'The towering 120-foot gopuram and the large temple tank (Teppakulam).', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chennai_Kapaleeshwarar_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chennai_Kapaleeshwarar_Temple.jpg', 'March-April (Arubathimoovar Festival).', '5:00 AM - 12:00 PM, 4:00 PM - 9:00 PM.', 'Traditional attire encouraged.', 'Very crowded during the annual festival featuring the 63 Nayanmars.', '["Daily puja","Pradosham prayers"]', '["Arubathimoovar","Panguni Uthiram"]', '{"history":"The original temple was likely destroyed by the Portuguese; the current structure dates back to the 16th century.","architecture":"Features a classic gopuram and a spacious pillared mandapa."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chennai-marundeeswarar-temple', 'shiva', 'Marundeeswarar Temple', 'Tamil Nadu', 'Chennai', 'Thiruvanmiyur', 'Shiva', 'Shaiva', '["Shiva","Healing","Chennai"]', 'A Shaiva temple in Thiruvanmiyur revered for healing traditions.', 'Seaside temple precincts and daily worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Marundeeswarar_temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Marundeeswarar_temple.jpg', 'Morning visits for calmer darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Crowds increase during festival days.', '["Daily puja","Evening aarti"]', '["Panguni Brahmotsavam","Mahashivratri"]', '{"history":"Marundeeswarar Temple is a Shiva temple in Thiruvanmiyur, Chennai with a long devotional history.","puranicView":"The temple is among the Paadal Petra Sthalams revered by Tamil Shaiva saints.","puranicSources":[{"label":"Marundeeswarar Temple","url":"https://en.wikipedia.org/wiki/Marundeeswarar_Temple","type":"Encyclopedia"}],"folklore":"Local worship emphasizes prayers for wellbeing and health.","folkloreSources":[{"label":"Marundeeswarar Temple","url":"https://en.wikipedia.org/wiki/Marundeeswarar_Temple","type":"Encyclopedia"}],"sources":[{"label":"Marundeeswarar Temple","url":"https://en.wikipedia.org/wiki/Marundeeswarar_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chennai-parthasarathy-temple', 'shiva', 'Parthasarathy Temple', 'Tamil Nadu', 'Chennai', 'Triplicane', 'Vishnu (Parthasarathy)', 'Vaishnava', '["Divya Desam","Vishnu","Krishna"]', 'One of the few temples where Lord Vishnu is worshipped as Krishna in the form of a charioteer (Parthasarathy) with a moustache.', 'The scar marks on the idol\'s face, symbolizing wounds received from Bhishma\'s arrows in the Mahabharata.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Parthasarathy-Temple-Triplicane-Chennai-7.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Parthasarathy-Temple-Triplicane-Chennai-7.JPG', 'Vaikuntha Ekadashi.', '6:00 AM - 12:30 PM, 4:00 PM - 9:00 PM.', 'Traditional.', 'Known for its delicious \'Puliyodarai\' (tamarind rice) prasadam.', '["Daily Thirumanjanam"]', '["Vaikuntha Ekadashi","Theppotsavam"]', '{"history":"Built by the Pallavas in the 8th century.","architecture":"Features shrines for five different incarnations of Vishnu."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chidambaram-ariswaramudaiyar-temple', 'shiva', 'Ariswaramudaiyar Temple', 'Tamil Nadu', 'Chidambaram', 'Chidambaram region, Cuddalore district', 'Shiva', 'Shaiva', '["Shaiva","Ariswaramudaiyar","Temple Circuit"]', 'A local Shiva shrine named Ariswaramudaiyar, counted in regional Chidambaram devotional routes.', 'A traditional village-temple style Shaiva node.', '/temples/temple-06.svg', 'Not Available', 'Not Available', 'Morning and evening darshan hours.', 'Open daily; local timings vary.', 'Traditional and modest attire recommended.', 'Local pronunciation/spelling may vary by village usage.', '["Daily puja"]', '["Mahashivratri","Pradosham"]', '{"history":"Part of Chidambaram\'s wider network of local Shaiva worship centers.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Ariswaramudaiyar%20Temple%20Chidambaram"}]}', '2026-02-23T13:19:31+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chidambaram-azhageshwarar-temple', 'shiva', 'Azhageshwarar Temple', 'Tamil Nadu', 'Chidambaram', 'Chidambaram region, Cuddalore district', 'Shiva (Azhageshwarar)', 'Shaiva', '["Shaiva","Azhageshwarar","Local Shrine"]', 'A Shiva temple associated with local Chidambaram devotional circuits and traditional worship.', 'A compact regional Shaiva shrine for daily darshan.', '/temples/temple-01.svg', 'Not Available', 'Not Available', 'Morning puja time.', 'Open daily; local timings vary.', 'Traditional and modest attire recommended.', 'Best visited as part of a grouped Chidambaram temple route.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"The shrine is preserved through ongoing local temple worship traditions.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Azhageshwarar%20Temple%20Chidambaram"}]}', '2026-02-23T13:19:31+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chidambaram-chidambaram-nataraja-temple', 'shiva', 'Chidambaram Nataraja Temple', 'Tamil Nadu', 'Chidambaram', 'Cauvery Delta', 'Nataraja', 'Shaiva', '["Nataraja","Dance","Heritage"]', 'A famed temple of Nataraja where art, dance, and Shaiva devotion meet.', 'Evening rituals and the temple\'s golden roofline.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chidambaram-Thillai_Nataraja_Temple-WUS02398.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chidambaram-Thillai_Nataraja_Temple-WUS02398.jpg', 'Early mornings or evenings for rituals.', 'Open daily; timings vary by season.', 'Traditional attire recommended.', 'Large temple complex; expect walking within the precincts.', '["Daily puja","Arudra darshan"]', '["Arudra Darshan","Mahashivratri"]', '{"puranicView":"The temple centers on Nataraja\'s cosmic dance (Ananda Tandava), a Shaiva Puranic symbol of creation and dissolution. Chidambaram is revered as one of the Pancha Bhoota kshetras, representing the element of akasha (ether).","puranicSources":[{"label":"Chidambaram Nataraja Temple","url":"https://en.wikipedia.org/wiki/Chidambaram_Nataraja_Temple","type":"Encyclopedia (Shaiva tradition)"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
