INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-chidambaram-thillai-nataraja-temple-the-supreme-macro-center', 'shiva', 'Thillai Nataraja Temple (The supreme macro-center)', 'Tamil Nadu', 'Chidambaram', 'Cuddalore District', 'Shiva (Nataraja)', 'Shaiva', '["Akasha Lingam","Nataraja","Pancha Bhoota"]', 'This is where Shiva is worshipped as the Lord of Dance (Nataraja). It represents the element \'Ether\' (Akasha).', 'The Chidambara Rahasyam (Secret of Chidambaram) and the golden-roofed sanctum.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thillai_Nataraja_Temple_(Chidambaram_Nataraja_Temple).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Thillai_Nataraja_Temple_(Chidambaram_Nataraja_Temple).jpg', 'December (Arudhra Darisanam).', '6:00 AM - 12:00 PM, 5:00 PM - 10:00 PM.', 'Traditional attire mandatory.', 'Known for the cosmic connection to the center of the earth.', '["Ananda Tandava Puja","Spatika Linga Abhishekam"]', '["Arudhra Darisanam","Natyanjali"]', '{"history":"The temple is managed by a unique community of priests called Dikshitars.","architecture":"Includes depictions of the 108 Karanas from Natya Shastra.","sources":[{"label":"Chidambaram Temple","url":"https://chidambaramnataraja.org/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
