INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-cholapuram-bhairavesvarar-temple', 'shiva', 'Bhairavesvarar Temple', 'Tamil Nadu', 'Cholapuram', 'Thanjavur District', 'Shiva', 'Shaiva', '["Shaiva","Thanjavur district","Temple"]', 'Bhairavesvarar Temple is a Shiva temple in Thanjavur district with active local worship traditions.', 'Traditional Shiva worship at Cholapuram.', 'Not Available', 'Not Available', 'Not Available', 'October to March and Mahashivratri period.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Bhairavesvarar Temple is listed among Shiva temples in Thanjavur district, Tamil Nadu.","architecture":"Dravidian temple architecture with regional variation.","visitorNotes":"Check local opening times before planning your visit.","sources":[{"label":"Bhairavesvarar Temple (Wikipedia)","url":"https://en.wikipedia.org/wiki/Bhairavesvarar_Temple%2C_Cholapuram","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-courtallam-kutralanathar-temple', 'shiva', 'Kutralanathar Temple', 'Tamil Nadu', 'Courtallam', 'Tenkasi District', 'Shiva (Kutralanathar)', 'Shaiva', '["Pancha Sabhai","Waterfall","Chitra Sabha"]', 'Home to the \'Chitra Sabha\' (Hall of Pictures), one of the five places where Shiva performed his cosmic dance. It is located right next to the famous Courtallam waterfalls.', 'The Chitra Sabha with its stunning 18th-century murals depicting puranic stories.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Courtallam_%2C_Arulmigu_Thiru_Kuttralanathar_Temple_(58267).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Courtallam_,_Arulmigu_Thiru_Kuttralanathar_Temple_(58267).jpg', 'June-September (Monsoon season).', '6:00 AM - 8:00 PM.', 'Casual/Modest.', 'Devotees often take a holy dip in the waterfalls before entering.', '["Thiruvasagam recitation"]', '["Arudhra Darisanam"]', '{"history":"Sage Agastya is said to have shrunk a Vishnu idol into a Shiva linga here.","architecture":"Conch-shaped temple layout."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-cuddalore-pataaleeswarar-temple', 'shiva', 'Pataaleeswarar Temple', 'Tamil Nadu', 'Cuddalore', 'Tirupapuliyur', 'Shiva', 'Shaiva', '["Pataliputra of South","Appar","Miracle"]', 'Where saint Appar was tied to a stone and thrown into the sea, but floated back to shore by the grace of Shiva.', 'The shrine for saint Appar and the stone he floated on.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pataleeswarar_Temple,_Cuddalore_(15966262253).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pataleeswarar_Temple,_Cuddalore_(15966262253).jpg', 'Vaikasi Visakam.', '6:00 AM - 12:00 PM, 4:00 PM - 9:00 PM.', 'Modest.', 'Known as the capital of ancient Saivism in the region.', '["Saint Appar festival rituals"]', '["Maha Shivratri"]', '{"history":"Originally a Jain center before the conversion of the Pallava king.","architecture":"Chola era stone work."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-darasuram-airavatesvara-temple', 'shiva', 'Airavatesvara Temple', 'Tamil Nadu', 'Darasuram', 'Kumbakonam', 'Shiva', 'Shaiva', '["UNESCO","Chola","Miniature Carvings"]', 'Part of the Great Living Chola Temples, it is named after Airavata, the white elephant of Indra, who worshipped Shiva here.', 'The \'Musical Steps\' (Saptaswara steps) and the chariot-shaped mandapa.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Darasuram,_Airavatesvara_Temple,_Entrance,_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Darasuram,_Airavatesvara_Temple,_Entrance,_India.jpg', 'Winter (Oct-Feb).', '6:00 AM - 8:00 PM.', 'Casual.', 'The temple is smaller but much more intricately carved than Thanjavur.', '["Daily puja"]', '["Maha Shivratri"]', '{"history":"Built by Rajaraja Chola II in the 12th century.","architecture":"Famous for its intricate stone carvings that look like wood-work."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-darasuram-airavatesvara-temple-darasuram', 'shiva', 'Airavatesvara Temple (Darasuram)', 'Tamil Nadu', 'Darasuram', 'Darasuram, Thanjavur district', 'Shiva', 'Shaiva', '["Thanjavur","Darasuram","Airavatesvara"]', 'Airavatesvara Temple (Darasuram) is a Shiva temple in the Thanjavur sacred landscape.', 'Traditional Shiva worship at Darasuram.', 'https://commons.wikimedia.org/wiki/Special:FilePath/12th_century_Airavatesvara_Temple_at_Darasuram,_dedicated_to_Shiva,_built_by_the_Chola_king_Rajaraja_II_Tamil_Nadu_India_(5).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:12th_century_Airavatesvara_Temple_at_Darasuram,_dedicated_to_Shiva,_built_by_the_Chola_king_Rajaraja_II_Tamil_Nadu_India_(5).jpg', 'October to March and Mahashivratri period.', 'Open daily; timings vary by temple and season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja","Abhishekam"]', '["Mahashivratri"]', '{"history":"Airavatesvara Temple (Darasuram) is listed in the Thanjavur-region Shiva temple circuit of Tamil Nadu.","architecture":"Dravidian temple architecture with local variation.","visitorNotes":"Check local opening times before planning your visit.","sources":[{"label":"Thanjavur district","url":"https://en.wikipedia.org/wiki/Thanjavur_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Airavatesvara%20Temple%20(Darasuram)%20Darasuram%20Tamil%20Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
