INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-gangaikonda-cholapuram-brihadisvara-temple-gangaikonda-cholapuram', 'shiva', 'Brihadisvara Temple (Gangaikonda Cholapuram)', 'Tamil Nadu', 'Gangaikonda Cholapuram', 'Ariyalur District', 'Shiva', 'Shaiva', '["Shiva","UNESCO","Chola"]', 'A celebrated Chola temple complex dedicated to Shiva in Gangaikonda Cholapuram.', 'Great Living Chola heritage and towering vimana.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gangaikonda_Cholapuram-Temple-WUS02536.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gangaikonda_Cholapuram-Temple-WUS02536.jpg', 'Morning hours for calm darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage monument; respect site guidelines.', '["Daily puja","Evening aarti"]', '["Mahashivratri","Thiruvadirai"]', '{"history":"The temple was built under Rajendra Chola I and is part of the Great Living Chola Temples.","puranicView":"The shrine follows Shaiva worship traditions centered on the Shiva lingam.","puranicSources":[{"label":"Brihadisvara Temple, Gangaikonda Cholapuram","url":"https://en.wikipedia.org/wiki/Brihadisvara_Temple,_Gangaikonda_Cholapuram","type":"Encyclopedia"}],"folklore":"Local festivals and heritage walks keep the temple active year round.","folkloreSources":[{"label":"Brihadisvara Temple, Gangaikonda Cholapuram","url":"https://en.wikipedia.org/wiki/Brihadisvara_Temple,_Gangaikonda_Cholapuram","type":"Encyclopedia"}],"sources":[{"label":"Brihadisvara Temple, Gangaikonda Cholapuram","url":"https://en.wikipedia.org/wiki/Brihadisvara_Temple,_Gangaikonda_Cholapuram"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-jayankondam-gangaikonda-cholapuram', 'shiva', 'Gangaikonda Cholapuram', 'Tamil Nadu', 'Jayankondam', 'Ariyalur District', 'Shiva (Brihadeeswarar)', 'Shaiva', '["UNESCO","Chola","Massive Linga"]', 'Built to commemorate the victory of Rajendra Chola I over the northern kings up to the Ganges. It was once the capital of the Chola Empire.', 'The massive 13-foot high Shiva Linga and the elegant lion-shaped water well (Simhakeni).', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gangaikonda_Cholapuram_Temple_entrance.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gangaikonda_Cholapuram_Temple_entrance.jpg', 'Winter.', '6:00 AM - 8:00 PM.', 'Casual.', 'A quieter alternative to Thanjavur with massive open spaces.', '["Anna Abhishekam (covering the linga with cooked rice)"]', '["Maha Shivratri"]', '{"history":"The temple was the spiritual centerpiece of the new capital after the fall of Thanjavur\'s dominance.","architecture":"Resembles the Thanjavur temple but with more feminine, curved lines in the vimana."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-kanchipuram-ekambareswarar-temple-the-macro-center-the-earth-lingam', 'shiva', 'Ekambareswarar Temple (The macro-center, the Earth Lingam)', 'Tamil Nadu', 'Kanchipuram', 'Temple Town', 'Shiva', 'Shaiva', '["Prithvi Lingam","Mango Tree","Pancha Bhoota"]', 'Representing the element \'Earth,\' the main Linga is made of sand. Goddess Parvati is said to have worshipped it under an ancient mango tree.', 'The 3500-year-old sacred mango tree that yields four different types of fruit.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ekambareswarar_Temple_at_night_in_Kanchipuram_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ekambareswarar_Temple_at_night_in_Kanchipuram_01.jpg', 'March-April (Panguni Uthiram).', '6:00 AM - 12:30 PM, 4:00 PM - 8:30 PM.', 'Modest.', 'One of the most ancient temples in Kanchipuram.', '["Daily puja to the sand linga"]', '["Panguni Uthiram"]', '{"history":"Built by the Pallavas and later expanded by the Vijayanagar kings.","architecture":"Features a 1000-pillar hall.","sources":[{"label":"Kanchi Ekambareswarar","url":"https://ekambaranathar.hrce.tn.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-kanchipuram-iravatanesvara-temple', 'shiva', 'Iravatanesvara Temple', 'Tamil Nadu', 'Kanchipuram', 'Big Kanchipuram zone, Kanchipuram district', 'Shiva (Iravatanesvara)', 'Shaiva', '["Shaiva","Iravatanesvara","Heritage"]', 'Iravatanesvara Temple is an old Shiva temple in Kanchipuram associated with early stone temple traditions.', 'A historically notable Kanchi Shiva shrine documented in temple photography archives.', 'https://commons.wikimedia.org/wiki/Special:FilePath/N-TN-C24%20Iravatanesvara%20temple-Big%20Kanchipuram.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:N-TN-C24_Iravatanesvara_temple-Big_Kanchipuram.jpg', 'Morning and winter-season visits.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Also written as Iravathanesvara/Iravadhisvarar in some records.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"The shrine is part of Kanchipuram\'s documented cluster of classical Shiva temples.","sources":[{"label":"Commons file: Iravatanesvara temple","url":"https://commons.wikimedia.org/wiki/File:N-TN-C24_Iravatanesvara_temple-Big_Kanchipuram.jpg"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Iravatanesvara%20Temple%20Kanchipuram"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-kanchipuram-jvarahareswarar-temple', 'shiva', 'Jvarahareswarar Temple', 'Tamil Nadu', 'Kanchipuram', 'Kanchipuram city, Kanchipuram district', 'Shiva (Jvarahareswarar)', 'Shaiva', '["Jvarahara","Shaiva","Heritage"]', 'Jvarahareswarar Temple is a Shiva shrine in Kanchipuram associated with healing-oriented devotional practices.', 'A documented heritage temple with active local worship continuity.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jvaraharesvara%20Temple.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jvaraharesvara_Temple.JPG', 'Morning darshan; Mahashivratri period.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Name appears as Jvaraharesvara/Jvarahareswarar in different sources.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"The temple is listed in Kanchipuram\'s historic Shiva temple corpus.","sources":[{"label":"Commons file: Jvaraharesvara Temple","url":"https://commons.wikimedia.org/wiki/File:Jvaraharesvara_Temple.JPG"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Jvarahareswarar%20Temple%20Kanchipuram"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-kanchipuram-kachabeswarar-temple', 'shiva', 'Kachabeswarar Temple', 'Tamil Nadu', 'Kanchipuram', 'Kanchipuram city, Kanchipuram district', 'Shiva (Kachabeswarar)', 'Shaiva', '["Shaiva","Kanchi","Historic Shrine"]', 'Kachabeswarar Temple is a traditional Shiva temple in Kanchipuram associated with the city\'s layered Shaiva temple network.', 'An important local Shaiva shrine in the temple-town grid of Kanchi.', '/temples/temple-01.svg', 'Not Available', 'Not Available', 'Morning darshan and Pradosham evenings.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Can be covered with Ekambareswarar and Kailasanathar in one circuit.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"Kachabeswarar worship forms part of Kanchipuram\'s long-standing Shaiva heritage routes.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Kachabeswarar%20Temple%20Kanchipuram"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-kanchipuram-kailasanathar-temple', 'shiva', 'Kailasanathar Temple', 'Tamil Nadu', 'Kanchipuram', 'Temple Town', 'Shiva', 'Shaiva', '["Pallava","Sandstone","Ancient"]', 'The oldest structure in Kanchipuram, this temple is a masterpiece of Pallava architecture and served as an inspiration for the Thanjavur Big Temple.', 'The incredible sandstone carvings and the narrow \'entry and exit\' passage symbolizing birth and death.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kailasanathar_Temple._Kanchipuram,_TamilNadu.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kailasanathar_Temple._Kanchipuram,_TamilNadu.jpg', 'Maha Shivratri.', '6:00 AM - 12:00 PM, 4:00 PM - 7:00 PM.', 'Modest.', 'A heritage site with active worship; great for photography.', '["Daily puja"]', '["Maha Shivratri"]', '{"history":"Built by King Rajasimha Pallava in the 8th century AD.","architecture":"Features a pyramidal shikhara and 58 small shrines around the main compound."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-kanchipuram-kailasanathar-temple-the-oldest-pallava-structure-in-the-grid', 'shiva', 'Kailasanathar Temple (The oldest Pallava structure in the grid)', 'Tamil Nadu', 'Kanchipuram', 'Kanchi City', 'Shiva', 'Shaiva', '["Shiva","Pallava","Heritage"]', 'A Pallava era Shiva temple known for its early stone architecture.', 'Historic carvings and a serene temple courtyard.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kailasanathar_temple_Kanchipuram_(16).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kailasanathar_temple_Kanchipuram_(16).jpg', 'Morning visits for quieter darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage monument; respect site guidelines.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"Kailasanathar Temple is a Pallava era Shiva temple in Kanchipuram dating to around the 7th century.","puranicView":"The shrine follows Shaiva worship traditions and early Dravidian temple forms.","puranicSources":[{"label":"Kailasanathar Temple, Kanchipuram","url":"https://en.wikipedia.org/wiki/Kailasanathar_Temple,_Kanchipuram","type":"Encyclopedia"}],"folklore":"Visitors note the early stone reliefs and quiet atmosphere.","folkloreSources":[{"label":"Kailasanathar Temple, Kanchipuram","url":"https://en.wikipedia.org/wiki/Kailasanathar_Temple,_Kanchipuram","type":"Encyclopedia"}],"sources":[{"label":"Kailasanathar Temple, Kanchipuram","url":"https://en.wikipedia.org/wiki/Kailasanathar_Temple,_Kanchipuram"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-kanchipuram-kamakshi-amman-temple', 'shiva', 'Kamakshi Amman Temple', 'Tamil Nadu', 'Kanchipuram', 'Temple Town', 'Kamakshi (Parvati)', 'Shakta', '["Shakti Peetha","Adi Shankara","Goddess"]', 'The main Shakti shrine in Kanchipuram. Unlike other cities, there are no other Parvati shrines in the Shiva temples here, as Kamakshi is the supreme goddess of Kanchi.', 'The Sri Chakra established by Adi Shankara in front of the deity.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kanchipuram_Kamakshi_Amman_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kanchipuram_Kamakshi_Amman_Temple.jpg', 'February-March (Brahmmotsavam).', '5:30 AM - 12:30 PM, 4:00 PM - 8:30 PM.', 'Traditional.', 'Golden gopuram over the sanctum is a key feature.', '["Sahasranama Archana"]', '["Navratri","Brahmmotsavam"]', '{"history":"Associated with Adi Shankara, who is said to have pacified the goddess.","architecture":"Dravidian style with a large temple tank."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
