INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-kuranganilmuttam-valeeswarar-temple-kuranganilmuttam', 'shiva', 'Valeeswarar Temple (Kuranganilmuttam)', 'Tamil Nadu', 'Kuranganilmuttam', 'Kuranganilmuttam, Kanchipuram district', 'Shiva (Valeeswarar)', 'Shaiva', '["Shaiva","Heritage","Kuranganilmuttam"]', 'Valeeswarar Temple is an old Shiva shrine at Kuranganilmuttam, known for its stone architecture and village-temple continuity.', 'Historic stone temple complex with active local worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Valeeswarar%20temple,%20Kuranganilmuttam%20(13).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Valeeswarar_temple,_Kuranganilmuttam_(13).jpg', 'Morning darshan and winter months.', 'Open daily; local timings vary.', 'Traditional and modest attire recommended.', 'Can be paired with nearby Kanchipuram-region Shiva temples.', '["Daily puja"]', '["Mahashivratri","Pradosham"]', '{"history":"The temple is preserved in local worship and documented in photographic commons archives.","sources":[{"label":"Commons file: Valeeswarar Temple","url":"https://commons.wikimedia.org/wiki/File:Valeeswarar_temple,_Kuranganilmuttam_(13).jpg"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Valeeswarar%20Temple%20Kuranganilmuttam"}]}', '2026-02-23T13:13:38+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-madurai-aadhi-sokkanathar-temple', 'shiva', 'Aadhi Sokkanathar Temple', 'Tamil Nadu', 'Madurai', 'Simmakkal, Madurai district', 'Shiva (Aadhi Sokkanathar)', 'Shaiva', '["Madurai","Simmakkal","Sokkanathar"]', 'The Aadhi Sokkanathar Temple at Simmakkal is one of the Shiva shrines forming the sacred Madurai Shiva kshetra. Sokkanathar is a form of Shiva widely venerated across the Madurai region.', 'An ancient Shiva shrine at Simmakkal, a key junction area in Madurai\'s sacred urban landscape.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'October to March.', 'Open daily; timings vary.', 'Modest attire recommended.', 'Footwear is not allowed inside the temple.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Panguni Uthiram"]', '{"history":"Part of the ancient Shiva temple network in Madurai, centred on the Meenakshi Sundareswarar complex.","architecture":"Traditional Dravidian temple style.","visitorNotes":"Located at Simmakkal, easily accessible within Madurai city.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Aadhi+Sokkanathar+Temple+Simmakkal+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-madurai-immayilum-nanmai-tharuvar-temple', 'shiva', 'Immayilum Nanmai Tharuvar Temple', 'Tamil Nadu', 'Madurai', 'Madurai city, Madurai district', 'Shiva (Immayilum Nanmai Tharuvar)', 'Shaiva', '["Madurai","West-facing Shiva","Unique","Rare iconography"]', 'A structurally unique temple in Madurai where Shiva is depicted facing west — a rare and sacred orientation associated with liberation. This makes it a distinctive node in the Madurai Shiva pilgrimage circuit.', 'The rare west-facing Shiva shrine, an unusual and auspicious iconographic arrangement found nowhere else in the Madurai sacred landscape.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'October to March.', 'Open daily; timings vary.', 'Modest attire recommended.', 'Footwear is not allowed inside the temple.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Pradosham"]', '{"history":"A notable temple in the Madurai Shiva kshetra known for its unique west-facing icon of Shiva, considered highly auspicious in the Shaiva tradition.","architecture":"Traditional Dravidian style with a compact sanctum.","visitorNotes":"A lesser-known but spiritually significant site for devotees completing the Madurai Shiva temple circuit.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Immayilum+Nanmai+Tharuvar+Temple+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-madurai-kasi-viswanathar-temple-madurai-city', 'shiva', 'Kasi Viswanathar Temple (Madurai City)', 'Tamil Nadu', 'Madurai', 'Madurai city, Madurai district', 'Shiva (Kasi Viswanathar)', 'Shaiva', '["Madurai","Kasi Viswanathar","Shiva"]', 'The Kasi Viswanathar Temple in Madurai city is a Shiva shrine bearing the sacred name of the presiding deity of Kashi (Varanasi). It forms part of the Madurai Shiva temple network and is a revered place of worship for city residents.', 'A city-centre Shiva shrine linking Madurai\'s sacred geography to the holy city of Kashi through the name and form of Kasi Viswanathar.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kasi%20Viswanathar%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kasi_Viswanathar_Temple.jpg', 'October to March.', 'Open daily; timings vary.', 'Modest attire recommended.', 'Footwear is not allowed inside the temple.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Pradosham"]', '{"history":"A Shiva temple in Madurai city dedicated to Kasi Viswanathar, part of the extended Madurai Shiva pilgrimage circuit.","architecture":"Traditional Dravidian temple architecture.","visitorNotes":"Located within Madurai city, convenient for pilgrims visiting the Meenakshi Sundareswarar complex.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Kasi+Viswanathar+Temple+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-madurai-masi-veedhi-sokkanathar-temple', 'shiva', 'Masi Veedhi Sokkanathar Temple', 'Tamil Nadu', 'Madurai', 'Masi Street, Madurai district', 'Shiva (Sokkanathar)', 'Shaiva', '["Madurai","Masi Street","Sokkanathar"]', 'Located on the sacred Masi Veedhi (Masi Street) — one of the major circumambulatory streets encircling the Meenakshi Sundareswarar Temple — this Sokkanathar shrine is an integral part of Madurai\'s concentric sacred geography.', 'A Shiva shrine on the sacred Masi Veedhi, the outermost circumambulatory road of the Madurai temple complex.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'October to March.', 'Open daily; timings vary.', 'Modest attire recommended.', 'Located on Masi Street, one of the concentric circumambulatory roads around the Meenakshi Sundareswarar Temple.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Panguni Uthiram"]', '{"history":"Masi Veedhi is the outermost sacred circumambulatory street of Madurai. The Sokkanathar shrine here forms part of the mandala of Shiva temples defining the sacred boundaries of the city.","architecture":"Traditional Dravidian shrine architecture.","visitorNotes":"Pilgrims performing pradakshina of the Meenakshi Sundareswarar Temple pass this shrine on the Masi Veedhi route.","sources":[{"label":"Meenakshi Amman Temple","url":"https://en.wikipedia.org/wiki/Meenakshi_Amman_Temple","type":"Encyclopedia"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Masi+Veedhi+Sokkanathar+Temple+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-madurai-meenakshi-amman-temple', 'shiva', 'Meenakshi Amman Temple', 'Tamil Nadu', 'Madurai', 'Vaigai River Bank', 'Meenakshi & Sundareswarar', 'Shaiva/Shakta', '["Dravidian","Gopuram","Shakti Peetha"]', 'The heart of Madurai, dedicated to Meenakshi (Parvati) and Sundareswarar (Shiva). Legend says the wedding of the deities took place here, attended by Lord Vishnu.', 'The 14 massive gopurams covered in thousands of colorful stone figures.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Madurai_Meenakshi_Amman_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Madurai_Meenakshi_Amman_Temple.jpg', 'April (Chithirai Festival).', '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM.', 'Strict traditional attire (Dhoti/Saree).', 'Mobile phones and cameras are strictly prohibited inside.', '["Palliyarai Puja (Night Ceremony)","Thanga Ratham (Gold Chariot)"]', '["Meenakshi Tirukalyanam"]', '{"history":"Rebuilt in its current form by the Nayak rulers in the 16th-17th century.","architecture":"Features the Hall of Thousand Pillars (Aayiram Kaal Mandapam).","darshan":"Meenakshi is worshipped first as per tradition.","sources":[{"label":"Madurai Meenakshi","url":"https://maduraimeenakshi.hrce.tn.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-madurai-muktheeswarar-temple', 'shiva', 'Muktheeswarar Temple', 'Tamil Nadu', 'Madurai', 'Vandiyur Teppakulam, Madurai district', 'Shiva (Muktheeswarar)', 'Shaiva', '["Madurai","Vandiyur","Teppakulam","Muktheeswarar"]', 'Located near the famous Vandiyur Mariamman Teppakulam tank, the Muktheeswarar Temple is a Shiva shrine that forms part of the sacred Madurai pilgrimage circuit. The tank is one of the largest in Tamil Nadu and is associated with the grand float festival.', 'A Shiva shrine near the spectacular Vandiyur Teppakulam, one of Tamil Nadu\'s largest temple tanks.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Madurai%20muktisvarar7.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Madurai_muktisvarar7.jpg', 'October to March; Thai Pongal float festival season.', 'Open daily; timings vary.', 'Modest attire recommended.', 'The Vandiyur Teppakulam area is a major landmark; the temple is located nearby.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Teppam (Float Festival)"]', '{"history":"A Shiva temple in the Vandiyur area, closely associated with the Vandiyur Teppakulam built by the Nayak rulers in the 17th century.","architecture":"Traditional Dravidian temple style.","visitorNotes":"Visit during the Thai float festival season for a spectacular experience at the nearby Teppakulam.","sources":[{"label":"Vandiyur Mariamman Teppakulam","url":"https://en.wikipedia.org/wiki/Vandiyur_Mariamman_Teppakulam","type":"Encyclopedia"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Muktheeswarar+Temple+Vandiyur+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-madurai-sri-meenakshi-sundareswarar-temple', 'shiva', 'Sri Meenakshi Sundareswarar Temple', 'Tamil Nadu', 'Madurai', 'Madurai city, Madurai district', 'Shiva (Sundareswarar)', 'Shaiva', '["Madurai","Pancha Sabhai","Sundareswarar","Meenakshi","Nataraja","Dravidian"]', 'The iconic temple of Madurai enshrines Shiva as Sundareswarar and Parvati as Meenakshi. The Velli Ambalam (Silver Hall) within the complex is one of the five Pancha Sabhai where Shiva performed his cosmic dance as Nataraja.', 'The Velli Ambalam Nataraja shrine and the grand Sundareswarar sanctum at the heart of one of India\'s most magnificent Dravidian temple complexes.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Madurai_Meenakshi_Amman_Temple_from_top.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Madurai_Meenakshi_Amman_Temple_from_top.jpg', 'October to March; Chithirai Festival in April–May.', '5:00 AM - 12:30 PM, 4:00 PM - 9:30 PM.', 'Traditional attire; men must wear dhoti inside the sanctum.', 'Non-Hindus may not be permitted into the main sanctum. Camera fees apply.', '["Kala Puja","Abhishekam","Alankaram","Thiruvanandal"]', '["Chithirai Festival","Mahashivratri","Aadi Pooram","Navarathri"]', '{"history":"One of the most ancient temples of Tamil Nadu, rebuilt in its present form primarily during the Nayak period (16th–17th centuries). The Velli Ambalam is counted among the Pancha Sabhai — five sacred halls of Shiva\'s cosmic dance.","architecture":"Exemplary Dravidian architecture with 14 gopurams, the tallest reaching 51.9 metres. The complex covers 6 hectares and houses over 33,000 sculptures.","visitorNotes":"One of the most visited pilgrimage sites in India. The Velli Ambalam Nataraja is a highlight within the complex.","festivals":"The Chithirai Festival celebrating the divine marriage of Meenakshi and Sundareswarar draws millions of devotees annually.","sources":[{"label":"Meenakshi Amman Temple","url":"https://en.wikipedia.org/wiki/Meenakshi_Amman_Temple","type":"Encyclopedia"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Meenakshi+Sundareswarar+Temple+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-madurai-thiruvaappudaiyar-temple', 'shiva', 'Thiruvaappudaiyar Temple', 'Tamil Nadu', 'Madurai', 'Sellur, Madurai district', 'Shiva (Thiruvaappudaiyar)', 'Shaiva', '["Madurai","Sellur","Paadal Petra Sthalams","Tevaram"]', 'The Thiruvaappudaiyar Temple at Sellur is a Paadal Petra Sthalams — a temple glorified in the Tevaram hymns by the Nayanmars. Shiva is worshipped here as Thiruvaappudaiyar, and the shrine holds a place of honour in Madurai\'s sacred landscape.', 'A Paadal Petra Sthalams glorified in the Tevaram, situated in the Sellur locality of Madurai.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'October to March.', 'Open daily; timings vary.', 'Modest attire recommended.', 'Footwear is not allowed inside the temple.', '["Daily puja","Abhishekam","Tevaram recitation"]', '["Mahashivratri","Skanda Sashti"]', '{"history":"A Paadal Petra Sthalams of the Madurai region sung in the Tevaram, the sacred hymns of the Tamil Shaiva Nayanmars.","architecture":"Traditional Dravidian architecture with gopuram.","visitorNotes":"Located in the Sellur area of Madurai city.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Thiruvaappudaiyar+Temple+Sellur+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-mahabalipuram-shore-temple', 'shiva', 'Shore Temple', 'Tamil Nadu', 'Mahabalipuram', 'Coromandel Coast', 'Shiva & Vishnu', 'Shaiva/Vaishnava', '["UNESCO","Pallava","Monolithic"]', 'One of the oldest stone temples in South India, built by the Pallavas to overlook the Bay of Bengal. It survived the 2004 Tsunami almost unscathed.', 'The structural beauty standing against the ocean waves.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mamallapuram,_Shore_Temple,_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mamallapuram,_Shore_Temple,_India.jpg', 'Winter (Dec-Jan) for the Dance Festival.', '6:00 AM - 6:00 PM.', 'Casual/Modest.', 'ASI ticket required; covers multiple monuments in the town.', '["No active worship (Protected monument)"]', '["Mamallapuram Dance Festival"]', '{"history":"Built by King Narasimhavarman II in the 8th century.","architecture":"Cut-stone structural temple rather than rock-cut.","sources":[{"label":"UNESCO Mamallapuram","url":"https://whc.unesco.org/en/list/249"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-mandaikadu-mondaicaud-amman-temple', 'shiva', 'Mondaicaud Amman Temple', 'Tamil Nadu', 'Mandaikadu', 'Kanyakumari Coast', 'Bhagavathi (Adi Parashakti)', 'Shakta', '["Bhagavathi","Kanyakumari","Pilgrimage"]', 'A coastal Shakta shrine near Colachel known for the Maasi Kodai festival.', 'Sea-coast pilgrimage tradition and the Maasi Kodai celebrations.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mondaikkadu%20temple.%20tamil%20nadu%20-%20panoramio.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mondaikkadu_temple._tamil_nadu_-_panoramio.jpg', 'Maasi Kodai festival season.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Close to the seashore; expect larger crowds during festivals.', '["Daily puja","Evening aarti"]', '["Maasi Kodai","Navratri"]', '{"history":"Mandaikadu Bhagavathy Amman Temple is a major Shakta shrine in Kanyakumari district dedicated to Bhagavathi.","architecture":"Dravidian temple complex near the coast.","darshan":"Darshan is available daily with special rituals during Maasi.","seasonal":"Maasi Kodai draws the largest pilgrim inflow.","visitorNotes":"Plan for coastal crowds and festival traffic.","festivals":"Maasi Kodai · Navratri","sources":[{"label":"Mondaicaud Amman Temple","url":"https://en.wikipedia.org/wiki/Mondaicaud_Amman_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-mandurai-amravaneswarar-temple-mandurai', 'shiva', 'Amravaneswarar Temple (Mandurai)', 'Tamil Nadu', 'Mandurai', 'Mandurai/Manthurai area, Tiruchirappalli district', 'Shiva (Amravaneswarar)', 'Shaiva', '["Mandurai","Shaiva","Regional Shrine"]', 'Amravaneswarar Temple is a Shiva shrine in the Mandurai belt of Trichy district, visited in regional Shaiva circuits.', 'A district-level Mahadev node with local devotional significance.', '/temples/temple-01.svg', 'Not Available', 'Not Available', 'Morning puja and festival periods.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Mandurai/Manthurai spellings may both be encountered locally.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"The shrine continues in regional temple worship listings of Trichy district.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Amravaneswarar%20Temple%20Mandurai%20Trichy"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-mangadu-kamakshi-amman-temple-mangadu', 'shiva', 'Kamakshi Amman Temple (Mangadu)', 'Tamil Nadu', 'Mangadu', 'Chennai Suburbs', 'Kamakshi (Parvati)', 'Shakta', '["Kamakshi","Chennai","Pilgrimage"]', 'A revered Kamakshi shrine in Mangadu, known for the Tapas Kamakshi tradition.', 'Tantric Ardhameru Sri Chakram and a seven-tiered gopuram.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mangadu%20kamatchiamman%20temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mangadu_kamatchiamman_temple.jpg', 'Navratri and early morning darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple draws large crowds during Navratri.', '["Daily puja","Evening aarti"]', '["Navratri","Vijaya Dashami"]', '{"history":"The Mangadu Kamakshi Amman Temple is a major pilgrimage shrine dedicated to Tapas Kamakshi.","architecture":"Chola-style architecture with a prominent seven-tiered gopuram.","darshan":"Darshan is open daily with regular aarti schedules.","seasonal":"Navratri is the busiest season for pilgrims.","visitorNotes":"Plan for crowds during festival aartis.","festivals":"Navratri · Vijaya Dashami","sources":[{"label":"Kamakshi Amman Temple, Mangadu","url":"https://en.wikipedia.org/wiki/Kamakshi_Amman_Temple%2C_Mangadu"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-mannachanallur-neelivaneswarar-temple-mannachanallur', 'shiva', 'Neelivaneswarar Temple (Mannachanallur)', 'Tamil Nadu', 'Mannachanallur', 'Mannachanallur, Tiruchirappalli district', 'Shiva (Neelivaneswarar)', 'Shaiva', '["Mannachanallur","Shaiva","Neelivaneswarar"]', 'Neelivaneswarar Temple at Mannachanallur is a local Shiva shrine in the Trichy district worship network.', 'A village-linked Shaiva temple with regular local ritual life.', '/temples/temple-05.svg', 'Not Available', 'Not Available', 'Morning darshan.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Useful to combine with nearby rural Trichy temple circuits.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Maintained in local Shaiva worship continuity in Mannachanallur.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Neelivaneswarar%20Temple%20Mannachanallur"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-maruthuvakudi-airavateswarar-temple', 'shiva', 'Airavateswarar Temple', 'Tamil Nadu', 'Maruthuvakudi', 'Thanjavur District', 'Shiva', 'Shaiva', '["Shaiva","Thanjavur district","Temple"]', 'Airavateswarar Temple is a Shiva temple in Thanjavur district with active local worship traditions.', 'Traditional Shiva worship at Maruthuvakudi.', 'Not Available', 'Not Available', 'Not Available', 'October to March and Mahashivratri period.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Airavateswarar Temple is listed among Shiva temples in Thanjavur district, Tamil Nadu.","architecture":"Dravidian temple architecture with regional variation.","visitorNotes":"Check local opening times before planning your visit.","sources":[{"label":"Airavateswarar Temple (Wikipedia)","url":"https://en.wikipedia.org/wiki/Airavateswarar_Temple%2C_Maruthuvakudi","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
