INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-palani-arulmigu-dhandayuthapani-swamy-temple', 'shiva', 'Arulmigu Dhandayuthapani Swamy Temple', 'Tamil Nadu', 'Palani', 'Dindigul District', 'Murugan', 'Kaumaram/Shaiva', '["Arupadaiveedu","Murugan","Hilltop"]', 'The third of Murugan\'s six abodes. Legend says he came here as a renunciant after a dispute over a divine fruit.', 'The main idol made of \'Navapashanam\' (nine poisonous substances) by Siddha Bogar.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arulmigu_Dhandayuthapani_Swamy_Temple_in_Palany_hill.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Arulmigu_Dhandayuthapani_Swamy_Temple_in_Palany_hill.jpg', 'Thai Poosam (Jan-Feb).', '6:00 AM - 8:00 PM.', 'Traditional attire mandatory.', 'Accessible by winch, ropeway, or climbing 600+ steps.', '["Panchamirtham Abhishekam","Kavadi offerings"]', '["Thai Poosam","Panguni Uthiram"]', '{"history":"One of the most visited pilgrimage sites in India.","architecture":"Ancient hilltop shrine with modern amenities like ropeway."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
