INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-parvathamalai-parvathamalai-mallikarjunaswamy-temple-a-high-altitude-extreme-trek-hilltop-node', 'shiva', 'Parvathamalai Mallikarjunaswamy Temple (A high-altitude, extreme-trek hilltop node)', 'Tamil Nadu', 'Parvathamalai', 'Parvathamalai hill range, Tiruvannamalai district', 'Shiva (Mallikarjunaswamy)', 'Shaiva', '["Hill Temple","Trek","Mallikarjunaswamy"]', 'A high-elevation Shiva shrine reached by steep trekking routes, revered for intense sadhana-oriented pilgrimage.', 'Demanding hill ascent culminating in a remote Mallikarjunaswamy darshan point.', '/temples/temple-01.svg', 'Not Available', 'Not Available', 'Cool season months and early-start trekking days.', 'Open daily; trek timing depends on weather and safety.', 'Traditional and modest attire with trek-appropriate footwear.', 'Carry water, follow local guidance, and avoid unsafe weather windows.', '["Hilltop darshan","Festival-day puja"]', '["Mahashivratri","Full-moon hill pilgrimages"]', '{"history":"Parvathamalai has long been treated as a tapas-oriented Shaiva hill route by local devotees.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Parvathamalai%20Mallikarjunaswamy%20Temple"}]}', '2026-02-23T13:13:38+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
