INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-punnainallur-punnainallur-mariamman-temple', 'shiva', 'Punnainallur Mariamman Temple', 'Tamil Nadu', 'Punnainallur', 'Thanjavur', 'Mariamman', 'Shakta', '["Mariamman","Thanjavur","Heritage"]', 'A revered Mariamman temple near Thanjavur with strong local devotion.', 'Rajagopuram views and steady pilgrim flow.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Punnainallur_Mariamman_Entrance.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Punnainallur_Mariamman_Entrance.jpg', 'Morning visits for calmer darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja","Evening aarti"]', '["Navratri","Aadi festival"]', '{"history":"Punnainallur Mariamman Temple is a Hindu temple near Thanjavur dedicated to Goddess Mariamman.","sources":[{"label":"Punnainallur Mariamman Temple","url":"https://en.wikipedia.org/wiki/Punnainallur_Mariamman_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-rameswaram-ramanathaswamy-temple', 'shiva', 'Ramanathaswamy Temple', 'Tamil Nadu', 'Rameswaram', 'Pamban Island', 'Shiva', 'Shaiva', '["Jyotirlinga","Char Dham","Corridors"]', 'Lord Rama is believed to have built the Linga here to pray for penance after the war in Lanka.', 'The longest temple corridor in the world with over 1200 pillars.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rameswaram_Temple_Corridor.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rameswaram_Temple_Corridor.jpg', 'All year; early morning for holy bath.', '5:00 AM - 1:00 PM, 3:00 PM - 9:00 PM.', 'Strict traditional dress code.', 'Devotees usually bathe in 22 holy wells (Theerthams) before darshan.', '["Mani Darshanam (Early morning)","Theertha Snanam"]', '["Maha Shivratri","Thirukalyanam"]', '{"history":"Expanded significantly by the Jaffna kings and later Sethupathi Rajas.","architecture":"Massive outer walls and magnificent sculpted pillars.","sources":[{"label":"Rameswaram Temple","url":"https://rameswaram.hrce.tn.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-rameswaram-spatika-lingam-sannidhi-a-highly-specific-crystalline-node-inside-the-main-corridor', 'shiva', 'Spatika Lingam Sannidhi (A highly specific crystalline node inside the main corridor)', 'Tamil Nadu', 'Rameswaram', 'Inside Ramanathaswamy Temple corridor zone, Rameswaram', 'Shiva', 'Shaiva', '["Rameswaram","Spatika Lingam","Sannidhi"]', 'Spatika Lingam Sannidhi is a specific crystalline-lingam worship node in the Ramanathaswamy temple ritual environment.', 'Focused sannidhi worship tied to early-morning abhishekam traditions.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Early morning puja window.', 'Follows Ramanathaswamy temple darshan schedule.', 'Traditional/modest attire recommended.', 'This is an internal sannidhi; access sequence follows the main temple protocol.', '["Spatika linga abhishekam","Archana"]', '["Mahashivratri"]', '{"history":"Spatika-lingam worship is preserved within select Shaiva ritual contexts at major temple complexes.","architecture":"Internal sannidhi setting integrated into corridor-led movement patterns.","visitorNotes":"Confirm current abhishekam ticketing/queue details locally.","sources":[{"label":"Rameswaram HRCE Temple","url":"https://rameswaram.hrce.tn.gov.in/","type":"Temple administration"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Ramanathaswamy%20Temple%20Rameswaram","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T22:30:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-rameswaram-sri-viswanathar-sannidhi-the-kashi-lingam-node-structurally-distinct-within-the-complex', 'shiva', 'Sri Viswanathar Sannidhi (The Kashi Lingam node, structurally distinct within the complex)', 'Tamil Nadu', 'Rameswaram', 'Inside Ramanathaswamy Temple complex, Rameswaram', 'Shiva', 'Shaiva', '["Rameswaram","Sannidhi","Kashi Lingam"]', 'Sri Viswanathar Sannidhi is a Shiva sub-shrine node within the wider Ramanathaswamy temple complex.', 'A focused sannidhi darshan tradition linked with the larger Rameswaram pilgrimage circuit.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Early morning and non-peak darshan hours.', 'Follows Ramanathaswamy temple darshan schedule.', 'Traditional/modest attire recommended.', 'This is an internal sannidhi; queue flow follows the main complex protocol.', '["Daily puja","Archana"]', '["Mahashivratri"]', '{"history":"Viswanathar worship is traditionally integrated into the Rameswaram ritual sequence.","architecture":"Sub-shrine architecture integrated with the larger corridor-based complex.","visitorNotes":"Confirm internal sannidhi access sequence at the temple counter.","sources":[{"label":"Rameswaram HRCE Temple","url":"https://rameswaram.hrce.tn.gov.in/","type":"Temple administration"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Ramanathaswamy%20Temple%20Rameswaram","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T22:30:00+05:30');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-salem-kottai-mariamman-temple', 'shiva', 'Kottai Mariamman Temple', 'Tamil Nadu', 'Salem', 'Fort Area', 'Mariamman', 'Shakta', '["Mariamman","Salem","Festival"]', 'A celebrated Mariamman shrine in Salem, known for its summer festival and fire-walk.', 'Kottai Mariamman festival with fire-walk rituals.', 'https://commons.wikimedia.org/wiki/Special:FilePath/KOTTAI%20MARIAMMAN%20TEMPLE,%20SALEM%20-%20panoramio%20(12).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:KOTTAI_MARIAMMAN_TEMPLE,_SALEM_-_panoramio_(12).jpg', 'July–August festival season.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect large crowds during the annual festival.', '["Daily puja","Festival fire-walk"]', '["Kottai Mariamman festival"]', '{"history":"Kottai Mariamman Temple in Salem is a major Mariamman shrine with a well-known July–August festival.","architecture":"Urban temple complex within Salem city.","darshan":"Darshan is open daily; festival rituals draw large crowds.","seasonal":"The July–August festival season is the busiest.","visitorNotes":"Plan early for the festival week and fire-walk rituals.","festivals":"Kottai Mariamman festival","sources":[{"label":"Mariamman Temple (Salem district tourism)","url":"https://salem.nic.in/tourism/temples/mariamman-temple/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-samayapuram-mariamman-temple-samayapuram', 'shiva', 'Mariamman Temple (Samayapuram)', 'Tamil Nadu', 'Samayapuram', 'Tiruchirappalli', 'Samayapuram Mariamman', 'Shakta', '["Mariamman","Pilgrimage","Trichy"]', 'An ancient Mariamman shrine in Tiruchirappalli district with strong rural devotion.', 'Chithirai festival processions and temple rituals.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Samayapuram_Mariamman_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Samayapuram_Mariamman_Temple.jpg', 'Festival days and early mornings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect crowds on festival days.', '["Daily puja","Evening aarti"]', '["Chithirai festival","Navratri"]', '{"history":"Arulmigu Sri Mariamman Temple at Samayapuram is an ancient Mariamman shrine in Tiruchirappalli district.","sources":[{"label":"Mariamman Temple, Samayapuram","url":"https://en.wikipedia.org/wiki/Mariamman_Temple,_Samayapuram"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-sankarankoil-gomathi-amman-temple-sankarankoil', 'shiva', 'Gomathi Amman Temple (Sankarankoil)', 'Tamil Nadu', 'Sankarankoil', 'Tenkasi District', 'Gomathi Amman', 'Shakta', '["Gomathi Amman","Sankarankoil","Adi Tapasu"]', 'A Gomathi Amman shrine within the Sankaranarayanasamy Temple complex in Sankarankoil.', 'Adi Tapasu festival linked to Gomathi Amman’s penance.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sankara%20nainar%20temple%20gopuram.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sankara_nainar_temple_gopuram.JPG', 'Adi Tapasu festival season.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple complex can be busy during Adi Tapasu.', '["Daily puja","Evening aarti"]', '["Adi Tapasu","Navratri"]', '{"history":"Gomathi Amman is the consort deity in the Sankarankoil temple complex and is revered as a manifestation of Adi Shakti.","architecture":"Dravidian temple architecture within the Sankarankoil complex.","darshan":"Darshan is available daily with festival rituals in Adi.","seasonal":"Adi Tapasu is the busiest festival period.","visitorNotes":"Expect queues during Adi Tapasu days.","festivals":"Adi Tapasu · Navratri","sources":[{"label":"Gomathi Amman","url":"https://en.wikipedia.org/wiki/Gomathi_Amman"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
