INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-sivapuri-thirunelvayil-uchinatheshwarar-temple-sivapuri', 'shiva', 'Thirunelvayil Uchinatheshwarar Temple (Sivapuri)', 'Tamil Nadu', 'Sivapuri', 'Thirunelvayil (Sivapuri), Cuddalore district', 'Shiva (Uchinatheshwarar)', 'Shaiva', '["Shaiva","Sivapuri","Historic Shrine"]', 'An established Shiva shrine at Sivapuri (Thirunelvayil), connected to regional temple traditions around Chidambaram.', 'Important Sivapuri Shaiva temple in the Chidambaram cluster.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thirunelvayil%20(14).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Thirunelvayil_(14).jpg', 'Morning puja and festival days.', 'Open daily; local timings vary.', 'Traditional and modest attire recommended.', 'Located in the Sivapuri/Thirunelvayil temple area.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"Thirunelvayil is a known Shaiva locality in the Chidambaram region.","sources":[{"label":"Commons file: Thirunelvayil","url":"https://commons.wikimedia.org/wiki/File:Thirunelvayil_(14).jpg"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Thirunelvayil%20Uchinatheshwarar%20Temple%20Sivapuri"}]}', '2026-02-23T13:19:31+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-srirangam-sri-ranganathaswamy-temple', 'shiva', 'Sri Ranganathaswamy Temple', 'Tamil Nadu', 'Srirangam', 'Cauvery River Island', 'Vishnu (Ranganatha)', 'Vaishnava', '["Divya Desam","Largest","Vishnu"]', 'The foremost of the 108 Divya Desams, this temple city is the largest functioning Hindu temple complex in the world.', 'The Rajagopuram, one of the tallest in Asia (237 feet).', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_view_of_Sri_Rangam_temple_near_Tiruchirapalli_1.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Aerial_view_of_Sri_Rangam_temple_near_Tiruchirapalli_1.jpg', 'December (Vaikuntha Ekadashi).', '6:00 AM - 9:00 PM (with breaks).', 'Traditional attire mandatory for inner sanctum.', 'The temple complex covers 156 acres with 7 enclosures.', '["Viswaroopa Seva","Pagal Pathu"]', '["Vaikuntha Ekadashi"]', '{"history":"Associated with the philosopher Ramanuja, who is preserved in a shrine here.","architecture":"Saptaprakaram (7 concentric walls).","sources":[{"label":"Srirangam Temple","url":"https://srirangam.org/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
