INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thanjavur-brihadeeswarar-temple', 'shiva', 'Brihadeeswarar Temple', 'Tamil Nadu', 'Thanjavur', 'Chola Heartland', 'Shiva', 'Shaiva', '["UNESCO","Chola","Nandi"]', 'A monumental Chola masterpiece where stone and devotion meet grand scale.', 'The massive Nandi and sunset glow on the vimana.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brihadeeswarar%20Temple%20thanjavur.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Brihadeeswarar_Temple_thanjavur.jpg', 'Sunset for dramatic shadows on the vimana.', 'Open daily; timings vary by season.', 'Comfortable, modest attire.', 'Large heritage complex; allow extra time.', '["Daily puja","Evening aarti"]', '["Mahashivratri","Annual temple festivals"]', '{"history":"Built under the Chola ruler Rajaraja I around 1003-1010 CE, the Brihadishvara Temple stands as a monumental Chola-era shrine in Thanjavur.","puranicView":"As a Shiva temple known as Peruvudaiyar Kovil, Brihadeeswarar worship aligns with Shaiva Puranic devotion to Shiva as the great lord. The shrine\'s central linga and Nandi mandapa emphasize this Shaiva focus.","puranicSources":[{"label":"Brihadeeswarar Temple (Thanjavur Tourism)","url":"https://thanjavurtourism.com/big-temple-thanjavur.html","type":"Government tourism (Shiva temple)"}],"sources":[{"label":"Brihadishvara Temple (Britannica)","url":"https://www.britannica.com/place/Brihadishvara-temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thanjavur-brihadisvara-temple', 'shiva', 'Brihadisvara Temple', 'Tamil Nadu', 'Thanjavur', 'Cauvery Delta', 'Shiva (Peruvudaiyar)', 'Shaiva', '["UNESCO","Chola","Big Temple"]', 'Known as \'Thanjai Periya Kovil,\' this architectural marvel was built by Raja Raja Chola I. The shadow of the main tower (Vimana) is said to never fall on the ground at noon.', 'The 80-ton monolithic stone cap (Kumbam) atop the 216-foot Vimana.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brihadisvara_Temple,_Thanjavur,_Tamil_Nadu,_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Brihadisvara_Temple,_Thanjavur,_Tamil_Nadu,_India.jpg', 'Winter (Nov-Feb).', '6:00 AM - 12:30 PM, 4:00 PM - 8:30 PM.', 'Modest attire.', 'UNESCO World Heritage site; very well maintained.', '["Daily Abhishekam to the massive Nandi"]', '["Maha Shivratri","Raja Raja Chola\'s Birthday"]', '{"history":"Completed in 1010 AD, it is one of the largest temples in India.","architecture":"Pure Dravidian style with all-granite construction.","darshan":"The massive 12-foot high Linga is a sight to behold.","sources":[{"label":"ASI Thanjavur","url":"https://asi.nic.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
