INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thirunedungulam-nedungalanathar-temple-thirunedungulam', 'shiva', 'Nedungalanathar Temple (Thirunedungulam)', 'Tamil Nadu', 'Thirunedungulam', 'Thirunedungulam, Tiruchirappalli district', 'Shiva (Nedungalanathar)', 'Shaiva', '["Thirunedungulam","Shaiva","Padal Petra"]', 'Nedungalanathar Temple is a well-known Shiva shrine in Thirunedungulam, associated with classical Shaiva traditions.', 'A historic regional Mahadev temple in the Trichy sacred geography.', '/temples/temple-06.svg', 'Not Available', 'Not Available', 'Morning and evening puja windows.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Temple name and village spelling may appear as Nedunkalam/Thirunedungulam variants.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"The shrine is included in traditional Shaiva temple lists of the Tiruchirappalli region.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Nedungalanathar%20Temple%20Thirunedungulam"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thirupanjeeli-gneelivaneswarar-temple-thirupanjeeli', 'shiva', 'Gneelivaneswarar Temple (Thirupanjeeli)', 'Tamil Nadu', 'Thirupanjeeli', 'Thirupanjeeli, Tiruchirappalli district', 'Shiva (Gneelivaneswarar)', 'Shaiva', '["Thirupanjeeli","Shaiva","Historic Shrine"]', 'Gneelivaneswarar Temple at Thirupanjeeli is an established Shiva shrine in the Trichy region\'s traditional temple network.', 'A heritage Shaiva temple in Thirupanjeeli with deep local devotional continuity.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thirupanjeeli%20(6).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Thirupanjeeli_(6).jpg', 'Morning darshan and cooler season months.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Local usage may also transliterate the name as Neelivaneswarar/Gnana-linked variants.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"Thirupanjeeli\'s Shiva temple remains a recognized regional pilgrimage node.","sources":[{"label":"Commons file: Thirupanjeeli","url":"https://commons.wikimedia.org/wiki/File:Thirupanjeeli_(6).jpg"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Gneelivaneswarar%20Temple%20Thirupanjeeli"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
