INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thiruvadavur-thirumarainathar-temple', 'shiva', 'Thirumarainathar Temple', 'Tamil Nadu', 'Thiruvadavur', 'Thiruvadavur, Madurai district', 'Shiva (Thirumarainathar)', 'Shaiva', '["Madurai","Thiruvadavur","Manikkavacakar","Paadal Petra Sthalams"]', 'Thiruvadavur is the birthplace of the great saint-poet Manikkavacakar, author of the Thiruvasagam. The Thirumarainathar Temple here is a Paadal Petra Sthalams and holds deep significance for Shaiva devotees as the home shrine of one of the greatest Tamil Shiva bhaktas.', 'Birthplace of saint Manikkavacakar, composer of the Thiruvasagam — one of the most sublime works of Tamil devotional literature.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiruvathavur_tirumarainathar_temple6.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tiruvathavur_tirumarainathar_temple6.jpg', 'October to March.', 'Open daily; timings vary.', 'Modest attire recommended.', 'Located at Thiruvadavur, near Madurai.', '["Daily puja","Abhishekam","Thiruvasagam recitation"]', '["Mahashivratri","Manikkavacakar Jayanti"]', '{"history":"Thiruvadavur is renowned as the birthplace of Manikkavacakar (9th century), the Pandya minister-turned-saint who composed the Thiruvasagam. The temple is a Paadal Petra Sthalams.","architecture":"Traditional Dravidian temple architecture.","visitorNotes":"A significant pilgrimage stop for devotees of Manikkavacakar on the Madurai Shiva circuit.","sources":[{"label":"Manikkavacakar","url":"https://en.wikipedia.org/wiki/Manikkavacakar","type":"Encyclopedia"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Thirumarainathar+Temple+Thiruvadavur+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
