INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thiruvarur-thyagaraja-temple', 'shiva', 'Thyagaraja Temple', 'Tamil Nadu', 'Thiruvarur', 'Cauvery Delta', 'Shiva (Thyagaraja)', 'Shaiva', '["Sapta Vidangam","Massive Tank","Chariot"]', 'One of the largest and most ancient Shiva temples. The \'Kamalalayam\' tank here is one of the biggest in India, and the temple chariot is legendary for its size.', 'The Ajapa Thanam dance of Lord Thyagaraja and the massive temple complex.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Birds_view_of_Thyagaraja_Temple_Tiruvarur_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Birds_view_of_Thyagaraja_Temple_Tiruvarur_India.jpg', 'April (Azhu Thair Chariot Festival).', '5:00 AM - 12:00 PM, 4:00 PM - 9:00 PM.', 'Traditional.', 'Known as the capital of the Sapta Vidangam (seven temples where Shiva performs different dances).', '["Ajapa Thanam","Daily Abhishekam"]', '["Chariot Festival"]', '{"history":"Ancient site mentioned in Tevaram hymns; expanded by Cholas and Pandyas.","architecture":"Features several shrines and massive pillared halls."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thiruvasi-mattruraivaradeswarar-temple-thiruvasi', 'shiva', 'Mattruraivaradeswarar Temple (Thiruvasi)', 'Tamil Nadu', 'Thiruvasi', 'Thiruvasi, Tiruchirappalli district', 'Shiva (Mattruraivaradeswarar)', 'Shaiva', '["Thiruvasi","Shaiva","Historic Shrine"]', 'Mattruraivaradeswarar Temple is a Shiva shrine at Thiruvasi, associated with traditional Trichy-region Shaiva worship.', 'A revered Thiruvasi Mahadev node in the district circuit.', '/temples/temple-04.svg', 'Not Available', 'Not Available', 'Morning darshan and festival days.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Name may appear in variant transliterations in local boards.', '["Daily puja"]', '["Mahashivratri","Pradosham"]', '{"history":"The shrine is part of longstanding temple worship in the Thiruvasi area.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Mattruraivaradeswarar%20Temple%20Thiruvasi"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thiruvavaduthurai-gomatheswarar-temple', 'shiva', 'Gomatheswarar Temple', 'Tamil Nadu', 'Thiruvavaduthurai', 'Mayiladuthurai District', 'Shiva', 'Shaiva', '["Bull","Tirumular","Saivism"]', 'Where Goddess Parvati worshipped Shiva in the form of a cow (Go). It is the headquarters of one of the oldest Saivite monasteries.', 'The massive Nandi statue and its association with saint Tirumular.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thirukailaya_Parambarai_Thiruvavaduthurai_Adheenam_Guruparambarai.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Thirukailaya_Parambarai_Thiruvavaduthurai_Adheenam_Guruparambarai.jpg', 'Winter.', '6:00 AM - 12:00 PM, 4:00 PM - 8:30 PM.', 'Traditional.', 'A very peaceful and scholarly atmosphere.', '["Daily puja by the Adheenam priests"]', '["Maha Shivratri"]', '{"history":"Associated with the Thiruvavaduthurai Adheenam (monastery).","architecture":"Grand Chola structure."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thiruvedagam-edaganathar-temple', 'shiva', 'Edaganathar Temple', 'Tamil Nadu', 'Thiruvedagam', 'Thiruvedagam, Madurai district', 'Shiva (Edaganathar)', 'Shaiva', '["Madurai","Paadal Petra Sthalams","Tevaram","Thiruvedagam"]', 'The Edaganathar Temple at Thiruvedagam is a Paadal Petra Sthalams glorified in the Tevaram hymns. Located on the outskirts of Madurai, it is one of the significant ancient Shiva temples of the region.', 'An ancient Paadal Petra Sthalams on the Madurai Shiva circuit, sung in the Tevaram by the saint poets.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiruvedagam2.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tiruvedagam2.JPG', 'October to March.', 'Open daily; timings vary.', 'Modest attire recommended.', 'Located at Thiruvedagam, a short distance from central Madurai.', '["Daily puja","Abhishekam","Tevaram recitation"]', '["Mahashivratri","Panguni Uthiram"]', '{"history":"A Paadal Petra Sthalams of the Madurai region, glorified in the Tevaram hymns of the Nayanmars.","architecture":"Traditional Dravidian architecture.","visitorNotes":"Thiruvedagam is a village near Madurai accessible by road.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Edaganathar+Temple+Thiruvedagam+Madurai+Tamil+Nadu","type":"Map search"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-02-23T17:00:00+05:30');
