INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-thiruverumbur-erumbeeswarar-temple-thiruverumbur', 'shiva', 'Erumbeeswarar Temple (Thiruverumbur)', 'Tamil Nadu', 'Thiruverumbur', 'Thiruverumbur, Tiruchirappalli district', 'Shiva (Erumbeeswarar)', 'Shaiva', '["Padal Petra","Hill Shrine","Shaiva"]', 'Erumbeeswarar Temple is a historic Shiva shrine at Thiruverumbur, traditionally linked with ant-worship legends and hilltop devotion.', 'Ancient hill temple with a strong Tevaram-linked Shaiva legacy.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arulmigu%20Erumbeeswarar%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Arulmigu_Erumbeeswarar_Temple.jpg', 'Morning darshan and cooler season months.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Access includes climbing steps to the hill temple.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"The temple is one of the notable historic Shaiva shrines in Tiruchirappalli district.","sources":[{"label":"Commons file: Erumbeeswarar Temple","url":"https://commons.wikimedia.org/wiki/File:Arulmigu_Erumbeeswarar_Temple.jpg"},{"label":"Erumbeeswarar Temple","url":"https://en.wikipedia.org/wiki/Erumbeeswarar_Temple"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
