INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruchirappalli-panchavarnaswamy-temple-woraiyur', 'shiva', 'Panchavarnaswamy Temple (Woraiyur)', 'Tamil Nadu', 'Tiruchirappalli', 'Woraiyur, Tiruchirappalli district', 'Shiva (Panchavarnaswamy)', 'Shaiva', '["Woraiyur","Shaiva","Historic Shrine"]', 'Panchavarnaswamy Temple in Woraiyur is a traditional Shiva temple in the older sacred quarter of Trichy.', 'A classic Woraiyur Shaiva node in the urban Trichy temple grid.', '/temples/temple-01.svg', 'Not Available', 'Not Available', 'Morning and evening puja windows.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Can be combined with other Woraiyur temple visits.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"Part of Woraiyur\'s historical temple fabric in Tiruchirappalli.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Panchavarnaswamy%20Temple%20Woraiyur"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruchirappalli-thanthondreeswarar-temple-woraiyur', 'shiva', 'Thanthondreeswarar Temple (Woraiyur)', 'Tamil Nadu', 'Tiruchirappalli', 'Woraiyur, Tiruchirappalli district', 'Shiva (Thanthondreeswarar)', 'Shaiva', '["Woraiyur","Shaiva","Local Shrine"]', 'Thanthondreeswarar Temple is a local Shiva shrine in Woraiyur associated with Trichy\'s longstanding Shaiva worship routes.', 'A compact Woraiyur Mahadev node with active daily worship.', '/temples/temple-02.svg', 'Not Available', 'Not Available', 'Morning darshan and Pradosham days.', 'Open daily; timings vary locally.', 'Traditional and modest attire recommended.', 'Local spelling may vary as Thandondreeswarar/Thanthondreeswarar.', '["Daily puja"]', '["Mahashivratri","Pradosham"]', '{"history":"Maintained through local Woraiyur Shaiva devotional continuity.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Thanthondreeswarar%20Temple%20Woraiyur"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruchirappalli-thayumanaswami-temple-rockfort-hill', 'shiva', 'Thayumanaswami Temple (Rockfort Hill)', 'Tamil Nadu', 'Tiruchirappalli', 'Rockfort Hill, Tiruchirappalli district', 'Shiva (Thayumanaswami)', 'Shaiva', '["Rockfort","Shaiva","Hill Temple"]', 'Thayumanaswami Temple is a major Shiva shrine on Rockfort Hill in Trichy, deeply tied to city pilgrimage traditions.', 'Hilltop and mid-hill darshan points with panoramic city views from the Rockfort complex.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thayumanavar%20shrine.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Thayumanavar_shrine.jpg', 'Early morning or late afternoon for comfortable hill climb.', 'Open daily; timings vary by shrine schedule.', 'Traditional and modest attire recommended.', 'Part of the Rockfort route; stair climbing is involved.', '["Daily puja","Abhishek"]', '["Mahashivratri","Pradosham"]', '{"history":"Rockfort\'s temple complex preserves a long continuity of Shaiva worship in Tiruchirappalli.","sources":[{"label":"Commons file: Thayumanavar shrine","url":"https://commons.wikimedia.org/wiki/File:Thayumanavar_shrine.jpg"},{"label":"Rockfort overview","url":"https://en.wikipedia.org/wiki/Rockfort_Ucchi_Pillayar_Temple"}]}', '2026-02-23T13:30:36+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
