INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tirunageswaram-naganathar-temple', 'shiva', 'Naganathar Temple', 'Tamil Nadu', 'Tirunageswaram', 'Kumbakonam', 'Shiva', 'Shaiva', '["Navagraha","Rahu","Blue Milk"]', 'The Rahu Sthalam. When milk is poured over the deity of Rahu here during Abhishekam, it magically turns blue.', 'The blue milk miracle during Rahu Kaalam Abhishekam.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thirunageswaram_gopuram.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Thirunageswaram_gopuram.JPG', 'Sundays (Rahu Kaalam).', '6:00 AM - 1:00 PM, 4:00 PM - 9:00 PM.', 'Traditional.', 'A key destination for people with Rahu-related astrological doshas.', '["Milk Abhishekam"]', '["Rahu Peyarchi"]', '{"history":"Significant Chola era temple.","architecture":"Massive gopurams and a spacious courtyard."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tirunelveli-nellaiappar-temple', 'shiva', 'Nellaiappar Temple', 'Tamil Nadu', 'Tirunelveli', 'Thamirabarani Bank', 'Shiva (Nellaiappar) & Gandhimathi Amman', 'Shaiva', '["Musical Pillars","Shiva","Pancha Sabhai"]', 'Representing the \'Copper Hall\' (Thamra Sabha) of Shiva\'s dance, this temple is a giant complex where Shiva and Parvati are worshipped side-by-side.', 'The \'Musical Pillars\' that produce different musical notes when tapped.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tirunelveli_Nellaiappar_Temple_1.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tirunelveli_Nellaiappar_Temple_1.jpg', 'June-July (Ani Car Festival).', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM.', 'Traditional.', 'One of the largest temple complexes in South India.', '["Musical pillar demonstrations"]', '["Ani Car Festival"]', '{"history":"Dates back to the 7th century; extensively renovated by Pandyas and Nayaks.","architecture":"Known for the Thamra Sabha hall with exquisite woodwork."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
