INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruvalangadu-vataranyeswarar-temple', 'shiva', 'Vataranyeswarar Temple', 'Tamil Nadu', 'Tiruvalangadu', 'Thiruvallur District', 'Shiva (Vataranyeswarar)', 'Shaiva', '["Pancha Sabhai","Ratna Sabha","Karaikkal Ammeiyar"]', 'The \'Ratna Sabha\' (Hall of Gems). This is where Shiva performed the Urdhva Tandava (upward dance) to defeat Kali in a dance competition.', 'The temple is associated with Karaikkal Ammeiyar, who walked on her hands to reach this shrine.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiruvalangaduvadaaraneswarartemple2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tiruvalangaduvadaaraneswarartemple2.jpg', 'Winter.', '6:00 AM - 8:00 PM.', 'Traditional.', 'One of the most powerful and quiet spiritual spots near Chennai.', '["Daily puja to Nataraja"]', '["Maha Shivratri"]', '{"history":"Mentioned in the early Tamil hymns of the 6th century.","architecture":"Chola style with a very sacred banyan tree (Vata vriksha)."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruvannamalai-adi-annamalai-temple-the-ancient-foundational-node-on-the-girivalam-path', 'shiva', 'Adi Annamalai Temple (The ancient, foundational node on the Girivalam path)', 'Tamil Nadu', 'Tiruvannamalai', 'Adi Annamalai, Girivalam route, Tiruvannamalai district', 'Shiva (Annamalaiyar)', 'Shaiva', '["Girivalam","Ancient Shrine","Annamalai"]', 'A historically important Shiva shrine on the Girivalam route, revered as one of the foundational worship points around Arunachala.', 'Key early-stop darshan point on the hill circumambulation route.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aadi%20Annamalai%20Temple%20-%20Tiruvannamalai%20(1).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Aadi_Annamalai_Temple_-_Tiruvannamalai_(1).jpg', 'Early morning and full moon Girivalam nights.', 'Open daily; local timings vary.', 'Traditional and modest attire recommended.', 'Often visited before or during Arunachala Girivalam.', '["Daily puja","Girivalam stop darshan"]', '["Karthigai Deepam","Mahashivratri"]', '{"history":"Adi Annamalai is closely connected with traditional Arunachala pilgrimage sequencing.","sources":[{"label":"Commons file: Aadi Annamalai Temple","url":"https://commons.wikimedia.org/wiki/File:Aadi_Annamalai_Temple_-_Tiruvannamalai_(1).jpg"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Adi%20Annamalai%20Temple%20Tiruvannamalai"}]}', '2026-02-23T13:13:38+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruvannamalai-agni-lingam-girivalam-circuit-node', 'shiva', 'Agni Lingam (Girivalam circuit node)', 'Tamil Nadu', 'Tiruvannamalai', 'Girivalam route, Tiruvannamalai district', 'Shiva', 'Shaiva', '["Ashta Lingam","Agni","Girivalam"]', 'Agni Lingam is a major directional lingam stop reflecting the fire principle deeply tied to Arunachala\'s identity.', 'A highly significant Ashta-lingam node in the fire-identified Arunachala kshetra.', 'https://commons.wikimedia.org/wiki/Special:FilePath/2.%20Agni%20Lingam.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2._Agni_Lingam.jpg', 'Pournami and pre-dawn Girivalam windows.', 'Open daily; local timings vary.', 'Traditional and modest attire recommended.', 'Commonly paired with main Arunachaleswarar temple visit.', '["Girivalam darshan","Deepa offering"]', '["Karthigai Deepam","Mahashivratri"]', '{"history":"Agni symbolism is foundational to Tiruvannamalai\'s Shaiva identity.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Agni%20Lingam%20Tiruvannamalai"}]}', '2026-02-23T13:13:38+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruvannamalai-annamalaiyar-temple', 'shiva', 'Annamalaiyar Temple', 'Tamil Nadu', 'Tiruvannamalai', 'Annamalai Hills', 'Shiva (Arunachaleswarar)', 'Shaiva', '["Agni Lingam","Hill","Pancha Bhoota"]', 'Representing the element \'Fire,\' Shiva is worshipped here as a massive column of light. The hill itself is considered a Linga.', 'The massive Karthigai Deepam flame lit atop the hill.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiruvannamalai_arunachaleswarar_kovil.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tiruvannamalai_arunachaleswarar_kovil.jpg', 'Full moon nights (Girivalam).', '5:00 AM - 9:00 PM (with breaks).', 'Modest.', 'The 14km circumambulation (Girivalam) around the hill is a primary ritual.', '["Girivalam","Pancha Murthi Abhishekam"]', '["Karthigai Deepam"]', '{"history":"Ancient site mentioned in Tevaram; expanded by Cholas and Vijayanagar rulers.","architecture":"Four grand gateway towers, the tallest being 217 feet.","sources":[{"label":"Annamalaiyar Temple","url":"https://annamalaiyar.hrce.tn.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruvannamalai-arulmigu-arunachaleswarar-temple-the-macro-center', 'shiva', 'Arulmigu Arunachaleswarar Temple (The macro-center)', 'Tamil Nadu', 'Tiruvannamalai', 'Arunachala Hill complex, Tiruvannamalai district', 'Shiva (Arunachaleswarar)', 'Shaiva', '["Pancha Bhoota","Agni Sthalam","Girivalam"]', 'The principal Shaiva center of Tiruvannamalai where Shiva is worshipped as Arunachaleswarar, identified with the fire element.', 'Karthigai Deepam and the full Girivalam route around Arunachala hill.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tiruvannamalai_arunachaleswarar_kovil.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tiruvannamalai_arunachaleswarar_kovil.jpg', 'Pournami (full moon) Girivalam nights and Karthigai Deepam season.', 'Open daily; timings vary by ritual schedule.', 'Traditional and modest attire recommended.', 'Expect heavy crowds on full moon and Karthigai Deepam days.', '["Girivalam","Deepam darshan","Daily puja"]', '["Karthigai Deepam","Mahashivratri"]', '{"history":"Arunachaleswarar Temple is one of Tamil Nadu\'s major Shaiva pilgrimage centers and part of the Pancha Bhoota tradition.","sources":[{"label":"Arunachalesvara Temple","url":"https://en.wikipedia.org/wiki/Arunachalesvara_Temple"},{"label":"Annamalaiyar Temple HRCE","url":"https://annamalaiyar.hrce.tn.gov.in/"}]}', '2026-02-23T13:13:38+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruvannamalai-arunachaleswarar-temple', 'shiva', 'Arunachaleswarar Temple', 'Tamil Nadu', 'Tiruvannamalai', 'Arunachala Hill', 'Arunachaleswarar', 'Shaiva', '["Shiva","Pancha Bhoota","Pilgrimage"]', 'A major Shaiva temple at the foothills of Arunachala, revered across Tamil Nadu.', 'Karthigai Deepam and the Agni lingam tradition.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Annamalaiyar_Temple_(6).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Annamalaiyar_Temple_(6).jpg', 'Early morning or festival days.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect crowds during Karthigai Deepam.', '["Daily puja","Evening aarti"]', '["Karthigai Deepam","Mahashivratri"]', '{"history":"Arunachaleswarar Temple is a major Shaiva shrine in Tiruvannamalai dedicated to Shiva and Parvati.","puranicView":"The temple is one of the Pancha Bhuta Sthalams, representing the element of fire (Agni).","puranicSources":[{"label":"Arunachalesvara Temple","url":"https://en.wikipedia.org/wiki/Arunachalesvara_Temple","type":"Encyclopedia"}],"folklore":"Pilgrims gather for hill circumambulation and seasonal festival worship.","folkloreSources":[{"label":"Arunachalesvara Temple","url":"https://en.wikipedia.org/wiki/Arunachalesvara_Temple","type":"Encyclopedia"}],"sources":[{"label":"Arunachalesvara Temple","url":"https://en.wikipedia.org/wiki/Arunachalesvara_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-tiruvannamalai-chandra-lingam', 'shiva', 'Chandra Lingam', 'Tamil Nadu', 'Tiruvannamalai', 'Tiruvannamalai sacred circuit, Tiruvannamalai district', 'Shiva', 'Shaiva', '["Chandra","Lingam","Circuit Shrine"]', 'Chandra Lingam is a Shiva shrine linked to lunar devotional symbolism within the Tiruvannamalai worship landscape.', 'A complementary lunar-themed lingam stop in the extended temple circuit.', '/temples/temple-05.svg', 'Not Available', 'Not Available', 'Evening and full moon devotional visits.', 'Open daily; local timings vary.', 'Traditional and modest attire recommended.', 'Best visited with other lingam nodes around Arunachala.', '["Daily puja"]', '["Pournami observances","Mahashivratri"]', '{"history":"Chandra-linked lingam worship appears in regional Shaiva devotional patterns.","sources":[{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Chandra%20Lingam%20Tiruvannamalai"}]}', '2026-02-23T13:13:38+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
