INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-vellore-jalakandeswarar-temple', 'shiva', 'Jalakandeswarar Temple', 'Tamil Nadu', 'Vellore', 'Vellore district', 'Shiva (Jalakandeswarar)', 'Shaiva', '["Vellore Fort","Water Lingam","Nayak Era"]', 'A historic Shiva temple inside Vellore Fort, known for the Jalakandeswarar linga surrounded by a water moat.', 'Ornate stone pillars within the fort complex.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vellore_Fort_Jalakandeswarar_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vellore_Fort_Jalakandeswarar_Temple.jpg', 'Winter months.', 'Open daily; timings vary.', 'Modest attire recommended.', 'Located within the Vellore Fort precinct.', '["Daily puja"]', '["Mahashivratri"]', '{"history":"A Vijayanagar/Nayak period shrine that anchors the Vellore Fort complex.","architecture":"Dravidian temple architecture with richly carved pillars.","sources":[{"label":"Jalakandeswarar Temple, Vellore","url":"https://en.wikipedia.org/wiki/Jalakandeswarar_Temple,_Vellore"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-vellore-sripuram-golden-temple', 'shiva', 'Sripuram Golden Temple', 'Tamil Nadu', 'Vellore', 'Thirumalaikodi', 'Mahalakshmi', 'Vaishnava', '["Gold","Modern","Mahalakshmi"]', 'A modern marvel, this temple is gilded with 1500kg of pure gold. It is designed to be a spiritual destination for peace.', 'The star-shaped path leading to the sanctum, adorned with spiritual messages.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Golden_Temple,_Vellore,_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Golden_Temple,_Vellore,_India.jpg', 'All year.', '8:00 AM - 8:00 PM.', 'Traditional/Modest.', 'Strict security; cameras and phones are not allowed.', '["Daily puja"]', '["Deepavali"]', '{"history":"Inaugurated in 2007 by Narayani Peedam.","architecture":"Fully gilded exterior and interior structures."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-vriddhachalam-virdhachalam-temple', 'shiva', 'Virdhachalam Temple', 'Tamil Nadu', 'Vriddhachalam', 'Cuddalore District', 'Shiva', 'Shaiva', '["Shiva","Ancient","Pancha Mukha"]', 'An ancient temple dedicated to Lord Vriddhagiriswarar. It is a major spiritual center for Saivism.', 'The five gateway towers (Gopurams) representing the five elements.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Virudhagiriswarar_temple_(10).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Virudhagiriswarar_temple_(10).jpg', 'Winter.', '6:00 AM - 12:00 PM, 4:00 PM - 9:00 PM.', 'Modest.', 'One of the largest temples in the region.', '["Daily puja"]', '["Maha Shivratri"]', '{"history":"Praised by the ancient Saivite saints in their songs.","architecture":"Dravidian style with stone masonry."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tamil-nadu-vriddhachalam-vriddhagiriswarar-temple', 'shiva', 'Vriddhagiriswarar Temple', 'Tamil Nadu', 'Vriddhachalam', 'Cuddalore District', 'Shiva (Vriddhagiriswarar)', 'Shaiva', '["Hill Temple","Five","Ancient"]', 'Everything in this temple is \'five\'—five gopurams, five prakarams, and five chariots. It is older than Kashi.', 'The ancient hill-like structure and the significance of the number five.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vridachaleswarar_gopuram.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vridachaleswarar_gopuram.jpg', 'Masi Magam.', '6:00 AM - 12:00 PM, 4:00 PM - 9:00 PM.', 'Traditional.', 'The temple name literally means \'Old Mountain\'.', '["Daily abhishekam"]', '["Masi Magam"]', '{"history":"Visited and praised by the Tevaram saints.","architecture":"Gigantic complex with massive walls."}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-ainavolu-ainavolu-mallikarjuna-swamy-temple', 'shiva', 'Ainavolu Mallikarjuna Swamy Temple', 'Telangana', 'Ainavolu', 'Warangal', 'Mallikarjuna Swamy', 'Shaivism', '["Kakatiya Keerthi Toranam","108 Pillars","Jathara"]', 'Built by Kakatiya minister Ayyanna. It features huge Keerthi Toranams (arches) similar to Warangal Fort.', 'Magnificent stone gateways.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Kakatiya-style_Mallikarjuna_temple_Ainavolu%2C_Inavolu_Telangana_10.jpg/960px-Kakatiya-style_Mallikarjuna_temple_Ainavolu%2C_Inavolu_Telangana_10.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kakatiya-style_Mallikarjuna_temple_Ainavolu,_Inavolu_Telangana_10.jpg', 'January to March', '6:00 AM - 8:00 PM', 'Traditional', 'Free entry', '["Oggu Katha","Bonam"]', '["Mallanna Jathara"]', '{"history":"11th Century Kakatiya construction.","architecture":"Kakatiya style with 108 pillars.","darshan":"Main deity.","seasonal":"Festive atmosphere during Jathara.","visitorNotes":"Close to Warangal.","festivals":"Jathara is very famous.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-ainavolu-ainavolu-mallikarjuna-temple', 'shiva', 'Ainavolu Mallikarjuna Temple', 'Telangana', 'Ainavolu', 'Warangal', 'Mallikarjuna (Shiva)', 'Shaivism', '["Kakatiya Keerthi Toranam","Shepherd Deity","Grand Architecture"]', 'An ancient temple built by Kakatiya minister Ayyanna Deva. It features massive stone toranas (gateways) similar to Warangal Fort.', 'Kakatiya Keerthi Toranams.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Kakatiya-style_Mallikarjuna_temple_Ainavolu%2C_Inavolu_Telangana_10.jpg/960px-Kakatiya-style_Mallikarjuna_temple_Ainavolu%2C_Inavolu_Telangana_10.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kakatiya-style_Mallikarjuna_temple_Ainavolu,_Inavolu_Telangana_10.jpg', 'Winter', '6:00 AM - 8:00 PM', 'Traditional', 'Free Entry', '["Oggu Katha","Bonalu"]', '["Mallanna Jatara","Shivaratri"]', '{"history":"Kakatiya era (11th Century).","architecture":"Grand Toranas.","darshan":"Lingam.","seasonal":"Jatara is colorful.","visitorNotes":"Must see the gateways.","festivals":"Mallanna Jatara.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-arka-brahma-temple', 'shiva', 'Arka Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Arka Brahma (Shiva)', 'Shaivism', '["Navabrahma Group","Sun God","Ruins"]', 'Dedicated to the Sun aspect (Arka) of Shiva, this temple is largely ruined but retains its basement structure.', 'Historical remnants.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/7th_century_Arka_Brahma_Temple%2C_Alampur_Navabrahma%2C_Telangana_India_-_19.jpg/960px-7th_century_Arka_Brahma_Temple%2C_Alampur_Navabrahma%2C_Telangana_India_-_19.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:7th_century_Arka_Brahma_Temple,_Alampur_Navabrahma,_Telangana_India_-_19.jpg', 'Winter', 'Sunrise to Sunset', 'Casual', 'Ruins', '["None"]', '["None"]', '{"history":"7th Century CE.","architecture":"Nagara style.","darshan":"Ruins.","seasonal":"Open air.","visitorNotes":"Historical interest.","festivals":"None.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-bala-brahma-temple', 'shiva', 'Bala Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Bala Brahmeswara (Shiva)', 'Shaivism/Shaktism', '["Active Worship","Navabrahma Group","Shakti Peetham Complex"]', 'The only active temple in the Navabrahma group, Bala Brahma is the largest and most significant. It houses the Jogulamba Devi shrine within its complex.', 'Active temple rituals and Jogulamba shrine.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/7th_century_Bala_Brahma_Temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_India_-_21.jpg/960px-7th_century_Bala_Brahma_Temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_India_-_21.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:7th_century_Bala_Brahma_Temple,_Navabrahma_group,_Alampur,_Telangana_India_-_21.jpg', 'Winter', '6:00 AM - 1:00 PM, 4:00 PM - 8:00 PM', 'Traditional', 'Main temple of the group', '["Abhishekam","Nitya Puja"]', '["Shivaratri","Dasara"]', '{"history":"7th Century CE, renovated later.","architecture":"Nagara style with recent additions.","darshan":"Lingam and Jogulamba Devi.","seasonal":"Crowded during Dasara.","visitorNotes":"Visit Jogulamba Shakti Peetham here.","festivals":"Dasara is grandly celebrated.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-bala-brahmeswara-swamy-temple', 'shiva', 'Bala Brahmeswara Swamy Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Bala Brahmeswara Swamy', 'Shaivism/Shaktism', '["Navabrahma Temples","Shakti Peetham","Badami Chalukya"]', 'Part of the Navabrahma group, this temple houses a unique Lingam with a footprint-like top. It is the principal shrine for the Jogulamba Shakti Peetham.', 'Jogulamba Shakti Peetham complex.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/7th_century_Bala_Brahma_Temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_India_-_21.jpg/960px-7th_century_Bala_Brahma_Temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_India_-_21.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:7th_century_Bala_Brahma_Temple,_Navabrahma_group,_Alampur,_Telangana_India_-_21.jpg', 'Winter', '7:00 AM - 8:30 PM', 'Traditional', 'Significant security due to antiquity', '["Abhishekam","Kumkum Archana (for Devi)"]', '["Dasara","Shivaratri"]', '{"history":"Built by Badami Chalukyas in the 7th century. It is considered the western gateway of Srisailam.","architecture":"Nagara style architecture.","darshan":"Lingam has an irregualr shape.","seasonal":"Hot in summer.","visitorNotes":"Visit all 9 Brahma temples in the complex.","festivals":"Navaratri is celebrated grandly.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-garuda-brahma-temple', 'shiva', 'Garuda Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Garuda Brahma (Shiva)', 'Shaivism', '["Navabrahma Group","Garuda Carvings","Pillared Hall"]', 'Named after the Garuda motif, this temple has a large pillared hall and intricate lattice windows.', 'Lattice window carvings.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/7th_8th_century_Garuda_Brahma_Temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_India_-_69.jpg/960px-7th_8th_century_Garuda_Brahma_Temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_India_-_69.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:7th_8th_century_Garuda_Brahma_Temple,_Navabrahma_group,_Alampur,_Telangana_India_-_69.jpg', 'Winter', 'Sunrise to Sunset', 'Traditional', 'ASI Site', '["Darshan"]', '["Shivaratri"]', '{"history":"7th Century CE.","architecture":"Nagara style.","darshan":"Lingam.","seasonal":"Winter is best.","visitorNotes":"Walk around the complex.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-kudavelli-sangameswara-temple', 'shiva', 'Kudavelli Sangameswara Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Sangameswara Swamy', 'Shaivism', '["Relocated Temple","Chalukya Art","River Confluence"]', 'Originally at the confluence of Krishna and Tungabhadra, this temple was dismantled and relocated to Alampur to save it from the Srisailam dam backwaters.', 'Successful transplant of an ancient temple.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Sangameshwar_temple_alampur_Mahboobnagar_India.jpg/960px-Sangameshwar_temple_alampur_Mahboobnagar_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sangameshwar_temple_alampur_Mahboobnagar_India.jpg', 'Winter', 'Sunrise to Sunset', 'Casual/Traditional', 'Located near the town entrance', '["Nitya Harathi"]', '["Shivaratri"]', '{"history":"7th Century Chalukyan temple. Relocated in 1979 by ASI.","architecture":"Northern Nagara curvilinear tower.","darshan":"Ancient Lingam.","seasonal":"Near river banks.","visitorNotes":"A marvel of conservation.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-kumara-brahma-temple', 'shiva', 'Kumara Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Kumara Brahma (Shiva)', 'Shaivism', '["Navabrahma Group","Pillar Carvings","Peacock Motifs"]', 'Known for the peacock motifs (vehicle of Kumara/Kartikeya) on the pillars.', 'Fine pillar artwork.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Kumara_Brahma_Temple%2C_Alampur_Navabrahma%2C_Telangana_India_-_11.jpg/960px-Kumara_Brahma_Temple%2C_Alampur_Navabrahma%2C_Telangana_India_-_11.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kumara_Brahma_Temple,_Alampur_Navabrahma,_Telangana_India_-_11.jpg', 'Winter', 'Sunrise to Sunset', 'Traditional', 'ASI Site', '["Darshan"]', '["Shivaratri"]', '{"history":"7th Century CE.","architecture":"Nagara style.","darshan":"Lingam.","seasonal":"Winter is best.","visitorNotes":"Part of the group.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-padma-brahma-temple', 'shiva', 'Padma Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Padma Brahma (Shiva)', 'Shaivism', '["Navabrahma Group","Mirror Lingam","Ruins"]', 'This temple contained a polished stone Lingam that was said to reflect like a mirror. It is now mostly in ruins.', 'Remnants of the polished Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Padma_Brahma_Temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_-_36.jpg/1920px-Padma_Brahma_Temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_-_36.jpg?20210219004107', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Padma_Brahma_Temple,_Navabrahma_group,_Alampur,_Telangana_-_36.jpg', 'Winter', 'Sunrise to Sunset', 'Casual', 'ASI Site', '["None (Ruins)"]', '["None"]', '{"history":"7th Century CE.","architecture":"Nagara style.","darshan":"Ruined sanctum.","seasonal":"Open site.","visitorNotes":"Last temple in the row.","festivals":"No active worship.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-papanasi-group-of-temples', 'shiva', 'Papanasi Group of Temples', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Papanaseswara (Shiva)', 'Shaivism', '["Relocated Temples","Nagara Style","Group of 23"]', 'A group of 23 temples originally located at Papanasi, relocated to Alampur to save them from submersion. They feature distinct Nagara style towers.', 'Cluster of Nagara Shikharas.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/9th_to_11th_century_Alampur_Papanasi_Temples%2C_Telangana_India_-_2.jpg/960px-9th_to_11th_century_Alampur_Papanasi_Temples%2C_Telangana_India_-_2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:9th_to_11th_century_Alampur_Papanasi_Temples,_Telangana_India_-_2.jpg', 'Winter', 'Sunrise to Sunset', 'Casual', 'ASI Protected', '["Darshan"]', '["Shivaratri"]', '{"history":"9th-11th Century Rashtrakuta/Chalukya.","architecture":"Phamsana/Nagara style.","darshan":"Multiple Lingams.","seasonal":"Hot summers.","visitorNotes":"Near Navabrahma temples.","festivals":"None specific active.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Papanasi_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-swarga-brahma-temple', 'shiva', 'Swarga Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Swarga Brahma (Shiva)', 'Shaivism', '["Ornate Carvings","Navabrahma Group","Flying Figures"]', 'Considered the finest of the Navabrahma temples, Swarga Brahma is known for its elaborate sculptures and \'flying\' figures on the ceiling.', 'Intricate sculptural details.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Alampur_Nava_Brahma_Temples_-_Swarga_Brahma.jpg/960px-Alampur_Nava_Brahma_Temples_-_Swarga_Brahma.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Alampur_Nava_Brahma_Temples_-_Swarga_Brahma.jpg', 'Winter', 'Sunrise to Sunset', 'Traditional', 'ASI Ticket required', '["Darshan"]', '["Shivaratri"]', '{"history":"Built by Badami Chalukyas (Lokaditya) in 689 CE.","architecture":"Nagara style with rich ornamentation.","darshan":"Lingam.","seasonal":"Pleasant in winter.","visitorNotes":"Do not miss the ceiling carvings.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-taraka-brahma-temple', 'shiva', 'Taraka Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Taraka Brahma (Shiva)', 'Shaivism', '["Navabrahma Group","Early Chalukya","Ruins"]', 'One of the nine Navabrahma temples, Taraka Brahma has a unique architectural style with a southern-style shikhara. It is currently in a semi-ruined state.', 'Ancient inscriptions.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Taraka_Brahma_temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_India_-_2.jpg/960px-Taraka_Brahma_temple%2C_Navabrahma_group%2C_Alampur%2C_Telangana_India_-_2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Taraka_Brahma_temple,_Navabrahma_group,_Alampur,_Telangana_India_-_2.jpg', 'Winter', 'Sunrise to Sunset', 'Traditional', 'Part of ASI complex', '["Darshan"]', '["Shivaratri"]', '{"history":"6th-7th Century CE Chalukya architecture.","architecture":"Early Nagara style.","darshan":"Lingam.","seasonal":"Hot summers.","visitorNotes":"Explore the inscriptions.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-vira-brahma-temple', 'shiva', 'Vira Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Vira Brahma (Shiva)', 'Shaivism', '["Navabrahma Group","Warrior Shiva","Chalukya Art"]', 'Represents the Vira (Hero/Warrior) aspect of Shiva. It has simple yet elegant carvings.', 'Warrior motifs.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Relief_sculpture_the_Hindu_god_Brahma_and_goddess_Saraswati_in_the_Mallikarjuna_temple_at_Basaralu.JPG/960px-Relief_sculpture_the_Hindu_god_Brahma_and_goddess_Saraswati_in_the_Mallikarjuna_temple_at_Basaralu.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Relief_sculpture_the_Hindu_god_Brahma_and_goddess_Saraswati_in_the_Mallikarjuna_temple_at_Basaralu.JPG', 'Winter', 'Sunrise to Sunset', 'Traditional', 'ASI Site', '["Darshan"]', '["Shivaratri"]', '{"history":"7th Century CE.","architecture":"Nagara style.","darshan":"Lingam.","seasonal":"Winter.","visitorNotes":"Part of the complex.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-alampur-vishwa-brahma-temple', 'shiva', 'Vishwa Brahma Temple', 'Telangana', 'Alampur', 'Jogulamba Gadwal', 'Vishwa Brahma (Shiva)', 'Shaivism', '["Navabrahma Group","Intricate Art","Cosmic Form"]', 'One of the most artistic temples in the group, Vishwa Brahma features elaborate scrollwork and sculptures of flying celestials.', 'Artistic excellence of early Chalukyas.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Vishwa_Brahma_%28L%29_and_Veera_Brahma_%28R%29_Temples%2C_Alampur%2C_Telangana_India.jpg/960px-Vishwa_Brahma_%28L%29_and_Veera_Brahma_%28R%29_Temples%2C_Alampur%2C_Telangana_India.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Vishwa_Brahma_(L)_and_Veera_Brahma_(R)_Temples,_Alampur,_Telangana_India.jpg', 'Winter', 'Sunrise to Sunset', 'Traditional', 'ASI Site', '["Darshan"]', '["Shivaratri"]', '{"history":"7th Century CE.","architecture":"Nagara style with floral motifs.","darshan":"Lingam.","seasonal":"Winter.","visitorNotes":"Highly recommended for art lovers.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Alampur_Navabrahma_Temples"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-armoor-navanatha-siddeshwara-temple', 'shiva', 'Navanatha Siddeshwara Temple', 'Telangana', 'Armoor', 'Nizamabad', 'Siddeshwara (Shiva)', 'Shaivism/Nath', '["Rock Formations","Navanathas","Swayambhu"]', 'Located on the Siddulagutta hillock, this temple is surrounded by unique rock formations. Legend says nine sages (Navanathas) meditated here.', 'Ancient rock formations and cave temple.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/The_MLA%2C_Armoor%2C_Shri_A._Jeevan_Reddy%2C_the_Municipal_Chairperson%2C_Armoor%2C_Smt._Swathi_Singh_Babloo%2C_the_District_Magistrate_and_District_Collector%2C_Nizamabad.jpg/960px-thumbnail.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:The_MLA,_Armoor,_Shri_A._Jeevan_Reddy,_the_Municipal_Chairperson,_Armoor,_Smt._Swathi_Singh_Babloo,_the_District_Magistrate_and_District_Collector,_Nizamabad.jpg', 'Winter', '6:00 AM - 7:00 PM', 'Casual', 'Hillock climb/Walkway', '["Cave meditation","Abhishekam"]', '["Shivaratri"]', '{"history":"Associated with Nath tradition sages.","architecture":"Cave and rock-cut.","darshan":"Swayambhu Lingam in cave.","seasonal":"Morning visits are best.","visitorNotes":"Explore the pile of rocks.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-bellampalli-bugga-rajeshwara-swamy-temple', 'shiva', 'Bugga Rajeshwara Swamy Temple', 'Telangana', 'Bellampalli', 'Mancherial', 'Bugga Rajeshwara Swamy', 'Shaivism', '["Natural Water Source","Bugga (Bubble)","Forest Temple"]', 'Named after \'Bugga\' (water bubble), as a natural spring flows continuously near the Shiva Lingam, believed to have healing powers.', 'Perennial underground water spring.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Legislative_Assembly_constituencies_of_Telangana_%283-Bellampalli_highlighted%29.png/862px-Legislative_Assembly_constituencies_of_Telangana_%283-Bellampalli_highlighted%29.png', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Legislative_Assembly_constituencies_of_Telangana_(3-Bellampalli_highlighted).png', 'Monsoon/Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Forest area', '["Jalabhisekam"]', '["Shivaratri","Kartheeka Masam"]', '{"history":"Ancient local shrine developed over centuries.","architecture":"Dravidian influence.","darshan":"Shiva Lingam with water spring.","seasonal":"Lush green in monsoon.","visitorNotes":"Peaceful forest environment.","festivals":"Huge Jathara on Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-bhongir-bhongir-fort-shiva-temple', 'shiva', 'Bhongir Fort Shiva Temple', 'Telangana', 'Bhongir', 'Yadadri Bhuvanagiri', 'Shiva', 'Shaivism', '["Fort Temple","Hilltop","Trekking"]', 'Located within the historic Bhongir Fort atop a monolithic rock. The temple offers spiritual solace and a panoramic view of the surroundings.', 'Shiva temple inside a massive hilltop fort.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/A_view_of_Bhongir_Fort%2C_AP_W_IMG_3108.jpg/900px-A_view_of_Bhongir_Fort%2C_AP_W_IMG_3108.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:A_view_of_Bhongir_Fort,_AP_W_IMG_3108.jpg', 'Winter/Morning', '10:00 AM - 5:00 PM', 'Casual/Trekking', 'Fort entry fee applies', '["Archana"]', '["Maha Shivaratri"]', '{"history":"Part of the 10th-century fort built by Chalukyas.","architecture":"Rock-cut/Fort style.","darshan":"Shiva Lingam.","seasonal":"Avoid summer.","visitorNotes":"Requires steep climb.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Bhongir_Fort"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-bikkanur-siddha-rameshwara-swamy-temple-bikkanur', 'shiva', 'Siddha Rameshwara Swamy Temple (Bikkanur)', 'Telangana', 'Bikkanur', 'Kamareddy', 'Siddha Rameshwara Swamy', 'Shaivism', '["Siddha","Rameshwara","Ancient"]', 'An ancient temple dedicated to Shiva as Siddha Rameshwara. It is known for its peaceful atmosphere and historical significance.', 'Serene environment and ancient structure.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Free entry', '["Abhishekam"]', '["Maha Shivaratri"]', '{"history":"Believed to be very old.","architecture":"Stone construction.","darshan":"Shiva Lingam.","seasonal":"Year-round.","visitorNotes":" Located near NH-44.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-bonthapally-bonthapally-veerabhadra-swamy-temple', 'shiva', 'Bonthapally Veerabhadra Swamy Temple', 'Telangana', 'Bonthapally', 'Sangareddy', 'Veerabhadra Swamy', 'Shaivism', '["Veerabhadra","Fire Walking","Agnigundam"]', 'Famous for the fierce form of Shiva, Veerabhadra Swamy. The annual Agnigundam (fire walking) festival is a major event here.', 'Devotees walking on fire (Agnigundam).', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Winter', '6:00 AM - 8:00 PM', 'Traditional', 'Near Hyderabad ORR', '["Agnigundam","Abhishekam"]', '["Shivaratri","Bhadrapada Poornima"]', '{"history":"Kakatiya era origins.","architecture":"Dravidian style.","darshan":"Veerabhadra idol.","seasonal":"Crowded during festivals.","visitorNotes":"Powerful deity.","festivals":"Fire walking ceremony.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-cheruvugattu-cheruvugattu-jadala-ramalingeswara', 'shiva', 'Cheruvugattu Jadala Ramalingeswara', 'Telangana', 'Cheruvugattu', 'Nalgonda', 'Jadala Ramalingeswara (Shiva)', 'Shaivism', '["Hill Temple","Jadala Lingam","Parashurama"]', 'A hill temple dedicated to Jadala Ramalingeswara. Legend says Parashurama installed the Lingam here. It is famous for its rocky terrain and Jatara.', 'Hilltop view and Jatara.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Winter', '6:00 AM - 8:00 PM', 'Traditional', 'Climb required', '["Gundu (Rock) Pradakshina","Abhishekam"]', '["Brahmotsavam","Shivaratri"]', '{"history":"Mythological origins.","architecture":"Hill fort/temple style.","darshan":"Lingam.","seasonal":"Jatara draws thousands.","visitorNotes":"Be prepared to walk.","festivals":"Brahmotsavam.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-ghanpur-ghanpur-group-of-temples', 'shiva', 'Ghanpur Group of Temples', 'Telangana', 'Ghanpur', 'Mulugu', 'Ganapeswara (Shiva)', 'Shaivism', '["Kota Gullu","Kakatiya Ruins","Red Sandstone"]', 'Also known as Kota Gullu, this complex of ruined temples resembles the Ramappa Temple in style. It was a major fortress temple complex built by King Ganapatideva.', 'Collapsing yet majestic Shikharas.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Ghanpur_temples%2C_known_as_Kota_Gullu_at_Ghanpur%2C_Telangana_29.jpg/960px-Ghanpur_temples%2C_known_as_Kota_Gullu_at_Ghanpur%2C_Telangana_29.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ghanpur_temples,_known_as_Kota_Gullu_at_Ghanpur,_Telangana_29.jpg', 'Winter', 'Sunrise to Sunset', 'Casual', 'ASI Site', '["Darshan"]', '["Shivaratri"]', '{"history":"Built by King Ganapatideva (1199-1262 CE).","architecture":"Kakatiya style, similar to Ramappa.","darshan":"Ruined sanctums, main Lingam active.","seasonal":"Best in winter.","visitorNotes":"Requires some walking.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-hanamkonda-siddeshwara-temple', 'shiva', 'Siddeshwara Temple', 'Telangana', 'Hanamkonda', 'Hanamkonda', 'Siddeshwara (Shiva)', 'Shaivism', '["West Facing","Paschimdwara","Chalukya"]', 'An ancient 3rd-century temple, unique for its west-facing (Paschimdwara) entrance, which is rare in Hindu temple architecture.', 'West-facing sanctum.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/11th_12th_century_Siddheshwara_Temple_Kalgi_Karnataka_India_-_18.jpg/960px-11th_12th_century_Siddheshwara_Temple_Kalgi_Karnataka_India_-_18.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:11th_12th_century_Siddheshwara_Temple_Kalgi_Karnataka_India_-_18.jpg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Near Thousand Pillar Temple', '["Abhishekam"]', '["Shivaratri"]', '{"history":"3rd Century AD origins.","architecture":"Chalukya style.","darshan":"Lingam facing West.","seasonal":"Pleasant surroundings.","visitorNotes":"Peaceful spot.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-hanamkonda-thousand-pillar-temple', 'shiva', 'Thousand Pillar Temple', 'Telangana', 'Hanamkonda', 'Warangal', 'Rudreshwara Swamy', 'Shaivism', '["Kakatiya Architecture","1000 Pillars","Trikutalayam"]', 'A masterpiece of Kakatiya art, this temple is known for its intricately carved pillars and a massive monolithic Nandi.', 'Star-shaped architecture with 1000 richly carved pillars.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Nandi_Thousand_Pillar_Temple.jpg/960px-Nandi_Thousand_Pillar_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nandi_Thousand_Pillar_Temple.jpg', 'September to March', '5:00 AM - 9:00 PM', 'Traditional', 'Free entry', '["Rudrabhishekam","Bilvarchana"]', '["Maha Shivaratri","Karthika Pournami"]', '{"history":"Constructed in 1163 AD by Rudra Deva. It is a Trikutalayam dedicated to Shiva, Vishnu, and Surya.","architecture":"Star-shaped plan with perforated stone screens, rich icons, and rock-cut elephants. The Nandi is carved from a single black basalt stone.","darshan":"The main shrine is dedicated to Rudreshwara (Shiva).","seasonal":"Avoid peak summer.","visitorNotes":"Located in the heart of Hanamkonda city.","festivals":"Saralamma Samaakka Jathara is also significant in the region.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thousand_Pillar_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-hyderabad-kashi-bugga-shiva-temple', 'shiva', 'Kashi Bugga Shiva Temple', 'Telangana', 'Hyderabad', 'Hyderabad', 'Kashi Vishwanatha (Shiva)', 'Shaivism', '["Underground Stream","Kishan Bagh","Mystery"]', 'A 200-year-old temple where a continuous stream of water (\'Bugga\') flows underground over the Shiva Lingam, believed to have medicinal properties.', 'Mysterious underground water stream.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Kashi_Bugga_Temple%2C_Jiyaguda%2C_Hyderabad_2.jpg/960px-Kashi_Bugga_Temple%2C_Jiyaguda%2C_Hyderabad_2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kashi_Bugga_Temple,_Jiyaguda,_Hyderabad_2.jpg', 'Year-round', '6:00 AM - 11:00 AM, 5:00 PM - 8:00 PM', 'Traditional', 'Near Bahadurpura', '["Jala Abhishekam"]', '["Shivaratri"]', '{"history":"Built in 1822.","architecture":"House-like structure with cellar.","darshan":"Lingam in water.","seasonal":"Stream active year-round.","visitorNotes":"Hidden gem in Old City.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-hyderabad-somnath-temple', 'shiva', 'Somnath Temple', 'Telangana', 'Hyderabad', 'Hyderabad', 'Somnath (Shiva)', 'Shaivism', '["Old City","Sun God","Ancient"]', 'Located in Yakutpura, this ancient temple is dedicated to Shiva and also houses shrines for the Sun God and Vishnu.', 'Ancient temple in Old City Hyderabad.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/A_handbook_for_travellers_in_India%2C_Burma%2C_and_Ceylon_._%28IA_handbooktravelle00john%29.pdf/page1-640px-A_handbook_for_travellers_in_India%2C_Burma%2C_and_Ceylon_._%28IA_handbooktravelle00john%29.pdf.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:A_handbook_for_travellers_in_India,_Burma,_and_Ceylon_._(IA_handbooktravelle00john).pdf', 'Year-round', '6:00 AM - 8:00 PM', 'Traditional', 'Near Charminar area', '["Nitya Puja"]', '["Shivaratri"]', '{"history":"Ancient heritage.","architecture":"Traditional.","darshan":"Lingam.","seasonal":"Busy area.","visitorNotes":"Visit while exploring Charminar.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Somnath_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-hyderabad-sri-mahadev-temple', 'shiva', 'Sri Mahadev Temple', 'Telangana', 'Hyderabad', 'Hyderabad', 'Mahadev (Shiva)', 'Shaivism', '["North Indian Style","Feelkhana","Heritage"]', 'A heritage temple in the Feelkhana area, reflecting North Indian architectural styles and serving the local community for generations.', 'Heritage architecture.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Mahadev_Temple_Salewada.jpg/960px-Mahadev_Temple_Salewada.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahadev_Temple_Salewada.jpg', 'Year-round', '6:00 AM - 8:00 PM', 'Traditional', 'Old City area', '["Aarti","Bhajan"]', '["Shivaratri","Shravan Month"]', '{"history":"Historic.","architecture":"Nagara style influence.","darshan":"Lingam.","seasonal":"Shravan month is festive.","visitorNotes":"Busy market area.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-ismailkhanpet-bhavani-shankara-temple-ismailkhanpet', 'shiva', 'Bhavani Shankara Temple (Ismailkhanpet)', 'Telangana', 'Ismailkhanpet', 'Sangareddy', 'Bhavani Shankara Swamy', 'Shaivism', '["Sapta Prakara","Kakatiya","Fortified"]', 'Also known as Sapta Prakara Bhavani Shankara Swamy Temple. Use to have seven compound walls (Prakaras). Built by Kakatiyas.', 'Historical significance and fortification walls.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Free entry', '["Abhishekam"]', '["Maha Shivaratri"]', '{"history":"Built during Kakatiya era.","architecture":"Kakatiya style.","darshan":"Shiva and Parvathi.","seasonal":"Pleasant.","visitorNotes":"Near Sangareddy town.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-jharasangam-ketaki-sangameswara-swamy-temple', 'shiva', 'Ketaki Sangameswara Swamy Temple', 'Telangana', 'Jharasangam', 'Sangareddy', 'Ketaki Sangameswara Swamy', 'Shaivism', '["Ketaki Flowers","Brahma Stapana","Amrutha Gundam"]', 'Legend says Brahma installed the Lingam here. It is one of the few temples where Ketaki flowers are offered to Shiva.', 'Offering of forbidden Ketaki flowers.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Monsoon/Winter', '5:00 AM - 8:00 PM', 'Traditional', 'Free entry', '["Ketaki Flower Puja","Holy dip in Gundam"]', '["Maha Shivaratri"]', '{"history":"Mythology dates back to Treta Yuga. King Kupendra was cured of skin disease here.","architecture":"Simple ancient stone structure.","darshan":"Water flows continuously from the Gomukha.","seasonal":"Lush green surroundings.","visitorNotes":"Take a bath in the Amrutha Gundam.","festivals":"Grand fair during Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-jharasangam-kethaki-sangameshwara-temple', 'shiva', 'Kethaki Sangameshwara Temple', 'Telangana', 'Jharasangam', 'Sangareddy', 'Sangameshwara (Shiva)', 'Shaivism', '["Kethaki Flowers","Dakshina Kasi","Brahma Installed"]', 'One of the few temples where Kethaki flowers are offered to Shiva, usually forbidden. It is believed to be installed by Lord Brahma.', 'Kethaki flower offering.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Zaheerabad_MLA_Koninty_Manik.jpg/960px-Zaheerabad_MLA_Koninty_Manik.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Zaheerabad_MLA_Koninty_Manik.jpg', 'All Year', '6:00 AM - 8:00 PM', 'Traditional', 'Free Entry', '["Kethaki Pooja","Abhishekam"]', '["Shivaratri"]', '{"history":"Ancient mythology.","architecture":"Dravidian.","darshan":"Lingam.","seasonal":"Shivaratri.","visitorNotes":"Rare tradition here.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jharasangam"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kadile-papa-hareshwara-temple', 'shiva', 'Papa Hareshwara Temple', 'Telangana', 'Kadile', 'Nirmal', 'Papa Hareshwara Swamy', 'Shaivism', '["Swinging Lingam","Parashurama","Annapurna Devi"]', 'Legend says Parashurama performed penance here to remove his sins. The Lingam is believed to swing slightly (\'Kadile\') due to water pressure below.', 'The \'Kadile\' (moving) Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Kadile_Nataraja.jpg/960px-Kadile_Nataraja.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kadile_Nataraja.jpg', 'Monsoon/Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Forest surroundings', '["Abhishekam to remove sins"]', '["Shivaratri","Shravana Masam"]', '{"history":"Associated with Parashurama legend.","architecture":"Western Chalukya style.","darshan":"Lingam with serpent.","seasonal":"Scenic beauty.","visitorNotes":"Near Nirmal town.","festivals":"Month-long fair in Shravana.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kaleshwaram-kaleshwara-mukteshwara-swamy-temple', 'shiva', 'Kaleshwara Mukteshwara Swamy Temple', 'Telangana', 'Kaleshwaram', 'Jayashankar Bhupalpally', 'Kaleshwara (Yama) and Mukteshwara (Shiva)', 'Shaivism', '["Triveni Sangamam","Two Lingams","Trilinga Desam"]', 'Unique for having two Shiva Lingams on a single pedestal - one for Shiva (Mukteshwara) and one for Yama (Kaleshwara).', 'Situated at the confluence of Godavari, Pranahita, and Saraswati rivers.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/VasaviTemple_side.jpg/960px-VasaviTemple_side.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:VasaviTemple_side.jpg', 'November to February', '4:30 AM - 8:00 PM', 'Traditional', 'Free entry', '["Punya Snanam (Holy Bath)","Abhishekam to both Lingams"]', '["Karthika Masam","Shivaratri"]', '{"history":"One of the three Shiva temples mentioned in the \'Trilinga Desam\'.","architecture":"Dravidian style with a towering Gopuram.","darshan":"Devotees first worship Lord Yama (Kaleshwara) and then Lord Shiva (Mukteshwara).","seasonal":"River levels rise in monsoon.","visitorNotes":"Check for river boat rides.","festivals":"Kalyanam is performed periodically.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Kaleshwaram"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kallur-kallur-shiva-temple', 'shiva', 'Kallur Shiva Temple', 'Telangana', 'Kallur', 'Khammam', 'Shiva', 'Shaivism', '["Kakatiya","Pancha Lingams","Prataparudra"]', 'Built by Kakatiya King Prataparudra, this temple is known for housing five Shiva Lingams and a large temple tank.', 'Five Lingams and Kakatiya history.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Kallur_Temple_Sideway.jpg/960px-Kallur_Temple_Sideway.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kallur_Temple_Sideway.jpg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Historical site', '["Pancha Linga Archana"]', '["Shivaratri"]', '{"history":"13th Century Kakatiya.","architecture":"Kakatiya style.","darshan":"Five Lingams.","seasonal":"Festive during Shivaratri.","visitorNotes":"Near Khammam.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kazipet-mettugutta-ramalingeswara-temple', 'shiva', 'Mettugutta Ramalingeswara Temple', 'Telangana', 'Kazipet', 'Hanamkonda', 'Ramalingeswara (Shiva)', 'Shaivism/Vaishnavism', '["Hilltop","Twin Temples","Ramayana"]', 'Located on a hillock with twin temples for Shiva and Rama. Legend says Rama worshipped a Swayambhu Lingam here.', 'Twin temples and rock formations.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Main_entrance_Kazipet.JPG/960px-Main_entrance_Kazipet.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Main_entrance_Kazipet.JPG', 'Winter', '6:00 AM - 7:30 PM', 'Traditional', 'Near Railway Station', '["Abhishekam","Kalyanotsavam"]', '["Shivaratri","Sri Rama Navami"]', '{"history":"Kakatiya era.","architecture":"Rock-cut influence.","darshan":"Lingam and Rama idol.","seasonal":"Evening view is good.","visitorNotes":"Climb up for city view.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-keesara-ramalingeswara-swamy-temple', 'shiva', 'Ramalingeswara Swamy Temple', 'Telangana', 'Keesara', 'Medchal-Malkajgiri', 'Ramalingeswara Swamy', 'Shaivism', '["Hill Top","Ramayana Legend","101 Lingas"]', 'Legend says Lord Rama installed the Lingam here to atone for killing Ravana. Hanuman, who was late, threw 101 Lingams on the hill.', 'Beautiful hillock view and scattered Lingams all around.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Temple_at_Keesaragutta%2C_AP_W_IMG_9127.jpg/824px-Temple_at_Keesaragutta%2C_AP_W_IMG_9127.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Temple_at_Keesaragutta,_AP_W_IMG_9127.jpg', 'Winter', '6:00 AM - 7:30 PM', 'Traditional', 'Hill road entry fee for vehicles', '["Abhishekam","Lakh Bilvarchana"]', '["Maha Shivaratri","Sri Rama Navami"]', '{"history":"Associated with Vishnukundin dynasty.","architecture":"Ancient stone architecture mixed with modern renovations.","darshan":"Swayambhu Lingam dedicated by Rama.","seasonal":"Very crowded on Karthika Mondays.","visitorNotes":"Beware of monkeys.","festivals":"Brahmotsavam is grand.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Keesaragutta_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-khammam-amara-lingeswara-swamy-temple-khammam', 'shiva', 'Amara Lingeswara Swamy Temple (Khammam)', 'Telangana', 'Khammam', 'Khammam', 'Amara Lingeswara Swamy', 'Shaivism', '["Pancharama","Ancient","River Bank"]', 'A significant Shiva temple located in Khammam, often associated with the Pancharama Kshetras of Andhra Pradesh in style and significance.', 'Ancient Shiva Lingam.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Winter', '6:00 AM - 8:00 PM', 'Traditional', 'Free entry', '["Abhishekam"]', '["Maha Shivaratri","Kartheeka Masam"]', '{"history":"Ancient temple with regular worship.","architecture":"Traditional.","darshan":"Shiva Lingam.","seasonal":"Pleasant.","visitorNotes":"Easily accessible.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-khammam-guntimalleswara-swamy-temple', 'shiva', 'Guntimalleswara Swamy Temple', 'Telangana', 'Khammam', 'Khammam', 'Guntimalleswara (Shiva)', 'Shaivism', '["River Bank","Munneru","Ancient"]', 'Located on the banks of the Munneru river, this temple is an ancient spiritual center in Khammam town.', 'Riverbank location.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/A_side_view_of_Ganapeshwaralayam_temple%2C_Kusumanchi%2C_Khammam_district%2C_Telangana_02.jpg/960px-A_side_view_of_Ganapeshwaralayam_temple%2C_Kusumanchi%2C_Khammam_district%2C_Telangana_02.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:A_side_view_of_Ganapeshwaralayam_temple,_Kusumanchi,_Khammam_district,_Telangana_02.jpg', 'Winter', '5:30 AM - 7:30 PM', 'Traditional', 'In Khammam town', '["River bath (occasional)","Abhishekam"]', '["Shivaratri","Kartheeka Masam"]', '{"history":"Ancient origins.","architecture":"Traditional.","darshan":"Lingam.","seasonal":"River full in monsoon.","visitorNotes":"Peaceful spot in town.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kolanupaka-kolanupaka-someswara-temple', 'shiva', 'Kolanupaka Someswara Temple', 'Telangana', 'Kolanupaka', 'Yadadri Bhuvanagiri', 'Someswara (Shiva)', 'Shaivism', '["Swayambhu","Chalukya Capital","Cultural Hub"]', 'An ancient temple in the historic capital of Kulpak, dedicated to Swayambhu Someswara. It is located near the famous Jain temple.', 'Ancient Chalukya architecture.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Model_showing_entrance_of_Kolanupaka_temple.jpg/960px-Model_showing_entrance_of_Kolanupaka_temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Model_showing_entrance_of_Kolanupaka_temple.jpg', 'All Year', '6:00 AM - 8:00 PM', 'Traditional', 'Near Jain Temple', '["Abhishekam","Nitya Pooja"]', '["Shivaratri","Brahmotsavam"]', '{"history":"11th Century, Chalukya period.","architecture":"Dravidian/Chalukya mix.","darshan":"Lingam.","seasonal":"Busy during festivals.","visitorNotes":"Visit the museum nearby.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Kolanupaka_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-komuravelli-komuravelli-mallikarjuna-swamy-temple', 'shiva', 'Komuravelli Mallikarjuna Swamy Temple', 'Telangana', 'Komuravelli', 'Siddipet', 'Mallikarjuna Swamy (Mallanna)', 'Folk Shaivism', '["Folk Deity","Clay Idol","Yadava Tradition"]', 'A popular folk temple where Lord Shiva is worshipped as Mallanna in a clay idol form.', 'Clay idol of the deity.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Mallanna_Swamy_temple%2C_Komuravelli_Telangana_-_8.jpg/960px-Mallanna_Swamy_temple%2C_Komuravelli_Telangana_-_8.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mallanna_Swamy_temple,_Komuravelli_Telangana_-_8.jpg', 'December to March (Jathara season)', '4:30 AM - 8:30 PM', 'Casual/Traditional', 'Very crowded during Jathara', '["Patnam (Turmeric designs)","Bonam"]', '["Mallanna Jathara","Shivaratri"]', '{"history":"Ancient folk tradition temple.","architecture":"Cave-like structure expanded into a temple.","darshan":"Clay idol of Mallanna with Kethamma and Medalamma.","seasonal":"Peak season during Jathara.","visitorNotes":"Famous for \'Pedda Patnam\' ritual.","festivals":"The Jathara lasts for 3 months.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kondapaka-kondapaka-rudreshwara-temple', 'shiva', 'Kondapaka Rudreshwara Temple', 'Telangana', 'Kondapaka', 'Siddipet', 'Rudreshwara Swamy', 'Shaivism', '["Kakatiya","Restored","Rural"]', 'An ancient Kakatiya-era Shiva temple that recently underwent restoration. It features a beautiful detached mandapam and a Shiva Lingam.', 'Restored Kakatiya architecture in a rural setting.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Free entry', '["Abhishekam"]', '["Maha Shivaratri"]', '{"history":"Built during Kakatiya period.","architecture":"Kakatiya style with mandapam.","darshan":"Shiva Lingam.","seasonal":"Pleasant.","visitorNotes":"Near Siddipet.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Kondapaka"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kondapur-sri-kamakshi-ekambareswara-temple', 'shiva', 'Sri Kamakshi Ekambareswara Temple', 'Telangana', 'Kondapur', 'Rangareddy', 'Ekambareswara (Shiva)', 'Shaivism (Smarta)', '["Kanchi Tradition","Urban","Ekambareswara"]', 'Modeled after the famous Kanchi temple, this modern temple in the IT corridor attracts many devotees.', 'Kanchi-style architecture and rituals.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Year-round', '6:00 AM - 9:00 PM', 'Traditional', 'Near Botanical Gardens', '["Rudra Homam","Abhishekam"]', '["Shivaratri","Kalyanotsavam"]', '{"history":"Modern construction.","architecture":"Dravidian style.","darshan":"Lingam.","seasonal":"Regular cultural events.","visitorNotes":"Peaceful atmosphere.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kothur-devunigutta-temple', 'shiva', 'Devunigutta Temple', 'Telangana', 'Kothur', 'Mulugu', 'Shiva', 'Shaivism', '["Angkor Wat Style","Unique Architecture","Mystery"]', 'A recently popularized temple with unique sandstone brick architecture and carvings that resemble the style of Angkor Wat, puzzling archaeologists.', 'Unique Angkor Wat-like architecture.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Devunigutta_Temple_In_Telangana_State_02.jpg/960px-Devunigutta_Temple_In_Telangana_State_02.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Devunigutta_Temple_In_Telangana_State_02.jpg', 'Winter', 'Sunrise to Sunset', 'Casual', 'Remote location', '["Simple prayers"]', '["Shivaratri"]', '{"history":"6th Century CE Vakataka/Vishnukundin era.","architecture":"Unique recessed brick style.","darshan":"Lingam.","seasonal":"Difficult access in monsoon.","visitorNotes":"Archaeological marvel.","festivals":"Local worship.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Devunigutta_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-koti-lingala-sri-koteswara-siddeshwara-swamy-temple', 'shiva', 'Sri Koteswara Siddeshwara Swamy Temple', 'Telangana', 'Koti Lingala', 'Jagtial', 'Koteswara Siddeshwara Swamy', 'Shaivism', '["Satavahana Capital","Ancient Port","Koti Linga"]', 'Believed to be the first capital of the Satavahanas. The site is ancient, containing millions (Koti) of Lingams in the river bed/surroundings.', 'Ancient historical significance.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Winter', '6:00 AM - 6:00 PM', 'Traditional', 'River bank location', '["Holy Bath","Abhishekam"]', '["Maha Shivaratri"]', '{"history":"Satavahana era (2nd Century BCE).","architecture":"Ancient limestone structures.","darshan":"Lingam and river worship.","seasonal":"River full in monsoon.","visitorNotes":"Site of archaeological importance.","festivals":"Shivaratri fair.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Koti_Lingala"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kukatpally-sri-ramalingeswara-swamy-temple', 'shiva', 'Sri Ramalingeswara Swamy Temple', 'Telangana', 'Kukatpally', 'Medchal-Malkajgiri', 'Ramalingeswara (Shiva)', 'Shaivism', '["Urban Temple","Community","Modern"]', 'A prominent Shiva temple in the bustling area of Kukatpally, serving the spiritual needs of the urban population.', 'Peaceful oasis in the city.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Legend_of_Bugga_Ramalingeswara_Swamy_Temple_Documentary.jpg/960px-Legend_of_Bugga_Ramalingeswara_Swamy_Temple_Documentary.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Legend_of_Bugga_Ramalingeswara_Swamy_Temple_Documentary.jpg', 'Year-round', '5:30 AM - 8:30 PM', 'Traditional/Casual', 'KPHB Colony', '["Nitya Abhishekam","Pradosha Puja"]', '["Shivaratri","Kartheeka Masam"]', '{"history":"Modern development.","architecture":"South Indian style.","darshan":"Lingam.","seasonal":"Crowded on Mondays.","visitorNotes":"Easy access.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kuntala-kuntala-shiva-temple', 'shiva', 'Kuntala Shiva Temple', 'Telangana', 'Kuntala', 'Adilabad', 'Someshwara (Shiva)', 'Shaivism', '["Waterfall","Cave Temple","Nature"]', 'Situated near the stunning Kuntala Waterfalls, this cave temple houses a Swayambhu Lingam. Devotees trek here amidst nature.', 'Temple located near the waterfall.', 'https://upload.wikimedia.org/wikipedia/commons/a/aa/Kuntala-waterfalls1.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kuntala-waterfalls1.jpg', 'July to December (Monsoon/Winter)', '9:00 AM - 5:00 PM', 'Casual', 'Forest entry check', '["Nature worship"]', '["Shivaratri"]', '{"history":"Ancient natural cave.","architecture":"Cave.","darshan":"Lingam in cave.","seasonal":"Waterfalls are best in monsoon.","visitorNotes":"Combine with waterfall visit.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kuravi-veerabhadra-swamy-temple-kuravi', 'shiva', 'Veerabhadra Swamy Temple (Kuravi)', 'Telangana', 'Kuravi', 'Mahabubabad', 'Veerabhadra Swamy', 'Shaivism', '["Veerabhadra","Kakatiya","Fierce Form"]', 'Dedicated to the fierce form of Shiva, Veerabhadra. It is believed to have been built by the Kakatiyas.', 'Ancient temple dedicated to Veerabhadra Swamy.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'Year-round', '5:00 AM - 8:00 PM', 'Traditional', 'Free entry', '["Agnigundaalu"]', '["Maha Shivaratri","Brahmotsavam"]', '{"history":"Ancient temple with deep historical roots.","architecture":"South Indian style with Kakatiya influence.","darshan":"Fierce form of Shiva.","seasonal":"Crowded during festivals.","visitorNotes":"Near Mahabubabad.","festivals":"Jathara is famous.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Veerabhadra_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-kusumanchi-kusumanchi-ganapeswara-temple', 'shiva', 'Kusumanchi Ganapeswara Temple', 'Telangana', 'Kusumanchi', 'Khammam', 'Ganapeswara (Shiva)', 'Shaivism', '["Large Lingam","Kakatiya Era","Group of Temples"]', 'Home to one of the largest Shiva Lingams in Telangana, this temple complex was built during the Kakatiya reign. It stands on a high platform and faces east.', 'Huge Shiva Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Sri_Ganapeshwaralayam_Kusumanchi_Nandi_Statue.jpg/960px-Sri_Ganapeshwaralayam_Kusumanchi_Nandi_Statue.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sri_Ganapeshwaralayam_Kusumanchi_Nandi_Statue.jpg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Free Entry', '["Abhishekam"]', '["Shivaratri","Karthika Masam"]', '{"history":"12th-13th Century Kakatiya period.","architecture":"Massive scale, pillared mandapa.","darshan":"Giant Lingam.","seasonal":"Shivaratri is huge.","visitorNotes":"Near Khammam.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Kusumanchi"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-mahabubnagar-uma-maheshwara-swamy-temple', 'shiva', 'Uma Maheshwara Swamy Temple', 'Telangana', 'Mahabubnagar', 'Nagarkurnool', 'Uma Maheshwara Swamy', 'Shaivism', '["Northern Gateway to Srisailam","Nallamala Hills","Scenic View"]', 'Considered the northern gateway to Srisailam. It is believed that a visit to Srisailam is incomplete without visiting here.', 'Scenic location in the Nallamala hills.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Uma_Maheshwara_Temple_Inner_sanctum.jpg/960px-Uma_Maheshwara_Temple_Inner_sanctum.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Uma_Maheshwara_Temple_Inner_sanctum.jpg', 'Monsoon/Winter', '6:00 AM - 8:00 PM', 'Traditional', 'Ghat road access', '["Abhishekam"]', '["Shivaratri","Karthika Masam"]', '{"history":"2nd Century AD. Expanded by Kakatiyas.","architecture":"Dravidian style.","darshan":"Idol of Shiva and Parvati.","seasonal":"Beautiful waterfalls in monsoon.","visitorNotes":"Enjoy the view of the Nallamala forest.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-mahabubnagar-uma-maheshwara-temple', 'shiva', 'Uma Maheshwara Temple', 'Telangana', 'Mahabubnagar', 'Nagarkurnool', 'Uma Maheshwara (Shiva)', 'Shaivism', '["Northern Gateway","Hill Station","Srisailam Gateway"]', 'Considered the northern gateway to Srisailam. Located in the hills, it enjoys a cool climate and scenic surroundings.', 'Views and cool weather.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Uma_Maheshwara_Temple_Inner_sanctum.jpg/960px-Uma_Maheshwara_Temple_Inner_sanctum.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Uma_Maheshwara_Temple_Inner_sanctum.jpg', 'Monsoon/Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Drive up the hill', '["Abhishekam"]', '["Shivaratri","Karthika Masam"]', '{"history":"Ancient link to Srisailam.","architecture":"Hill temple.","darshan":"Lingam.","seasonal":"Foggy in monsoon.","visitorNotes":"Gateway to Srisailam.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-maheshwaram-maheshwaram-shiva-temple', 'shiva', 'Maheshwaram Shiva Temple', 'Telangana', 'Maheshwaram', 'Rangareddy', 'Shiva', 'Shaivism', '["Pushkarini","Ancient Steps","Shivaganga"]', 'Known for its unique \'Shivaganga\' pushkarini (pond) with the temple located in the center. It has a history dating back to the Qutb Shahi era.', 'Temple in the middle of a pond.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Shivaganga_Temple_Maheshwaram_.jpg/960px-Shivaganga_Temple_Maheshwaram_.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shivaganga_Temple_Maheshwaram_.jpg', 'Monsoon/Winter', '6:00 AM - 8:00 PM', 'Traditional', 'Free Entry', '["Abhishekam"]', '["Shivaratri"]', '{"history":"~300-400 years old.","architecture":"Vernacular stone style.","darshan":"Lingam.","seasonal":"Pond full in monsoon.","visitorNotes":"Near Hyderabad airport.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Maheshwaram"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-manthani-gautameshwara-temple', 'shiva', 'Gautameshwara Temple', 'Telangana', 'Manthani', 'Peddapalli', 'Gautameshwara Swamy', 'Shaivism', '["Ruins","Kakatiya Art","Mantra Puri"]', 'Located in the ancient town of Manthani (Mantrapuri), this temple, though in ruins, showcases exceptional Kakatiya craftsmanship.', 'Historical ruins on the banks of Godavari.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Gautameshwara_temple%2C_Manthani_Telangana_-_5.jpg/960px-Gautameshwara_temple%2C_Manthani_Telangana_-_5.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gautameshwara_temple,_Manthani_Telangana_-_5.jpg', 'Winter', 'Sunrise to Sunset', 'Casual', 'Open ruins', '["Simple puja"]', '["Shivaratri"]', '{"history":"Kakatiya era renovation of an older shrine.","architecture":"Kakatiya style.","darshan":"Shiva Lingam.","seasonal":"Godavari river proximity.","visitorNotes":"Explore other ruins in Manthani.","festivals":"Local celebration.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Manthani"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-mellacheruvu-mellacheruvu-swayambhu-temple', 'shiva', 'Mellacheruvu Swayambhu Temple', 'Telangana', 'Mellacheruvu', 'Suryapet', 'Shambhu Lingeswara (Shiva)', 'Shaivism', '["Swayambhu","Dakshina Kashi","Hole in Lingam"]', 'Known as Dakshina Kashi, the Swayambhu Lingam here has a hole on top that is said to be always filled with water. The temple dates back to the Kakatiya era.', 'Water-filled hole in Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Mellacheruvu_Anjaneyaswamy_Temple.jpg/960px-Mellacheruvu_Anjaneyaswamy_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mellacheruvu_Anjaneyaswamy_Temple.jpg', 'Winter', '6:00 AM - 8:00 PM', 'Traditional', 'Free Entry', '["Abhishekam","Kalyanam"]', '["Shivaratri","Karthika Masam"]', '{"history":"Kakatiya period construciton.","architecture":"Classic Kakatiya.","darshan":"Swayambhu Lingam.","seasonal":"Shivaratri is grand.","visitorNotes":"See the water miracle.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mellacheruvu"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-nagunur-nagunur-fort-shiva-temple', 'shiva', 'Nagunur Fort Shiva Temple', 'Telangana', 'Nagunur', 'Karimnagar', 'Shiva', 'Shaivism', '["Fort Ruins","Red Stone","Musical Pillars"]', 'Located inside the Nagunur Fort, this temple is made of red stone and was once a center of great political and religious power under the Kakatiyas.', 'Intricate carvings on beams and pillars.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Historic_heritage_sites_of_Telangana_with_GPS_coordinates.jpg/960px-Historic_heritage_sites_of_Telangana_with_GPS_coordinates.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Historic_heritage_sites_of_Telangana_with_GPS_coordinates.jpg', 'Winter', 'Sunrise to Sunset', 'Casual', 'Ruins exploration', '["None (Ruins)"]', '["None"]', '{"history":"12th-13th Century Kakatiya.","architecture":"Kakatiya style with red stone.","darshan":"Ruined sanctum.","seasonal":"Open air.","visitorNotes":"Explore the fort walls.","festivals":"None.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-nallamala-forest-saleshwaram-lingamaiah-swamy-temple', 'shiva', 'Saleshwaram Lingamaiah Swamy Temple', 'Telangana', 'Nallamala Forest', 'Nagarkurnool', 'Lingamaiah Swamy', 'Shaivism', '["Deep Forest","Waterfall","Limited Access"]', 'Located deep in the tiger reserve, this temple is open only for 3-5 days a year during Chaitra Purnima.', 'Hidden cave temple with a waterfall.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Saleshwaram_temple_route.jpg/960px-Saleshwaram_temple_route.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Saleshwaram_temple_route.jpg', 'April (Chaitra Purnima)', 'Open only during festival', 'Trekking gear/Traditional', 'Requires trek. Strict forest department control.', '["Deeparadhana","Holy Bath"]', '["Saleshwaram Jathara"]', '{"history":"Ancient site mentioned in Puranas.","architecture":"Cave temple.","darshan":"Swayambhu Lingam inside a cave.","seasonal":"Closed rest of the year.","visitorNotes":"Difficult trek. Carry water.","festivals":"Huge crowd during the few open days.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-nallamala-forest-saleshwaram-lingamaiah-temple', 'shiva', 'Saleshwaram Lingamaiah Temple', 'Telangana', 'Nallamala Forest', 'Nagarkurnool', 'Lingamaiah (Shiva)', 'Shaivism/Tribal', '["Cave Temple","Adventure","Once a Year"]', 'Located deep in the Tiger Reserve, this temple is open only for a few days a year during Chaitra Purnima. It involves a trek and is in a scenic cave.', 'Cave location and limited access.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Saleshwaram_temple_route.jpg/960px-Saleshwaram_temple_route.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Saleshwaram_temple_route.jpg', 'Chaitra Purnima (April)', 'Open only during Jathara', 'Casual/Trekking', 'Permit required/Restricted', '["Deep Forest Pooja","Cave Darshan"]', '["Saleshwaram Jathara"]', '{"history":"Ancient cave shrine.","architecture":"Natural cave.","darshan":"Lingam in cave.","seasonal":"Only open ~5 days a year.","visitorNotes":"Difficult trek.","festivals":"Jathara (April).","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-nandi-kandi-ramalingeswara-swamy-temple-nandi-kandi', 'shiva', 'Ramalingeswara Swamy Temple (Nandi Kandi)', 'Telangana', 'Nandi Kandi', 'Sangareddy', 'Ramalingeswara Swamy', 'Shaivism', '["Star Shaped","Kalyana Chalukya","Unique Architecture"]', 'A unique star-shaped temple built by the Kalyana Chalukyas in the 11th century. The sunlight passes through the Nandi and falls on the Shivalingam.', 'Star-shaped architecture and Nandi aligned to sun rays.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Free entry', '["Abhishekam"]', '["Maha Shivaratri"]', '{"history":"Built during the reign of Vikramaditya VI of Kalyana Chalukyas.","architecture":"Stellate plan with intricate carvings.","darshan":"Main deity Shiva.","seasonal":"Pleasant.","visitorNotes":"Located on NH-65.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-nandikandi-ramalingeswara-temple', 'shiva', 'Ramalingeswara Temple', 'Telangana', 'Nandikandi', 'Sangareddy', 'Ramalingeswara Swamy', 'Shaivism', '["Star Shaped","Kalyani Chalukya","Pillar Carvings"]', 'A hidden gem of Kalyani Chalukya architecture, this temple features a unique star-shaped plan and a giant Nandi carved from black stone.', 'Star-shaped sanctum and intricate pillars.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Bugga_Ramalingeswara_temple.jpg/960px-Bugga_Ramalingeswara_temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bugga_Ramalingeswara_temple.jpg', 'Winter', '6:00 AM - 6:00 PM', 'Traditional', 'Near NH-65', '["Nitya Puja"]', '["Shivaratri"]', '{"history":"11th Century Chalukyan temple.","architecture":"Star-shaped plan.","darshan":"Sun rays fall on Lingam through perforated windows.","seasonal":"Accessible year-round.","visitorNotes":"Close to Hyderabad-Mumbai highway.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-nizamabad-neelakanteshwara-temple', 'shiva', 'Neelakanteshwara Temple', 'Telangana', 'Nizamabad', 'Nizamabad', 'Neelakanteshwara Swamy', 'Shaivism', '["Converted Jain Temple","Ratha Saptami","Hill Top"]', 'Originally a Jain temple, converted to a Shiva temple. Sun rays fall on the Lingam on Ratha Saptami.', 'Location on a hillock in Nizamabad town.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Neelakanteshwara_swamy_temple_Nizamabad.jpg/960px-Neelakanteshwara_swamy_temple_Nizamabad.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Neelakanteshwara_swamy_temple_Nizamabad.jpg', 'January (Ratha Saptami)', '6:00 AM - 8:00 PM', 'Traditional', 'Climb required', '["Abhishekam"]', '["Ratha Saptami","Shivaratri"]', '{"history":"Satavahana era. Converted during Kakatiya rule.","architecture":"Nagara style shikhara.","darshan":"Blue-throated Shiva.","seasonal":"Good city view.","visitorNotes":"Easy access from Nizamabad center.","festivals":"Two-day annual fair.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-odela-odela-mallikarjuna-swamy-temple', 'shiva', 'Odela Mallikarjuna Swamy Temple', 'Telangana', 'Odela', 'Peddapalli', 'Mallikarjuna Swamy', 'Shaivism', '["Swayambhu Lingam","Village Deity","Plough Mark"]', 'The Lingam is said to have been discovered by a farmer while ploughing. A mark of the plough is visible on the Lingam.', 'Plough mark on the Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Lord_Shiva_Mallanna_Temple.jpg/960px-Lord_Shiva_Mallanna_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lord_Shiva_Mallanna_Temple.jpg', 'Year-round', '5:00 AM - 8:00 PM', 'Traditional', 'Rural approach road', '["Abhishekam","Oggu Katha"]', '["Pedda Patnam","Shivaratri"]', '{"history":"Ancient temple renovated by Kakatiyas.","architecture":"Simple village temple style.","darshan":"Swayambhu Lingam.","seasonal":"Crowded on Sundays.","visitorNotes":"Important pilgrim center in Peddapalli.","festivals":"Annual Jathara.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-palakurthy-someshwara-lakshmi-narasimha-swamy-temple', 'shiva', 'Someshwara Lakshmi Narasimha Swamy Temple', 'Telangana', 'Palakurthy', 'Jangaon', 'Someshwara (Shiva) & Narasimha (Vishnu)', 'Harihara (Shaivism & Vaishnavism)', '["Caves","Hara Hari Kshetram","Palkuriki Somanatha"]', 'A unique cave temple dedicated to both Shiva and Vishnu, situated on a hillock. This is the birthplace of the great poet Palkuriki Somanatha.', 'Natural cave shrines for both deities.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Lakshmi_Narasimha_temple_at_Nuggehalli.JPG/960px-Lakshmi_Narasimha_temple_at_Nuggehalli.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lakshmi_Narasimha_temple_at_Nuggehalli.JPG', 'Winter', '6:00 AM - 7:30 PM', 'Traditional', 'Hill climb', '["Pradakshina around the hill"]', '["Shivaratri","Narasimha Jayanti"]', '{"history":"12th Century Kakatiya era.","architecture":"Cave temple.","darshan":"Lingam and Narasimha idol in adjacent caves.","seasonal":"Good hill view.","visitorNotes":"Famous literary center.","festivals":"Grand Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-palampet-ramappa-temple-rudreshwara', 'shiva', 'Ramappa Temple (Rudreshwara)', 'Telangana', 'Palampet', 'Mulugu', 'Ramalingeswara Swamy', 'Shaivism', '["UNESCO World Heritage","Kakatiya Architecture","Floating Bricks"]', 'Known as the brightest star in the galaxy of temples, this 13th-century engineering marvel is famous for its floating bricks and intricate carvings.', 'UNESCO World Heritage Site with earthquake-resistant sandbox technology.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Ramappa_Temple_8.jpg/960px-Ramappa_Temple_8.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ramappa_Temple_8.jpg', 'October to March', '6:00 AM - 6:00 PM', 'Traditional/Decent', 'Free entry', '["Abhishekam","Archana"]', '["Maha Shivaratri","Kartheeka Masam"]', '{"history":"Built in 1213 CE by Recharla Rudra, a general of Kakatiya King Ganapati Deva. It is the only temple in India named after its sculptor, Ramappa.","architecture":"Kakatiya style on a 6ft high star-shaped platform. Features include the sandbox foundation technique and lightweight \'floating\' bricks.","darshan":"The main sanctum houses a Shivalinga. The Nandi facing the shrine is in an alert posture, ready to follow the Lord\'s command.","seasonal":"Pleasant in winter.","visitorNotes":"Located about 77km from Warangal. Guide services recommended to understand the carvings.","festivals":"Shivaratri is celebrated with great pomp.","sources":[{"name":"UNESCO","url":"https://whc.unesco.org/en/list/1570/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-panagal-chaya-someswara-swamy-temple', 'shiva', 'Chaya Someswara Swamy Temple', 'Telangana', 'Panagal', 'Nalgonda', 'Chaya Someswara Swamy', 'Shaivism', '["Architectural Wonder","Shadow Mystery","Kunduru Cholas"]', 'Famous for the mysterious shadow that falls on the Shiva Lingam throughout the day, caused by light diffraction.', 'Eternal shadow on the Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/11th_12th_century_Chaya_Someshwara_Temple%2C_Panagal_Telangana_India_-_18.jpg/960px-11th_12th_century_Chaya_Someshwara_Temple%2C_Panagal_Telangana_India_-_18.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:11th_12th_century_Chaya_Someshwara_Temple,_Panagal_Telangana_India_-_18.jpg', 'Morning for shadow viewing', '6:00 AM - 6:00 PM', 'Casual/Traditional', 'Free entry', '["Nitya Puja"]', '["Shivaratri"]', '{"history":"Built in the 11th-12th century by Kunduru Cholas.","architecture":"Trikutalayam style. The shadow phenomenon is a masterpiece of ancient physics.","darshan":"Witness the shadow formed by pillar reflections.","seasonal":"Good all year.","visitorNotes":"Located near the Pachala Someswara Temple.","festivals":"Shivaratri attracts huge crowds.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chaya_Someswara_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-panagal-chaya-someswara-temple', 'shiva', 'Chaya Someswara Temple', 'Telangana', 'Panagal', 'Nalgonda', 'Chaya Someswara (Shiva)', 'Shaivism', '["Shadow Miracle","Kakatiya Architecture","Trikutalayam"]', 'Famous for the eternal shadow that falls on the Shiva Lingam throughout the day, believed to be formed by the pillars\' placement. It is a Trikutalayam dedicated to Shiva.', 'Eternal shadow on the Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/11th_12th_century_Chaya_Someshwara_Temple%2C_Panagal_Telangana_India_-_18.jpg/960px-11th_12th_century_Chaya_Someshwara_Temple%2C_Panagal_Telangana_India_-_18.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:11th_12th_century_Chaya_Someshwara_Temple,_Panagal_Telangana_India_-_18.jpg', 'Winter', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', 'Traditional', 'Free Entry', '["Abhishekam","Nitya Pooja"]', '["Shivaratri"]', '{"history":"Built by Cholas/Kakatiyas in 11th-12th Century.","architecture":"Trikutalaya with complex pillar placement.","darshan":"Lingam in shadow.","seasonal":"Crowded on Mondays.","visitorNotes":"Shadow is a must-see.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Chaya_Someswara_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-panagal-pachala-someswara-swamy-temple', 'shiva', 'Pachala Someswara Swamy Temple', 'Telangana', 'Panagal', 'Nalgonda', 'Pachala Someswara Swamy', 'Shaivism', '["Green Onyx Lingam","Complex Carvings","Museum"]', 'Named \'Pachala\' (Emerald/Green) because the Lingam is made of green onyx stone.', 'Intricately carved pillars depicting Ramayana and Mahabharata.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/11th_12th_century_Pachala_Someshwara_Temple_reliefs_and_mandapams%2C_Panagal_Telangana_India_-_8.jpg/864px-11th_12th_century_Pachala_Someshwara_Temple_reliefs_and_mandapams%2C_Panagal_Telangana_India_-_8.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:11th_12th_century_Pachala_Someshwara_Temple_reliefs_and_mandapams,_Panagal_Telangana_India_-_8.jpg', 'Winter', '6:00 AM - 6:00 PM', 'Traditional', 'Next to Panagal Museum', '["Abhishekam"]', '["Maha Shivaratri"]', '{"history":"Built by Kakatiya rulers (Prataparudra I).","architecture":"Features 70 pillars with exquisite sculpture.","darshan":"Green stone Lingam.","seasonal":"Pleasant weather in winter.","visitorNotes":"Visit the archaeological museum nearby.","festivals":"Regular pujas performed.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pachala_Someswara_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-panagal-pachala-someswara-temple', 'shiva', 'Pachala Someswara Temple', 'Telangana', 'Panagal', 'Nalgonda', 'Pachala Someswara (Shiva)', 'Shaivism', '["Green Lingam","Intricate Carvings","Museum"]', 'Named after the emerald (Pacha) green stone Lingam. The temple features intricate carvings on pillars depicting scenes from Ramayana and Mahabharata.', 'Green Onyx Lingam and carved pillars.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/11th_12th_century_Pachala_Someshwara_Temple_reliefs_and_mandapams%2C_Panagal_Telangana_India_-_8.jpg/864px-11th_12th_century_Pachala_Someshwara_Temple_reliefs_and_mandapams%2C_Panagal_Telangana_India_-_8.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:11th_12th_century_Pachala_Someshwara_Temple_reliefs_and_mandapams,_Panagal_Telangana_India_-_8.jpg', 'Winter', '6:00 AM - 12:00 PM, 4:00 PM - 8:00 PM', 'Traditional', 'Free Entry', '["Abhishekam"]', '["Shivaratri"]', '{"history":"11th-12th Century, Kakatiya era.","architecture":"Richly carved pillars.","darshan":"Green stone Lingam.","seasonal":"Pleasant.","visitorNotes":"Visit the museum nearby.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pachala_Someswara_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-patancheru-beeramguda-mallikarjuna-swamy-temple', 'shiva', 'Beeramguda Mallikarjuna Swamy Temple', 'Telangana', 'Patancheru', 'Sangareddy', 'Mallikarjuna Swamy', 'Shaivism', '["Hill Top","Second Srisailam","Industrial Area"]', 'Situated on a small hillock in the industrial hub of Patancheru, this ancient temple attracts thousands of devotees during its annual Jathara.', 'Hilltop view and ancient architecture.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/TE_ME_Beeramguda.jpg/960px-TE_ME_Beeramguda.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:TE_ME_Beeramguda.jpg', 'Shivaratri Season', '6:00 AM - 8:00 PM', 'Traditional', 'Easy climb', '["Abhishekam","Bonam"]', '["Beeramguda Jathara","Shivaratri"]', '{"history":"Ancient temple renovated recently.","architecture":"Dravidian/Kakatiya mix.","darshan":"Lingam.","seasonal":"Very crowded during Jathara.","visitorNotes":"Near Hyderabad.","festivals":"State festival Jathara.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-pembatla-dubba-rajeshwara-swamy-temple', 'shiva', 'Dubba Rajeshwara Swamy Temple', 'Telangana', 'Pembatla', 'Jagtial', 'Dubba Rajeshwara Swamy', 'Shaivism', '["Ancient Shrine","Swayambhu","Village Deity"]', 'A renowned ancient temple where the Lingam is believed to be Swayambhu (self-manifested). It is a major pilgrim center in the Jagtial region.', 'Ancient Swayambhu Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/DubbaRajanna_Rathotsavam_Pembatla.jpg/960px-DubbaRajanna_Rathotsavam_Pembatla.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:DubbaRajanna_Rathotsavam_Pembatla.jpg', 'Winter', '5:00 AM - 8:00 PM', 'Traditional', 'Free entry', '["Abhishekam","Archana"]', '["Shivaratri"]', '{"history":"Ancient origins.","architecture":"Traditional South Indian.","darshan":"Swayambhu Lingam.","seasonal":"Festive during Shivaratri.","visitorNotes":"Accessible from Jagtial.","festivals":"Grand celebrations on Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-pillalamarri-erakeswara-temple', 'shiva', 'Erakeswara Temple', 'Telangana', 'Pillalamarri', 'Suryapet', 'Erakeswara Swamy', 'Shaivism', '["Recherla Reddy","Paintings","Intricate Carvings"]', 'Built by Erakasani, wife of a Recherla chief. The temple walls still bear traces of ancient fresco paintings.', 'Ancient frescoes and carvings.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Erakesvara_temple%2C_Pillalamarri%2C_Suryapet_district%2C_Telangana_03.jpg/960px-Erakesvara_temple%2C_Pillalamarri%2C_Suryapet_district%2C_Telangana_03.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Erakesvara_temple,_Pillalamarri,_Suryapet_district,_Telangana_03.jpg', 'Winter', '6:00 AM - 6:00 PM', 'Traditional', 'ASI protected monument', '["Nitya Puja"]', '["Shivaratri"]', '{"history":"Built in 1208 CE.","architecture":"Kakatiya style.","darshan":"Main Lingam.","seasonal":"Hot in summer.","visitorNotes":"Part of the Pillalamarri temple complex.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-pillalamarri-nameswara-temple', 'shiva', 'Nameswara Temple', 'Telangana', 'Pillalamarri', 'Suryapet', 'Nameswara Swamy', 'Shaivism', '["Double Temple","Kakatiya Feudatories","Heritage"]', 'Commissioned by Nami Reddy in 1202 CE. It stands parallel to the Trikuteshwara temple.', 'Historical inscriptions and architecture.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/1200_CE_Nameshwara_temple_Pillalamari%2C_Kakatiya_era%2C_Suryapet_Telangana_India_-_01.jpg/960px-1200_CE_Nameshwara_temple_Pillalamari%2C_Kakatiya_era%2C_Suryapet_Telangana_India_-_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:1200_CE_Nameshwara_temple_Pillalamari,_Kakatiya_era,_Suryapet_Telangana_India_-_01.jpg', 'Winter', '6:00 AM - 6:00 PM', 'Traditional', 'ASI protected', '["Puja"]', '["Shivaratri"]', '{"history":"1202 CE construction.","architecture":"Kakatiya style.","darshan":"Shiva Lingam.","seasonal":"Check before visiting as renovation works happen.","visitorNotes":"Visit all 3 temples in Pillalamarri.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-pillalamarri-pillalamarri-erakeswara-temple', 'shiva', 'Pillalamarri Erakeswara Temple', 'Telangana', 'Pillalamarri', 'Suryapet', 'Erakeswara (Shiva)', 'Shaivism', '["Recherla Reddys","Fresco Paintings","Kakatiya Art"]', 'Built by Erakasani of the Recherla Reddy family in 1208 CE. It is famous for its intricate carvings and remnants of ancient fresco paintings.', 'Carvings and paintings.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Erakesvara_temple%2C_Pillalamarri%2C_Suryapet_district%2C_Telangana_03.jpg/960px-Erakesvara_temple%2C_Pillalamarri%2C_Suryapet_district%2C_Telangana_03.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Erakesvara_temple,_Pillalamarri,_Suryapet_district,_Telangana_03.jpg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'ASI Site', '["Darshan"]', '["Shivaratri"]', '{"history":"1208 CE, by Recherla family.","architecture":"Kakatiya style.","darshan":"Lingam.","seasonal":"Visit in daylight.","visitorNotes":"Look for paintings.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pillalamarri"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-pillalamarri-pillalamarri-nameswara-temple', 'shiva', 'Pillalamarri Nameswara Temple', 'Telangana', 'Pillalamarri', 'Suryapet', 'Nameswara (Shiva)', 'Shaivism', '["Detailed Carvings","Nameswara","Kakatiya"]', 'Located close to Erakeswara temple, the Nameswara temple is another gem of the Kakatiya period, known for its polished pillars and detailed vimana.', 'Architectural symmetry.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/1200_CE_Nameshwara_temple_Pillalamari%2C_Kakatiya_era%2C_Suryapet_Telangana_India_-_01.jpg/960px-1200_CE_Nameshwara_temple_Pillalamari%2C_Kakatiya_era%2C_Suryapet_Telangana_India_-_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:1200_CE_Nameshwara_temple_Pillalamari,_Kakatiya_era,_Suryapet_Telangana_India_-_01.jpg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'ASI Site', '["Darshan"]', '["Shivaratri"]', '{"history":"12th-13th Century.","architecture":"Kakatiya.","darshan":"Lingam.","seasonal":"Pleasant.","visitorNotes":"Visit both temples.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-pillalamarri-trikuteshwara-temple', 'shiva', 'Trikuteshwara Temple', 'Telangana', 'Pillalamarri', 'Suryapet', 'Trikuteshwara Swamy', 'Shaivism', '["Three Shrines","Kakatiya Style","Heritage Site"]', 'A triple-shrine temple (Trikutalaya) located next to the Nameswara temple, showcasing the architectural prowess of the Recherla Reddys.', 'Trikuta architecture.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Trikuteshwara_temple%2C_Pillalamarri_10.jpg/960px-Trikuteshwara_temple%2C_Pillalamarri_10.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Trikuteshwara_temple,_Pillalamarri_10.jpg', 'Winter', '6:00 AM - 6:00 PM', 'Traditional', 'ASI Site', '["Harathi"]', '["Shivaratri"]', '{"history":"12th Century Kakatiya era.","architecture":"Trikutalayam.","darshan":"Three Lingams.","seasonal":"Best in cooler months.","visitorNotes":"Near Suryapet.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-pochera-pochera-shiva-temple', 'shiva', 'Pochera Shiva Temple', 'Telangana', 'Pochera', 'Adilabad', 'Shiva', 'Shaivism', '["Waterfall","Scenic","Nature"]', 'Located near the Pochera Waterfalls, this small shrine is set in a picturesque location, offering a spiritual retreat in nature.', 'Scenic beauty formed by Godavari tributaries.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Pochera_waterfall_2.jpg/960px-Pochera_waterfall_2.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pochera_waterfall_2.jpg', 'Monsoon/Winter', '9:00 AM - 5:00 PM', 'Casual', 'Near Boath', '["Simple Pooja"]', '["Shivaratri"]', '{"history":"Local shrine.","architecture":"Simple.","darshan":"Lingam.","seasonal":"Lush greenery.","visitorNotes":"Great picnic spot.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-polasa-polasa-paulasteeswara-temple', 'shiva', 'Polasa Paulasteeswara Temple', 'Telangana', 'Polasa', 'Jagtial', 'Paulasteeswara (Shiva)', 'Shaivism', '["Ancient Lingam","Pulse of Polasa","Historical"]', 'Dedicated to Lord Shiva as Paulasteeswara, believed to be installed by Ravana\'s grandfather Pulastya. It is an ancient site with deep mythological roots.', 'Mythological connection to Sage Pulastya.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Rom%C3%A2nia_liber%C4%83_1886-09-12%2C_nr._2728.pdf/page1-640px-Rom%C3%A2nia_liber%C4%83_1886-09-12%2C_nr._2728.pdf.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rom%C3%A2nia_liber%C4%83_1886-09-12,_nr._2728.pdf', 'All Year', '6:00 AM - 7:00 PM', 'Traditional', 'Free Entry', '["Abhishekam","Archana"]', '["Shivaratri"]', '{"history":"Ancient origins.","architecture":"Traditional.","darshan":"Lingam.","seasonal":"Shivaratri.","visitorNotes":"Near Jagtial.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Polasa"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-raikal-raikal-bhimanna-temple', 'shiva', 'Raikal Bhimanna Temple', 'Telangana', 'Raikal', 'Jagtial', 'Bhimanna (Shiva)', 'Shaivism/Folk', '["Bhimanna Jatara","Panchamukha Lingam","Local Deity"]', 'Famous for the Bhimanna Jatara, this temple houses a rare Panchamukha (Five-faced) Lingeshwara Swamy. It is a major pilgrim center in the district.', 'Panchamukha Lingam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Rameshwara_Temple%2C_Raikal%2C_Farooqnagar%2C_Mahbubnagar_District%2CTelangana_State_07.jpg/960px-Rameshwara_Temple%2C_Raikal%2C_Farooqnagar%2C_Mahbubnagar_District%2CTelangana_State_07.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rameshwara_Temple,_Raikal,_Farooqnagar,_Mahbubnagar_District,Telangana_State_07.jpg', 'Jan-Mar (Jatara)', '6:00 AM - 7:00 PM', 'Traditional', 'Crowded during Jatara', '["Bhimanna Jatara","Bonam"]', '["Bhimanna Jatara"]', '{"history":"11th Century Chalukya origins.","architecture":"Dravidian influence.","darshan":"Five-faced Lingam.","seasonal":"Jatara time is peak.","visitorNotes":"Rural setting.","festivals":"Jatara.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Raikal"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-sangareddy-kalabgoor-kasi-vishweshwara-temple', 'shiva', 'Kalabgoor Kasi Vishweshwara Temple', 'Telangana', 'Sangareddy', 'Sangareddy', 'Kasi Vishweshwara (Shiva)', 'Harihara (Shaivism & Vaishnavism)', '["Trikutalayam","HariHara","Kakatiya"]', 'A fine example of Kakatiya architecture, this Trikutalayam houses Kasi Vishweshwara (Shiva), Venugopala (Vishnu), and Ananthapadmanabha.', 'Trikuta temple with Shiva and Vishnu.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Historic_heritage_sites_of_Telangana_with_GPS_coordinates.jpg/960px-Historic_heritage_sites_of_Telangana_with_GPS_coordinates.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Historic_heritage_sites_of_Telangana_with_GPS_coordinates.jpg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Near Manjeera Barrage', '["Abhishekam","Archana"]', '["Shivaratri","Vaikunta Ekadasi"]', '{"history":"11th Century Kakatiya.","architecture":"Star-shaped pillars.","darshan":"Three sanctums.","seasonal":"Near river.","visitorNotes":"Architectural gem.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-somasila-lalitha-someswara-swamy-temple', 'shiva', 'Lalitha Someswara Swamy Temple', 'Telangana', 'Somasila', 'Nagarkurnool', 'Someswara Swamy', 'Shaivism', '["Translocated Temple","River Bank","Group of 15"]', 'Part of a group of 15 temples relocated from the Srisailam submergence zone. It is beautifully situated on the banks of the Krishna River.', 'Scenic river location and museum.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Somasila_Dam_-_September_2018_%282%29.jpg/960px-Somasila_Dam_-_September_2018_%282%29.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Somasila_Dam_-_September_2018_(2).jpg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'River bank', '["River bath","Darshan"]', '["Pushkaralu","Shivaratri"]', '{"history":"7th Century Chalukyan. Relocated in late 20th century.","architecture":"Chalukya/Kakatiya styles.","darshan":"Lingam.","seasonal":"River full after monsoon.","visitorNotes":"Boating to Srisailam available.","festivals":"Pushkarams every 12 years.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-somasila-loddi-mallikarjuna-swamy-temple', 'shiva', 'Loddi Mallikarjuna Swamy Temple', 'Telangana', 'Somasila', 'Nagarkurnool', 'Mallikarjuna Swamy', 'Shaivism', '["Forest","Cave","Nallamala"]', 'A secluded temple located in a valley (Loddi) within the Nallamala forests. It offers a spiritual retreat in nature.', 'Scenic location in the forest valley.', '/temples/temple-03.svg', 'Not Available', '/temples/temple-03.svg', 'Winter', 'Sunrise to Sunset', 'Casual/Trekking', 'Difficult access', '["Abhishekam"]', '["Maha Shivaratri"]', '{"history":"Ancient site used by sages.","architecture":"Cave/Rock shelter style.","darshan":"Shiva Lingam.","seasonal":"Avoid monsoon.","visitorNotes":"Requires short trek.","festivals":"Shivaratri.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-somasila-sangameshwara-temple', 'shiva', 'Sangameshwara Temple', 'Telangana', 'Somasila', 'Nagarkurnool', 'Sangameshwara (Shiva)', 'Shaivism', '["Submerged","Seven Rivers","Summer Visit"]', 'A unique temple that remains submerged in the Krishna river water for most of the year, surfacing only during the summer months. It is located at the confluence of seven rivers.', 'Submerged temple visible only in summer.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/7th_century_Sangameshwara_Temple%2C_Alampur%2C_Telangana_India_-_9.jpg/960px-7th_century_Sangameshwara_Temple%2C_Alampur%2C_Telangana_India_-_9.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:7th_century_Sangameshwara_Temple,_Alampur,_Telangana_India_-_9.jpg', 'April-June (When visible)', 'Sunrise to Sunset (When accessible)', 'Casual', 'Boat ride required usually', '["River worship"]', '["Shivaratri (if visible)"]', '{"history":"7th Century Chalukya.","architecture":"Nagara style.","darshan":"Lingam (seasonal).","seasonal":"Submerged in Monsoon/Winter.","visitorNotes":"Check water levels before going.","festivals":"Special pujas when resurfaced.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-velagatoor-koti-lingala-temple', 'shiva', 'Koti Lingala Temple', 'Telangana', 'Velagatoor', 'Jagtial', 'Koteswara (Shiva)', 'Shaivism', '["Satavahana","Godavari","Historical"]', 'An ancient site on the banks of the Godavari, believed to be the capital of the Satavahanas. It is famous for its shiva lingam and archaeological significance.', 'Satavahana history and river view.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Shivalingam_at_Kotilingala_Temple_at_Telugu_Museum.jpg/960px-Shivalingam_at_Kotilingala_Temple_at_Telugu_Museum.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shivalingam_at_Kotilingala_Temple_at_Telugu_Museum.jpg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'River bank location', '["River bath","Abhishekam"]', '["Shivaratri","Godavari Pushkaralu"]', '{"history":"Satavahana era capital.","architecture":"Ancient/Reconstructed.","darshan":"Lingam.","seasonal":"River full in monsoon.","visitorNotes":"Archaeological site nearby.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Koti_Lingala"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-velala-mallikarjuna-swamy-temple-velala', 'shiva', 'Mallikarjuna Swamy Temple (Velala)', 'Telangana', 'Velala', 'Mancherial', 'Mallikarjuna Swamy', 'Shaivism', '["Mallanna","River Godavari","Jathara"]', 'Located on the banks of Godavari, this temple is famous for the annual Jathara. The deity is worshipped as Mallanna.', 'Riverside location and Jathara.', '/temples/temple-05.svg', 'Not Available', '/temples/temple-05.svg', 'During Jathara', '6:00 AM - 7:00 PM', 'Traditional', 'Crowded during Jathara', '["Bonalu"]', '["Maha Shivaratri","Mallanna Jathara"]', '{"history":"Significant pilgrim center in the region.","architecture":"Folk style influence.","darshan":"Mallanna Swamy.","seasonal":"Feb-March for festival.","visitorNotes":"Near Chennur.","festivals":"Velala Jathara.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mallikarjuna_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-vemulawada-raja-rajeshwara-swamy-temple', 'shiva', 'Raja Rajeshwara Swamy Temple', 'Telangana', 'Vemulawada', 'Rajanna Sircilla', 'Raja Rajeshwara Swamy (Shiva)', 'Shaivism and Vaishnavism', '["Dakshina Kasi","Harihara Kshetram","Dharma Gundam"]', 'Known as \'Dakshina Kasi\', this temple is unique for its Dargah inside the complex, symbolizing religious harmony.', 'Devotees perform \'Kode Mokku\' (offering a bull) to the deity.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Sri_Raja_Rajeshwara_temple.jpg/680px-Sri_Raja_Rajeshwara_temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sri_Raja_Rajeshwara_temple.jpg', 'Year-round', '4:00 AM - 9:00 PM', 'Strict Traditional', 'Queue system for Dharma Gundam bath', '["Kode Mokku","Abhishekam","Anna Puja"]', '["Maha Shivaratri","Sri Rama Navami"]', '{"history":"Built by King Raja Narendra. It was the capital of the Vemulawada Chalukyas (750-973 CE).","architecture":"Chalukyan style. The temple tank is called Dharma Gundam.","darshan":"The Lingam is Neela Lohitha Shiva Lingam.","seasonal":"Crowded on Mondays.","visitorNotes":"Ritual bath in Dharma Gundam is considered sacred.","festivals":"Massive crowd during Shivaratri Jathara.","sources":[{"name":"Telangana Tourism","url":"https://tourism.telangana.gov.in/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-vilasagar-trilinga-sanghameshwara-swamy-temple', 'shiva', 'Trilinga Sanghameshwara Swamy Temple', 'Telangana', 'Vilasagar', 'Karimnagar', 'Trilinga Sanghameshwara (Shiva)', 'Shaivism/Vaishnavism', '["Three Lingams","Kakatiya Era","HariHara Kshetram"]', 'A unique Trikutalaya with three sanctums facing East, North, and South. It is also known as a HariHara Kshetram.', 'Three identical Shiva Lingams.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Winter', '6:00 AM - 7:00 PM', 'Traditional', 'Village temple', '["Abhishekam","Tri-Linga Archana"]', '["Shivaratri","Sri Rama Navami"]', '{"history":"Built by Kakatiya King Prola II (1115-1157 AD).","architecture":"Kakatiya Trikuta style with stepped pyramidal shikharas.","darshan":"Three Lingams.","seasonal":"Village festivals.","visitorNotes":"Near Vemulawada.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Trilinga_Sanghameshwara_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-wadapally-wadapally-agastheshwara-temple', 'shiva', 'Wadapally Agastheshwara Temple', 'Telangana', 'Wadapally', 'Nalgonda', 'Agastheshwara (Shiva)', 'Shaivism', '["Sangamam","Agastya","Water Miracle"]', 'Located at the confluence of Krishna and Musi rivers. The Lingam has a crevice that holds water, believed to be the Ganges installed by Sage Agastya.', 'Confluence point and miracle Lingam.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'Winter/Monsoon', '6:00 AM - 7:30 PM', 'Traditional', 'River bank location', '["Nadi Snanam (River Bath)","Abhishekam"]', '["Shivaratri","Pushkarams"]', '{"history":"Ancient, linked to Sage Agastya.","architecture":"Dravidian/Kakatiya.","darshan":"Lingam with water.","seasonal":"Pushkarams are huge.","visitorNotes":"Take a dip in the Sangamam.","festivals":"Shivaratri.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wadapally"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-telangana-warangal-swayambhu-shambunishwara-temple', 'shiva', 'Swayambhu Shambunishwara Temple', 'Telangana', 'Warangal', 'Warangal', 'Swayambhu Shambunishwara (Shiva)', 'Shaivism', '["Warangal Fort","Kakatiya Thoranam","Keerthi Toranam"]', 'Located in the heart of Warangal Fort, this temple\'s four massive gateways (Keerthi Toranams) are now the official emblem of Telangana.', 'The iconic Kakatiya Kala Thoranam.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Swayambhu_Ganapati_Temple_in_Ganpatipule_%282810750852%29.jpg/960px-Swayambhu_Ganapati_Temple_in_Ganpatipule_%282810750852%29.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Swayambhu_Ganapati_Temple_in_Ganpatipule_(2810750852).jpg', 'Winter', '9:00 AM - 6:00 PM (Fort timings)', 'Casual', 'Entry fee for Fort', '["None (Active ruins)"]', '["Kakatiya Festival"]', '{"history":"Built by Kakatiya Kings Ganapati Deva and Rudrama Devi (12th-13th Century). Destroyed by Tughlaq forces.","architecture":"Grand Kakatiya style. The gateways are masterpieces.","darshan":"Ruins of the Swayambhu Lingam temple.","seasonal":"Evening light show available.","visitorNotes":"Explore the open-air museum.","festivals":"Government cultural festivals.","sources":[{"name":"Wikipedia","url":"https://en.wikipedia.org/wiki/Warangal_Fort"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-tripura-abhaynagar-putiba-shiva-temple', 'shiva', 'Putiba Shiva Temple', 'Tripura', 'Abhaynagar', 'West Tripura', 'Shiva', 'Shaiva', '["Shaiva","Tripura","Temple"]', 'Putiba Shiva Temple is a Shiva-oriented shrine or sacred site associated with local worship traditions in Tripura.', 'Local Shaiva worship at Abhaynagar.', 'Not Available', 'Not Available', 'Not Available', 'October to March and Mahashivratri period.', 'Open daily; timings vary locally.', 'Modest traditional attire recommended.', 'Please verify local darshan timings and access rules before visiting.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Shravan month observances"]', '{"history":"Putiba Shiva Temple is included in the project Tripura Shiva temple dataset for continued field-level verification.","visitorNotes":"Some sites are heritage carvings or local shrines with limited formal infrastructure."}', '2026-02-19T21:10:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
