INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttar-pradesh-mahoba-fringe-nilkantha-mahadev-kalinjar-adjacent', 'shiva', 'Nilkantha Mahadev (Kalinjar-Adjacent)', 'Uttar Pradesh', 'Mahoba fringe', 'Mahoba district', 'Shiva (Nilkantha)', 'Shaiva', '["Nilkantha","Kalinjar Fringe","Cave Abhishek"]', 'A Kalinjar-adjacent Shaiva node associated with cave-based dripping-water abhishek tradition, serving as a warrior-frequency interface for the Mahoba-Bundelkhand belt.', 'Self-sustaining cave-abhishek Shiva node on the Mahoba-Kalinjar edge.', '/temples/temple-06.svg', 'Not Available', '/temples/temple-06.svg', 'October to March.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Kalinjar-side terrain can involve climbs and cave sections.', '["Jal abhishek","Cave darshan"]', '["Mahashivratri","Kalinjar festival window"]', '{"history":"Linked to the long-standing Nilkantha cave worship continuum of the Kalinjar frontier zone.","architecture":"Cave-linked shrine setting with natural drip-fed ritual flow.","visitorNotes":"Check route and fort-side timings before travel.","sources":[{"label":"Kalinjar Fort","url":"https://en.wikipedia.org/wiki/Kalinjar_Fort","type":"Encyclopedia"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Nilkantha%20Mahadev%20Kalinjar","type":"Map search"}]}', '2026-02-25T17:02:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
