INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttar-pradesh-mirzapur-shivpur-panchmukhi-mahadev', 'shiva', 'Shivpur (Panchmukhi Mahadev)', 'Uttar Pradesh', 'Mirzapur', 'Mirzapur district', 'Shiva', 'Shaiva', '["Panchmukhi","Shivpur","Five Aspects"]', 'A Panchmukhi Shiva node in the Mirzapur township belt, centered on a five-faced lingam associated with multi-aspect Shaiva worship.', 'Multi-band Shiva resonance through Panchmukhi lingam tradition.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'October to March; Shravan month is active.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Local naming may vary between Shivpur and Panchmukhi Mahadev references.', '["Jal abhishek","Panchamrit puja"]', '["Mahashivratri","Shravan Somvar"]', '{"history":"Part of Mirzapur\'s active urban-rural Shaiva devotional matrix.","architecture":"Five-faced lingam-focused sanctum with local ritual continuity.","visitorNotes":"Verify exact local route with residents before travel.","sources":[{"label":"Mirzapur district","url":"https://en.wikipedia.org/wiki/Mirzapur_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Panchmukhi%20Mahadev%20Shivpur%20Mirzapur","type":"Map search"}]}', '2026-02-25T18:22:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttar-pradesh-mirzapur-sidhnath-ki-dari', 'shiva', 'Sidhnath Ki Dari', 'Uttar Pradesh', 'Mirzapur', 'Mirzapur district', 'Shiva', 'Shaiva', '["Waterfall Node","Hydro-Acoustic","Rock Carvings"]', 'A waterfall-linked Shaiva nature-interface site where rock-carved lingam traditions are associated with a constant hydro-acoustic environment.', 'Raw hydro-acoustic Shiva node charged by perennial waterfall dynamics.', '/temples/temple-02.svg', 'Not Available', '/temples/temple-02.svg', 'Post-monsoon to winter; exercise caution during peak monsoon.', 'Daylight visit recommended.', 'Outdoor-friendly modest attire.', 'Terrain can be slippery near falls; local guidance is recommended.', '["Jal offerings","Meditative darshan"]', '["Mahashivratri","Shravan month"]', '{"history":"Maintained in local memory as a combined rock-water Shiva node in the Mirzapur belt.","architecture":"Natural rock-face setting with shrine markers integrated into waterfall terrain.","visitorNotes":"Plan for safe approach and footwear suitable for wet rock.","sources":[{"label":"Mirzapur district","url":"https://en.wikipedia.org/wiki/Mirzapur_district","type":"District reference"},{"label":"OpenStreetMap search","url":"https://www.openstreetmap.org/search?query=Sidhnath%20Ki%20Dari%20Mirzapur","type":"Map search"}]}', '2026-02-25T18:22:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
