INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttarakhand-gangolihat-patal-bhuvaneshwar-adjacent-transition', 'shiva', 'Patal Bhuvaneshwar (Adjacent Transition)', 'Uttarakhand', 'Gangolihat', 'Pithoragarh district', 'Shiva', 'Shaiva', '["Deep Earth Cave","Almora Gangolihat Route","Subterranean Core"]', 'A major limestone cave shrine on the Almora-Gangolihat transition belt, where naturally formed stalactite-stalagmite structures sustain a deep subterranean Shaiva current.', 'Subterranean transition node linked to the wider Almora pilgrimage logic.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Patal_Bhuvaneshwar_Cave.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Patal_Bhuvaneshwar_Cave.jpg', 'Year-round.', 'Open daily (Daylight).', 'Casual/Comfortable.', 'Steep and narrow cave descent; physical caution required.', '["Cave Darshan"]', '["Not Available"]', '{"history":"Preserved in long-running Himalayan cave-worship narratives with strong Shaiva framing.","architecture":"Natural karst cave architecture with ritualized passage movement.","visitorNotes":"Carry non-slip footwear and avoid peak crowd hours inside the cave passage.","sources":[{"label":"Patal Bhuvaneshwar","url":"https://en.wikipedia.org/wiki/Patal_Bhuvaneshwar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttarakhand-gangotri-gangotri-mahadev-shrines', 'shiva', 'Gangotri Mahadev Shrines', 'Uttarakhand', 'Gangotri', 'Uttarkashi district', 'Shiva', 'Shaiva', '["Glacial Interface","Gaumukh","Ice Stabilizer"]', 'Shiva shrines in the Gangotri-Gaumukh corridor function as glacial-interface nodes where source-ice and river-flow transitions are ritually stabilized through Shaiva worship.', 'High-purity glacier-to-river transition nodes in the Bhagirathi source belt.', 'Not Available', 'Not Available', 'Not Available', 'May to October.', 'Seasonal route access.', 'High-altitude trekking gear required.', 'Permit and route regulations apply for Gaumukh-side access within Gangotri National Park.', '["Personal prayer","Mantra japa"]', '["Shravan month observances"]', '{"history":"Connected to longstanding source-pilgrimage traditions around Gangotri and Gaumukh in the upper Bhagirathi valley.","architecture":"A distributed set of small shrines and pilgrimage markers rather than one large single complex.","visitorNotes":"Weather, altitude, and permit compliance should be planned carefully before travel.","sources":[{"label":"Gangotri","url":"https://en.wikipedia.org/wiki/Gangotri","type":"Location reference"},{"label":"Gaumukh","url":"https://en.wikipedia.org/wiki/Gaumukh","type":"Location reference"}]}', '2026-02-19T23:10:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
