INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttarakhand-garjiya-garjiya-devi-complex-shiva-node', 'shiva', 'Garjiya Devi Complex Shiva Node', 'Uttarakhand', 'Garjiya', 'Nainital district', 'Shiva (complex-integrated shrine)', 'Shaiva/Shakta', '["River Island","Shiva Shakti","Kosi"]', 'Within the Garjiya Devi pilgrimage complex, the Shiva shrine on the high Kosi rock functions as the grounding complement to the Shakti current, with continuous river acoustics shaping a kinetic prayer field.', 'Kosi river-island style Shiva grounding node in the Garjiya complex.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'October to March and post-monsoon.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Located on the Ramnagar-Kosi route; check river conditions in monsoon.', '["Daily puja","Jal abhishek"]', '["Mahashivratri","Navratri-linked observances"]', '{"history":"Maintained in the local Garjiya pilgrimage stream as a linked Shiva support node.","architecture":"River-bank/rock-based shrine integration within a larger temple complex.","visitorNotes":"Expect crowd spillover from Garjiya Devi festival days.","sources":[{"label":"Garjiya Devi Temple","url":"https://en.wikipedia.org/wiki/Garjiya_Devi_Temple","type":"Encyclopedia"}]}', '2026-02-25T20:45:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttarakhand-gopeshwar-gopeshwar-gopinath-temple', 'shiva', 'Gopeshwar (Gopinath Temple)', 'Uttarakhand', 'Gopeshwar', 'Gopeshwar, Chamoli district', 'Shiva (Gopinath)', 'Shaiva', '["Gopinath","Gopeshwar","Ancient Trishul"]', 'The Gopinath Temple at Gopeshwar is the key Chamoli urban Shiva anchor, known for its giant ancient trident traditionally described as a resilient, non-rusting sacred alloy marker.', 'Primary Chamoli valley motherboard with a monumental trishul-antennic identity.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gopinath_Temple,_Gopeshwar,_District_Chamoli.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gopinath_Temple,_Gopeshwar,_District_Chamoli.jpg', 'Year-round; October to April is generally comfortable.', 'Open daily.', 'Modest attire recommended.', 'Central Gopeshwar node; commonly paired with wider Chamoli circuit travel.', '["Daily puja","Abhishekam"]', '["Mahashivratri","Shravan month"]', '{"history":"Gopinath at Gopeshwar has long functioned as a historic district-level Shiva center in Chamoli\'s pilgrimage map.","architecture":"Ancient Himalayan stone shrine profile with iconic trident artifact presence.","visitorNotes":"Allocate time for both the shrine and trishul viewing in the temple precinct.","sources":[{"label":"Gopeshwar","url":"https://en.wikipedia.org/wiki/Gopeshwar","type":"Encyclopedia"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttarakhand-gopeshwar-rudranath-temple', 'shiva', 'Rudranath Temple', 'Uttarakhand', 'Gopeshwar', 'Rudranath area, Chamoli district', 'Shiva (Rudranath)', 'Shaiva', '["Panch Kedar","Rudranath","Face of Shiva"]', 'Rudranath is the Panch Kedar shrine of Shiva\'s mukha (face), set in high alpine terrain where deep forest and meadow routes create a strongly meditative pilgrimage field.', 'High-altitude natural-interface Panch Kedar node with deeply contemplative mountain resonance.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rudranath_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rudranath_Temple.jpg', 'June to September (weather window), with local variation by snowfall.', 'Seasonal opening; local timings vary.', 'Trekking gear and warm layers recommended.', 'Long mountain trek required; route and weather verification is essential.', '["Darshan","Pitru tarpan"]', '["Mahashivratri","Annual local mela"]', '{"history":"Rudranath is one of the Panch Kedar temples associated with Shiva\'s mukha manifestation.","architecture":"Stone temple form embedded in alpine landscape.","visitorNotes":"Plan acclimatization, local guide support, and shelter points in advance.","sources":[{"label":"Rudranath","url":"https://en.wikipedia.org/wiki/Rudranath","type":"Encyclopedia"}]}', '2026-02-23T12:53:30+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
