INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttarakhand-uttarkashi-someshwar-mahadev-uttarkashi-town', 'shiva', 'Someshwar Mahadev (Uttarkashi Town)', 'Uttarakhand', 'Uttarkashi', 'Uttarkashi district', 'Shiva (Someshwar)', 'Shaiva', '["Lunar Cooled","Urban Anchor","Bhagirathi Valley"]', 'A Someshwar Mahadev node in Uttarkashi town that provides a rhythmic stabilizing Shaiva baseline for day-to-day district worship.', 'Gentle urban stabilizer balancing the high-intensity upper mountain circuits.', '/temples/temple-04.svg', 'Not Available', '/temples/temple-04.svg', 'Year-round.', 'Open daily; local timings vary.', 'Modest temple attire recommended.', 'Within the Uttarkashi town pilgrimage circuit.', '["Daily puja","Aarti"]', '["Mahashivratri","Shravan month"]', '{"history":"Maintained as part of Uttarkashi\'s town-level Shaiva continuity alongside major Vishwanath worship.","architecture":"Regional town-temple style.","visitorNotes":"Usually visited as a complementary stop to Kashi Vishwanath (Uttarkashi).","sources":[{"label":"Uttarkashi","url":"https://en.wikipedia.org/wiki/Uttarkashi","type":"Encyclopedia"}]}', '2026-02-25T22:10:00+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-uttarakhand-yamunotri-yamunotri-shiva-markers', 'shiva', 'Yamunotri Shiva Markers', 'Uttarakhand', 'Yamunotri', 'Uttarkashi district', 'Shiva (source-corridor markers)', 'Shaiva', '["Western Sentinel","Thermal Kinetic","Source Zone"]', 'Shiva markers in the Yamunotri source corridor serve as sentinel nodes at the western edge of Uttarkashi, shaped by both glacial flow and nearby geothermal spring dynamics.', 'Warm-cold source-loop nodes interfacing river origin and thermal spring fields.', '/temples/temple-01.svg', 'Not Available', '/temples/temple-01.svg', 'May to October (seasonal access window).', 'Seasonal route access; local timings vary.', 'Trekking-suitable modest clothing.', 'Route conditions depend on weather and seasonal opening schedules.', '["Source prayers","Jal and thermal-kund offerings"]', '["Yamunotri opening season","Shravan observances"]', '{"history":"Part of broader Yamunotri source-pilgrimage practice with integrated Shaiva observances.","architecture":"Small route-side shrine-marker typology in a high-altitude environment.","visitorNotes":"Coordinate with official Yamunotri route advisories before travel.","sources":[{"label":"Yamunotri","url":"https://en.wikipedia.org/wiki/Yamunotri","type":"Encyclopedia"}]}', '2026-02-25T22:10:03+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shakti-uttarakhand-yamunotri-yamunotri-temple', 'shakti', 'Yamunotri Temple', 'Uttarakhand', 'Yamunotri', 'Uttarkashi district', 'Yamuna Devi', 'Vaishnava/Shakta', '["Char Dham","River","Glacier"]', 'The source of the holy Yamuna river; the temple is dedicated to Goddess Yamuna.', 'Char Dham source.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Yamunotri_Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Yamunotri_Temple.jpg', 'May to Oct.', 'Summer only.', 'Casual.', 'Trek from Janki Chatti.', '["Hot spring rice cooking"]', '["Akshaya Tritiya"]', '{"history":"19th Century rebuild.","architecture":"Hill style.","visitorNotes":"Divya Shila nearby.","sources":[{"label":"Uttarkashi","url":"https://en.wikipedia.org/wiki/Yamunotri","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-baidyapur-jora-shiva-temple-baidyapur', 'shiva', 'Jora Shiva Temple (Baidyapur)', 'West Bengal', 'Baidyapur', 'Purba Bardhaman', 'Shiva', 'Shaiva', '["Twin Temples","Brick","Deul"]', 'Two unique brick temples joined by a porch, resembling the Rekha Deul style but with distinct Bengali features.', 'The joined twin structure.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baidyapur%20Deul%2C%20Purba%20Bardhaman.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baidyapur_Deul,_Purba_Bardhaman.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Kalna.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in 1550 AD (very old).","architecture":"Rekha Deul (Brick).","darshan":"Heritage.","seasonal":"Good in winter.","visitorNotes":"Combine with Kalna trip.","festivals":"Shivratri.","sources":[{"label":"Baidyapur","url":"https://en.wikipedia.org/wiki/Baidyapur","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-bakreshwar-bakreshwar-temple', 'shiva', 'Bakreshwar Temple', 'West Bengal', 'Bakreshwar', 'Birbhum', 'Shakti', 'Shakta', '["Shakti Peetha","Hot Springs","Pilgrimage"]', 'A Shakti Peetha temple town in Birbhum known for its hot springs and Devi shrine.', 'Pilgrimage circuit that pairs temple darshan with hot springs.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bakreswar%20Temples%20and%20Hot%20spring%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bakreswar_Temples_and_Hot_spring_01.jpg', 'Winter mornings for the hot springs.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Hot spring areas can be crowded during peak pilgrimage season.', '["Daily puja"]', '["Navratri","Kali Puja"]', '{"history":"Bakreshwar is a Shakti Peetha in Birbhum and a major pilgrimage site with famed hot springs.","architecture":"Temple cluster set within the pilgrimage town and hot spring precinct.","darshan":"Darshan is available daily; pilgrimage peaks on festival days.","seasonal":"Winter is most comfortable for temple and spring visits.","visitorNotes":"Combine temple visits with the nearby hot springs.","festivals":"Navratri · Kali Puja","sources":[{"label":"Bakreswar Temple (Birbhum district)","url":"https://birbhum.gov.in/tourist-place/bakreshwar/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-bankura-ekteswar-shiva-temple', 'shiva', 'Ekteswar Shiva Temple', 'West Bengal', 'Bankura', 'Ekteswar, Bankura', 'Ekteswar (Shiva)', 'Folk/Shaiva', '["Folk Deity","Laterite","Pilgrimage"]', 'A unique temple dedicated to \'Ek-Paad\' (One-footed) Shiva, also known as Ekteswar. The deity is a natural rock considered a swayambhu linga.', 'The unique mythology of the one-footed Shiva form.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ekteshwar%20Temple%2C%20Bankura.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ekteshwar_Temple,_Bankura.jpg', 'Charak Puja (April).', 'Open daily.', 'Modest.', 'Located on the banks of Dwarakeswar river.', '["Charak Gajan"]', '["Gajan Festival","Charak Puja"]', '{"history":"Built by the Malla kings of Bishnupur.","architecture":"Robust laterite structure.","darshan":"Devotional.","seasonal":"Hot in summer.","visitorNotes":"Famous for the Gajan festival.","festivals":"Charak Puja.","sources":[{"label":"Ekteswar","url":"https://en.wikipedia.org/wiki/Ekteswar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-bansberia-hangseshwari-temple', 'shiva', 'Hangseshwari Temple', 'West Bengal', 'Bansberia', 'Hooghly', 'Hangseshwari', 'Shakta', '["Ratna Temple","Hooghly","Kali"]', 'A distinctive ratna-style temple in Bansberia dedicated to Goddess Hangseshwari.', 'Unique 13-ratna architecture in the Bansberia temple complex.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hangseswari%20Temple.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hangseswari_Temple.JPG', 'Kali Puja and winter months.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Part of a larger temple complex in Bansberia.', '["Daily puja","Evening aarti"]', '["Kali Puja","Navratri"]', '{"history":"Hangseshwari Temple is a ratna-style temple in Bansberia dedicated to Hangseshwari, a form of Kali.","architecture":"Known for its unique ratna architecture with multiple spires.","darshan":"Darshan is available throughout the day.","seasonal":"Kali Puja brings the largest crowds.","visitorNotes":"Combine with other shrines in the complex.","festivals":"Kali Puja · Navratri","sources":[{"label":"Hangseshwari Temple","url":"https://en.wikipedia.org/wiki/Hangseshwari_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-barakar-begunia-shiva-temples', 'shiva', 'Begunia Shiva Temples', 'West Bengal', 'Barakar', 'Paschim Bardhaman', 'Shiva (Siddheswara)', 'Shaiva', '["Ancient Stone","Deul","Archaeology"]', 'A group of ancient stone temples (No. 4 is the most famous) resembling the Odia Rekha Deul style, dating back to the 8th-9th century.', 'Ancient stone carvings and inscriptions found at the site.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Begunia%20temples%20at%20Begunia%2C%20Barakar%20in%20Paschim%20Bardhaman%20district%2005.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Begunia_temples_at_Begunia,_Barakar_in_Paschim_Bardhaman_district_05.jpg', 'Winter.', 'Open daily.', 'Casual.', 'ASI protected monument.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built by the Pala dynasty or local chieftains; inscriptions date to the 15th century renovation.","architecture":"Rekha Deul style (rare in Bengal).","darshan":"Historic.","seasonal":"Hot industrial area in summer.","visitorNotes":"Look for the Ganesha idol near the entrance.","festivals":"Shivratri.","sources":[{"label":"Barakar Temples","url":"https://en.wikipedia.org/wiki/Barakar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-baranagar-bhavaniswar-temple', 'shiva', 'Bhavaniswar Temple', 'West Bengal', 'Baranagar', 'Murshidabad district', 'Shiva', 'Shaiva', '["Inverted Lotus","Unique","Lime Stucco"]', 'Also built by Rani Bhabani, this temple is unique for its dome shaped like an inverted lotus, distinct from the usual Chala or Ratna styles.', 'The inverted lotus dome architecture.', 'https://commons.wikimedia.org/wiki/Special:FilePath/DSC%200382%20Bhabanishwar%20Temple%20Baranagar%20Murshidabad.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:DSC_0382_Bhabanishwar_Temple_Baranagar_Murshidabad.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near the Char Bangla group.', '["Daily puja"]', '["Shivratri"]', '{"history":"18th-century construction by Rani Bhabani.","architecture":"Octagonal with Lotus Dome.","darshan":"Historic.","seasonal":"Good in winter.","visitorNotes":"One of the tallest in the area.","festivals":"Shivratri.","sources":[{"label":"Baranagar","url":"https://en.wikipedia.org/wiki/Baranagar,_Murshidabad","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-baranagar-char-bangla-temples', 'shiva', 'Char Bangla Temples', 'West Bengal', 'Baranagar', 'Murshidabad district', 'Shiva', 'Shaiva', '["Terracotta","Masterpiece","Do-chala"]', 'A complex of four temples built in the distinct \'Do-chala\' (two-roofed) style by Rani Bhabani. They are considered the apex of terracotta art in Bengal.', 'The incredible detail of the terracotta panels on all four shrines.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Char%20Bangla%20Temples%20WLM2016-1040479.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Char_Bangla_Temples_WLM2016-1040479.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Managed by ASI.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in the 18th century by Rani Bhabani of Natore.","architecture":"Do-chala (Jor-bangla style).","darshan":"Artistic.","seasonal":"Pleasant in winter.","visitorNotes":"A must-visit for art lovers.","festivals":"Shivratri.","sources":[{"label":"Baranagar Temples","url":"https://en.wikipedia.org/wiki/Baranagar,_Murshidabad","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-baranagar-gangeswar-temple', 'shiva', 'Gangeswar Temple', 'West Bengal', 'Baranagar', 'Murshidabad district', 'Shiva', 'Shaiva', '["Jor-Bangla","Terracotta","Heritage"]', 'Another gem in the Baranagar complex, featuring the classic Jor-Bangla design and ornate terracotta decorations.', 'High-quality terracotta reliefs.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gangeswar%20Shiva%20Temple%20Baranagar.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gangeswar_Shiva_Temple_Baranagar.JPG', 'Winter.', 'Open daily.', 'Casual.', 'Part of the Rani Bhabani complex.', '["Daily puja"]', '["Shivratri"]', '{"history":"Part of the 18th-century temple building spree by Rani Bhabani.","architecture":"Jor-Bangla.","darshan":"Artistic.","seasonal":"Pleasant.","visitorNotes":"Walkable from Char Bangla.","festivals":"Shivratri.","sources":[{"label":"Baranagar","url":"https://en.wikipedia.org/wiki/Baranagar,_Murshidabad","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-baranagar-kripamayee-kali-temple-joy-mitra-kalibari', 'shiva', 'Kripamayee Kali Temple (Joy Mitra Kalibari)', 'West Bengal', 'Baranagar', 'North 24 Parganas', 'Kali (Kripamayee)', 'Shakta', '["Kripamayee Kali","Joy Mitra Kalibari","Hooghly River"]', 'A riverside Kali temple at Baranagar, also known as Joy Mitra Kalibari, dedicated to Kripamayee.', 'Navaratna-style temple on the Hooghly riverbank.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Joy%20Mitra%20Kripamoyee%20Kalibari%20-%20front%20view%20of%20the%20main%20temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Joy_Mitra_Kripamoyee_Kalibari_-_front_view_of_the_main_temple.jpg', 'Kali Puja and cooler months.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Located on the Hooghly riverbank in Baranagar.', '["Daily puja","Evening aarti"]', '["Kali Puja"]', '{"history":"Kripamayee Kali Temple, built in 1848 by Jai Narayan Mitra, is a notable Baranagar Kali shrine.","architecture":"Navaratna-style temple with associated Shiva shrines.","darshan":"Darshan is available daily with festival aartis.","seasonal":"Kali Puja is the peak season for devotees.","visitorNotes":"Plan a riverbank visit and expect crowds on puja nights.","festivals":"Kali Puja","sources":[{"label":"Kripamayee Kali Temple","url":"https://en.wikipedia.org/wiki/Kripamayee_Kali_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-bardhaman-108-shiva-temple-bardhaman', 'shiva', '108 Shiva Temple (Bardhaman)', 'West Bengal', 'Bardhaman', 'Purba Bardhaman', 'Shiva', 'Shaiva', '["Shiva","Temple Cluster","Heritage"]', 'A temple complex of 108 Shiva shrines in the Bardhaman region.', 'At-chala style shrines arranged in a large courtyard.', 'https://commons.wikimedia.org/wiki/Special:FilePath/108_Shiva_Temple_complex,_Bardhaman_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:108_Shiva_Temple_complex,_Bardhaman_01.jpg', 'Morning visits for calmer darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage complex; respect site guidelines.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"The 108 Shiva Temple complex is documented in Bardhaman and known for its shrine cluster.","puranicView":"The 108 shrine layout reflects longstanding Shaiva devotional practice.","puranicSources":[{"label":"108 Shiva Temple, Bardhaman (Media)","url":"https://commons.wikimedia.org/wiki/Category:108_Shiva_Temple,_Bardhaman","type":"Media archive"}],"folklore":"Devotees visit multiple shrines during a single circuit.","folkloreSources":[{"label":"108 Shiva Temple, Bardhaman (Media)","url":"https://commons.wikimedia.org/wiki/Category:108_Shiva_Temple,_Bardhaman","type":"Media archive"}],"sources":[{"label":"108 Shiva Temple, Bardhaman (Media)","url":"https://commons.wikimedia.org/wiki/Category:108_Shiva_Temple,_Bardhaman"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-bardhaman-sarbamangala-temple', 'shiva', 'Sarbamangala Temple', 'West Bengal', 'Bardhaman', 'Purba Bardhaman', 'Sarbamangala', 'Shakta', '["Nabaratna","Folk Goddess","Burdwan"]', 'A major Devi shrine in Bardhaman dedicated to the folk goddess Sarvamangala.', 'One of the earliest Nabaratna temples in undivided Bengal.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sarbamangala%20Temple%20in%20Burdwan1.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sarbamangala_Temple_in_Burdwan1.jpg', 'Sharad Puja season and winter months.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple complex sits within Bardhaman town.', '["Daily puja","Evening aarti"]', '["Sharad Utsav","Navratri"]', '{"history":"The Sarbamangala Temple in Bardhaman was built in 1702 by Maharaja Kirtichand and is considered the first Nabaratna temple in undivided Bengal.","architecture":"A Nabaratna (nine-spired) temple with terracotta details.","darshan":"Darshan is open daily; festival processions are significant.","seasonal":"Sharad Puja draws major crowds in Bardhaman.","visitorNotes":"Expect festival processions during Sharad Utsav.","festivals":"Sharad Utsav · Navratri","sources":[{"label":"Sarvamangala temple","url":"https://en.wikipedia.org/wiki/Sarvamangala_temple"},{"label":"Sarbamangala Mandir (Purba Bardhaman)","url":"https://purbabardhaman.nic.in/tourist-place/sarbamangala-mondir/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-bhatpara-ratneswar-temple', 'shiva', 'Ratneswar Temple', 'West Bengal', 'Bhatpara', 'North 24 Parganas', 'Shiva', 'Shaiva', '["Bhatpara","Pancha-ratna","Culture"]', 'A prominent Pancha-ratna temple in Bhatpara, a town historically known for its Sanskrit scholars.', 'The five-pinnacle architecture.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Panch%20Mandir%20premises%20at%20Bhatpara%20near%20Naihati%20in%20North%2024%20Parganas%20district%2C%20West%20Bengal%2006.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Panch_Mandir_premises_at_Bhatpara_near_Naihati_in_North_24_Parganas_district,_West_Bengal_06.jpg', 'Winter.', 'Open daily.', 'Modest.', 'Near the river.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in the 17th/18th century.","architecture":"Pancha-ratna.","darshan":"Traditional.","seasonal":"Humid.","visitorNotes":"Explore the pandit culture of Bhatpara.","festivals":"Shivratri.","sources":[{"label":"Bhatpara","url":"https://en.wikipedia.org/wiki/Bhatpara","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-bishnupur-malleswar-temple', 'shiva', 'Malleswar Temple', 'West Bengal', 'Bishnupur', 'Bankura district', 'Shiva (Malleswar)', 'Shaiva', '["Terracotta","Malla Kings","Heritage"]', 'The oldest temple in Bishnupur, built by King Raghunath Singha in 1622. It stands as a testament to the early Malla architecture.', 'The earliest example of laterite stone and terracotta combination in Bishnupur.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Temples%20in%20Bishnupur%20town%20in%20Bankura%2012.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Temples_in_Bishnupur_town_in_Bankura_12.jpg', 'Winter (Dec-Feb) for the Bishnupur Mela.', 'Sunrise to Sunset.', 'Casual.', 'ASI protected monument; ticket required for the temple group.', '["Daily puja"]', '["Shivratri","Bishnupur Mela"]', '{"history":"Built in 1622 AD by Malla King Raghunath Singha.","architecture":"Deul style built of laterite stone.","darshan":"Historic.","seasonal":"Best in winter.","visitorNotes":"Near the Rashmancha.","festivals":"Shivratri.","sources":[{"label":"Bishnupur Heritage","url":"https://en.wikipedia.org/wiki/Bishnupur,_Bankura","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-budhpur-budhpur-siva-temple', 'shiva', 'Budhpur Siva Temple', 'West Bengal', 'Budhpur', 'Purulia District', 'Shiva', 'Shaiva', '["Shiva","Heritage","Purulia"]', 'A historic Shiva temple site in Budhpur with stone relics.', 'Rural temple setting and carved stonework.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Budhpur_Siva_temple_of_Purulia_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Budhpur_Siva_temple_of_Purulia_01.jpg', 'Morning visits for quieter darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Remote site; check local access conditions.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"Budhpur Siva Temple in Purulia is documented in regional photo archives.","puranicView":"The shrine follows Shaiva worship traditions of the district.","puranicSources":[{"label":"Budhpur Siva Temple (Media)","url":"https://commons.wikimedia.org/wiki/Category:Budhpur_Siva_temple","type":"Media archive"}],"folklore":"Local devotees visit for seasonal worship and darshan.","folkloreSources":[{"label":"Budhpur Siva Temple (Media)","url":"https://commons.wikimedia.org/wiki/Category:Budhpur_Siva_temple","type":"Media archive"}],"sources":[{"label":"Budhpur Siva Temple (Media)","url":"https://commons.wikimedia.org/wiki/Category:Budhpur_Siva_temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-chandrakona-malleshwar-temple-chandrakona', 'shiva', 'Malleshwar Temple (Chandrakona)', 'West Bengal', 'Chandrakona', 'Paschim Medinipur', 'Shiva', 'Shaiva', '["Tallest","Laterite","Heritage"]', 'A towering 60-foot laterite temple built by King Malla Raj in the 17th century. It is a massive Rekha Deul.', 'The massive height and laterite stone construction.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Malleshwar%20Shiva%20Temple%20at%20Malleswarpur%20area%20of%20Chandrakona%20at%20Paschim%20Medinipur%20district%2005.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Malleshwar_Shiva_Temple_at_Malleswarpur_area_of_Chandrakona_at_Paschim_Medinipur_district_05.jpg', 'Winter.', 'Open daily.', 'Casual.', 'In Chandrakona town.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in 1655 AD.","architecture":"Rekha Deul (Laterite).","darshan":"Historic.","seasonal":"Good in winter.","visitorNotes":"Chandrakona has many other temples.","festivals":"Shivratri.","sources":[{"label":"Chandrakona","url":"https://en.wikipedia.org/wiki/Chandrakona","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-cooch-behar-anathnath-shiva-temple', 'shiva', 'Anathnath Shiva Temple', 'West Bengal', 'Cooch Behar', 'Cooch Behar District', 'Shiva', 'Shaiva', '["Shiva","Heritage","Cooch Behar"]', 'A Shiva temple in Cooch Behar documented in local photo archives.', 'Compact shrine with steady local worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Anathnath_Shiva_Temple,_Cooch_Behar,_WB,_In_4_(3).JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Anathnath_Shiva_Temple,_Cooch_Behar,_WB,_In_4_(3).JPG', 'Morning visits for quieter darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Respect local customs during worship.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"The temple is documented in Wikimedia Commons archives for Cooch Behar.","puranicView":"Local Shaiva worship continues through daily offerings.","puranicSources":[{"label":"Anathnath Shiva Temple (Media)","url":"https://commons.wikimedia.org/wiki/File:Anathnath_Shiva_Temple,_Cooch_Behar,_WB,_In_4_(3).JPG","type":"Media archive"}],"folklore":"Local devotees visit for daily puja and festival days.","folkloreSources":[{"label":"Anathnath Shiva Temple (Media)","url":"https://commons.wikimedia.org/wiki/File:Anathnath_Shiva_Temple,_Cooch_Behar,_WB,_In_4_(3).JPG","type":"Media archive"}],"sources":[{"label":"Anathnath Shiva Temple (Media)","url":"https://commons.wikimedia.org/wiki/File:Anathnath_Shiva_Temple,_Cooch_Behar,_WB,_In_4_(3).JPG"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-cooch-behar-baneshwar-shiva-temple', 'shiva', 'Baneshwar Shiva Temple', 'West Bengal', 'Cooch Behar', 'Baneshwar', 'Shiva', 'Shaiva', '["Tortoise","Royal","Pond"]', 'Famous for its \'Mohan\' tortoises that live in the temple pond. It was built by the Cooch Behar Maharajas.', 'The ancient tortoises in the Shiv Pukur (pond).', 'https://commons.wikimedia.org/wiki/Special:FilePath/Baneshwar%20Shiva%20Temple%20at%20Cooch%20Behar%20District%20in%20West%20Bengal%2012.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baneshwar_Shiva_Temple_at_Cooch_Behar_District_in_West_Bengal_12.jpg', 'Winter.', 'Open daily.', 'Casual.', '10km from Cooch Behar town.', '["Tortoise feeding"]', '["Shiv Chaturdashi"]', '{"history":"Built by Maharaja Pran Narayan.","architecture":"Chala style with a dome.","darshan":"Unique.","seasonal":"Good all year.","visitorNotes":"Do not harm the tortoises.","festivals":"Shivratri.","sources":[{"label":"Baneshwar","url":"https://en.wikipedia.org/wiki/Baneshwar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-cooch-behar-hiranyagarbha-shiva-temple', 'shiva', 'Hiranyagarbha Shiva Temple', 'West Bengal', 'Cooch Behar', 'Cooch Behar District', 'Shiva', 'Shaiva', '["Shiva","Heritage","Cooch Behar"]', 'A Shiva shrine near Sagar Dighi in Cooch Behar.', 'Temple by the tank with a calm atmosphere.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hiranyagarbha_Shiva_Temple_(3116566105).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hiranyagarbha_Shiva_Temple_(3116566105).jpg', 'Morning visits for calmer darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Respect local customs during worship.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"The temple is documented in Wikimedia Commons archives near Sagar Dighi in Cooch Behar.","puranicView":"Local Shaiva worship continues through daily offerings.","puranicSources":[{"label":"Hiranyagarbha Shiva Temple (Media)","url":"https://commons.wikimedia.org/wiki/File:Hiranyagarbha_Shiva_Temple_(3116566105).jpg","type":"Media archive"}],"folklore":"Devotees visit the shrine alongside nearby heritage sites.","folkloreSources":[{"label":"Hiranyagarbha Shiva Temple (Media)","url":"https://commons.wikimedia.org/wiki/File:Hiranyagarbha_Shiva_Temple_(3116566105).jpg","type":"Media archive"}],"sources":[{"label":"Hiranyagarbha Shiva Temple (Media)","url":"https://commons.wikimedia.org/wiki/File:Hiranyagarbha_Shiva_Temple_(3116566105).jpg"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-darjeeling-mahakal-temple-darjeeling', 'shiva', 'Mahakal Temple (Darjeeling)', 'West Bengal', 'Darjeeling', 'Observatory Hill', 'Shiva', 'Shaiva', '["Shiva","Hilltop","Heritage"]', 'A hilltop Shiva shrine in Darjeeling known for its shared sacred space.', 'Prayer flags and hilltop darshan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mahakal_Temple,_Darjeeling_02.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahakal_Temple,_Darjeeling_02.jpg', 'Early morning for a calm visit.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"Mahakal Temple stands at Observatory Hill and is one of the best known shrines in Darjeeling.","puranicView":"The temple honors Shiva as Mahakal within a shared sacred landscape.","puranicSources":[{"label":"Mahakal Temple","url":"https://en.wikipedia.org/wiki/Mahakal_Temple_(Darjeeling)","type":"Encyclopedia"},{"label":"Mahakal Temple (Darjeeling Tourism)","url":"https://darjeeling.gov.in/tourist-place/mahakal-temple/","type":"Government tourism"}],"folklore":"Local tradition highlights shared worship practices on the hilltop.","folkloreSources":[{"label":"Mahakal Temple","url":"https://en.wikipedia.org/wiki/Mahakal_Temple_(Darjeeling)","type":"Encyclopedia"}],"sources":[{"label":"Mahakal Temple","url":"https://en.wikipedia.org/wiki/Mahakal_Temple_(Darjeeling)"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-deulghata-deulghata-temples', 'shiva', 'Deulghata Temples', 'West Bengal', 'Deulghata', 'Purulia district', 'Shiva', 'Shaiva/Jain history', '["Ancient Ruins","Jain/Hindu","River Kansabati"]', 'Ancient brick temples located on the bank of the Kansabati river. Once a Jain center, now a site for Shiva worship.', 'Tall brick deuls with intricate stucco work.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Group%20of%20Deuls%2C%20ancient%20architectural%20style%20temples%20at%20Deulghata%2C%20Purulia%20district%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Group_of_Deuls,_ancient_architectural_style_temples_at_Deulghata,_Purulia_district_01.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Jaipur, Purulia.', '["Daily puja"]', '["Tusu Parab"]', '{"history":"11th-12th century construction; immense archaeological value.","architecture":"Rekha Deul (Brick).","darshan":"Historic.","seasonal":"Winter is best.","visitorNotes":"Visit during Tusu festival for local culture.","festivals":"Shivratri.","sources":[{"label":"Deulghata","url":"https://en.wikipedia.org/wiki/Deulghata","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-dihar-salleswar-temple', 'shiva', 'Salleswar Temple', 'West Bengal', 'Dihar', 'Bankura district', 'Shiva', 'Shaiva', '["Laterite","Oldest","Architecture"]', 'One of the oldest laterite stone temples in Bankura, dating back to the 14th century, pre-dating the Bishnupur style.', 'Ancient Rekha Deul structure.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Saileswar%20and%20Sareswar%20temple%20of%20Dihar%20in%20Bankura%20district%20(02).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Saileswar_and_Sareswar_temple_of_Dihar_in_Bankura_district_(02).jpg', 'Winter.', 'Open daily.', 'Casual.', 'Archaeological site.', '["Daily puja"]', '["Gajan"]', '{"history":"Built by King Prithvimalla in 1346 AD.","architecture":"Rekha Deul (Laterite).","darshan":"Historic.","seasonal":"Hot summer.","visitorNotes":"See the Nandi bull outside.","festivals":"Gajan.","sources":[{"label":"Dihar","url":"https://en.wikipedia.org/wiki/Dihar","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-diknagar-raghabeswar-temple', 'shiva', 'Raghabeswar Temple', 'West Bengal', 'Diknagar', 'Nadia district', 'Shiva', 'Shaiva', '["Terracotta","King Raghab","Art"]', 'Built in 1669 by King Raghab of Nadia, this temple is famous for having some of the most intricate terracotta work in the district.', 'Early period terracotta art.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Charchala%20Raghabeswar%20temple%20at%20Diknagar%20in%20Nadia%20district%2005.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Charchala_Raghabeswar_temple_at_Diknagar_in_Nadia_district_05.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Krishnanagar.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in 1669 AD.","architecture":"Char-chala.","darshan":"Historic.","seasonal":"Pleasant.","visitorNotes":"A key heritage site in Nadia.","festivals":"Shivratri.","sources":[{"label":"Raghabeswar Temple","url":"https://en.wikipedia.org/wiki/Raghabeswar_Temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-dubrajpur-jora-shiva-temple-dubrajpur', 'shiva', 'Jora Shiva Temple (Dubrajpur)', 'West Bengal', 'Dubrajpur', 'Birbhum district', 'Shiva', 'Shaiva', '["Mama Bhagne","Rock Formation","Terracotta"]', 'Located near the famous Mama Bhagne rock formations, these twin temples add a spiritual dimension to the geological wonder.', 'Proximity to Mama Bhagne rocks.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mama%20Bhagne%20Hills%20and%20Temple%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mama_Bhagne_Hills_and_Temple_01.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Combine with rock climbing/viewing.', '["Daily puja"]', '["Shivratri"]', '{"history":"19th-century construction.","architecture":"Bengal style.","darshan":"Casual.","seasonal":"Hot rocks in summer.","visitorNotes":"Unique landscape.","festivals":"Shivratri.","sources":[{"label":"Dubrajpur","url":"https://en.wikipedia.org/wiki/Dubrajpur","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-fullara-fullara-temple-attahas', 'shiva', 'Fullara Temple (Attahas)', 'West Bengal', 'Fullara', 'Birbhum', 'Devi', 'Shakta', '["Shakti Peetha","Attahas","Pilgrimage"]', 'A Shakti Peetha at Fullara where a sacred stone is worshiped as Devi.', 'Temple-town setting near Labhpur in Birbhum.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fullara%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fullara_Temple.jpg', 'Magh Purnima fair season.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'The sanctum holds a sacred stone rather than a deity image.', '["Daily puja"]', '["Magh Purnima","Navratri"]', '{"history":"Fullara is a temple-town in Birbhum and one of the 51 Shakti Peethas.","architecture":"Compact shrine with a simple temple complex.","darshan":"Darshan is available daily with local ritual cycles.","seasonal":"Magh Purnima hosts a major fair.","visitorNotes":"Expect heavier crowds during festival fairs.","festivals":"Magh Purnima · Navratri","sources":[{"label":"Fullara","url":"https://en.wikipedia.org/wiki/Fullara"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-gaganeshwar-kurumbera-fort-shiva-temple', 'shiva', 'Kurumbera Fort Shiva Temple', 'West Bengal', 'Gaganeshwar', 'Paschim Medinipur', 'Shiva', 'Shaiva', '["Fort","Odisha Style","Heritage"]', 'A unique Shiva temple located inside the medieval Kurumbera Fort. The architecture shows a distinct blend of Odisha and Bengal styles.', 'The grand courtyard of the fort surrounding the temple.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kurumbera%20Fort%203.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kurumbera_Fort_3.jpg', 'Winter.', 'Sunrise to Sunset.', 'Casual.', 'ASI protected monument.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built during the rule of Kapilendra Deva (Odisha) in the 15th century.","architecture":"Bhadra Deul style.","darshan":"Historic.","seasonal":"Pleasant in winter.","visitorNotes":"Photographers delight.","festivals":"Shivratri.","sources":[{"label":"Kurumbera Fort","url":"https://en.wikipedia.org/wiki/Kurumbera_Fort","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-garh-panchakot-garh-panchakot-temple-ruins', 'shiva', 'Garh Panchakot Temple Ruins', 'West Bengal', 'Garh Panchakot', 'Purulia district', 'Shiva (Ruins)', 'Shaiva', '["Ruins","Panchet Hill","Fort"]', 'Ruined temples located at the foothills of Panchet Hill, remnants of the Singh Deo dynasty\'s fort complex.', 'The atmospheric ruins against the backdrop of Panchet Hill.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pancharatna%20Temple%2C%20Garh%20Panchakot.JPG', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pancharatna_Temple,_Garh_Panchakot.JPG', 'Monsoon (lush green) or Winter.', 'Open daily.', 'Casual.', 'Nature and history walk.', '["None (Ruins)"]', '["None"]', '{"history":"Destroyed by the Bargi (Maratha) invasion in the 18th century.","architecture":"Pancha-ratna (Ruins).","darshan":"Scenic.","seasonal":"Green hills in monsoon.","visitorNotes":"Great for hiking.","festivals":"None.","sources":[{"label":"Garh Panchakot","url":"https://en.wikipedia.org/wiki/Garh_Panchakot","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-ghurisha-ghurisha-shiva-temple', 'shiva', 'Ghurisha Shiva Temple', 'West Bengal', 'Ghurisha', 'Birbhum district', 'Shiva', 'Shaiva', '["Terracotta","Raghunath","Art"]', 'A stunning example of Char-chala architecture known as the Raghunath Shiva Temple, famous for its exquisite terracotta facade.', 'High-quality terracotta preservation.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Charchala%20temple%20of%20Raghunathjee%20at%20Ghurisha%20village%20in%20Birbhum%20district.%2013.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Charchala_temple_of_Raghunathjee_at_Ghurisha_village_in_Birbhum_district._13.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Ilambazar.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in 1633 AD (very old terracotta).","architecture":"Char-chala.","darshan":"Artistic.","seasonal":"Pleasant in winter.","visitorNotes":"Look for the Ramayana panels.","festivals":"Shivratri.","sources":[{"label":"Birbhum Temples","url":"https://en.wikipedia.org/wiki/Birbhum_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-gobardanga-pancha-ratna-shiva-temple-gobardanga', 'shiva', 'Pancha Ratna Shiva Temple (Gobardanga)', 'West Bengal', 'Gobardanga', 'North 24 Parganas', 'Shiva', 'Shaiva', '["Zamindar","Heritage","River Jamuna"]', 'Built by the local Zamindars, this temple stands on the bank of the Jamuna river (a local tributary).', 'Zamindar heritage.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Twin%20Panchartana%20Temple%20in%20Jamdani%20area%20of%20Gobardanga%20in%20North%2024%20Parganas%20district%2C%20West%20Bengal%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Twin_Panchartana_Temple_in_Jamdani_area_of_Gobardanga_in_North_24_Parganas_district,_West_Bengal_01.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near the river.', '["Daily puja"]', '["Shivratri"]', '{"history":"19th-century construction.","architecture":"Pancha-ratna.","darshan":"Local.","seasonal":"Pleasant.","visitorNotes":"Visit the Gobardanga Zamindar Bari.","festivals":"Shivratri.","sources":[{"label":"Gobardanga","url":"https://en.wikipedia.org/wiki/Gobardanga","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-gonpur-gonpur-shiva-temple', 'shiva', 'Gonpur Shiva Temple', 'West Bengal', 'Gonpur', 'Birbhum district', 'Shiva', 'Shaiva', '["Tallest","Terracotta","Forest"]', 'Located in a forest clearing, this is one of the tallest temples in Birbhum, towering over the surroundings with fine terracotta work.', 'The impressive height and forest setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ganpur%20temples%20(Birbhum)%20-%20Rameswar%20Shiva%20temple%20complex.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ganpur_temples_(Birbhum)_-_Rameswar_Shiva_temple_complex.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Md. Bazar.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in the 18th century.","architecture":"Rekha Deul (with ridges).","darshan":"Scenic.","seasonal":"Winter is best.","visitorNotes":"Very photogenic.","festivals":"Shivratri.","sources":[{"label":"Birbhum Temples","url":"https://en.wikipedia.org/wiki/Birbhum_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-gourangapur-ichai-ghosh-deul', 'shiva', 'Ichai Ghosh Deul', 'West Bengal', 'Gourangapur', 'Paschim Bardhaman', 'Shiva (Historical)', 'Shaiva', '["Towering","Brick","History"]', 'A massive, towering brick temple located deep in the forest near the Ajay river. Legend links it to Ichai Ghosh, a local chieftain.', 'The sheer height and isolation of the structure.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Temple%20of%20Ichai%20Ghosh.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Temple_of_Ichai_Ghosh.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Remote location; strictly day visit.', '["Occasional puja"]', '["None"]', '{"history":"Dates to the 16th-17th century; linked to the Dharma Mangal poems.","architecture":"Rekha Deul (Brick).","darshan":"Adventure.","seasonal":"Accessible in winter.","visitorNotes":"No shops nearby.","festivals":"None.","sources":[{"label":"Ichai Ghosh Deul","url":"https://en.wikipedia.org/wiki/Ichai_Ghosh","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-hetampur-chandranath-shiva-temple', 'shiva', 'Chandranath Shiva Temple', 'West Bengal', 'Hetampur', 'Birbhum district', 'Shiva', 'Shaiva', '["Terracotta","Octagonal","Royal"]', 'A rare octagonal terracotta temple built by the Royal family of Hetampur. It is known for its European-influenced terracotta motifs.', 'Octagonal shape and colonial-style terracotta figures.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hetampur%20Chandranath%20Shib%20Temple%20Front%20Side%20Right%20Panel07%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hetampur_Chandranath_Shib_Temple_Front_Side_Right_Panel07_01.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Dubrajpur.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in 1847 by Govinda Sundari.","architecture":"Navaratna (Nine pinnacles) on Octagonal base.","darshan":"Artistic.","seasonal":"Pleasant in winter.","visitorNotes":"Look for Queen Victoria on terracotta panels!","festivals":"Shivratri.","sources":[{"label":"Hetampur","url":"https://en.wikipedia.org/wiki/Hetampur","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-ilambazar-bhairabnath-temple-ilambazar', 'shiva', 'Bhairabnath Temple (Ilambazar)', 'West Bengal', 'Ilambazar', 'Birbhum District', 'Shiva', 'Shaiva', '["Shiva","Village Temple","Birbhum"]', 'A local Shiva shrine in the Ilambazar area with village worship traditions.', 'Compact temple structure and steady local darshan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhairabnath_Temple,_Ilambazar_3.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bhairabnath_Temple,_Ilambazar_3.jpg', 'Morning visits for calm darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Respect local customs during worship.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"Bhairabnath Temple in Ilambazar is documented in the Wikimedia Commons archive.","puranicView":"The shrine follows local Shaiva worship traditions.","puranicSources":[{"label":"Bhairabnath Temple, Ilambazar (Media)","url":"https://commons.wikimedia.org/wiki/File:Bhairabnath_Temple,_Ilambazar_3.jpg","type":"Media archive"}],"folklore":"Village devotees visit for regular puja and festival days.","folkloreSources":[{"label":"Bhairabnath Temple, Ilambazar (Media)","url":"https://commons.wikimedia.org/wiki/File:Bhairabnath_Temple,_Ilambazar_3.jpg","type":"Media archive"}],"sources":[{"label":"Bhairabnath Temple, Ilambazar (Media)","url":"https://commons.wikimedia.org/wiki/File:Bhairabnath_Temple,_Ilambazar_3.jpg"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-ilambazar-rameshwar-shiva-temple-ilambazar', 'shiva', 'Rameshwar Shiva Temple (Ilambazar)', 'West Bengal', 'Ilambazar', 'Birbhum District', 'Shiva', 'Shaiva', '["Shiva","Deul","Heritage"]', 'A deul style Shiva temple in the Ilambazar area of Birbhum.', 'Stone tower and sculpted facade.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Deul_temple_of_Rameshwar_Shiva_at_Illambazar_in_Birbhum_district_of_West_Bengal_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Deul_temple_of_Rameshwar_Shiva_at_Illambazar_in_Birbhum_district_of_West_Bengal_01.jpg', 'Morning visits for quieter darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage site; respect temple customs.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"The Rameshwar Shiva temple in Ilambazar is documented in regional photo archives.","puranicView":"The shrine follows Shaiva worship traditions of Birbhum.","puranicSources":[{"label":"Rameshwar Shiva Temple, Ilambazar (Media)","url":"https://commons.wikimedia.org/wiki/Category:Rameshwar_Shiva_Temple,_Ilambazar","type":"Media archive"}],"folklore":"Local devotion centers on regular worship and seasonal festivals.","folkloreSources":[{"label":"Rameshwar Shiva Temple, Ilambazar (Media)","url":"https://commons.wikimedia.org/wiki/Category:Rameshwar_Shiva_Temple,_Ilambazar","type":"Media archive"}],"sources":[{"label":"Rameshwar Shiva Temple, Ilambazar (Media)","url":"https://commons.wikimedia.org/wiki/Category:Rameshwar_Shiva_Temple,_Ilambazar"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-itachuna-pancha-ratna-shiva-temple-itachuna', 'shiva', 'Pancha Ratna Shiva Temple (Itachuna)', 'West Bengal', 'Itachuna', 'Hooghly district', 'Shiva', 'Shaiva', '["Terracotta","Rajbari","Cinema"]', 'Located near the famous Itachuna Rajbari (often used in movies), this temple features the classic five-pinnacle style.', 'Proximity to the heritage Rajbari stay.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Itachuna%20rajbari.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Itachuna_rajbari.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Check Rajbari entry rules.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built by the Kundu family (Maratha Bargis ancestors).","architecture":"Pancha-ratna.","darshan":"Atmospheric.","seasonal":"Good in winter.","visitorNotes":"Stay at the Rajbari for full experience.","festivals":"Shivratri.","sources":[{"label":"Itachuna Rajbari","url":"https://en.wikipedia.org/wiki/Itachuna_Rajbari","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-jagatnagar-jagatnagar-kalibari', 'shiva', 'Jagatnagar Kalibari', 'West Bengal', 'Jagatnagar', 'Hooghly', 'Kali', 'Shakta', '["Jagatnagar","Singur","Kali Puja"]', 'A local Kali temple at Jagatnagar near Singur, known for community Kali Puja rituals.', 'Neighborhood Kalibari and festival gatherings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jagatnagar%20Kalibari.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jagatnagar_Kalibari.jpg', 'Kali Puja and winter evenings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Located near Singur in Hooghly district.', '["Daily puja"]', '["Kali Puja"]', '{"history":"Jagatnagar Kalibari is a Kali temple in Jagatnagar near Singur in Hooghly district.","architecture":"Traditional Bengal temple layout.","darshan":"Darshan is available daily with local worship routines.","seasonal":"Kali Puja is the busiest time of the year.","visitorNotes":"Plan a short local visit; parking is limited.","festivals":"Kali Puja","sources":[{"label":"Jagatnagar Kalibari","url":"https://en.wikipedia.org/wiki/Jagatnagar_Kalibari"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-jhargram-rameshwar-temple-jhargram', 'shiva', 'Rameshwar Temple (Jhargram)', 'West Bengal', 'Jhargram', 'Jhargram District', 'Shiva', 'Shaiva', '["Shiva","Heritage","Deul"]', 'A Shiva temple in Jhargram district noted for its deul style architecture.', 'Stone deul tower and seasonal gatherings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rameshwar_Temple,_Jhargram,_West_Bengal_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Rameshwar_Temple,_Jhargram,_West_Bengal_01.jpg', 'Morning visits for calmer darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage site; respect temple customs.', '["Daily puja"]', '["Mahashivratri","Shravan month"]', '{"history":"Rameshwar Temple is a Shiva shrine in Jhargram district listed in local tourism guides.","puranicView":"The shrine follows Shaiva worship traditions of the region.","puranicSources":[{"label":"Rameshwar Temple (Jhargram Tourism)","url":"https://jhargram.gov.in/tourist-place/rameshwar-temple/","type":"Government tourism"},{"label":"Rameshwar Temple, Jhargram (Media)","url":"https://commons.wikimedia.org/wiki/Category:Rameshwar_Temple,_Jhargram","type":"Media archive"}],"folklore":"Local visitors gather during Shravan and festival days.","folkloreSources":[{"label":"Rameshwar Temple (Jhargram Tourism)","url":"https://jhargram.gov.in/tourist-place/rameshwar-temple/","type":"Government tourism"}],"sources":[{"label":"Rameshwar Temple (Jhargram Tourism)","url":"https://jhargram.gov.in/tourist-place/rameshwar-temple/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kalna-nava-kailash-mandir', 'shiva', 'Nava Kailash Mandir', 'West Bengal', 'Kalna', 'Purba Bardhaman', 'Shiva', 'Shaiva', '["Shiva","Temple Cluster","Heritage"]', 'A historic complex of 108 Shiva shrines arranged in concentric circles.', 'Circular temple layout unique to Kalna.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nava_Kailash_Temple-Kalna-West_Bengal-DSC0402.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nava_Kailash_Temple-Kalna-West_Bengal-DSC0402.jpg', 'Morning visits for quieter darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Heritage complex; respect site guidelines.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"Nava Kailash Mandir in Kalna is a complex of 108 Shiva temples arranged in two concentric circles.","puranicView":"The complex centers on Shiva worship across the 108 shrine layout.","puranicSources":[{"label":"Nava Kailash Mandir","url":"https://en.wikipedia.org/wiki/Nava_Kailash_Mandir","type":"Encyclopedia"}],"folklore":"Visitors often walk the concentric rings as part of their darshan.","folkloreSources":[{"label":"Nava Kailash Mandir","url":"https://en.wikipedia.org/wiki/Nava_Kailash_Mandir","type":"Encyclopedia"}],"sources":[{"label":"Nava Kailash Mandir","url":"https://en.wikipedia.org/wiki/Nava_Kailash_Mandir"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kalna-pratapeswar-temple', 'shiva', 'Pratapeswar Temple', 'West Bengal', 'Kalna', 'Purba Bardhaman', 'Shiva', 'Shaiva', '["Terracotta","Rekha Deul","Masterpiece"]', 'Considered one of the finest terracotta temples in Bengal, built in 1849. It stands out for its incredible detail and unique Rekha Deul shape.', 'Exquisite terracotta panels depicting Ramayana and Krishnaleela.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pratapeswar%20Shiva%20Temple.%20Kalna.%20Burdwan.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pratapeswar_Shiva_Temple._Kalna._Burdwan.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Part of the Kalna Rajbari complex.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built by King Pratap Chand of Bardhaman.","architecture":"Curvilinear Rekha Deul.","darshan":"Artistic.","seasonal":"Pleasant in winter.","visitorNotes":"Walk to the nearby 108 Shiva temples.","festivals":"Shivratri.","sources":[{"label":"Kalna Temples","url":"https://en.wikipedia.org/wiki/Kalna,_India","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kalna-siddheshwari-kali-mandir-kalna', 'shiva', 'Siddheshwari Kali Mandir (Kalna)', 'West Bengal', 'Kalna', 'Purba Bardhaman', 'Siddheshwari Kali', 'Shakta', '["Siddheshwari Kali","Jor-bangla","Kalna"]', 'A historic Jor-bangla style Kali temple in Kalna City dedicated to Siddheshwari.', 'Distinctive Jor-bangla architecture and terracotta heritage.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Siddheswari%20Kali%20Mandir%2C%20Ambika%20Kalna%2C%20Purba%20Bardhaman%20district%2C%20West%20Bengal%2003.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Siddheswari_Kali_Mandir,_Ambika_Kalna,_Purba_Bardhaman_district,_West_Bengal_03.jpg', 'Winter months and festival days.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Located on the outskirts of Kalna City.', '["Daily puja"]', '["Kali Puja","Durga Puja"]', '{"history":"Siddheshwari Kali Mandir in Kalna City was established in the 18th century and is dedicated to Siddheshwari Kali.","architecture":"Jor-bangla style Bengal temple architecture.","darshan":"Darshan is available daily with regular worship cycles.","seasonal":"Kali Puja and Durga Puja draw large crowds.","visitorNotes":"Combine with Kalna’s terracotta temple circuit.","festivals":"Kali Puja · Durga Puja","sources":[{"label":"Siddheshwari Kali Mandir","url":"https://en.wikipedia.org/wiki/Siddheshwari_Kali_Mandir"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kanchannagar-kankaleshwari-kali-temple', 'shiva', 'Kankaleshwari Kali Temple', 'West Bengal', 'Kanchannagar', 'Purba Bardhaman', 'Kankaleshwari Kali', 'Shakta', '["Nabaratna","Kali","Bardhaman"]', 'A Nabaratna Kali temple in Kanchannagar known for its historic idol discovery.', 'Nine-spired temple complex in Bardhaman town.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kankaleshwari%20Kali%20Temple%20in%20Kanchannagar,%20Bardhaman%2004.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kankaleshwari_Kali_Temple_in_Kanchannagar,_Bardhaman_04.jpg', 'Kali Puja and winter months.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple is in Kanchannagar within Bardhaman town.', '["Daily puja","Evening aarti"]', '["Kali Puja","Navratri"]', '{"history":"Kankaleshwari Kali Temple is located in Kanchannagar, Bardhaman, and is a Nabaratna temple with an idol found near the Damodar river in the 1700s.","architecture":"A nine-spired Nabaratna temple within the Bardhaman heritage precinct.","darshan":"Darshan is available daily with evening aarti.","seasonal":"Kali Puja draws the largest gatherings.","visitorNotes":"Located inside Bardhaman town; parking can be limited.","festivals":"Kali Puja · Navratri","sources":[{"label":"Places of Interest (Purba Bardhaman)","url":"https://purbabardhaman.nic.in/tourist-place/kankaleshwari-kali-temple/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kankalitala-kankalitala-temple', 'shiva', 'Kankalitala Temple', 'West Bengal', 'Kankalitala', 'Birbhum', 'Devgarbha (Devi)', 'Shakta', '["Shakti Peetha","Birbhum","Pilgrimage"]', 'A Shakti Peetha in Birbhum where Kankalitala is revered as a sacred Devi site.', 'Quiet shrine complex near the temple town.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kankalitala%20Temple%20complex,%20Birbhum,%20West%20Bengal%2004.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kankalitala_Temple_complex,_Birbhum,_West_Bengal_04.jpg', 'Morning darshan for quieter visits.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Local pilgrimage site; weekends draw larger crowds.', '["Daily puja"]', '["Navratri","Kali Puja"]', '{"history":"Kankalitala is one of the Shakti Peethas in Birbhum, associated with the Kankal (waist) of Sati in the Shakti Peetha tradition.","architecture":"A compact temple complex with associated shrines.","darshan":"Darshan is available daily with local ritual cycles.","seasonal":"Navratri brings the largest pilgrim gatherings.","visitorNotes":"Plan for modest queues during festival days.","festivals":"Navratri · Kali Puja","sources":[{"label":"Kankalitala","url":"https://en.wikipedia.org/wiki/Kankalitala"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-ketugram-bahula-shaktipeeth-temple', 'shiva', 'Bahula Shaktipeeth Temple', 'West Bengal', 'Ketugram', 'Purba Bardhaman', 'Bahula', 'Shakta', '["Shakti Peetha","Ketugram","Pilgrimage"]', 'A Shakti Peetha in Ketugram dedicated to Goddess Bahula.', 'A revered Devi shrine in the Bardhaman countryside.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shri%20Bahula%20Shaktipeeth%20Temple,%20Ketugram.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shri_Bahula_Shaktipeeth_Temple,_Ketugram.jpg', 'Navratri and winter mornings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Village setting; plan transport accordingly.', '["Daily puja"]', '["Navratri","Kali Puja"]', '{"history":"Bahula Temple, also called Shri Bahula Shaktipeeth, is a Shakti Peetha at Ketugram in Purba Bardhaman.","architecture":"A village temple complex with a focused Devi sanctum.","darshan":"Darshan is available daily with local rituals.","seasonal":"Navratri is the busiest season for pilgrims.","visitorNotes":"Plan for rural travel times and limited amenities.","festivals":"Navratri · Kali Puja","sources":[{"label":"Bahula Temple","url":"https://en.wikipedia.org/wiki/Bahula_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-khardaha-26-shiva-temples-khardaha', 'shiva', '26 Shiva Temples (Khardaha)', 'West Bengal', 'Khardaha', 'North 24 Parganas', 'Shiva', 'Shaiva', '["Shiva","Temple Cluster","Riverside"]', 'A riverside complex of 26 Shiva shrines along the Hooghly in Khardaha.', 'Compact temple row and ghat side atmosphere.', 'https://commons.wikimedia.org/wiki/Special:FilePath/26_Shiva_Temples_Khardah.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:26_Shiva_Temples_Khardah.jpg', 'Morning visits for calmer darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Riverside crowds increase during festival days.', '["Daily puja"]', '["Mahashivratri","Shravan month"]', '{"history":"Khardaha is known for its cluster of 26 Shiva temples on the Hooghly riverbank.","puranicView":"The complex centers on Shaiva worship across multiple small shrines.","puranicSources":[{"label":"Khardaha","url":"https://en.wikipedia.org/wiki/Khardaha","type":"Encyclopedia"},{"label":"26 Shiva Temples, Khardaha (Media)","url":"https://commons.wikimedia.org/wiki/Category:26_Shiva_Temples,_Khardaha","type":"Media archive"}],"folklore":"Local devotees visit several shrines in a single visit.","folkloreSources":[{"label":"Khardaha","url":"https://en.wikipedia.org/wiki/Khardaha","type":"Encyclopedia"}],"sources":[{"label":"Khardaha","url":"https://en.wikipedia.org/wiki/Khardaha"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-khirpai-pancha-ratna-shiva-temple-khirpai', 'shiva', 'Pancha Ratna Shiva Temple (Khirpai)', 'West Bengal', 'Khirpai', 'Paschim Medinipur', 'Shiva', 'Shaiva', '["Pancha-ratna","Heritage","Town"]', 'A classic five-pinnacle Shiva temple in the historic trading town of Khirpai.', 'The Pancha-ratna architecture.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sitalananda%20Shiva%20Temple%20at%20Kshirpai%20or%20Khirpai%20ast%20Paschim%20Medinipur%20district%20in%20West%20Bengal%2023.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sitalananda_Shiva_Temple_at_Kshirpai_or_Khirpai_ast_Paschim_Medinipur_district_in_West_Bengal_23.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Ghatal.', '["Daily puja"]', '["Shivratri"]', '{"history":"19th-century construction.","architecture":"Pancha-ratna.","darshan":"Local.","seasonal":"Pleasant.","visitorNotes":"Khirpai was historically famous for weaving.","festivals":"Shivratri.","sources":[{"label":"Khirpai","url":"https://en.wikipedia.org/wiki/Khirpai","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kiritkona-kiriteswari-temple', 'shiva', 'Kiriteswari Temple', 'West Bengal', 'Kiritkona', 'Murshidabad', 'Kiriteswari', 'Shakta', '["Shakti Peetha","Bhagirathi","Murshidabad"]', 'A Shakti Peetha in Murshidabad dedicated to Devi Kiriteswari.', 'A revered Devi shrine near the Bhagirathi river.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kiriteswari%20Temple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kiriteswari_Temple.jpg', 'Morning darshan and winter visits.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Temple is in a village setting; allow time for local travel.', '["Daily puja","Evening aarti"]', '["Navratri","Kali Puja"]', '{"history":"Kiriteswari Temple is a Shakta Peetha at Kiritkona village in Murshidabad district.","architecture":"A compact shrine in the village precinct near the Bhagirathi.","darshan":"Darshan is available daily with aarti in the evening.","seasonal":"Festival days draw larger pilgrim flows.","visitorNotes":"Plan transport in advance for the village location.","festivals":"Navratri · Kali Puja","sources":[{"label":"Kiriteswari Temple","url":"https://en.wikipedia.org/wiki/Kiriteswari_Temple"},{"label":"Shaktipeeth Shri Kiriteswari Temple (Murshidabad)","url":"https://murshidabad.gov.in/gallery/shaktipeeth-shri-kiriteswari-temple/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-adyapith-temple', 'shiva', 'Adyapith Temple', 'West Bengal', 'Kolkata', 'Dakshineswar', 'Adya Ma', 'Shakta', '["Shakti","Adya Ma","Pilgrimage"]', 'A Shakta shrine dedicated to Adya Ma with a large temple complex.', 'Spacious courtyards and devotional atmosphere.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Adya%20Ma%20Shakespeare%20Sarani%20Arnab%20Dutta%202011.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Adya_Ma_Shakespeare_Sarani_Arnab_Dutta_2011.jpg', 'Early morning darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Navratri","Kali Puja"]', '{"history":"The white marble Adyapith temple was consecrated on January 14, 1967, and the larger Adyapeath campus is known for combining worship with service institutions such as schools, orphanages, and a charitable dispensary.","puranicView":"Adya Ma is revered here as the Primordial Shakti (Divine Mother), and worship emphasizes the universal motherly aspect of the Goddess.","puranicSources":[{"label":"Adyapith history (Dakshineswar Ramkrishna Sangha Adyapeath)","url":"https://adyapeathusa.org/adyapith-history/","type":"Temple organization"},{"label":"Adyapeath overview","url":"https://adyapeathusa.org/","type":"Temple organization"}],"folklore":"Temple tradition notes that daily food offerings are prepared in a separate Bhog Ghar, following instructions said to have been received by Annada Thakur in dreams.","folkloreSources":[{"label":"Adyapeath main temple","url":"https://adyapeathusa.org/adyapeath-main-temple/","type":"Temple organization"}],"sources":[{"label":"Adyapith history","url":"https://adyapeathusa.org/adyapith-history/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-balaram-mandir', 'shiva', 'Balaram Mandir', 'West Bengal', 'Kolkata', 'Baghbazar', 'Sri Ramakrishna', 'Ramakrishna Order', '["Ramakrishna","Mission","Heritage"]', 'A Ramakrishna Mission temple honoring Sri Ramakrishna in north Kolkata.', 'Quiet prayer hall and mission heritage.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Balaram%20Mandir%20Baghbazar%20Kolkata.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Balaram_Mandir_Baghbazar_Kolkata.jpg', 'Morning prayers.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Ramakrishna Jayanti","Vijaya Dashami"]', '{"history":"Balaram Mandir was the residence of Balaram Bose, where Swami Vivekananda met disciples on May 1, 1897 to plan the Ramakrishna Mission. It later became a place of worship in 1922 and was recognized as a branch center in 2002.","puranicView":"The temple follows the Ramakrishna Order tradition, centering worship on Sri Ramakrishna and the ideal of the Divine Mother rather than a specific Puranic deity.","puranicSources":[{"label":"Balaram Mandir (Baghbazar)","url":"https://en.wikipedia.org/wiki/Balaram_Mandir","type":"Encyclopedia"}],"folklore":"The Baghbazar Math is often recalled as a formative gathering place for early Ramakrishna Mission activity in Kolkata.","folkloreSources":[{"label":"Balaram Mandir (Baghbazar)","url":"https://en.wikipedia.org/wiki/Balaram_Mandir","type":"Encyclopedia"}],"sources":[{"label":"Balaram Mandir","url":"https://en.wikipedia.org/wiki/Balaram_Mandir"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-birla-mandir-kolkata', 'shiva', 'Birla Mandir (Kolkata)', 'West Bengal', 'Kolkata', 'Ballygunge', 'Lakshminarayan', 'Vaishnava', '["Lakshminarayan","Marble","Urban"]', 'A modern marble temple dedicated to Lakshminarayan in south Kolkata.', 'Marble spires and evening illumination.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Birla_mandir_kolkata_1190.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Birla_mandir_kolkata_1190.jpg', 'Evening darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Evening aarti","Daily puja"]', '["Janmashtami","Diwali"]', '{"history":"The temple was constructed between 1970 and 1996 by the Birla family and inaugurated in 1996, with architecture inspired by Odisha\'s Lingaraja Temple style.","puranicView":"The shrine is dedicated to Lakshminarayan (Vishnu and Lakshmi), with Krishna and Radha in the main sanctum, while side domes honor Durga and Shiva, reflecting a broad spectrum of Hindu devotion.","puranicSources":[{"label":"Birla Mandir, Kolkata","url":"https://en.wikipedia.org/wiki/Birla_Mandir,_Kolkata","type":"Encyclopedia"}],"folklore":"Janmashtami draws large crowds to the temple each year, keeping the Krishna-focused devotional atmosphere vivid in local memory.","folkloreSources":[{"label":"Birla Mandir, Kolkata","url":"https://en.wikipedia.org/wiki/Birla_Mandir,_Kolkata","type":"Encyclopedia"}],"sources":[{"label":"Birla Mandir, Kolkata","url":"https://en.wikipedia.org/wiki/Birla_Mandir,_Kolkata"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-calcutta-jain-temple', 'shiva', 'Calcutta Jain Temple', 'West Bengal', 'Kolkata', 'Maniktala', 'Parshvanatha', 'Jain', '["Jain","Marble","Heritage"]', 'A prominent Jain temple complex dedicated to Parshvanatha.', 'Ornate marble and glasswork interiors.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jain_Temple_-_Calcutta.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jain_Temple_-_Calcutta.jpg', 'Morning hours for calm darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily darshan"]', '["Paryushan","Mahavir Jayanti"]', '{"history":"Built in 1867 by Rai Badridas Bahadoor Mookim, the complex houses multiple temples, with the main shrine dedicated to Shitalanatha and another to Parshvanatha.","puranicView":"As a Jain complex, the temple centers on Tirthankara devotion rather than Hindu Puranic narratives, highlighting Jain dharmic traditions in Kolkata.","puranicSources":[{"label":"Calcutta Jain Temple","url":"https://en.wikipedia.org/wiki/Calcutta_Jain_Temple","type":"Encyclopedia (Jain tradition)"}],"folklore":"The ornate interior is famed for stained glass, mirror mosaics, and a Shitalanatha image said to have a diamond on the forehead, a detail visitors often remember.","folkloreSources":[{"label":"Calcutta Jain Temple","url":"https://en.wikipedia.org/wiki/Calcutta_Jain_Temple","type":"Encyclopedia"}],"sources":[{"label":"Calcutta Jain Temple","url":"https://en.wikipedia.org/wiki/Calcutta_Jain_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-dakshineswar-kali-temple', 'shiva', 'Dakshineswar Kali Temple', 'West Bengal', 'Kolkata', 'Hooghly River', 'Kali', 'Shakta', '["Kali","Riverbank","Heritage"]', 'A storied riverside Kali temple with a vibrant devotional culture.', 'Evening bells and the riverfront breeze.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dakshineswar_Kali_Temple,_Dakshineswar,_West_Bengal,_India_(2007).jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dakshineswar_Kali_Temple,_Dakshineswar,_West_Bengal,_India_(2007).jpg', 'Evenings by the riverbank.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Riverside crowds increase during festivals.', '["Evening aarti","Daily puja"]', '["Kali Puja","Navratri"]', '{"puranicView":"The temple venerates Bhavatarini, a form of Kali identified with Mahadevi or Adishakti in Puranic Shakta tradition. Worship here centers on Kali as the liberating, motherly power who ferries devotees across samsara.","puranicSources":[{"label":"Dakshineswar Kali Temple","url":"https://en.wikipedia.org/wiki/Dakshineswar_Kali_Temple","type":"Encyclopedia (Kali tradition)"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-firingi-kalibari', 'shiva', 'Firingi Kalibari', 'West Bengal', 'Kolkata', 'Bowbazar', 'Kali', 'Shakta', '["Kali","Heritage","City temple"]', 'A well-known Kali temple in central Kolkata with a distinct local history.', 'Shrine atmosphere in the old city lanes.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Firingi%20Kali%20Bari.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Firingi_Kali_Bari.jpg', 'Evening darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Kali Puja","Navratri"]', '{"history":"Firingi Kalibari is over two centuries old and is associated with Anthony Firingee, a European devotee of Kali after whom the temple is named.","puranicView":"The deity is worshipped as Kali in the Shakta tradition, with the shrine honoring the fierce protective aspect of the Goddess.","puranicSources":[{"label":"Firinghi Kali Bari","url":"https://en.wikipedia.org/wiki/Firinghi_Kali_Bari","type":"Encyclopedia"}],"folklore":"Local memory preserves the story of Anthony Firingee as the temple\'s founding devotee, a narrative that still shapes its identity in the old city lanes.","folkloreSources":[{"label":"Firinghi Kali Bari","url":"https://en.wikipedia.org/wiki/Firinghi_Kali_Bari","type":"Encyclopedia"}],"sources":[{"label":"Firinghi Kali Bari","url":"https://en.wikipedia.org/wiki/Firinghi_Kali_Bari"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-iskcon-temple-kolkata', 'shiva', 'ISKCON Temple, Kolkata', 'West Bengal', 'Kolkata', 'Minto Park', 'Radha Govinda', 'Gaudiya Vaishnava', '["ISKCON","Krishna","Kirtan"]', 'A vibrant ISKCON center with daily kirtan and Krishna worship.', 'Kirtan halls and devotional gatherings.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bhaktivinoda_Asan_Roof_1_-_ISKCON_Ultadanga,_Kolkata.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bhaktivinoda_Asan_Roof_1_-_ISKCON_Ultadanga,_Kolkata.jpg', 'Evening aarti and kirtan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Mangala aarti","Kirtan"]', '["Janmashtami","Gaura Purnima"]', '{"history":"ISKCON established its first center in India in Kolkata in 1970 at 3C Albert Road, with the first deities installed in May 1971 and the first Rath Yatra held in July 1972.","puranicView":"The temple is known as Sri Sri Radha Govinda Mandir and follows the Gaudiya Vaishnava tradition of Krishna devotion.","puranicSources":[{"label":"ISKCON Kolkata (History)","url":"https://www.iskconkolkata.com/history/","type":"Temple site"},{"label":"ISKCON Kolkata (Contact)","url":"https://www.iskconkolkata.com/contact/","type":"Temple site"}],"folklore":"The early Rath Yatra in 1972, organized soon after the center opened, became a defining tradition for the Kolkata community and continues to shape the temple\'s public devotional identity.","folkloreSources":[{"label":"ISKCON Kolkata (History)","url":"https://www.iskconkolkata.com/history/","type":"Temple site"}],"sources":[{"label":"ISKCON Kolkata","url":"https://www.iskconkolkata.com"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-kalighat-kali-temple', 'shiva', 'Kalighat Kali Temple', 'West Bengal', 'Kolkata', 'Kalighat', 'Kali', 'Shakta', '["Kali","Shakti Peetha","Heritage"]', 'One of Kolkata\'s most revered Kali temples, rooted in long-standing Shakti traditions.', 'Morning rituals and the vibrant temple lanes.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalighat_Temple,_Kalighat.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kalighat_Temple,_Kalighat.jpg', 'Early mornings for quieter darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect crowds during festive seasons.', '["Morning puja","Evening aarti"]', '["Kali Puja","Durga Puja"]', '{"puranicView":"Kalighat is revered as a Shakti Peetha where Sati\'s right toe is believed to have fallen, with Shakti worshipped as Kali and Bhairava as Nakulesh. This places the shrine within the Puranic Shakti Peetha network.","puranicSources":[{"label":"Kalighat Kali Temple","url":"https://en.wikipedia.org/wiki/Kalighat_Kali_Temple","type":"Encyclopedia (Shakti Peetha tradition)"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-lake-kalibari', 'shiva', 'Lake Kalibari', 'West Bengal', 'Kolkata', 'Southern Avenue', 'Kali', 'Shakta', '["Kali","Lake","Community"]', 'A popular neighborhood Kali temple near the lakes of south Kolkata.', 'Community rituals by the lakefront.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Goddess_Kali_at_Lake_Temple,_Kolkata.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Goddess_Kali_at_Lake_Temple,_Kolkata.jpg', 'Evening visits.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Evening aarti","Daily puja"]', '["Kali Puja","Durga Puja"]', '{"history":"Also known as Sree Sree 108 Karunamoyee Kalimata Mandir, the temple was founded in 1949 by Haripada Chakraborty and later expanded; major reconstruction work began after 2002.","puranicView":"The shrine honors Kali as Karunamoyee, emphasizing the compassionate Shakti aspect within Kolkata\'s Shakta tradition.","puranicSources":[{"label":"Lake Kalibari","url":"https://en.wikipedia.org/wiki/Lake_Kalibari","type":"Encyclopedia"}],"folklore":"Kali Puja, Durga Puja, Kaushiki Amavasya, Annapurna Puja, and Vishvakarma Puja are among the temple\'s best-known festival observances, drawing neighborhood crowds each year.","folkloreSources":[{"label":"Lake Kalibari","url":"https://en.wikipedia.org/wiki/Lake_Kalibari","type":"Encyclopedia"}],"sources":[{"label":"Lake Kalibari","url":"https://en.wikipedia.org/wiki/Lake_Kalibari"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kolkata-thanthania-kalibari', 'shiva', 'Thanthania Kalibari', 'West Bengal', 'Kolkata', 'Bidhan Sarani', 'Kali', 'Shakta', '["Kali","Heritage","City temple"]', 'A historic Kali temple in north Kolkata known for local devotion.', 'Festive gatherings during Kali Puja.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thanthania%20Kalibari%20in%20Kolkata.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Thanthania_Kalibari_in_Kolkata.jpg', 'Evening hours.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Footwear is not allowed inside temple areas.', '["Daily puja"]', '["Kali Puja","Navratri"]', '{"history":"Thanthania Kalibari was founded in 1703 by the tantrik Uday Narayan Brahmachari and re-established in 1806 by Shankar Ghosh, making it one of Kolkata\'s oldest Kali temples.","puranicView":"Kali is worshipped here as Maa Siddheshwari, and the shrine is rooted in the Shakta tradition where Kali is revered as the first of the ten Mahavidyas and the supreme deity of the Kalikula stream.","puranicSources":[{"label":"Thanthania Kalibari","url":"https://en.wikipedia.org/wiki/Thanthania_Kalibari","type":"Encyclopedia"}],"folklore":"Local tradition says the name \'Thanthania\' comes from the bell sounds heard in the old forest paths. Devotees gather in large numbers for Kali Puja, Kaushiki Amavasya, and Phalaharini Amavasya.","folkloreSources":[{"label":"Thanthania Kalibari","url":"https://en.wikipedia.org/wiki/Thanthania_Kalibari","type":"Encyclopedia"}],"sources":[{"label":"Thanthania Kalibari","url":"https://en.wikipedia.org/wiki/Thanthania_Kalibari"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kurseong-hateshwar-mahadev', 'shiva', 'Hateshwar Mahadev', 'West Bengal', 'Kurseong', 'Darjeeling district', 'Shiva', 'Shaiva', '["Hilltop","Nature","Tea Gardens"]', 'A revered Shiva temple amidst the tea gardens of Kurseong, known for a natural rock linga.', 'The serene atmosphere and views of the tea estates.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Coronation%20Bridge%20at%20Sevoke%2016.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Coronation_Bridge_at_Sevoke_16.jpg', 'March-May.', 'Open daily.', 'Casual.', 'Short walk from the road.', '["Daily puja"]', '["Shivratri"]', '{"history":"Local shrine worshipped by tea garden workers.","architecture":"Simple hill temple.","darshan":"Peaceful.","seasonal":"Misty in monsoon.","visitorNotes":"Enjoy the tea garden walk.","festivals":"Shivratri.","sources":[{"label":"Kurseong","url":"https://en.wikipedia.org/wiki/Kurseong","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-kusumba-jora-shiva-temples-kusumba', 'shiva', 'Jora Shiva Temples (Kusumba)', 'West Bengal', 'Kusumba', 'Rampurhat, Birbhum', 'Shiva', 'Shaiva', '["Twin Temples","Terracotta","Pond"]', 'Two identical Shiva temples standing side-by-side on the banks of a pond, known for their high-quality terracotta decorations.', 'The twin structure and reflection in the pond.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Twin%20deul%20styled%20temple%20dedicated%20to%20Shiva%20at%20Supur%20in%20Birbhum%20district.%2002.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Twin_deul_styled_temple_dedicated_to_Shiva_at_Supur_in_Birbhum_district._02.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Village location.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in the 19th century.","architecture":"Char-chala.","darshan":"Scenic.","seasonal":"Good in winter.","visitorNotes":"Photogenic spot.","festivals":"Shivratri.","sources":[{"label":"Birbhum Temples","url":"https://en.wikipedia.org/wiki/Birbhum_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-lataguri-mahakal-temple-lataguri', 'shiva', 'Mahakal Temple (Lataguri)', 'West Bengal', 'Lataguri', 'Jalpaiguri District', 'Shiva', 'Shaiva', '["Shiva","Forest","Pilgrimage"]', 'A local Shiva shrine near Lataguri and the Gorumara forest belt.', 'Forest side darshan with a calm rural setting.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mahakal_Mandir,_Lataguri,_beside_Gorumara_National_Park_01.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahakal_Mandir,_Lataguri,_beside_Gorumara_National_Park_01.jpg', 'Morning visits for peaceful darshan.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Check local access during monsoon.', '["Daily puja"]', '["Mahashivratri","Local temple festivals"]', '{"history":"The temple is documented in the Wikimedia Commons archive for Lataguri.","puranicView":"Local Shaiva worship continues through daily offerings.","puranicSources":[{"label":"Mahakal Temple, Lataguri (Media)","url":"https://commons.wikimedia.org/wiki/Category:Mahakal_Temple,_Lataguri","type":"Media archive"}],"folklore":"Devotees often visit alongside nearby forest routes.","folkloreSources":[{"label":"Mahakal Temple, Lataguri (Media)","url":"https://commons.wikimedia.org/wiki/Category:Mahakal_Temple,_Lataguri","type":"Media archive"}],"sources":[{"label":"Mahakal Temple, Lataguri (Media)","url":"https://commons.wikimedia.org/wiki/Category:Mahakal_Temple,_Lataguri"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-mahanad-mahanad-kali-temple-shiva-complex', 'shiva', 'Mahanad Kali Temple (Shiva Complex)', 'West Bengal', 'Mahanad', 'Hooghly district', 'Shiva (Jateswarnath)', 'Shaiva', '["Gupta Era","Shiva","History"]', 'Mahanad is an ancient site often identified with the Gupta period. The Shiva temple here is locally famous as Jateswarnath.', 'Historical antiquity of the site.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mahanad%20Jora%20Shiva%20Temple%20at%20Mahanad%2C%20Hooghly%20district%2002.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahanad_Jora_Shiva_Temple_at_Mahanad,_Hooghly_district_02.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Polba.', '["Daily puja"]', '["Shivratri"]', '{"history":"Mahanad was a provincial capital in ancient Bengal.","architecture":"Traditional.","darshan":"Historic.","seasonal":"Good all year.","visitorNotes":"Archaeological finds nearby.","festivals":"Shivratri.","sources":[{"label":"Mahanad","url":"https://en.wikipedia.org/wiki/Mahanad","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-maynaguri-jataleswar-temple', 'shiva', 'Jataleswar Temple', 'West Bengal', 'Maynaguri', 'Jalpaiguri district', 'Shiva (Jataleswar)', 'Shaiva', '["North Bengal","Forest","Ancient"]', 'One of the oldest temples in North Bengal, dedicated to Lord Jataleswar (Shiva). It dates back to the Gupta period (320 AD).', 'Ancient history and deep reverence in the Dooars region.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mahakal%20Mandir%2C%20Lataguri%2C%20beside%20Gorumara%20National%20Park%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mahakal_Mandir,_Lataguri,_beside_Gorumara_National_Park_01.jpg', 'Winter.', 'Open daily.', 'Modest.', 'Near Maynaguri.', '["Water offering"]', '["Shivratri Fair"]', '{"history":"Rebuilt by the Kings of Cooch Behar after original Gupta era construction.","architecture":"Bengal style.","darshan":"Pilgrimage.","seasonal":"Pleasant in winter.","visitorNotes":"Major fair held during Shivratri.","festivals":"Shivratri.","sources":[{"label":"Jataleswar Temple","url":"https://en.wikipedia.org/wiki/Jataleswar_Temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-moyna-moyna-garh-lokeshwar', 'shiva', 'Moyna Garh Lokeshwar', 'West Bengal', 'Moyna', 'Purba Medinipur', 'Shiva (Lokeshwar)', 'Shaiva', '["Island Fort","Unique","Heritage"]', 'Moyna Garh is a unique fort surrounded by two moats. Inside lies the Lokeshwar Shiva temple.', 'The island-like setting inside the moats.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lokeswara%20Shiva%20Temple%20at%20Moyna%20Garh%20at%20Purba%20Medinipur%20district%20in%20West%20Bengal%2004.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lokeswara_Shiva_Temple_at_Moyna_Garh_at_Purba_Medinipur_district_in_West_Bengal_04.jpg', 'Winter (Rash Mela).', 'Open daily.', 'Casual.', 'Accessible by boat or causeway.', '["Daily puja"]', '["Rash Mela"]', '{"history":"Ancient fort of the Lausen kings.","architecture":"Pyramidal Rasmancha style.","darshan":"Scenic.","seasonal":"Beautiful water body.","visitorNotes":"Historical atmosphere.","festivals":"Rash Mela.","sources":[{"label":"Moyna","url":"https://en.wikipedia.org/wiki/Moyna","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-murshidabad-ghoshwara-shiva-temple', 'shiva', 'Ghoshwara Shiva Temple', 'West Bengal', 'Murshidabad', 'Lalbagh', 'Shiva', 'Shaiva', '["Terracotta","Murshidabad","Heritage"]', 'A classic example of Char-chala (four-roofed) temple architecture in the historic Murshidabad region.', 'Exquisite terracotta panels depicting mythological scenes.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ajhapur%20Char%20Chala%20Shiva%20Temple%20of%20Mitra%20family%20of%20Purba%20Bardhaman%20district%20in%20West%20Bengal%2003.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ajhapur_Char_Chala_Shiva_Temple_of_Mitra_family_of_Purba_Bardhaman_district_in_West_Bengal_03.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Part of the Murshidabad heritage circuit.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in the 18th century.","architecture":"Char-chala.","darshan":"Historic.","seasonal":"Good in winter.","visitorNotes":"Visit the nearby Hazarduari Palace.","festivals":"Shivratri.","sources":[{"label":"Murshidabad Temples","url":"https://en.wikipedia.org/wiki/Murshidabad","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-nabadwip-buro-shiv-mandir', 'shiva', 'Buro Shiv Mandir', 'West Bengal', 'Nabadwip', 'Nadia district', 'Shiva (Buro Shiv)', 'Shaiva', '["Oldest","Chaitanya Era","Heritage"]', 'The oldest Shiva temple in Nabadwip, dating back to the era of Sri Chaitanya Mahaprabhu. The deity is Buro Shiv (The Old Shiva).', 'Traditional Bengali \'Dochala\' architecture and historical significance.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dandapani%20Shiva%20Temple%2C%20Nabadwip%2C%20Nadia%20district%2C%20West%20Bengal%2C%20India%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Dandapani_Shiva_Temple,_Nabadwip,_Nadia_district,_West_Bengal,_India_01.jpg', 'Rash Yatra.', 'Open daily.', 'Modest.', 'In the heart of Nabadwip.', '["Daily puja"]', '["Shivratri","Rash Yatra"]', '{"history":"Existing since the 16th century.","architecture":"Dochala (Two-roofed).","darshan":"Devotional.","seasonal":"Crowded during Rash.","visitorNotes":"Visit the nearby Vaishnava sites too.","festivals":"Shivratri.","sources":[{"label":"Nabadwip","url":"https://en.wikipedia.org/wiki/Nabadwip","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-naihati-boro-maa-kali-temple-naihati', 'shiva', 'Boro Maa Kali Temple, Naihati', 'West Bengal', 'Naihati', 'North 24 Parganas', 'Boro Maa Kali', 'Shakta', '["Boro Maa","Kali Puja","Naihati"]', 'A famed Naihati Kali shrine centered on Boro Maa, known for its towering Kali Puja idol and deep community devotion.', 'Kali Puja season with the giant Boro Maa idol and festive rituals.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Boro%20Maa%20Naihati%202022.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Boro_Maa_Naihati_2022.jpg', 'Kali Puja and winter evenings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect heavy crowds during Kali Puja.', '["Daily puja","Kali Puja"]', '["Kali Puja","Kaushiki Amavasya","Dipannwita Amavasya"]', '{"history":"Boro Maa Kali Temple in Naihati grew around the early 20th century and is revered for its annual Kali Puja traditions.","architecture":"Bengal temple architecture with a modernized complex.","darshan":"Daily darshan with special observances during festival nights.","seasonal":"Kali Puja draws the largest crowds and special rituals.","visitorNotes":"Plan for long queues and local traffic controls on puja nights.","festivals":"Kali Puja · Kaushiki Amavasya · Dipannwita Amavasya","sources":[{"label":"Boro Maa Kali Temple, Naihati","url":"https://en.wikipedia.org/wiki/Boro_Maa_Kali_Temple,_Naihati"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-onda-bahulara-siddheswar-temple', 'shiva', 'Bahulara Siddheswar Temple', 'West Bengal', 'Onda', 'Bankura district', 'Shiva (Siddheswar)', 'Shaiva', '["Rekha Deul","Brick","Architecture"]', 'The finest specimen of \'Rekha Deul\' architecture in Bengal, known for its intricate brickwork and towering height.', 'The towering brick deul structure.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Siddheshwara%20Temple%20at%20Bahulara%2C%20Bankura.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Siddheshwara_Temple_at_Bahulara,_Bankura.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Archaeological site.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built around the 11th century; pre-dates Bishnupur temples.","architecture":"Oriya-influenced Rekha Deul.","darshan":"Heritage.","seasonal":"Hot in summer.","visitorNotes":"A must for architecture students.","festivals":"Chaitra Gajan.","sources":[{"label":"Bahulara","url":"https://en.wikipedia.org/wiki/Bahulara","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-pareshnath-pareshnath-shiva-temple', 'shiva', 'Pareshnath Shiva Temple', 'West Bengal', 'Pareshnath', 'Bankura district', 'Shiva', 'Shaiva', '["Jain History","Conversion","Heritage"]', 'Originally a Jain site that transformed into a Shaiva pilgrimage center. The Shiva linga here is widely revered.', 'Fusion of Jain heritage and Shaiva worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pareshnath%20Shiva%20temple%20at%20Kalyanchak%20in%20Howrah%20district%2C%20West%20Bengal%2006.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pareshnath_Shiva_temple_at_Kalyanchak_in_Howrah_district,_West_Bengal_06.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Ranibandh.', '["Daily puja"]', '["Gajan"]', '{"history":"Ancient Jain idols found in the vicinity.","architecture":"Stone/Brick.","darshan":"Devotional.","seasonal":"Hot summer.","visitorNotes":"Remote location.","festivals":"Gajan.","sources":[{"label":"Bankura Tourism","url":"https://en.wikipedia.org/wiki/Bankura_district","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-pathra-pathra-temple-complex', 'shiva', 'Pathra Temple Complex', 'West Bengal', 'Pathra', 'Paschim Medinipur', 'Shiva (Navaratna)', 'Shaiva', '["Temple Village","Terracotta","Restoration"]', 'Known as the \'Village of Temples\', Pathra houses over 30 temples (mostly Shiva) built by the Ghoshal and Majumdar families, now being restored.', 'The sheer density of temples in one village.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pathra%20temple%2CMedinipur.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pathra_temple,Medinipur.jpg', 'Winter.', 'Open daily.', 'Casual.', '10km from Midnapore town.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built between 1732 and late 18th century.","architecture":"Chala and Ratna styles.","darshan":"Heritage walk.","seasonal":"Avoid summer heat.","visitorNotes":"Visit the Navaratna Shiva temple.","festivals":"Shivratri.","sources":[{"label":"Pathra","url":"https://en.wikipedia.org/wiki/Pathra","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-rampara-rampara-kalibari', 'shiva', 'Rampara Kalibari', 'West Bengal', 'Rampara', 'Hooghly', 'Siddheshwari Kali', 'Shakta', '["Rampara","Siddheshwari Kali","Kali Puja"]', 'A village Kali temple in Rampara dedicated to Siddheshwari Kali and celebrated for its Kali Puja.', 'Traditional Bengal temple courtyard and festival worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kalibari%200161.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kalibari_0161.jpg', 'Kali Puja and autumn evenings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Located in Rampara, Hooghly district.', '["Daily puja","Kali Puja"]', '["Kali Puja","Durga Puja"]', '{"history":"Rampara Kalibari is a Kali temple in Hooghly district built by the Nandy family and dedicated to Siddheshwari Kali.","architecture":"Bengal temple architecture with a courtyard layout.","darshan":"Darshan is available daily; festival days are crowded.","seasonal":"Kali Puja is the major annual observance.","visitorNotes":"Plan for village roads and limited facilities.","festivals":"Kali Puja · Durga Puja","sources":[{"label":"Rampara Kalibari","url":"https://en.wikipedia.org/wiki/Rampara_Kalibari"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-sainthia-nandikeshwari-temple', 'shiva', 'Nandikeshwari Temple', 'West Bengal', 'Sainthia', 'Birbhum district', 'Nandikeshwari / Shiva (Nandikeshwar)', 'Shakta/Shaiva', '["Shakti Peetha","Nandikeshwari","Tortoise Idol"]', 'A major Shakti Peetha where the necklace of Sati fell. The main deity is worshipped as a rock smeared with vermilion.', 'One of the 51 Shakti Peethas.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Goddess%20Nandikeshwari.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Goddess_Nandikeshwari.jpg', 'Navratri.', 'Open daily.', 'Modest.', 'In Sainthia town.', '["Daily puja"]', '["Kali Puja","Navratri"]', '{"history":"Ancient pilgrimage site.","architecture":"Simple Bengal style.","darshan":"Spiritual.","seasonal":"Crowded during Puja.","visitorNotes":"Visit the Shiva temple in the complex too.","festivals":"Navratri.","sources":[{"label":"Nandikeshwari Temple","url":"https://en.wikipedia.org/wiki/Nandikeshwari_Temple","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-santipur-jaleswar-shiva-temple', 'shiva', 'Jaleswar Shiva Temple', 'West Bengal', 'Santipur', 'Nadia district', 'Shiva', 'Shaiva', '["Tallest","Heritage","Terracotta"]', 'The tallest temple in Santipur, built by the Nadia Raj family. It features exquisite terracotta and a massive structure.', 'The towering height and the history of the Nadia royals.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shyamchand%20temple%20at%20Shantipur%20in%20Nadia%20district%2005.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shyamchand_temple_at_Shantipur_in_Nadia_district_05.jpg', 'Rash Yatra.', 'Open daily.', 'Modest.', 'In Santipur town.', '["Daily puja"]', '["Rash Yatra","Shivratri"]', '{"history":"Built by Raja Raghuram Ray in the 18th century.","architecture":"Char-chala/At-chala hybrid.","darshan":"Devotional.","seasonal":"Crowded during Rash.","visitorNotes":"Santipur is famous for sarees too.","festivals":"Rash Yatra.","sources":[{"label":"Santipur","url":"https://en.wikipedia.org/wiki/Shantipur","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-sevoke-sevoke-shiva-mandir', 'shiva', 'Sevoke Shiva Mandir', 'West Bengal', 'Sevoke', 'Darjeeling district', 'Shiva / Kali', 'Shakta/Shaiva', '["Coronation Bridge","Forest","River Teesta"]', 'Located near the iconic Coronation Bridge, this temple (often called Sevoke Kalibari but houses Shiva) offers stunning views of the Teesta River.', 'Panoramic view of Teesta river and the mountains.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Coronation%20Bridge%20at%20Sevoke%2002.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Coronation_Bridge_at_Sevoke_02.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Many stairs to climb.', '["Daily puja"]', '["Navratri","Shivratri"]', '{"history":"Built in the mid-20th century.","architecture":"Hill style.","darshan":"Scenic.","seasonal":"Monsoon view is dramatic.","visitorNotes":"Beware of monkeys.","festivals":"Navratri.","sources":[{"label":"Sevoke","url":"https://en.wikipedia.org/wiki/Sevoke","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-shyamnagar-mulajore-kalibari-shyamnagar', 'shiva', 'Mulajore Kalibari (Shyamnagar)', 'West Bengal', 'Shyamnagar', 'North 24 Parganas', 'Kali (Brahmamoyee)', 'Shakta', '["Mulajore Kalibari","Shyamnagar","Hooghly River"]', 'A historic Kali temple by the Hooghly river at Shyamnagar, associated with the Mulajore Kalibari traditions.', 'Riverside shrine with long local heritage.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mulajore%20kalibari.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mulajore_kalibari.jpg', 'Winter months and festival days.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Set near the Hooghly riverbanks in Shyamnagar.', '["Daily puja"]', '["Kali Puja"]', '{"history":"Mulajore Kalibari in Shyamnagar is a historic Kali temple by the Hooghly river noted in district tourism listings.","architecture":"Riverside temple complex with traditional Bengal layout.","darshan":"Darshan is available daily with local worship cycles.","seasonal":"Festival seasons draw larger local crowds.","visitorNotes":"Plan for riverside access and narrow lanes.","festivals":"Kali Puja","sources":[{"label":"Mulajore Kalibari (North 24 Parganas tourism)","url":"https://north24parganas.gov.in/tourism/"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-simlagarh-simlagarh-kalibari', 'shiva', 'Simlagarh Kalibari', 'West Bengal', 'Simlagarh', 'Hooghly', 'Kali', 'Shakta', '["Simlagarh","Kali Temple","G.T. Road"]', 'A Kali temple in Simlagarh beside G.T. Road, known locally as Simlagarh Kalibari.', 'Roadside Kali temple serving local devotees.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Simlagarh%20Kalibari%2C%20famous%20and%20old%20Kali%20temple%20beside%20G.T%20Road%2C%20Simlagarh%2006.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Simlagarh_Kalibari,_famous_and_old_Kali_temple_beside_G.T_Road,_Simlagarh_06.jpg', 'Kali Puja and winter evenings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Beside G.T. Road; brief roadside stop for darshan.', '["Daily puja"]', '["Kali Puja"]', '{"history":"Simlagarh Kalibari is a local Kali temple beside G.T. Road in Simlagarh.","architecture":"Compact roadside temple structure.","darshan":"Darshan is available daily with local worship routines.","seasonal":"Kali Puja is the peak season for devotees.","visitorNotes":"Use caution while parking along the highway.","festivals":"Kali Puja","sources":[{"label":"Simlagarh Kalibari (Commons photo description)","url":"https://commons.wikimedia.org/wiki/File:Simlagarh_Kalibari,_famous_and_old_Kali_temple_beside_G.T_Road,_Simlagarh_06.jpg"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-singur-singur-dakat-kali-temple', 'shiva', 'Singur Dakat Kali Temple', 'West Bengal', 'Singur', 'Hooghly', 'Kali (Dakat Kali)', 'Shakta', '["Dakat Kali","Singur","Kali Puja"]', 'A local Dakat Kali Mandir in the Singur area, known for community Kali Puja observances.', 'Village Kali temple worship traditions in Singur.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Singur%20Dakat%20Kali%20Temple%20at%20Singur%2009.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Singur_Dakat_Kali_Temple_at_Singur_09.jpg', 'Kali Puja and autumn evenings.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Located in the Singur area of Hooghly district.', '["Daily puja"]', '["Kali Puja"]', '{"history":"Singur town includes a Dakat Kali Mandir among its local temples and village shrines.","architecture":"Local Bengal temple structure with a small courtyard.","darshan":"Darshan is available daily with peak festival visits.","seasonal":"Kali Puja is the busiest time.","visitorNotes":"Expect village lanes and limited parking.","festivals":"Kali Puja","sources":[{"label":"Singur (Dakat Kali Mandir mentioned)","url":"https://en.wikipedia.org/wiki/Singur"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-sribati-sribati-terracotta-complex', 'shiva', 'Sribati Terracotta Complex', 'West Bengal', 'Sribati', 'Purba Bardhaman', 'Shiva', 'Shaiva', '["Terracotta","Complex","Hidden Gem"]', 'A hidden complex of three Shiva temples (Shri Bisweswar, Bholanath, and Chandreswar) featuring exquisite terracotta work.', 'Detailed terracotta panels on all three temples.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pancha%20Ratna%20temple%20of%20Chanda%20family%20at%20Sribati%20in%20Purba%20Bardhaman%20district%2031.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pancha_Ratna_temple_of_Chanda_family_at_Sribati_in_Purba_Bardhaman_district_31.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Katwa.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built by the Chandra family in the 19th century.","architecture":"Pancha-ratna and Rekha styles.","darshan":"Artistic.","seasonal":"Pleasant in winter.","visitorNotes":"Ask locals for the key if closed.","festivals":"Shivratri.","sources":[{"label":"Sribati","url":"https://en.wikipedia.org/wiki/Sribati","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-sripur-shantinath-shiva-temple', 'shiva', 'Shantinath Shiva Temple', 'West Bengal', 'Sripur', 'Hooghly district', 'Shiva', 'Shaiva', '["Terracotta","Mitra Mustafi","Details"]', 'Built by the famous Mitra Mustafi family, this temple is a showcase of fine terracotta craftsmanship.', 'The terracotta panels showing social scenes.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Panch%20Mandir%20premises%20at%20Bhatpara%20near%20Naihati%20in%20North%2024%20Parganas%20district%2C%20West%20Bengal%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Panch_Mandir_premises_at_Bhatpara_near_Naihati_in_North_24_Parganas_district,_West_Bengal_01.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Balagarh.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in the 18th century.","architecture":"At-chala.","darshan":"Artistic.","seasonal":"Pleasant.","visitorNotes":"The Chandimandap nearby is also famous.","festivals":"Shivratri.","sources":[{"label":"Sripur","url":"https://en.wikipedia.org/wiki/Sripur,_Hooghly","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-supur-supur-jora-shiva-mandir', 'shiva', 'Supur Jora Shiva Mandir', 'West Bengal', 'Supur', 'Birbhum district', 'Shiva', 'Shaiva', '["Twin Temples","Octagonal","Terracotta"]', 'Twin Shiva temples (Jora Mandir) built in the 18th century. One is octagonal (ridgeless Rekha) and the other is circular, both with stunning terracotta.', 'The rare octagonal and circular designs.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Twin%20deul%20styled%20temple%20dedicated%20to%20Shiva%20at%20Supur%20in%20Birbhum%20district.%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Twin_deul_styled_temple_dedicated_to_Shiva_at_Supur_in_Birbhum_district._01.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Bolpur.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built by local zamindars in the 18th-19th century.","architecture":"Mixed styles (Rekha/Chala).","darshan":"Historic.","seasonal":"Crowded during Poush Mela.","visitorNotes":"Often called the \'Twin Temples of Supur\'.","festivals":"Shivratri.","sources":[{"label":"Supur","url":"https://en.wikipedia.org/wiki/Supur","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-surul-surul-jora-shiva-temple', 'shiva', 'Surul Jora Shiva Temple', 'West Bengal', 'Surul', 'Birbhum district', 'Shiva', 'Shaiva', '["Terracotta","Santiniketan","Heritage"]', 'Located near Santiniketan, these twin temples feature some of the finest terracotta panels depicting Ramayana scenes.', 'Detailed terracotta work right near the tourist hub of Santiniketan.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Paschim%20Para%20Deul%20styled%20Siva%20Temple%20at%20Surul%20in%20Birbhum%20district%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Paschim_Para_Deul_styled_Siva_Temple_at_Surul_in_Birbhum_district_01.jpg', 'Winter (Poush Mela).', 'Open daily.', 'Casual.', '3km from Bolpur.', '["Daily puja"]', '["Shivratri"]', '{"history":"Built in the 19th century by the Sarkar family.","architecture":"Pancha-ratna.","darshan":"Artistic.","seasonal":"Crowded during Poush Mela.","visitorNotes":"Visit the Sarkar Rajbari next door.","festivals":"Shivratri.","sources":[{"label":"Surul","url":"https://en.wikipedia.org/wiki/Surul","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-tamluk-bargabhima-temple', 'shiva', 'Bargabhima Temple', 'West Bengal', 'Tamluk', 'Purba Medinipur', 'Bargabhima (Kali)', 'Shakta', '["Bargabhima","Shaktipeeth","Tamluk"]', 'An ancient Kali shrine at Tamluk on the Roopnarayana river, revered as a Shaktipeeth.', 'Riverside temple complex in historic Tamluk.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bargabhima%20temple%20at%20Tamluk%20town%20under%20Purba%20Medinipur%20district%20in%20West%20Bengal%2001.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bargabhima_temple_at_Tamluk_town_under_Purba_Medinipur_district_in_West_Bengal_01.jpg', 'Navratri and winter months.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Located near the Roopnarayana river in Tamluk.', '["Daily puja"]', '["Navratri","Kali Puja"]', '{"history":"Bargabhima Temple in Tamluk is an ancient Kali shrine, also known as a Shaktipeeth associated with Devi Sati.","architecture":"Historic temple complex maintained by local custodians.","darshan":"Darshan is available daily with peak visits during festivals.","seasonal":"Navratri and Kali Puja are the busiest seasons.","visitorNotes":"Plan for temple queues during festival days.","festivals":"Navratri · Kali Puja","sources":[{"label":"Bargabhima Temple","url":"https://en.wikipedia.org/wiki/Bargabhima_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-tarakeswar-taraknath-temple-tarakeswar', 'shiva', 'Taraknath Temple (Tarakeswar)', 'West Bengal', 'Tarakeswar', 'Hooghly District', 'Shiva', 'Shaiva', '["Shiva","Pilgrimage","Bengal"]', 'A major Shaiva pilgrimage shrine in Tarakeswar revered as Baba Taraknath.', 'Pilgrim gatherings in Shravan and a lively temple precinct.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Babataraknathtemple.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Babataraknathtemple.jpg', 'Mondays and Shravan season.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect larger crowds during Shravan.', '["Daily puja","Evening aarti"]', '["Shravan month","Mahashivratri"]', '{"history":"Taraknath Temple is a prominent Shiva shrine in Tarakeswar, Hooghly district.","puranicView":"Shiva is worshipped here as Taraknath, with strong pilgrimage traditions.","puranicSources":[{"label":"Taraknath Temple","url":"https://en.wikipedia.org/wiki/Taraknath_Temple","type":"Encyclopedia"}],"folklore":"Local devotion emphasizes Monday worship and seasonal temple fairs.","folkloreSources":[{"label":"Taraknath Temple","url":"https://en.wikipedia.org/wiki/Taraknath_Temple","type":"Encyclopedia"}],"sources":[{"label":"Taraknath Temple","url":"https://en.wikipedia.org/wiki/Taraknath_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-tarapith-tarapith-temple', 'shiva', 'Tarapith Temple', 'West Bengal', 'Tarapith', 'Birbhum', 'Tara', 'Shakta', '["Shakti Peetha","Tara","Tantra"]', 'A famed Shakta shrine in Tarapith dedicated to Maa Tara and revered as a Shakti Peetha.', 'A vibrant temple town anchored by Tara worship.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tarapith%20Temple%2005.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tarapith_Temple_05.jpg', 'Kali Puja and Tara Puja seasons; early mornings are calmer.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Expect long queues during festival days.', '["Daily puja","Evening aarti"]', '["Tara Puja","Kali Puja","Durga Puja"]', '{"history":"Tarapith Temple is a major Shakta shrine in Birbhum dedicated to Goddess Tara and recognized as a Shakti Peetha and Siddha Peetha.","architecture":"Bengal chala-style temple architecture within a dense pilgrimage town.","darshan":"Darshan is open throughout the day; aarti draws the biggest crowds.","seasonal":"Festival seasons are the busiest for pilgrims.","visitorNotes":"Plan extra time during Kali Puja and Tara Puja.","festivals":"Tara Puja · Kali Puja · Durga Puja","sources":[{"label":"Tarapith Temple","url":"https://en.wikipedia.org/wiki/Tarapith_Temple"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-titagarh-annapurna-temple-titagarh', 'shiva', 'Annapurna Temple, Titagarh', 'West Bengal', 'Titagarh', 'North 24 Parganas', 'Annapurna', 'Shakta', '["Annapurna","Navaratna","Hooghly River"]', 'A heritage navaratna temple on the Hooghly bank dedicated to Annapurna, with Shiva enshrined in the sanctum.', 'Riverside navaratna architecture near Rasmani Ghat.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Annapurna%20Temple%2C%20Titagarh%2C%20Barrackpore%2C%20North%2024%20Parganas.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Annapurna_Temple,_Titagarh,_Barrackpore,_North_24_Parganas.jpg', 'Winter months and festival days.', 'Open daily; timings vary by season.', 'Modest attire recommended.', 'Located near Rasmani Ghat on the Hooghly riverbank.', '["Daily puja"]', '["Navratri","Annapurna Puja"]', '{"history":"Annapurna Temple at Titagarh is a navaratna heritage temple on the Hooghly bank, opened in the late 19th century.","architecture":"Navaratna temple style similar to the Dakshineswar layout.","darshan":"Daily darshan with seasonal festival gatherings.","seasonal":"Navratri and winter festivals see larger footfall.","visitorNotes":"Combine with a riverside walk near Barrackpore.","festivals":"Navratri · Annapurna Puja","sources":[{"label":"Annapurna Temple, Titagarh","url":"https://en.wikipedia.org/wiki/Annapurna_Temple,_Titagarh"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
INSERT INTO `temples` (`slug`, `mode`, `name`, `state`, `city`, `region`, `deity`, `tradition`, `tags`, `story`, `highlight`, `image`, `credit`, `creditUrl`, `bestTime`, `timings`, `dressCode`, `entryNotes`, `rituals`, `festivals`, `moreDetails`, `addedAt`, `sourceType`, `sourceUrl`, `confidenceScore`, `lastVerifiedAt`) VALUES ('shiva-west-bengal-uchkaran-uchkaran-shiva-temple', 'shiva', 'Uchkaran Shiva Temple', 'West Bengal', 'Uchkaran', 'Birbhum district', 'Shiva', 'Shaiva', '["Char-chala","Terracotta","Detail"]', 'A beautiful Char-chala temple built in 1769, known for its intricate terracotta figures depicting social life and mythology.', 'The condition and detail of the terracotta panels.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Terracotta%20plaques%20on%20third%20temple%20from%20west%20in%20the%20group%20of%20four%20charchala%20temples%20at%20Uchkaran%20at%20Birbhum%2011.jpg', 'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Terracotta_plaques_on_third_temple_from_west_in_the_group_of_four_charchala_temples_at_Uchkaran_at_Birbhum_11.jpg', 'Winter.', 'Open daily.', 'Casual.', 'Near Nanur.', '["Daily puja"]', '["Shivratri"]', '{"history":"Established in 1769 AD.","architecture":"Char-chala.","darshan":"Artistic.","seasonal":"Pleasant.","visitorNotes":"Well preserved.","festivals":"Shivratri.","sources":[{"label":"Uchkaran","url":"https://en.wikipedia.org/wiki/Uchkaran","type":"Encyclopedia"}]}', '2026-02-19T15:18:12+05:30', 'seed', 'src/data/temples/index.js', 1, '2026-03-03T06:40:54.452Z');
